export const PREMIUM_V2 = {
  qian: `
<p>我认识一个人，三十四岁，在一个公司干了七年。他是那种最让人放心的人——加班最多，出错最少，谁有烂摊子都找他。</p>
<p>去年他跟我说了一件事，我到现在还记得。他说：「我最近老觉得不对劲。我什么都没做错，可我好像越来越不重要了。」</p>
<p>他确实什么都没做错。问题出在别的地方：他干的是初爻的活，人已经在三爻的位置上了。</p>
<p>乾卦六个爻，全是阳。很多人一看六条阳爻，以为是在讲「要刚强」。真读进去你会发现，它讲的是六个位置——一件事从起步到收场，你会挨个经过。每个位置有每个位置该干的事。你在初爻做初爻的事，叫沉得住气；你在三爻还做初爻的事，叫占着位置不出活。</p>
<p>我下面按六个位置说。你找一个最像自己的，剩下的可以先不看。</p>
<h3 id="p-初九-潜龙勿用-别出声">初九 · 潜龙勿用 —— 别出声</h3>
<blockquote class="pw-quote"><strong>初九：潜龙勿用。</strong><br>象曰：潜龙勿用，阳在下也。</blockquote>
<p><strong>你现在在这个位置：你有东西，但没人知道。你说的话，别人点点头就过去了。</strong></p>
<p>这个阶段的动作只有一个：别出声。</p>
<p>具体到能做的事——定一个三个月目标，不告诉任何人。不是「低调一点」，是<strong>一个字都不说</strong>。原因很实际：说出去，你会拿到几句夸奖，然后就没劲了。人是有这个毛病的，话一出口，心里那口气就松了。</p>
<p>还有一件：<strong>推掉所有让你露脸但学不到东西的场合</strong>。上台领奖、群里发言、行业饭局上被介绍给大家——这些东西给你的是面子，不是本事。你现在最不缺的就是面子。</p>
<p>再补一条更狠的：<strong>别去解释自己</strong>。有人误会你、低估你，别急着辩。这个阶段你越辩，别人越觉得你心虚，而且你花在辩上的时间，本来能用来长本事。</p>
<p>帝舜在雷泽那几年，唐尧还在位，天下太平，他就在那儿待着。<strong>刘邦当泗水亭长的时候不行，那时候秦朝还没乱，他要是敢冒头，第一件事就是掉脑袋。</strong></p>
<p><strong>什么情况可以破例：</strong>如果那个场合能让你直接接触到比你高一个量级的人，去。这时候你去不是让人看你，是让你看他——看清楚差在哪儿，比拿十次奖有用。</p>
<h3 id="p-九二-见龙在田-利见大人-找准那一个人">九二 · 见龙在田，利见大人 —— 找准那一个人</h3>
<blockquote class="pw-quote"><strong>九二：见龙在田，利见大人。</strong><br>象曰：见龙在田，德施普也。</blockquote>
<p><strong>你现在在这个位置：开始有人注意到你了。有人主动来问你意见。</strong></p>
<p>这时候的任务不是让更多人知道，是找到那个对的、能把你托起来的人。</p>
<p>韩鹏杰讲这一爻讲得特别实在。他说「见龙」是抓住机会表现一下，但在哪表现呢？<strong>要「在田」——田里有水、有湿地，你可别跑到硬地上去了。</strong></p>
<p>硬地是什么？就是那种你露了一手，没人接，还招来一堆眼红的地方。</p>
<p><strong>判断标准就一条：这个人愿不愿意把资源交给你试。</strong>光夸你不给事的，是客套，听完就完了。又夸你、又切一小块东西让你试的，那才是入口。</p>
<p>诸葛亮在卧龙岗待了那么多年，不是没人来请，是来的人不合。<strong>他要的不是一个位置，是一个真会照他说的做的人。</strong>刘备三顾，他出山；换个人来，隆中对就是一份没人执行的文件。</p>
<p>梁冬给了一个很好用的自查法：<strong>你用直觉问自己一句——当下我最焦虑的问题是什么？这世上有谁可能帮我？你脑子里第一个冒出来的那个人，就是你的大人。</strong></p>
<p>这个「大人」不一定是职位最高、最有钱的那个。你自己回想一下，这辈子真正在关键时刻帮过你的人，多半能力一般，<strong>胜在愿意帮你</strong>，或者刚好知道内情。</p>
<p><strong>什么情况不用这么挑：</strong>如果你现在连饭都吃不上，先接活。活下去比选对人要紧，你没有挑的资格。</p>
<h3 id="p-九三-君子终日乾乾-夕惕若厉-无咎-白天干-晚上">九三 · 君子终日乾乾，夕惕若厉，无咎 —— 白天干，晚上查</h3>
<blockquote class="pw-quote"><strong>九三：君子终日乾乾，夕惕若厉，无咎。</strong><br>象曰：终日乾乾，反复道也。</blockquote>
<p><strong>你现在在这个位置：事被推到你身上了。你不想干也不行，机会多了，麻烦也多了。</strong></p>
<p>这是六爻里最累的一段。你白天在干活，晚上补自己不会的，还是觉得不够。而且你会开始得罪人——你人没变坏，<strong>做事的人天然会挡别人的路</strong>。你做得越多，撞上的人就越多。</p>
<p>给你两个具体动作：</p>
<p>一是<strong>每天留半小时，只找一件事：「今天哪件事我做错了。」</strong>这个位置最危险的不是犯错，是忙到没空发现自己犯了错。</p>
<p>二是<strong>主动找一个敢跟你说真话的人</strong>。你现在听到的大多是好话，好话对你没用。</p>
<p>梁冬说他采访过很多做到千亿的创始人，问他们当初想没想过有今天，几乎都说没有——那时候就是想吃饱饭，然后<strong>人被事推着走了</strong>。中间吵过架、闹过散伙、有的还打过官司，一路九死一生。</p>
<p>梁冬还讲过另一面。他认识一些很优秀的人，三十多岁还没做出什么，他问为什么。对方说得很坦白：不怪天不怪地，怪自己——<strong>当年该拼的时候没拼，怕得罪人，怕犯错，怕辛苦。</strong></p>
<p><strong>什么情况别硬扛：</strong>如果你连着三个月，补窟窿的速度赶不上窟窿冒出来的速度，那这个位置本来就不是你的。这时候往下退一步不丢人，硬撑着往前，摔得更难看。</p>
<h3 id="p-九四-或跃在渊-无咎-跳不跳-都行">九四 · 或跃在渊，无咎 —— 跳不跳，都行</h3>
<blockquote class="pw-quote"><strong>九四：或跃在渊，无咎。</strong><br>象曰：或跃在渊，进无咎也。</blockquote>
<p><strong>你现在在这个位置：机会来了，但你不确定该不该上。也可能有人在跟你争同一个东西。</strong></p>
<p>这一段我给你一句可能不太像《周易》的话：<strong>怎么选都行。</strong></p>
<p>上面的领导走了或者调了，位置空出来，你可能被提上去；也可能看着是升了，其实被挪出了核心业务。这两种事都常见，都不是灾难。</p>
<p>梁冬讲过一位香港理工大学的校长潘宗光。他本来在化学上做得好，有机会做校长的时候，他问了自己一个问题：我是继续做研究，还是去做校长、让学校里出更多个「潘宗光」？他选了后者。<strong>这不是放弃，是换了一条路走。</strong></p>
<p><strong>你怎么判断：</strong></p>
<p>- <strong>有退路就跳</strong>。你现在跳出去还能活，那就跳。跳出去就断生计，那不叫勇敢，叫赌。</p>
<p>- <strong>「再等等看」说了超过三次</strong>，那你其实不想跳，只是不敢承认。把这事放下，别再耗着。</p>
<p>- <strong>看这事三年后还重不重要</strong>。三年后已经不重要的事，现在跳不跳都不重要。</p>
<p><strong>什么情况必须动：</strong>如果留在原地意味着你要天天做你明确知道没价值的事，那就走。耗时间比失败更贵。</p>
<h3 id="p-九五-飞龙在天-利见大人-把最擅长的那块交出去">九五 · 飞龙在天，利见大人 —— 把最擅长的那块交出去</h3>
<blockquote class="pw-quote"><strong>九五：飞龙在天，利见大人。</strong><br>象曰：飞龙在天，大人造也。</blockquote>
<p><strong>你现在在这个位置：这件事你说了算。下面的人都听你的。</strong></p>
<p>这个位置最容易犯的错，是<strong>越到上面越想证明自己还很强</strong>。你以前是靠亲手做具体的事上来的，现在位置变了，本能还是想自己上手。可你一动，下面的人就没法动了。</p>
<p>汉文帝是被拥立进京的，坐上去之后想修个露台，一算账要花百金，相当于十户中等人家的家产，他说那就不修了。<strong>钱他拿得出，他清楚自己刚上来，最不能被看成在享受。</strong></p>
<p>你现在该做的三件事：</p>
<p>- <strong>把最擅长的那块交出去</strong>，交给一个你信得过的人。</p>
<p>- <strong>定规则，别定结果</strong>。你管结果，下面的人就只剩执行；你管规则，他们才会想办法。</p>
<p>- <strong>主动去问反对意见</strong>。这个位置没人敢跟你说真话，你得自己去捞。</p>
<p><strong>什么情况别急着放权：</strong>如果这件事是救命的、错了就全盘皆输，先自己盯到稳了再交。交太早，等于把家底交给还没练出来的人。</p>
<h3 id="p-上九-亢龙有悔-差不多就到这儿了">上九 · 亢龙有悔 —— 差不多就到这儿了</h3>
<blockquote class="pw-quote"><strong>上九：亢龙有悔。</strong><br>象曰：亢龙有悔，盈不可久也。</blockquote>
<p><strong>你现在在这个位置：你最近老觉得「到头了」。事情还能转，但没有以前那个劲了。</strong></p>
<p>这一段的做法是：主动让出去一部分。</p>
<p>韩信死在长乐宫。刘邦封他齐王、楚王，他一路往上，到最后一步没停。<strong>刘邦夺他兵权、把他贬成淮阴侯的那两次，其实都是在提醒他，他没接住。</strong></p>
<p><strong>具体怎么做：</strong></p>
<p>- <strong>交出一部分最扎眼的东西</strong>。不用全交，全交是自保过度，反而让人看轻你。交出那个最显眼、最容易被人拿来说事的部分。</p>
<p>- <strong>换一种活法</strong>。从亲手做事的人，变成给别人讲经验的人。这不是退，是换赛道。</p>
<p>- <strong>别碰那些「非你不可」的事</strong>。到了一定位置，凡是「只有你能干」的活，都是危险信号。</p>
<p><strong>什么情况可以再冲一次：</strong>如果你身体、现金流、团队都还在上坡，你也确实还想干，那就把「亢」的那部分去掉再干——去掉排场，去掉跟人比的心气，只留事本身。这时候还能再走一程。</p>
<h3 id="p-最后-别当头">最后：别当头</h3>
<p>乾卦比别的卦多出一句，叫「用九」：</p>
<p><strong>见群龙无首，吉。</strong></p>
<p>六条龙，没有一条要站在最前面。这是吉。</p>
<p>我理解这句话的意思是：一个阶段结束了，该收的收完了，你从最前面那个位置上退下来，反而安全。梁冬说他给一个问姻缘的人解过这一爻——那人占到「亢龙有悔」，他判断这段关系该结束了。他给的劝告是：结束了别马上开始下一段，先空一段时间，把伤养好，别急着让另一个人来填位置。<strong>会用空窗期，也是本事。</strong></p>
<p><strong>乾卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">别总想着做最强的那个。该你上就上，该你退就退，站对位置比站得高重要。</blockquote>
  `,
  kun: `
<p>坤卦最有名的一句话是「黄裳元吉」。裳是下衣，就是裙子裤子那一层；黄是土地的颜色，最不起眼。</p>
<p>这一爻在第五位。第五位是君位，是整个卦里最高的位置。</p>
<p>事情就对上了：你已经站在最高的地方了，卦辞给你的建议是——把下面那件衣服穿上。</p>
<p>一个朋友做到公司二把手，老板出差他最大。上任第一个月，他把汇报线重新画了一遍，把三个老臣挪到边上，又开全员会讲了一次战略。半年后他还在，实权没了，成了一个只负责开会的人。</p>
<p>他没做错任何一件具体的事。他只是急着让大家承认，他配坐这个位置。</p>
<p>都说坤卦讲的是顺从、配角、老实人。真读进去，它讲的是<strong>你在什么位置上就用什么姿态，而且姿态永远比位置低半格</strong>。低半格安全，齐平危险，高出半格就要出事。上六那一爻，就是高出半格的结局。</p>
<h3 id="p-初六-履霜-坚冰至-那件事你已经看见了">初六 · 履霜，坚冰至 —— 那件事你已经看见了</h3>
<blockquote class="pw-quote"><strong>初六：履霜，坚冰至。</strong><br>象曰：履霜坚冰，阴始凝也。驯致其道，至坚冰也。</blockquote>
<p><strong>你现在的处境：有件事让你心里咯噔了一下，你转头就说服自己「应该没事」。</strong></p>
<p>「履霜，坚冰至」。脚下踩到霜，就知道后面的冰天雪地一定会来。霜不是冰，可霜是冰的第一次预告。</p>
<p>这个阶段只做一件事：<strong>把那个「咯噔」记下来，写一行字。</strong></p>
<p>不是让你去处理它，是让你留住证据。人在这个阶段最爱自我解释——他可能最近压力大；她就是这么个说话方式；这个季度波动很正常。</p>
<p>给你一把尺子：<strong>同一件让你不舒服的事出现三次，就不再是意外了。</strong>一次是偶发，两次是巧合，三次就是趋势。这时候你要调整的不是这件事，是你对这个人的判断。</p>
<p>汉宣帝刚即位时跟霍光同坐一辆车，后来他形容那次的感觉，叫「芒刺在背」。霍光明面上恭敬，一点错挑不出来。宣帝什么都没做，他就是记住了那个感觉。霍光一死，他一步一步把霍家的权收了回来。</p>
<p><strong>什么情况可以不动：</strong>如果这事只影响你一个人、不涉及钱和前途，先放着。把所有不舒服都当信号，人会变得疑神疑鬼，那比迟钝更麻烦。要是那个「咯噔」其实来自你自己——比如你只是被别人的成功刺激到了——记下来就行，别行动。</p>
<h3 id="p-六二-直-方-大-不习无不利-把本分做到挑不出毛">六二 · 直，方，大，不习无不利 —— 把本分做到挑不出毛病</h3>
<blockquote class="pw-quote"><strong>六二：直，方，大，不习无不利。</strong><br>象曰：六二之动，直以方也。不习无不利，地道光也。</blockquote>
<p><strong>你现在的处境：你在做一件本分的事，没人夸你，也没人拦你，日子有点平。</strong></p>
<p>「直方大，不习无不利」。直是正，方是有边界，大是容得下。这三样做到，就算你还没学会那些花活，也不会差到哪儿去。</p>
<p>这个阶段该干的，是<strong>把本分做到别人挑不出毛病</strong>。</p>
<p>具体点：你手上那件事有没有明确标准？交付的时间、质量、口径，是不是每次都对得上？答应别人的事，有没有失约过？</p>
<p><strong>你现在最值钱的资产是「靠得住」这三个字。</strong>这东西攒起来慢，掉起来快。</p>
<p>同时别做那些为了被看见而做的事。在会上显摆一个你半懂的东西、抢一个你干不了的活、在群里接一句你接不住的话——收益是面子，成本是信用。</p>
<p>「不习无不利」讲得挺妙：你不需要样样精通，位置对了就够了。</p>
<p><strong>什么情况要主动出头：</strong>如果这里没人知道你在干什么，而资源是靠自荐分配的，那你得说话。标准很简单——<strong>这里的人是不是靠「会哭」拿到东西的？</strong>是，你不哭就是放弃；不是，你哭就是自降身价。</p>
<h3 id="p-六三-含章可贞-或从王事-无成有终-本事够了-位">六三 · 含章可贞。或从王事，无成有终 —— 本事够了，位置不够</h3>
<blockquote class="pw-quote"><strong>六三：含章可贞。或从王事，无成有终。</strong><br>象曰：含章可贞，以时发也。或从王事，知光大也。</blockquote>
<p><strong>你现在的处境：你本事够了，位置不够。你干的事，最后功劳会记到别人头上。</strong></p>
<p>「含章可贞，或从王事，无成有终」。含章就是好东西揣在怀里不亮出来。无成有终——你拿不到那个「成」，但你能拿到「终」。</p>
<p>这一段最难，也最值钱。</p>
<p>先说该干什么：<strong>把这件事干到你自己的标准，而不是干到别人看得见的标准。</strong>这不是道德，是算账。功劳这东西，谁给的谁清楚。你这次让出去，对方心里记一笔；你这次抢过来，对方也记一笔。前一笔是资产，后一笔是负债。</p>
<p>再说别干什么：<strong>别在人前抱怨「活是我干的」。</strong>这句话一出口，你前面所有付出都变成了委屈，而委屈不值钱。</p>
<p>张良封赏的时候，刘邦让他自己在齐地挑三万户，他没要，只要了留县——那是他第一次见刘邦的地方，一个小地方。他不要那份功劳，所以他一直活着。</p>
<p>反过来说贾谊。他二十出头就被汉文帝破格提拔，《治安策》讲削藩讲得准，可他太急，周勃、灌婴那批老臣联手排挤他，文帝把他外放去做长沙王太傅。判断对，出手的时机错。</p>
<p><strong>什么情况不用让：</strong>如果这份功劳关系到你的岗位、职称、能不能留下来，就要。让功劳是给有余力的人准备的，你连位置都不稳，让出去的就是饭碗。另一种：对方要是惯于抢功、从不回报的人，你让了也白让，这时候把证据留清楚比让出去重要。</p>
<h3 id="p-六四-括囊-无咎无誉-这时候说什么都错">六四 · 括囊，无咎无誉 —— 这时候说什么都错</h3>
<blockquote class="pw-quote"><strong>六四：括囊，无咎无誉。</strong><br>象曰：括囊无咎，慎不害也。</blockquote>
<p><strong>你现在的处境：风向不明，你说了几句实话反而惹了麻烦。或者你发现，怎么表态都不对。</strong></p>
<p>「括囊，无咎无誉」。把口袋扎上。没有过错，也没有赞誉。</p>
<p>注意后半句——<strong>无誉</strong>。这一爻的代价是没人夸你，很多人受不了这个。他们宁可挨骂也要说话，因为挨骂好歹证明自己存在。</p>
<p>这个阶段的动作：<strong>把该说的话收进本子里，别收进群里。</strong></p>
<p>想说的话、对某人的判断、手上做成的事、憋着的那个方案——全部先落到文档里。见人只说三件事：事实、进度、需要对方做什么。</p>
<p>标准是：<strong>这句话说出去，痛快和风险哪个大？</strong>痛快大就别说。实在憋得难受，找一个人说，就一个，那个绝对不会有二心的人。</p>
<p>梁冬在这儿有个自省挺狠。他以前觉得自己是行坤德的人，后来发现那是给懒惰找借口——觉得只要不坏、不招人嫌、低调待着就行了。他后来明白这不是坤德。真正的坤德是<strong>嘴上不出声，手底下一步没停</strong>。</p>
<p>「括囊」是扎口袋，不是躺下。</p>
<p><strong>什么情况必须开口：</strong>两种。一是涉及合规、安全、法律，说出去是职责，不说才是错。二是有人在替你背锅——这时候闭嘴等于让人替你挨打，你不光丢人，还会结下真死仇。这两种之外，都先收着。</p>
<h3 id="p-六五-黄裳-元吉-姿态永远比位置低半格">六五 · 黄裳，元吉 —— 姿态永远比位置低半格</h3>
<blockquote class="pw-quote"><strong>六五：黄裳，元吉。</strong><br>象曰：黄裳元吉，文在中也。</blockquote>
<p><strong>你现在的处境：你已经在这个位置上了。可能是老板，是负责人，也可能是家里说了算的那个人。</strong></p>
<p>回到开头那句话。你已经坐在这个位置上了，但你不是靠抢上来的。这种时候最忌讳的就是——急着证明自己配得上。</p>
<p>坤卦这一爻给的答案很反直觉：<strong>你越是想显得像领导，越坐不稳。</strong></p>
<p>「裳」是穿在里面的、不显眼的那一层，「黄」是土的颜色，也不扎眼。合起来：你坐在上面，用的是下面的姿态。</p>
<p>三条能落地的：</p>
<p>- <strong>公开场合把「我」字用量减到最低。</strong>讲成绩时说「我们」和具体做事的人的名字。人记住的是谁在会上提过他。</p>
<p>- <strong>新官上任前三个月不动人。</strong>不动位置、不动汇报线、不动考核方式。你要改的是流程里的堵点，不是人的座位。画组织架构图是满足自己的快感，那个快感很贵。</p>
<p>- <strong>留一件只有你自己在干的具体事。</strong>这让你不脱离地面，也让下面的人知道你懂。别拿它去抢功劳。</p>
<p>王莽是反面。他早年散财结交名士，儿子杀了家奴，他逼儿子自杀抵命，天下人都说他谦恭有德。姿态做足了，他要的是那个位置本身。同样是谦恭，方向不一样，结果差得天远。</p>
<p><strong>什么情况不要这么收着：</strong>接手的要是个烂摊子，需要立规矩、需要开人，第一把火必须烧，而且要烧得让人看见。局面已经失控了你还客气，等于把摊子交给混乱。</p>
<p>还有一条：<strong>这个位置要是你自己挣来的、你投的钱、你担的风险，你不需要装得像个客人。</strong>该拍板就拍板。坤卦讲的是姿态低，不是没有主张。</p>
<h3 id="p-上六-龙战于野-其血玄黄-忍到头了">上六 · 龙战于野，其血玄黄 —— 忍到头了</h3>
<blockquote class="pw-quote"><strong>上六：龙战于野，其血玄黄。</strong><br>象曰：龙战于野，其道穷也。</blockquote>
<p><strong>你现在的处境：你一直在忍、在配合、在退让，但对方开始得寸进尺，或者你已经退到没有退路了。</strong></p>
<p>「龙战于野，其血玄黄」。玄是天色，黄是地色，血洒在天地之间。</p>
<p>这一爻讲的是：<strong>柔顺有上限，过了那个上限，柔顺就变成憋着，憋到某个点一定炸。而炸出来的样子，就是两败俱伤。</strong></p>
<p>这里有个很多人搞错的地方。「龙战于野」不是叫你勇敢反抗，它描写的是一场没人赢的场面。</p>
<p>具体怎么做：</p>
<p>- <strong>在爆发之前，先正式交涉一次。</strong>把你忍了多久、忍了什么，一件一件列出来，用最平的口气讲完，讲完先不说话。多数关系的崩掉，是因为从来没正式谈过，全靠暗示，而暗示对方永远接不到。</p>
<p>- <strong>准备一个退出动作。</strong>谈不拢，你要能走。上六的凶险在于你没有退路，所以只能硬碰。有退路的人不需要打这一仗。</p>
<p>- <strong>把「我对你多好」换成「我们要怎么办」。</strong>前者是算旧账，越算越伤人，还永远算不清。</p>
<p>霍光辅政二十年，废过一个皇帝，立过两个，权势到了顶点。他活着时没人能动他，死后三年，霍家满门被诛。他一生守着臣子的本分，可权柄太重，重到皇帝睡不安稳——到那时候，本分已经保不住他了。</p>
<p><strong>什么情况不该走到这一步：</strong>你要是忍的时间其实不长，只是这一次格外难受，那问题不在对方，在你的耐受力。再等等，别急着摊牌。摊牌是一次性消耗品，用完就没有了。</p>
<p>还有一种：对方要是那种「你越退他越进」的人，别忍到上六。在六三、六四那两个阶段就划清界限，成本低得多。</p>
<h3 id="p-最后-地在最低处-所以万物都归它">最后：地在最低处，所以万物都归它</h3>
<p>乾卦往上冲，坤卦往下接。</p>
<p>你回头看几年会发现，冲得最猛的那些人，往往不是最后留下来的。留下来的是那种不声不响、但一直都在、你什么时候找他都在的人。</p>
<p>坤卦讲的其实就一件事：<strong>你的位置可以很高，你的姿态得一直在下面。</strong></p>
<p>下面不是窝囊。地是全卦里最低的东西，可万物最后都得落在它身上。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别急着让人看见你配得上这个位置。你把事接住了，位置自己会认你。</blockquote>
  `,
  zhun: `
<p>你刚接手一个摊子。可能是新项目，可能是新部门，也可能是刚盘下来的店。</p>
<p>你坐下第一天就发现，事情比你想的乱得多。流程没有，人手不齐，账上钱不够，谁跟谁也不对付。你想干点什么，一动就卡住。</p>
<p>这个感觉有个专门的字：屯。</p>
<p>屯是草木刚顶出土的那一下。土是硬的，石头是有的，旁边还有别的东西抢地盘。它不是长不出来，是<strong>出来得特别费劲</strong>。</p>
<p>屯卦六个爻，讲的就是这一下。你从「不敢动」开始，经过「等错人」「追错东西」「求错人」，最后可能「哭都哭不出来」。每一爻都是创业初期一个具体的坑。</p>
<p>我下面按六个位置说。你现在最难受的那一条，就是你的位置。</p>
<h3 id="p-初九-磐桓-先别动-先聚人">初九 · 磐桓 —— 先别动，先聚人</h3>
<blockquote class="pw-quote"><strong>初九：磐桓，利居贞，利建侯。</strong><br>象曰：虽磐桓，志行正也。以贵下贱，大得民也。</blockquote>
<p><strong>你现在在这个位置：你有一堆想法，但一动就撞墙。你已经开始怀疑是不是自己不行。</strong></p>
<p>这个阶段的动作只有一个：<strong>停下来搭班子，不要往前冲</strong>。</p>
<p>「磐桓」是原地打转、迈不开腿的样子。王弼注这四个字注得很准：不是贪图舒服，是「息乱以静」——想平息乱局，得先静下来。</p>
<p>具体怎么做？把你的核心名单写出来，不超过五个人。然后一个个去谈，谈的不是愿景，是<strong>他具体负责什么、拿到什么</strong>。谈完还没定下来的，不算数。</p>
<p>还有一条：<strong>在这个阶段，你要主动往下走</strong>。「以贵下贱，大得民也」——你姿态低一点，人才会靠过来。开局你没有资源给人家，你只有尊重可以给。</p>
<p>刘邦进关中，约法三章，就三条，别的秦法全废。<strong>他不是来不及立法，是知道这个时候法越少，人来得越快。</strong></p>
<p><strong>什么情况可以破例：</strong>如果你手上是笔快钱，窗口期就三个月，那就先干起来，边干边搭。活下去比体系重要。</p>
<h3 id="p-六二-屯如邅如-该来的还没来">六二 · 屯如邅如 —— 该来的还没来</h3>
<blockquote class="pw-quote"><strong>六二：屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。</strong><br>象曰：六二之难，乘刚也。十年乃字，反常也。</blockquote>
<p><strong>你现在在这个位置：你有一个更好的offer在远处，但近处有人拽着你，你走不了。</strong></p>
<p>「乘马班如」是骑着马原地打转，马都想走了，你不让。这种状态最消耗人——你既没有投入到眼前，也没有脱身去远方。</p>
<p>这个阶段要做的判断是：<strong>近处那个人，是拦你的，还是留你的。</strong></p>
<p>标准很硬：他有没有在你不能给他带来好处的时候，仍然替你想过事？有过，他是留你的。没有，他只是在用你。</p>
<p>「女子贞不字，十年乃字」——字是许嫁的意思。这爻最后给的答案不是妥协，是等：等到那个真正该来的时候。</p>
<p>苏武在匈奴十九年，李陵去劝降，把汉武帝怎么对不起他一家都说了。<strong>苏武没答应，也没跟李陵翻脸，他就那么守着，守到昭帝时和亲，回了长安。</strong></p>
<p><strong>什么情况别等：</strong>如果那个远处的人三年内不会给你任何实质回应，那不是时机未到，是人家没打算。这时候该走。</p>
<h3 id="p-六三-即鹿无虞-没有向导就别进山">六三 · 即鹿无虞 —— 没有向导就别进山</h3>
<blockquote class="pw-quote"><strong>六三：即鹿无虞，惟入于林中，君子几不如舍，往吝。</strong><br>象曰：即鹿无虞，以从禽也。君子舍之，往吝穷也。</blockquote>
<p><strong>你现在在这个位置：你看上一个机会，但你其实不懂这个行当，也没人带你。</strong></p>
<p>「虞」是古代打猎的向导官。追鹿没有虞官，你只能瞎进林子，鹿追不到，人还得迷路。</p>
<p>孔颖达把这一爻解得特别实在：那三爻想去跟九五，但没先打听九五愿不愿意接他，这就叫「无虞」——<strong>没摸清对方的意思，就一头扎进去</strong>。</p>
<p>这个阶段的动作：<strong>在你投入第一笔实质成本之前，先做三件事。</strong>找一个在这个圈子里泡了三年的人问一次；把这件事最坏的结果写下来；给自己定一个撤退线。</p>
<p>「君子几不如舍」——几是「差不多」的意思。聪明人看到这个形势，会说一句「算了」。说这句话不丢人。</p>
<p>李广利征大宛，第一次去，路线不熟，沿途小国不肯供粮，走到郁成城下已经饿得打不动，只好退回来。<strong>他去了，但他没带向导。</strong></p>
<p><strong>什么情况可以硬闯：</strong>如果这件事的试错成本对你来说就是一笔学费，亏了不影响根基，那就当交学费去闯。亏钱能学会的东西，比看书快。</p>
<h3 id="p-六四-乘马班如-求婚媾-该求的人-去求">六四 · 乘马班如，求婚媾 —— 该求的人，去求</h3>
<blockquote class="pw-quote"><strong>六四：乘马班如，求婚媾，往吉，无不利。</strong><br>象曰：求而往，明也。</blockquote>
<p><strong>你现在在这个位置：你想跟一个人合作，但你觉得开口很难，或者怕被拒绝。</strong></p>
<p>同样是「乘马班如」，同样的原地打转，但六四这一爻的答案跟六二不一样。六二是等，六四是<strong>去</strong>。</p>
<p>「求而往，明也」——去求，而且去，这叫明白。</p>
<p>这个阶段的动作：<strong>把你犹豫的那件事，变成一个具体的、对方好答的问题，今天就发出去。</strong></p>
<p>不要说「有没有可能合作」，要说「下周三下午我能不能带方案去你办公室坐二十分钟」。前者是表态，后者是邀约。表态对方可以已读不回，邀约对方只能答是或不是。</p>
<p>刘备三顾茅庐，第三次进门时诸葛亮在睡觉。<strong>刘备就在台阶下站着等，等到人醒。</strong></p>
<p><strong>什么情况别去求：</strong>如果你们之间有过明确的过节，而且对方是记仇的人，那这趟去只会让对方觉得你在示弱。先找中间人递个话。</p>
<h3 id="p-九五-屯其膏-好处别撒得太开">九五 · 屯其膏 —— 好处别撒得太开</h3>
<blockquote class="pw-quote"><strong>九五：屯其膏，小贞吉，大贞凶。</strong><br>象曰：屯其膏，施未光也。</blockquote>
<p><strong>你现在在这个位置：你手里资源不多，但已经有好几拨人来找你要了。</strong></p>
<p>「膏」是恩泽、好处。「屯其膏」是把好处攥着不撒开。这一爻直接给了判断：<strong>小范围给，吉；大范围铺，凶。</strong></p>
<p>孔颖达说得明白：这个时候你「所施者褊狭」，但这不是坏事——出纳之吝，是小正之吉。你资源就这么多，撒开了谁都吃不饱，还养出一堆指望你的人。</p>
<p>具体怎么分：<strong>把资源集中给那个能形成正循环的点。</strong>其他的人说清楚「现在没有，什么条件成熟了我给你」。给一句准话，比给一点碎银子有用。</p>
<p>朱元璋打天下时定「高筑墙，广积粮，缓称王」。<strong>他有粮，但不急着大封群臣，也不急着把摊子铺开。</strong></p>
<p><strong>什么情况必须大撒：</strong>如果有一拨人正在被对手挖，而他们是你的命根子，那就砸。这不算铺开，这叫守门。</p>
<h3 id="p-上六-泣血涟如-这时候哭也没用">上六 · 泣血涟如 —— 这时候哭也没用</h3>
<blockquote class="pw-quote"><strong>上六：乘马班如，泣血涟如。</strong><br>象曰：泣血涟如，何可长也。</blockquote>
<p><strong>你现在在这个位置：你已经投进去太多了，退不出来，往前走也没路。</strong></p>
<p>「泣血涟如」是眼泪流得像血。这爻的象传只回了四个字：<strong>何可长也</strong>——这样能撑多久。</p>
<p>这一爻不给你解法，它给你一个提醒：<strong>这个位置是熬不过去的，你得认。</strong></p>
<p>动作只有两个。第一，<strong>现在就把这个摊子的真实账算一遍</strong>，包括已经投进去的时间、钱、关系，别用「再撑一下就好了」糊过去。第二，<strong>在你还能选的时候选</strong>——是止损，是转手，还是并入别家。</p>
<p>秦末的章邯，巨鹿之后退守棘原，手里还有二十万兵。他跟项羽谈降，谈的时候还在犹豫。<strong>谈判桌上拖的每一天，他手里的筹码都在往下掉。</strong></p>
<p><strong>什么情况别急着认输：</strong>如果你账上还有六个月现金，团队还在，那上六离你还远。别读了一句话就把自己的事判了死刑。</p>
<h3 id="p-最后-屯是草木顶土的那一下">最后：屯是草木顶土的那一下</h3>
<p>《易》里排卦，乾坤之后就是屯。天地开了，第一批东西要长出来，一定是最难的。</p>
<p>乾卦讲你怎么往上走，坤卦讲你怎么往下接。屯卦讲的是<strong>从零到一那一段，没有位置给你站，你得自己踩出一块地。</strong></p>
<p>屯卦最后给你的一句话：</p>
<blockquote class="pw-quote">开局那阵乱不是你的错，是规律。你要做的不是把乱理干净，是先找三个人站到你这边。</blockquote>
  `,
  meng: `
<p>你有没有过这种经历。</p>
<p>你去请教一个比你懂的人，问完，你心里其实已经有答案了。你只是想让他说「你对了」。</p>
<p>他说了别的。你点点头，回去还是按自己的来。</p>
<p>这就是蒙卦要讲的事。蒙是蒙昧，是看不见。但蒙卦真正扎人的地方不在「不懂」，在于<strong>你明明不懂，还不肯真的让人教你</strong>。</p>
<p>卦辞里那句最有名：「匪我求童蒙，童蒙求我。」——不是老师追着学生教，是学生来求老师。</p>
<p>还有后半句更狠：<strong>「初筮告，再三渎，渎则不告。」</strong> 你诚心问，我告诉你。你反反复复拿同一件事来磨，那是拿我当情绪垃圾桶，我就不说了。</p>
<p>蒙卦六个爻，讲的是求教的六种姿态。从「该立规矩」到「别做伸手党」。你找一条对得上的。</p>
<h3 id="p-初六-发蒙-利用刑人-该立规矩的时候别客气">初六 · 发蒙，利用刑人 —— 该立规矩的时候别客气</h3>
<blockquote class="pw-quote"><strong>初六：发蒙，利用刑人，用说桎梏，以往吝。</strong><br>象曰：利用刑人，以正法也。</blockquote>
<p><strong>你现在在这个位置：你手上带的人，或者你的孩子，正在犯一个明显会出事的错，你还没说什么。</strong></p>
<p>「发蒙」是把蒙昧打开。「利用刑人」不是让你去罚人，是<strong>把规矩立到别人知道疼</strong>。</p>
<p>孔颖达说得很直白：刑罚这东西「不可不施于国，鞭扑不可不施于家」。他不喜欢，但他承认必须有。</p>
<p>具体做：<strong>把那条最要紧的线，用一句话讲透，说清越过去会怎样。</strong>然后第一次越线必须真执行。规矩的成本只在第一次执行的时候最便宜，往后每次都更贵。</p>
<p>但这一爻还有个尾巴：「以往吝」——<strong>如果你一路只靠罚人管事，往后就鄙吝了。</strong>罚是开局的工具，不是常态。</p>
<p>孙武给吴王练宫女排兵，三令五申之后，两个当队长的宠姬还在笑。<strong>他直接斩了那两个，鼓声再响，队形再没人敢错。</strong></p>
<p><strong>什么情况不用立规矩：</strong>如果对方只是不熟练，不是不认你的线，那就再教一遍。把生手当刺头收拾，队伍会散。</p>
<h3 id="p-九二-包蒙吉-会教的人-什么人都接得住">九二 · 包蒙吉 —— 会教的人，什么人都接得住</h3>
<blockquote class="pw-quote"><strong>九二：包蒙吉，纳妇吉，子克家。</strong><br>象曰：子克家，刚柔接也。</blockquote>
<p><strong>你现在在这个位置：来找你的人水平参差不齐，有的问得很蠢，你有点烦。</strong></p>
<p>「包」是包容。九二处在下卦正中间，「童蒙悉来归己」，<strong>来的人他一个都不往外推</strong>。</p>
<p>这个阶段的动作：<strong>把所有来问的人分三档，用三种方式答。</strong></p>
<p>能自己查到的，给一个方向让他去查；问到点子上了，认真答，多花点时间；反复来磨同一件事的，明确告诉他「这个上次说过了，你先去做，做完再说」。</p>
<p>「纳妇吉，子克家」讲的是另一点：<strong>能教人的人，往往也是能扛事的人。</strong>你在教的过程里，自己把这件事想清楚了——这才是当老师真正的收益。</p>
<p>孔子办私学，「有教无类」。<strong>他的学生里有贵族，有商人，也有坐过牢的公冶长。</strong></p>
<p><strong>什么情况可以挑人：</strong>如果你的精力只够带一个人，那就挑那个学完会去做的人，不要挑那个学完只会来问第二个问题的人。</p>
<h3 id="p-六三-见金夫-不有躬-别做伸手党">六三 · 见金夫，不有躬 —— 别做伸手党</h3>
<blockquote class="pw-quote"><strong>六三：勿用取女，见金夫，不有躬，无攸利。</strong><br>象曰：勿用取女，行不顺也。</blockquote>
<p><strong>你现在在这个位置：你看到一个人很厉害，很想靠上去，但你手里什么都没有。</strong></p>
<p>「见金夫」是看见那个有钱有本事的男人。孔颖达说，六三这一爻是「女求男之时」——<strong>古代讲的是女方不该自己先跑过去</strong>。放到今天，说的是另一回事：</p>
<p><strong>你要是只带着「我想跟你学」去，什么都不带，那就是伸手党。</strong></p>
<p>这个阶段的动作很简单：<strong>每次开口请教之前，先给对方一样东西。</strong></p>
<p>不用贵重。可以是「我把这三个月试错的过程整理成了一页纸，你看看哪几条是浪费」；可以是「你要的那个数据我上周跑出来了」；可以是「我认识一个人可能对你的事有用」。</p>
<p>鬼谷子的徒弟苏秦，第一次游说秦王失败，回家被嫂子看不起。<strong>他没有再去求人，是关起门来读了一年书，第二次带着完整的方案去见赵王。</strong></p>
<p><strong>什么情况可以空手去：</strong>如果对方是你上级，教你是他的职责，那就直接去问，不用绕。这不算伸手。</p>
<h3 id="p-六四-困蒙-吝-一个人闷着头想-最耗人">六四 · 困蒙，吝 —— 一个人闷着头想，最耗人</h3>
<blockquote class="pw-quote"><strong>六四：困蒙，吝。</strong><br>象曰：困蒙之吝，独远实也。</blockquote>
<p><strong>你现在在这个位置：你卡了很久，但你谁也没问。你觉得问别人显得自己不行。</strong></p>
<p>「困蒙」就是困在蒙昧里。「独远实也」——实指九二那个能教你的人，六四离他太远了。</p>
<p>这一爻是六爻里最省事的一爻，它没有转折，就一个结果：<strong>吝。</strong></p>
<p>这个阶段要做的事只有一件：<strong>这周之内，把你卡住的那件事讲给一个懂的人听。</strong></p>
<p>不是问「我该怎么办」，是讲「我现在是这样、这样、这样，你觉得我漏了什么」。你把情况讲清楚，对方一句话就能点开。</p>
<p>还有一层：<strong>别在网上乱找答案。</strong>搜到的十条里九条是错的，你还得花时间分辨，不如直接找人。</p>
<p>屈原被放逐之后，「行吟泽畔」，颜色憔悴。<strong>他跟渔父说了一通话，渔父劝他，他没听，最后怀石沉江。</strong>那一段里，没有人能真正接住他的话。</p>
<p><strong>什么情况可以自己扛：</strong>如果这件事涉及保密或者别人的隐私，那就自己扛，但至少要写下来。写下来的东西，比在脑子里转要清楚。</p>
<h3 id="p-六五-童蒙-吉-位置越高-越要装不懂">六五 · 童蒙，吉 —— 位置越高，越要装不懂</h3>
<blockquote class="pw-quote"><strong>六五：童蒙，吉。</strong><br>象曰：童蒙之吉，顺以巽也。</blockquote>
<p><strong>你现在在这个位置：你是负责人，但这块业务你确实不如你手下的人懂。</strong></p>
<p>六五是尊位，是君位。这一爻给的答案特别反直觉：<strong>吉。就因为你像个小孩。</strong></p>
<p>「顺以巽也」——顺是心里服，巽是表面上也让。孔颖达注得清楚：六五「委物以能」，把事情交给有本事的人，自己「不先不为」，不自作主张。</p>
<p>这个阶段的动作：<strong>在你的短板上，明确说一句「这块我不懂，听你的」。</strong></p>
<p>这句话说出来，你会得到两样东西。一是对方的真本事，二是对方的责任心——被信任过的人，做事是不一样的。</p>
<p>而且注意：这一爻给的吉，是<strong>六爻里唯一一个纯粹的好字</strong>。蒙卦绕了一圈，最后告诉你，承认不懂是最划算的。</p>
<p>汉高祖刘邦在洛阳宫宴上说，运筹帷幄他不如张良，镇国家抚百姓他不如萧何，连百万之军他不如韩信。<strong>他说完那三句，底下的人服了。</strong></p>
<p><strong>什么情况不能装不懂：</strong>如果这件事关系到方向、钱、或者人的去留，你必须自己拍。把不懂当挡箭牌，是躲事。</p>
<h3 id="p-上九-击蒙-利御寇-该敲打就敲打-但别越界">上九 · 击蒙，利御寇 —— 该敲打就敲打，但别越界</h3>
<blockquote class="pw-quote"><strong>上九：击蒙，不利为寇，利御寇。</strong><br>象曰：利用御寇，上下顺也。</blockquote>
<p><strong>你现在在这个位置：有人一而再地不听你的，你快要发火了。</strong></p>
<p>「击蒙」是敲打蒙昧的人。但这一爻马上给你划了线：<strong>「不利为寇，利御寇。」</strong></p>
<p>寇是闯进别人家里打人，御寇是守在门口挡人。区别在这里：<strong>你是去纠正他的错，还是去证明你比他强。</strong></p>
<p>这个阶段的动作：<strong>把你要敲打的那件事写下来，只写行为，不写人品。</strong></p>
<p>「你这个月三次没交报告」是行为。「你就是个不靠谱的人」是人品。前一句能改，后一句只能吵。</p>
<p>还有：<strong>敲打要一次到位，别碎碎念。</strong>孔颖达说这一爻「上下顺」——敲打得当，两边都舒服；敲打成瘾，两边都别扭。</p>
<p>《史记》里写过一段：刘邦当了皇帝，他爹还按老规矩来见他。有个家令劝太公，说天无二日，之后太公拿着扫帚在门口迎刘邦。<strong>刘邦知道后，重赏了那个家令。</strong>这一敲，敲的是规矩。</p>
<p><strong>什么情况别敲：</strong>如果这个人刚来，或者刚经历一场失败，先扶。这个时候敲下去，人就走光了。</p>
<h3 id="p-最后-蒙是泉水刚出山">最后：蒙是泉水刚出山</h3>
<p>蒙卦的大象说：「山下出泉，蒙。」山下的泉水刚冒出来，还没找到河道，只能四处乱淌。</p>
<p>它不讲天赋，讲的是<strong>引导</strong>。</p>
<p>蒙卦最后给你的一句话：</p>
<blockquote class="pw-quote">求教不是丢人的事，装了才丢人。你真正要练的，是把「我不懂」这三个字说得又顺又自然。</blockquote>
  `,
  xu: `
<p>有件事你等了很久。</p>
<p>面试说两周给消息，三周了。项目报上去，会开完了，没人回你。你在等一个人的一句话，那个人一直没空。</p>
<p>这种时候人最难熬的不是坏消息，是<strong>没有消息</strong>。</p>
<p>于是你就开始动作了：发一条消息去问，再发一条，托人去打听，最后干脆自己上门。</p>
<p>本来还有五成的事，被你问成了三成。</p>
<p>需卦讲的就是这件事。需是等待。上面是坎，是险；下面是乾，是刚健。<strong>你很有劲，但前面是坑，所以你得等。</strong></p>
<p>很多人以为等待是被动的。需卦不这么看。它给了六个位置——郊、沙、泥、血、酒食、穴。<strong>你站得离危险多远，决定你该怎么等。</strong></p>
<h3 id="p-初九-需于郊-离得远-就按老规矩来">初九 · 需于郊 —— 离得远，就按老规矩来</h3>
<blockquote class="pw-quote"><strong>初九：需于郊，利用恒，无咎。</strong><br>象曰：需于郊，不犯难行也。利用恒无咎，未失常也。</blockquote>
<p><strong>你现在在这个位置：这件事跟你有关，但暂时还烧不到你身上。你有点坐不住。</strong></p>
<p>「郊」是城外，离水最远的地方。这一爻的意思是：<strong>你离危险还远，这时候最好的动作是照旧。</strong></p>
<p>孔颖达说得很清楚：初九「去难既远」，「宜利保守其常」。他还补了一句：「犹不能见几速进，但得无咎而已」——你这个时候就算看不出门道，也不会出事，因为你还远。</p>
<p>具体怎么做：<strong>把你现在每天做的事，一件不减地做下去。</strong>上班、锻炼、陪家人、把手上的活干完。把生活节奏保住，就是这一爻的全部要求。</p>
<p>还有一条：<strong>别去打听。</strong>这个阶段你打听到的任何消息都不准，打听来只会让你睡不着。</p>
<p>汉文帝刚被拥立的时候，代国群臣意见不一，他派舅舅薄昭先去长安探路。<strong>薄昭回来之前，文帝在代国该干嘛干嘛，一点没动。</strong></p>
<p><strong>什么情况要主动：</strong>如果你发现这事其实已经烧到你身上了，只是消息还没传到你耳朵里——比如你的岗位已经在会上被讨论过了——那就不是郊了，往前挪。</p>
<h3 id="p-九二-需于沙-有人开始说闲话了">九二 · 需于沙 —— 有人开始说闲话了</h3>
<blockquote class="pw-quote"><strong>九二：需于沙，小有言，终吉。</strong><br>象曰：需于沙，衍在中也。虽小有言，以吉终也。</blockquote>
<p><strong>你现在在这个位置：离得近了，已经有人开始议论你。你听着不太舒服。</strong></p>
<p>「沙」是水边的沙地。离水近了，但还没湿鞋。「小有言」是有人说你几句。</p>
<p>这一爻的判断是「终吉」——<strong>只要你别接招，这事会过去。</strong></p>
<p>这个阶段的动作：<strong>把「辩解」这个选项从你的动作清单里划掉。</strong></p>
<p>有人说你太慢，有人说你不主动，有人说你是不是要走。你一句都不回。回一句，你就得回十句，而且每一句都在帮对方把话题续下去。</p>
<p>孔颖达说九二「近不逼难，远不后时」——离得不近不远，站位正好。<strong>这个位置最忌讳的就是被人一说就动，一动就站错了。</strong></p>
<p>韩信在汉中，从齐王改封楚王，又被贬成淮阴侯。史书上写他「日夜怨望，居常鞅鞅」。<strong>他心里憋着，嘴上也开始说了。</strong>他这一憋，命就没了。</p>
<p><strong>什么情况必须回：</strong>如果说闲话的人在影响你的实际资源——比如他跟你的客户讲、跟你的老板讲——那就要当面去讲清楚，只讲一次。</p>
<h3 id="p-九三-需于泥-致寇至-站错位置-灾是自己招来的">九三 · 需于泥，致寇至 —— 站错位置，灾是自己招来的</h3>
<blockquote class="pw-quote"><strong>九三：需于泥，致寇至。</strong><br>象曰：需于泥，灾在外也。自我致寇，敬慎不败也。</blockquote>
<p><strong>你现在在这个位置：你已经贴到事情边上了，随时可能被卷进去。</strong></p>
<p>「泥」是水边的烂泥。踩进去了，走不快也退不回。「致寇至」是<strong>把强盗招来了</strong>。</p>
<p>这一爻最狠的是这句：「自我致寇。」——<strong>强盗是你自己招来的，不是天上掉的。</strong></p>
<p>孔颖达注得更绝：「由我欲进而致寇来，己若敬慎，则不有祸败也。」你想往前挤，所以有人来抢；你要是谨慎，就不会输。</p>
<p>这个阶段的动作：<strong>退半步，把姿态放低。</strong></p>
<p>具体到能做的事：这段时间不发朋友圈，不在会上抢话，不主动去那个核心的群里刷存在感。<strong>你越显得不着急，越没人拿你当对手。</strong></p>
<p>再补一条硬的：<strong>把你要争的那个东西，换成对方不要的东西。</strong>同一块蛋糕才有得抢，换一块就没了对手。</p>
<p><strong>什么情况已经躲不开：</strong>如果对手已经把你当目标了，退也没用，那就提前把证据、把关系、把退路备齐，别光顾着客气。</p>
<h3 id="p-六四-需于血-出自穴-打不过就先让">六四 · 需于血，出自穴 —— 打不过就先让</h3>
<blockquote class="pw-quote"><strong>六四：需于血，出自穴。</strong><br>象曰：需于血，顺以听也。</blockquote>
<p><strong>你现在在这个位置：冲突已经发生了，你有损失。硬碰下去你占不到便宜。</strong></p>
<p>「需于血」是在血里等——已经有伤。「出自穴」是从洞里出来。穴是阴暗的藏身处，出来意味着<strong>你放弃藏，选择正面面对，但姿态是低的</strong>。</p>
<p>象传给的三个字是全卦最省力的解法：<strong>顺以听。</strong></p>
<p>不是认输，是<strong>先把对方要的那部分让出去，换自己全身而退</strong>。</p>
<p>这个阶段的动作：<strong>列一张单子，写明这次你最多能接受让掉什么。</strong>让到这个数就签字，不要再谈。谈得越久，你让得越多。</p>
<p>刘邦去鸿门赴宴前，项伯来通风报信。<strong>刘邦第二天去了，见面就说自己和项羽是兄弟，绝没有二心，还把守住函谷关的事推给了别人。</strong>他让了，所以他活着出来了。</p>
<p><strong>什么情况不能让：</strong>如果对方要的是你的底线——你的岗位、你的团队、你的名声——那就不是让的时候。该走流程走流程，该找上级找上级。</p>
<h3 id="p-九五-需于酒食-等得最舒服的那一档">九五 · 需于酒食 —— 等得最舒服的那一档</h3>
<blockquote class="pw-quote"><strong>九五：需于酒食，贞吉。</strong><br>象曰：酒食贞吉，以中正也。</blockquote>
<p><strong>你现在在这个位置：事情卡住了，但你不慌。你手上的东西够你撑一阵。</strong></p>
<p>「需于酒食」——在酒饭旁边等着。这一爻是整卦里最从容的一爻。</p>
<p>孔颖达注：「五既为需之主，已得天位，无所复需。」——他已经坐到该坐的位置上了，没什么可再等的。</p>
<p>这一爻给的动作不是「忍」，是<strong>把等待的时间变成你的储备</strong>。</p>
<p>具体来说：去做那件你一直想做但没空做的事。把团队梳理一遍，把资料整理一遍，把身体养一养。别人在焦虑的时候你在补，等风向一变，你的速度就不一样。</p>
<p>还有一层：<strong>该吃吃，该喝喝，该见人见人。</strong>你越是显得从容，外面的人越觉得你心里有底。这不是装，这是位置带来的。</p>
<p>曹操在官渡跟袁绍对峙，粮草紧张。他给荀彧写信想退兵，荀彧回信让他坚守。<strong>曹操就守着，等到许攸来投，一把火烧了乌巢。</strong></p>
<p><strong>什么情况别端着：</strong>如果你账上只剩一个月，那不是九五，是九三。别学人家喝酒，先去找钱。</p>
<h3 id="p-上六-入于穴-有不速之客三人来-意外来的人-好生">上六 · 入于穴，有不速之客三人来 —— 意外来的人，好生招待</h3>
<blockquote class="pw-quote"><strong>上六：入于穴，有不速之客三人来，敬之终吉。</strong><br>象曰：不速之客来，敬之终吉。虽不当位，未大失也。</blockquote>
<p><strong>你现在在这个位置：事情快过去了，但来了几个你没请的人。你不知道他们是敌是友。</strong></p>
<p>「入于穴」是躲进洞里。「不速之客」是不请自来的人。孔颖达说这三位是下面的初九、九二、九三——<strong>三股力量自己找上门了</strong>。</p>
<p>这一爻给的答案就一个字：<strong>敬。</strong></p>
<p>「以一阴而为三阳之主，不可怠慢」——你是最弱的那个，来的人个个比你强。这个时候你唯一能做的就是客气。</p>
<p>但注意这个「敬」不是讨好。它的意思是：<strong>给对方面子，但不承诺任何实质的东西。</strong></p>
<p>怎么操作：见面要有，茶要倒，话要听完，点头要有。但决定一律往后推——「这事我得再想想」「等下周我给你回话」。</p>
<p>这一爻判断的结果是「未大失」。<strong>不是赚了，是没亏。</strong>这就够了。</p>
<p>汉初诛诸吕之后，代王刘恒被迎立。他到了长安，群臣劝进，他连着推让了五次。<strong>他没有一口答应，也没有翻脸，就这么客客气气地走完了流程。</strong></p>
<p><strong>什么情况不用这么客气：</strong>如果你清楚这几个人是来抢的，那就别摆茶，直接亮底牌，把边界讲明。礼数是给讲礼数的人准备的。</p>
<h3 id="p-最后-等不是空着">最后：等不是空着</h3>
<p>需卦的大象讲得特别妙：「云上于天，需；君子以饮食宴乐。」</p>
<p>天上全是云，雨还没下。这时候君子干什么？吃饭，喝酒，过日子。</p>
<p><strong>等不是停下来，是不空转。</strong></p>
<p>需卦最后给你的一句话：</p>
<blockquote class="pw-quote">该等的时候等，是一件事；等的时候还在长本事，是另一件事。前一件叫沉得住气，后一件叫赢得起。</blockquote>
  `,
  song: `
<p>你正在跟一个人较劲。</p>
<p>可能是前合伙人，可能是房东，可能是你上一个东家。理在你这边，证据你也有。律师说能打，朋友说别怂。</p>
<p>你晚上躺下的时候会想一遍赢了之后的样子。第二天醒来，你又想一遍打这场要花多少时间。</p>
<p>讼卦讲的就是这件事。上面是天，下面是水，天往西转，水往东流，<strong>两个东西朝相反方向走</strong>——这就是讼。</p>
<p>卦辞第一句就给了结论：<strong>「中吉，终凶。」</strong> 争到一半停手，吉。争到底，凶。</p>
<p>还有一句更扎心的，在最后一爻：「或锡之鞶带，终朝三褫之。」——你赢来的那条腰带，一天之内被人扒了三次。</p>
<p>讼卦六个爻，讲的是冲突里的六个位置。<strong>从「该不该开始」到「赢了也保不住」。</strong></p>
<h3 id="p-初六-不永所事-别当那个先开口的">初六 · 不永所事 —— 别当那个先开口的</h3>
<blockquote class="pw-quote"><strong>初六：不永所事，小有言，终吉。</strong><br>象曰：不永所事，讼不可长也。虽小有言，其辩明也。</blockquote>
<p><strong>你现在在这个位置：有人占了你的便宜，你还没吭声。你在想要不要开这个头。</strong></p>
<p>「不永所事」——不要把这件争讼的事拖长。孔颖达注：初六是「不为讼先」，是别人先来犯他，他才应。</p>
<p>这一爻给的动作很明确：<strong>先别挑头，但要把话说清楚一次。</strong></p>
<p>说清楚就一句：你做了什么，我认为哪里不对，我希望怎么处理。说完就停。</p>
<p>然后象传给了你一个好消息：<strong>「其辩明也。」</strong> 你把理讲明白，这件事本身就已经清楚了。很多时候，对方听完就不吭声了。</p>
<p>同时记住：<strong>一旦你先开口升级，性质就变了。</strong>本来是他理亏，变成两个人都理亏。</p>
<p>蔺相如在渑池之会后位在廉颇之上，廉颇放话要羞辱他。<strong>蔺相如每次上朝都称病，路上远远看见廉颇的车就掉头避开。</strong>他从头到尾没跟廉颇争过一次。</p>
<p><strong>什么情况必须马上打：</strong>如果这件事有时效——比如诉讼期、比如对账期限——那就别等，先按程序把时间点锁住，别让权利过期。</p>
<h3 id="p-九二-不克讼-归而逋-知道自己赢不了就赶紧退">九二 · 不克讼，归而逋 —— 知道自己赢不了就赶紧退</h3>
<blockquote class="pw-quote"><strong>九二：不克讼，归而逋，其邑人三百户，无眚。</strong><br>象曰：不克讼，归逋窜也。自下讼上，患至掇也。</blockquote>
<p><strong>你现在在这个位置：你要告的那个人，比你强。你心里明白这场大概赢不了。</strong></p>
<p>「不克讼」是打不赢。「归而逋」是回来躲起来。「其邑人三百户」——三百户是很小的一个地方，郑玄说这是「小国下大夫之制」，意思是<strong>你得把自己的摊子缩到这么小，人家才懒得再动你</strong>。</p>
<p>象传的话很重：「自下讼上，患至掇也。」——你以下告上，灾祸像用手捡东西一样，一伸手就来。</p>
<p>这一爻的动作：<strong>主动收缩。</strong></p>
<p>把你的诉求降到一个对方能接受的最低数，把事结了。别去算「我本来该拿多少」，只算「我现在能保住多少」。</p>
<p>还有一条更实操的：<strong>这段时间别在公开场合评价对方。</strong>你在群里说一句，对方就多一条证据。</p>
<p>周勃被免相回到封地，河东守尉来巡行，他每次都披甲相见，家里人还拿着兵器。<strong>有人告他谋反，他被下狱。</strong>他在狱里被狱吏欺负，出狱后说了一句「吾尝将百万军，然安知狱吏之贵乎」。</p>
<p><strong>什么情况可以接着打：</strong>如果对方其实没有你想象的那么强，或者你手上有能一击定胜负的东西，那就打。退让是给打不赢的人准备的。</p>
<h3 id="p-六三-食旧德-贞厉-吃老本-别争新">六三 · 食旧德，贞厉 —— 吃老本，别争新</h3>
<blockquote class="pw-quote"><strong>六三：食旧德，贞厉，终吉。或从王事，无成。</strong><br>象曰：食旧德，从上吉也。</blockquote>
<p><strong>你现在在这个位置：你没卷进冲突里，但你两边都得罪不起。你只想保住现在有的。</strong></p>
<p>「食旧德」是吃从前的老本——你原有的位置、原有的收入、原有的关系。</p>
<p>「贞厉」——守正是对的，但处境危险。孔颖达说六三「处两刚之间」，夹在中间，谁都不能得罪。</p>
<p>这个阶段的动作：<strong>什么都不新增，什么都别去争。</strong></p>
<p>不去接新的、有争议的活；不去要那笔本来就不明确归属的钱；不在会上替任何一方说话。<strong>你的目标只有一个：让这件事过去的时候，你还站在原地。</strong></p>
<p>「或从王事，无成」——这条你在坤卦里见过。你参与了，但功劳不是你的。这个位置上，功不功劳不重要，站住了才重要。</p>
<p>萧何在刘邦定天下后，主动把刘邦加封给他的封地退了一部分，还拿出家财充军。<strong>他没有去跟谁比功劳，他只是把自己钉在「管后勤」这个位置上。</strong></p>
<p><strong>什么情况必须站队：</strong>如果双方已经逼你表态，那中立就不成立了。这时候选那个能让你继续干活的一方，而不是看起来会赢的一方。</p>
<h3 id="p-九四-复自命-渝安贞-发现错了就掉头">九四 · 复自命，渝安贞 —— 发现错了就掉头</h3>
<blockquote class="pw-quote"><strong>九四：不克讼，复自命，渝安贞，吉。</strong><br>象曰：复自命，渝安贞，吉，不失也。</blockquote>
<p><strong>你现在在这个位置：这场争端是你挑起来的，现在你发现打不赢，或者不值得。</strong></p>
<p>九四跟九二不一样。九二是被人告，九四是「非理陵犯于初」——<strong>是九四先不讲理去欺负别人</strong>。</p>
<p>所以这一爻的关键字是「渝」——变。<strong>你自己改主意，自己撤。</strong></p>
<p>「复自命」是回到你本来的道理上。「渝安贞」是改掉之前跟你争的那个人定的那套说法，安下心来守正。</p>
<p>孔颖达引了一句《论语》：「为仁由己。」——<strong>要不要讲理，是你自己的事，不用等别人给你台阶。</strong></p>
<p>这个阶段的动作：<strong>找一个中间人，把「我不打了」这句话递过去。</strong></p>
<p>不要自己直接去说，也不要说「我让着你」。就说「这件事我不想再耗了，之前我有些做法不妥」。给对方留一个面子，这件事就结了。</p>
<p>廉颇知道蔺相如避着他是因为「先国家之急而后私仇」，就脱了上衣、背着荆条，到蔺相如门口请罪。<strong>是他先挑起的不满，也是他自己掉的头。</strong></p>
<p><strong>什么情况别掉头：</strong>如果对方已经把你的退让当成了软弱，加码来压，那你现在掉头只会更惨。要么不掉，要么一次到位。</p>
<h3 id="p-九五-讼-元吉-最会处理争端的人-不靠判">九五 · 讼，元吉 —— 最会处理争端的人，不靠判</h3>
<blockquote class="pw-quote"><strong>九五：讼，元吉。</strong><br>象曰：讼元吉，以中正也。</blockquote>
<p><strong>你现在在这个位置：两个人（或两拨人）闹到你这里来了，要你评理。</strong></p>
<p>九五是在尊位上的那一个。这一爻整卦最短，就四个字加一个「元吉」。</p>
<p>孔颖达注：九五「处得尊位，中而且正，以断狱讼」。<strong>他断案不靠偏袒，靠的是位置正、心思中。</strong></p>
<p>这个阶段的动作三条：</p>
<p><strong>第一，先听两边各自把话讲完，中间别插话。</strong>急着下判断，是最容易出错的。</p>
<p><strong>第二，把「谁对」这个问题换成「接下来怎么办」。</strong>争对错没有尽头，定方案有。</p>
<p><strong>第三，你的判断要能公开讲出来。</strong>凡是你不好意思公开讲的理由，都不能拿来当判据。</p>
<p>司马光和王安石在神宗面前争新法，争了很多次。神宗最后两边都没全听，用了折中的办法。<strong>他作为裁决者，没有让任何一方全赢，也没有让任何一方全输。</strong></p>
<p><strong>什么情况别和稀泥：</strong>如果一方明显违规、明显越线，那就按规矩办，别为了平衡而放过。你放一次，规矩就没了。</p>
<h3 id="p-上九-终朝三褫之-赢来的东西-最不牢">上九 · 终朝三褫之 —— 赢来的东西，最不牢</h3>
<blockquote class="pw-quote"><strong>上九：或锡之鞶带，终朝三褫之。</strong><br>象曰：以讼受服，亦不足敬也。</blockquote>
<p><strong>你现在在这个位置：你赢了。但赢了之后，你发现事情不太对。</strong></p>
<p>「鞶带」是古代的大带，是身份的象征。「终朝三褫之」——一个早上被扒下来三回。</p>
<p>象传只给了六个字：<strong>「以讼受服，亦不足敬也。」</strong> 靠打官司赢来的东西，别人不会敬你。</p>
<p>这一爻不是让你后悔，是让你提前想明白两件事。</p>
<p><strong>一是这种东西的性质。</strong>靠斗争得来的位置、资源、关系，<strong>随时可以被下一场斗争拿走</strong>。它不是你的资产，是你的战利品。</p>
<p><strong>二是这场胜利的账。</strong>把成本算出来：律师费、时间、你在这段时间里没做成的事、还有那些因为这场官司不敢跟你合作的人。</p>
<p>吴起在楚国变法，得罪了所有旧贵族。楚悼王一死，贵族们在葬礼上射杀他。<strong>他赢了一辈子，最后死在乱箭下，连尸体都被车裂。</strong></p>
<p><strong>什么情况该继续争：</strong>如果对方要的是原则问题——比如他做得不对但大家都当没看见——那你争的不只是自己的东西，这一场该赢。</p>
<h3 id="p-最后-最好的官司是不打的那一场">最后：最好的官司是不打的那一场</h3>
<p>讼卦的大象说：「天与水违行，讼；君子以作事谋始。」</p>
<p><strong>真正的高手不在事后争，在事前防。</strong>合作之前把账目、权责、退出条件写清楚，比事后请十个律师有用。</p>
<p>讼卦最后给你的一句话：</p>
<blockquote class="pw-quote">能赢就去赢，但要先问自己一句：赢来的这条腰带，你打算系多久。</blockquote>
  `,
  shi: `
<p>你手上现在有一支队伍。</p>
<p>可能是十几个人，可能是三个。你要他们跟你去做一件事，这件事有点难，也有点风险。</p>
<p>你讲过愿景了，也画过饼了。你发现一个问题：<strong>他们点头，但不动。</strong></p>
<p>师卦讲的就是这个。师是众人，是用兵。上面是地，下面是水——「地中有水」，兵藏在民里，看着平静，底下全是力量。</p>
<p>卦辞只有六个字最要紧：<strong>「贞，丈人吉，无咎。」</strong></p>
<p>贞是名分要正。丈人是<strong>你得是那种让人不敢随便的人</strong>。孔颖达注得很直接：如果带队的不是这种人，「无不畏惧，不能齐众，必有咎害」。</p>
<p>师卦六个爻，是带队伍的六个阶段。从「出发前定规矩」到「打完仗怎么分」。</p>
<h3 id="p-初六-师出以律-出门之前先立规矩">初六 · 师出以律 —— 出门之前先立规矩</h3>
<blockquote class="pw-quote"><strong>初六：师出以律，否臧凶。</strong><br>象曰：师出以律，失律凶也。</blockquote>
<p><strong>你现在在这个位置：项目要开动了，你还没把规矩定下来。你想先跑起来再补。</strong></p>
<p>「律」是法度。这一爻给的判词非常绝对：<strong>「否臧凶。」</strong>——打输了凶，打赢了也凶。</p>
<p>孔颖达把这句话讲透了：「失律而臧，何异于否？」没有纪律而侥幸成功，跟失败有什么区别？他还说了一句「失令有功，法所不赦」——<strong>违反规矩拿到的功劳，军法不能赦。</strong></p>
<p>这个阶段要做的具体事：<strong>开工前，把三件事写成一页纸，发给每个人。</strong></p>
<p>第一，这支队伍要做成什么，什么算做成。第二，谁负责什么，出了问题找谁。第三，什么行为是绝对不能有的——多半是数据造假、私下承诺、越级汇报这几样。</p>
<p>写完发出去，让每个人回一句「收到」。</p>
<p>周亚夫驻军细柳，汉文帝去劳军，前两队军营都直接放行，到了细柳营，守门军士说「军中闻将军令，不闻天子之诏」。<strong>文帝只能按规矩持节通报，才进得去。</strong></p>
<p><strong>什么情况可以不上规矩：</strong>如果是三天就能结束的急活，先干，干完再复盘。但要知道这是例外，不是常态。</p>
<h3 id="p-九二-在师中-吉无咎-站在队伍中间的-才是主心骨">九二 · 在师中，吉无咎 —— 站在队伍中间的，才是主心骨</h3>
<blockquote class="pw-quote"><strong>九二：在师中，吉无咎，王三锡命。</strong><br>象曰：在师中吉，承天宠也。王三锡命，怀万邦也。</blockquote>
<p><strong>你现在在这个位置：你是那个真正带队的人，但你不是名义上的头。</strong></p>
<p>「在师中」——在队伍中间。九二是阳爻居下卦之中，是这一卦真正的将。上面的六五是君，两者相应。</p>
<p>这个位置的动作是：<strong>把注意力放在队伍里，不要放在跟上面打交道上。</strong></p>
<p>具体说：你得知道每个人现在卡在哪、谁跟谁不对付、谁最近状态不好。这些东西只有你贴着队伍才看得出来。</p>
<p>「王三锡命」——君王三次下命令嘉奖。孔颖达引《曲礼》解释三赐：一命受爵，再命受服，三命受车马。<strong>赏赐一次次加码，是战功一次次被承认的信号。</strong></p>
<p>同时这也是提醒：<strong>你的位置来自上面的信任，而上面的信任来自你带的队伍能打。</strong>顺序不能倒。</p>
<p>韩信被刘邦拜为大将，登坛之后第一件事是跟刘邦分析项羽的为人，讲「还定三秦」的路线。<strong>他没有先要权，他先给方案。</strong></p>
<p><strong>什么情况要往上走：</strong>如果你的队伍打得很好，但上面一直不知道，那你得去汇报。功劳不汇报，就会被别人汇报。</p>
<h3 id="p-六三-师或舆尸-用错人-是要抬棺材回来的">六三 · 师或舆尸 —— 用错人，是要抬棺材回来的</h3>
<blockquote class="pw-quote"><strong>六三：师或舆尸，凶。</strong><br>象曰：师或舆尸，大无功也。</blockquote>
<p><strong>你现在在这个位置：你把一件重要的事交出去了，但你自己心里不太踏实。</strong></p>
<p>「舆尸」是用车拉着尸体回来。这一爻没有转折、没有例外，就一个「凶」。</p>
<p>孔颖达注六三为什么会这样：<strong>「以阴处阳，以柔乘刚，进无所应，退无所守。」</strong>——位置不对，能力不够，上面没人接应，下面也没有根基。这样去带兵，就是这个结果。</p>
<p>这一爻要你做的判断是：<strong>你现在手上这件要紧的事，交出去的那个人，是能扛的还是凑数的。</strong></p>
<p>判断标准只有一条：<strong>他有没有独立完成过一件同量级的事。</strong>不是他态度好不好，不是他跟你的关系近不近。是「做成过没有」。</p>
<p>如果没有，那这件事要么你亲自盯，要么换人。</p>
<p>赵括从小读兵书，跟他爹赵奢辩论，赵奢说不过他。蔺相如劝赵王别用赵括，说他「徒能读其父书传，不知合变」。<strong>赵王用了，长平之战四十多万赵军没了。</strong></p>
<p><strong>什么情况可以给机会：</strong>如果这件事的失败成本可控，而且他有老手在旁边盯着，那就让他上。不给第一次机会，永远没有能扛事的人。</p>
<h3 id="p-六四-师左次-该撤就撤-不丢人">六四 · 师左次 —— 该撤就撤，不丢人</h3>
<blockquote class="pw-quote"><strong>六四：师左次，无咎。</strong><br>象曰：左次无咎，未失常也。</blockquote>
<p><strong>你现在在这个位置：事情推不动了。你想再撑一撑，但你自己也觉得撑不出结果。</strong></p>
<p>「左次」是退到左边驻扎。古代兵法讲「右背山陵，前左水泽」，左是退守的位置。孔颖达注：六四「得位而无应，无应不可以行，得位则可以处」。</p>
<p><strong>没援兵就不能往前打，但你还能守住。那就守。</strong></p>
<p>这一爻的判词是六爻里少有的干净：「无咎。」——没有过错，也没有功劳。<strong>这就是退守的标准成绩。</strong></p>
<p>这个阶段的动作：<strong>把「继续投」和「停下来」成本算清楚，写成两栏。</strong></p>
<p>继续投：还要多少人、多少钱、多长时间。停下来：损失多少、还能保住什么、人往哪去。写完你自己就清楚了。</p>
<p>还有一条：<strong>撤退要发通知，要讲明白。</strong>别让人从别人嘴里知道你撤了。</p>
<p>刘邦在彭城大败，退到荥阳，靠着敖仓的粮和成皋的险守着。<strong>他守了很久，打不过就不打，等韩信在北方把局面打开。</strong></p>
<p><strong>什么情况不能守：</strong>如果你守的这个地方本身就是消耗战——每天在烧钱，而且对手耗得起你耗不起——那守就是慢性死亡。这种情况要退到位，退到能活的线后面。</p>
<h3 id="p-六五-长子帅师-弟子舆尸-该用谁-别看关系">六五 · 长子帅师，弟子舆尸 —— 该用谁，别看关系</h3>
<blockquote class="pw-quote"><strong>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。</strong><br>象曰：长子帅师，以中行也。弟子舆尸，使不当也。</blockquote>
<p><strong>你现在在这个位置：你是拍板的人。有两个人在争这个位置。</strong></p>
<p>「田有禽」是田里有禽兽来吃庄稼。「利执言」——你有理由去处理它，出师有名。</p>
<p>然后是这一爻真正的重点：<strong>「长子帅师，弟子舆尸。」</strong> 用长子带兵，行；用弟子带兵，抬尸回来。</p>
<p>孔颖达注得很清楚：「长子谓九二，德长于人。弟子谓六三，德劣于物。」<strong>长子和弟子的区别不是辈分，是德与能。</strong></p>
<p>这一爻的动作：<strong>把候选人的名字列出来，每个人后面只写一行——他做成过的最难的一件事。</strong>其他的都不写。</p>
<p>你会发现有些人那一行是空的。空的那一行，就是这一爻说的「弟子」。</p>
<p>李渊起兵的时候，两个儿子都上了。李世民带兵打的是硬仗，李建成坐镇后方。李渊打天下的时候一直在用李世民。<strong>但到了立太子的时候，他选了李建成。</strong>玄武门那一天，两个都完了。</p>
<p><strong>什么情况可以用资历浅的：</strong>如果这件事本身不大，或者你打算自己兜底，那就用年轻人。用错人的成本，是当老大的必须交的学费。</p>
<h3 id="p-上六-大君有命-开国承家-打完仗-最难的是分">上六 · 大君有命，开国承家 —— 打完仗，最难的是分</h3>
<blockquote class="pw-quote"><strong>上六：大君有命，开国承家，小人勿用。</strong><br>象曰：大君有命，以正功也。小人勿用，必乱邦也。</blockquote>
<p><strong>你现在在这个位置：事情做成了，到了分果子的时候。</strong></p>
<p>「开国承家」——功劳大的封诸侯，功劳小的做卿大夫。这一爻讲的是分配。</p>
<p>但它的落脚点在最后四个字：<strong>「小人勿用。」</strong></p>
<p>象传补了一句：「小人勿用，必乱邦也。」——用了这种人，必乱。</p>
<p>这一爻要你分开两件事：<strong>赏和有。</strong></p>
<p>赏是给人分钱分名，这个可以按功劳给，哪怕那个人你并不喜欢。有是给人位置，这个要按品性和能力给。</p>
<p><strong>很多团队散了，就是在这一步混了。</strong>打下江山的人里有能打的，也有会钻的。你把会钻的放到位置上，能打的第二天就走。</p>
<p>还有一个细节：<strong>分配要趁热。</strong>仗打完两个月还不分，人心就散了。这时候大家想的不是分多少，是「老板是不是想赖」。</p>
<p>刘邦定天下之后，封萧何为酂侯，食邑最多。功臣们不服，说他们身经百战，萧何只是拿着笔管发议论。<strong>刘邦说，打猎的时候追兔子的是狗，发号令的是人。</strong>他把话说在明面上，反而没人再闹。</p>
<p><strong>什么情况别急着分：</strong>如果局面还没稳，仗可能还要打第二场，那就先给承诺、给小的，把大的留到真安定之后。这时候分早了，等于把弹药先花光。</p>
<h3 id="p-最后-师出有名-也要师出有律">最后：师出有名，也要师出有律</h3>
<p>师卦的大象说：「地中有水，师；君子以容民畜众。」</p>
<p><strong>水藏在地里，看不见，但它一直在。</strong>带队伍最难的部分不在喊口号，在你平时怎么对待这些人。</p>
<p>师卦最后给你的一句话：</p>
<blockquote class="pw-quote">让人跟你走，靠的不是你有多大的目标，是你定下的规矩，和你自己先守不守。</blockquote>
  `,
  bi: `
<p>有一件事你可能经历过。</p>
<p>一个圈子刚起来的时候，谁都不看好，你也没上心。过了两年，里面的人互相都认识了，机会开始在里面流转。</p>
<p>你这时候想进去。你托了人，见了面，聊得也不错。但你就是感觉<strong>进不去</strong>——不是人家不礼貌，是那个位置已经满了。</p>
<p>比卦讲的就是这件事。比是亲附、是站队、是靠拢。上面是水，下面是地——水在地上流，哪儿低往哪儿去，<strong>水跟地是没有缝的</strong>。</p>
<p>卦辞最后三个字是全卦的刀：<strong>「后夫凶。」</strong> 来得晚的那个，凶。</p>
<p>孔颖达注得更狠：「亲比贵速，若及早而来，人皆亲己，故在先者吉。若在而后至者，人或疏己。」最后一句是：「亲成则诛。」——<strong>关系都定完了你才来，你就是多出来的那个。</strong></p>
<p>比卦六个爻，是亲附的六个时机。从「越早越好」到「错过了就别追」。</p>
<h3 id="p-初六-有孚比之-有孚盈缶-空着手去-带着诚去">初六 · 有孚比之，有孚盈缶 —— 空着手去，带着诚去</h3>
<blockquote class="pw-quote"><strong>初六：有孚比之，无咎。有孚盈缶，终来有他吉。</strong><br>象曰：比之初六，有他吉也。</blockquote>
<p><strong>你现在在这个位置：你想跟一个人、一个圈子建立关系，但你手里没什么能拿得出手的。</strong></p>
<p>「孚」是诚信。「盈缶」是把一个瓦罐装满——缶是最朴素的器皿，装的是最实在的东西。</p>
<p>孔颖达注初六：「应不在一，心无私吝，莫不比之。」——<strong>他没有指定要巴结谁，所以谁都能跟他处。</strong></p>
<p>这个阶段的动作：<strong>别挑人，先对所有人一样。</strong></p>
<p>具体做：你手上那些资源、信息、机会，能分就分出去，不分亲疏。帮过你的人，你记住；没帮过你的人，你也不冷脸。</p>
<p><strong>你越不挑，越容易进圈。</strong>因为挑人是强者的特权，初六还没到那个位置。</p>
<p>「终来有他吉」——最后会有意外的人来帮你。这个「他」字很妙：<strong>来的不是你等的那个，是别的人。</strong></p>
<p>萧何月下追韩信之前，韩信在汉营里只是个管粮的小官，跟谁都不熟。<strong>萧何注意他，是因为跟他聊过几次，发现这人懂的东西别人不懂。</strong>不是韩信去巴结萧何。</p>
<p><strong>什么情况要有选择：</strong>如果你已经明确知道自己要什么，时间也紧，那就直接找那个关键人，不用广撒网。</p>
<h3 id="p-六二-比之自内-认准了就别看别处">六二 · 比之自内 —— 认准了就别看别处</h3>
<blockquote class="pw-quote"><strong>六二：比之自内，贞吉。</strong><br>象曰：比之自内，不自失也。</blockquote>
<p><strong>你现在在这个位置：你已经跟了某个人，但外面有人来挖你，条件更好。</strong></p>
<p>「自内」是从内部生出来的亲附——<strong>不是被条件吸引，是心里认了。</strong></p>
<p>象传的三个字很要紧：<strong>「不自失也。」</strong>——你没有丢掉自己。</p>
<p>这个阶段的动作：<strong>把「为什么跟他」写下来，写在你能看见的地方。</strong></p>
<p>不是写他的好处，是写你自己认的那个东西。是这个人做事的方式，是他答应你的事做到了，还是他在你最难的时候没走。</p>
<p>以后每一次动摇，你就看这行字。</p>
<p>同时：<strong>外面的机会照样可以听，但听完就放下。</strong>听是知情，动心就是不自失了。</p>
<p>诸葛亮跟了刘备之后，曹操、孙权都来招过。他一次没动。<strong>他不是没得选，他是从隆中那一次就选定了。</strong></p>
<p><strong>什么情况该换：</strong>如果你跟的这个人变了，变成他当初答应你不做的那种人，那就不是「不自失」，是「抱着沉船」。这种情况该走。</p>
<h3 id="p-六三-比之匪人-跟错人-比没人跟更惨">六三 · 比之匪人 —— 跟错人，比没人跟更惨</h3>
<blockquote class="pw-quote"><strong>六三：比之匪人。</strong><br>象曰：比之匪人，不亦伤乎。</blockquote>
<p><strong>你现在在这个位置：你已经在某个圈子里了，但你自己心里清楚，这里面的人不太行。</strong></p>
<p>「匪人」就是不该跟的人。这一爻没有转折，没有例外，象传只回了一句反问：<strong>「不亦伤乎。」</strong>——这不是很伤吗。</p>
<p>孔颖达注得清楚：六三「四自外比，二为五贞，近不相得，远又无应」——<strong>想跟的人不理他，能跟的人不合适，所比皆非其亲。</strong></p>
<p>这一爻要你算一笔账：<strong>你在这个圈子里得到了什么，付出了什么。</strong></p>
<p>得到的是不是只有「有个圈子」这个感觉？付出的是不是你的时间、你的名声，还有你本来可以跟更好的人相处的时间？</p>
<p>如果是，那就要动。<strong>但动的方法不是翻脸退出，是慢慢淡出。</strong>少去，少说，少掺和。这种人多的圈子，你淡出没人会追。</p>
<p>范雎在魏国跟着须贾出使齐国，须贾怀疑他通齐，向魏相魏齐告发。<strong>魏齐把他打得肋骨折了，扔在厕所里让人往他身上撒尿。</strong>范雎装死才逃出去，后来到秦国做了相。</p>
<p><strong>什么情况可以先待着：</strong>如果你现在完全没别的路子，这个圈子是你唯一的收入来源，那就先待着，但心里要清楚这是过渡，别把它当成家。</p>
<h3 id="p-六四-外比之-往上靠-别不好意思">六四 · 外比之 —— 往上靠，别不好意思</h3>
<blockquote class="pw-quote"><strong>六四：外比之，贞吉。</strong><br>象曰：外比于贤，以从上也。</blockquote>
<p><strong>你现在在这个位置：你身边这个圈子里，最有本事的那个人在上面。你想跟他，但你觉得唐突。</strong></p>
<p>「外比之」是往外、往上跟人。「外比于贤，以从上也」——<strong>跟贤的人，往上的方向。</strong></p>
<p>孔颖达注：六四「上比于五，欲外比也。居得其位，比不失贤，所以贞吉」。</p>
<p>这个阶段的动作：<strong>主动去汇报、主动去请教、主动去承担他手上的麻烦事。</strong></p>
<p>不是去送礼，是去干活。<strong>靠拢一个人最有效的方式，是让他发现你能解决他的问题。</strong></p>
<p>具体到一句能照做的话：「您手上那件事，我可以接一部分。」——这句话比十顿饭有用。</p>
<p>李斯从楚国到秦国，先做吕不韦的门客，后来找机会向秦王嬴政上书说统一六国的事。<strong>他一步一步往上靠，靠的每一次都是给方案。</strong></p>
<p><strong>什么情况不要往上贴：</strong>如果你的直属上级就是那个「贤」，你越级去跟上面的人走近，先把直属得罪了。除非你的直属本身就有问题。</p>
<h3 id="p-九五-王用三驱-失前禽-最高明的团结-是不强求">九五 · 王用三驱，失前禽 —— 最高明的团结，是不强求</h3>
<blockquote class="pw-quote"><strong>九五：显比，王用三驱，失前禽，邑人不诫，吉。</strong><br>象曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。</blockquote>
<p><strong>你现在在这个位置：你是一群人的核心，有人想走，你在纠结要不要留。</strong></p>
<p>「显比」是光明正大地亲附。「王用三驱，失前禽」是古代打猎的规矩：只围三面，留一面。<strong>背对着你跑的那只，放它走。</strong></p>
<p>孔颖达注：「禽逆来向己者，则舍之而不害；禽顺去背己而走者，则射而取之。」<strong>向你跑来的放掉，背你走的才射。</strong></p>
<p>听上去反了，其实是这个意思：<strong>真心要来的你不用追，去意已决的你追也没用。</strong></p>
<p>这个阶段的动作三条：</p>
<p><strong>第一，把「去留自愿」这四个字挂在明处。</strong>谁是奔着你来的，谁是被条件绑着的，一眼就分出来了。</p>
<p><strong>第二，走的人好好送。</strong>不要卡他的手续，不要说他的坏话。<strong>他出去以后，是你最好的口碑。</strong></p>
<p><strong>第三，别为了留住一个人而破例。</strong>你给这个人破的例，剩下的人都会来要。</p>
<p>刘备取益州之后，对刘璋的旧部一个不杀，愿意留的留，愿意走的走。<strong>这不是宽厚，是他知道强留的人不会给他卖命。</strong></p>
<p><strong>什么情况要强留：</strong>如果这个人手上有你离不开的东西，那该谈条件就谈条件，该给股份就给股份。这不叫强留，这是交易，明着来。</p>
<h3 id="p-上六-比之无首-来晚了-就别挤了">上六 · 比之无首 —— 来晚了，就别挤了</h3>
<blockquote class="pw-quote"><strong>上六：比之无首，凶。</strong><br>象曰：比之无首，无所终也。</blockquote>
<p><strong>你现在在这个位置：你回头发现，你想进的那个圈子已经成型了。你在犹豫要不要硬挤。</strong></p>
<p>「比之无首」——没赶上打头的位置。「无所终也」——不会有结果。</p>
<p>卦辞里那句「后夫凶」，说的就是这一爻。孔颖达注：「它人皆比，亲道已成，己独在后，众人所弃，宜其凶也。」</p>
<p>这一爻给的动作是：<strong>别挤了，去找下一桌。</strong></p>
<p><strong>这是这一爻唯一正确的读法。</strong>它不是说「你完了」，是说「这一桌没你的位置了，换一桌」。</p>
<p>具体怎么判断：你跟这个圈子里的人见面，聊得客气但没有后续；你想约的人一直没空；你送出去的东西没有回音。这三条占了两条，就是「无首」。</p>
<p>这时候你应该去的地方，是那种<strong>刚起来、人还不齐、谁都不看好的地方</strong>。你在那里能当第一批人，而不是最后一排。</p>
<p>韩信先跟项梁，项梁死了跟项羽，项羽让他做郎中，他出的主意项羽不听。<strong>他跑到汉营去，那时候汉营正缺人。</strong>他要是留在项羽那儿硬挤，一辈子就是个执戟的。</p>
<p><strong>什么情况还能进去：</strong>如果这个圈子正在换核心——原来的头走了、散伙了、分裂了——那门就开了。抓住这种时候。</p>
<h3 id="p-最后-比是水往低处流">最后：比是水往低处流</h3>
<p>比卦的大象说：「地上有水，比；先王以建万国，亲诸侯。」</p>
<p>水不往高处去。<strong>你要别人靠过来，得先把自己的位置放低。</strong></p>
<p>孔子说：「近者说，远者来。」——身边的人是高兴的，远处的人自己会来。</p>
<p>比卦最后给你的一句话：</p>
<blockquote class="pw-quote">你在什么时机进场，比你在场里多努力，更决定你能拿到什么。</blockquote>
  `,
  xiaoxu: `
<p>你有没有过这样一段时间。</p>
<p>所有该做的事你都做了。方案改了七版，客户聊了三个月，人招齐了，钱也备好了。<strong>但就是不成。</strong></p>
<p>不是失败，是没动静。你问谁，谁都说「挺好的」「再等等」。</p>
<p>小畜卦讲的就是这个。上面是风，下面是天。风在天上吹，吹到东西了吗？没有，<strong>离地太远，什么都推不动</strong>。</p>
<p>卦辞那句是整部《周易》里最形象的一句：<strong>「密云不雨，自我西郊。」</strong> 云从西边压过来了，黑压压一片，可雨就是不落下来。</p>
<p>小畜是小有积蓄、力量还小。<strong>它讲的不是「怎么做成」，是「还没成的时候做什么」。</strong></p>
<p>六个爻，从「回到自己的路上」到「雨终于下了，但你别再走了」。</p>
<h3 id="p-初九-复自道-回到你自己的路上">初九 · 复自道 —— 回到你自己的路上</h3>
<blockquote class="pw-quote"><strong>初九：复自道，何其咎，吉。</strong><br>象曰：复自道，其义吉也。</blockquote>
<p><strong>你现在在这个位置：你为了赶进度，做了几件不太像你自己会做的事。你心里有点别扭。</strong></p>
<p>「复自道」——回到你本来的那条路上。</p>
<p>孔颖达注：初九「以阳升阴，反复于上，自用己道」——<strong>用自己那套办法，不学别人。</strong></p>
<p>这个阶段的动作：<strong>把你最近做的事，对着「我平时怎么做」过一遍。</strong></p>
<p>哪几件是为了讨好客户临时改的口径？哪几件是为了显得快而省掉的步骤？哪几件是学同行但学得不伦不类的？</p>
<p>挑出最别扭的一件，改回来。</p>
<p><strong>为什么是这一件？</strong>因为小畜的时候，你唯一能积攒的东西不是业绩，是<strong>别人对你这个人的判断</strong>。你做事的方式一旦歪了，攒的东西就散了。</p>
<p>东施效颦这个成语说的是西施心口疼，皱着眉在村里走，邻居觉得美。东施学着皱眉，把全村人吓跑了。<strong>她学的是动作，不是底子。</strong></p>
<p><strong>什么情况可以改道：</strong>如果你原来那套确实已经不灵了——比如整个行业的玩法都变了——那就不是复自道，是该换道。这时候要换得彻底，别半学半不学。</p>
<h3 id="p-九二-牵复-单干不如找个搭子">九二 · 牵复 —— 单干不如找个搭子</h3>
<blockquote class="pw-quote"><strong>九二：牵复，吉。</strong><br>象曰：牵复在中，亦不自失也。</blockquote>
<p><strong>你现在在这个位置：你想做点事，但一个人推不动。你有点拉不下脸去找人合作。</strong></p>
<p>「牵」是牵连、拉着。「牵复」是<strong>被人拉着一起回到正路上</strong>。</p>
<p>孔颖达注：「二欲往五，五非止畜之极，不闭固于己，可自牵连反复于上而得吉。」——九二跟上面的九五能接上，接上就顺。</p>
<p>这一爻的动作特别具体：<strong>找一个跟你处在同一阶段的人，结个伴。</strong></p>
<p>不是找大佬带，是找跟你差不多、也卡着的那个。<strong>你们交换的东西，恰恰是各自看不见的那部分。</strong></p>
<p>具体怎么开口：把你现在最卡的一件事说给他听，然后问他那件事卡在哪。一问一换，两边都赚。</p>
<p>管仲和鲍叔牙一起做生意，管仲分钱的时候多拿，鲍叔牙不跟他计较，说他是家里穷。<strong>后来鲍叔牙把管仲推荐给齐桓公，自己甘居其下。</strong></p>
<p><strong>什么情况别结伴：</strong>如果你们做的是同一件事、抢的是同一个客户，那就别结。这种搭子最后一定翻脸。</p>
<h3 id="p-九三-舆说辐-夫妻反目-内部先散了架">九三 · 舆说辐，夫妻反目 —— 内部先散了架</h3>
<blockquote class="pw-quote"><strong>九三：舆说辐，夫妻反目。</strong><br>象曰：夫妻反目，不能正室也。</blockquote>
<p><strong>你现在在这个位置：你跟你最核心的那个搭档，最近不太对劲。</strong></p>
<p>「舆说辐」——车轮的辐条脱落了，车走不动。<strong>车坏不是因为路，是因为轮子自己散了。</strong></p>
<p>象传的话是：「不能正室也。」——<strong>你连自己家里都整不明白。</strong></p>
<p>孔颖达注九三：「九三欲复而进，上九固而止之，不可以行。」一个想往前冲，一个按着不让走。<strong>这就是散架的起点。</strong></p>
<p>这个阶段的动作：<strong>把跟你搭档的那件事，单独约一次，只谈一件事——「你和我想要的是不是同一个东西」。</strong></p>
<p>不谈对错，不谈情绪，谈目标。你会发现很多矛盾是因为一个人要「做大」，另一个人要「做稳」；一个人想「今年就见钱」，另一个人想「先建品牌」。</p>
<p><strong>这两个目标都不错，但不能同时是同一个团队的目标。</strong>先选一个。</p>
<p>袁绍和曹操在官渡之前，袁绍内部的沮授和田丰主张持久战，郭图和审配主张速战。<strong>袁绍两边都听，两边都不全听，最后按郭图的打，输了。</strong></p>
<p><strong>什么情况就该散：</strong>如果谈了三次还是不在一条线上，那就别硬绑。这时候拆开，比拖着强。</p>
<h3 id="p-六四-血去惕出-心里有底就不慌">六四 · 血去惕出 —— 心里有底就不慌</h3>
<blockquote class="pw-quote"><strong>六四：有孚，血去惕出，无咎。</strong><br>象曰：有孚惕出，上合志也。</blockquote>
<p><strong>你现在在这个位置：你正在被夹在中间。上面压你，下面的人也不服。你天天提心吊胆。</strong></p>
<p>「血去」是伤害散去，「惕出」是恐惧离开。这一爻给的解法不是躲，是<strong>「有孚」——你手里得有真东西</strong>。</p>
<p>孔颖达注：六四「与上九同志，共恶于三」——<strong>六四找到上九这个同盟，恐惧就散了</strong>。</p>
<p>这个阶段的动作：<strong>找那个能给你撑腰的人，把你的处境讲清楚。</strong></p>
<p>不是去告状，是把事实摆出来：我现在被夹在什么位置、我做了什么、我需要什么。<strong>多数时候你怕的那件事，说出来就没那么可怕了。</strong></p>
<p>第二条：<strong>有孚这两个字，指的是你手上要有拿得出来的东西。</strong>一份清楚的账、一个能跑通的流程、一批认你的人。<strong>手上的东西越实在，心里越不慌。</strong></p>
<p>萧何进咸阳的时候，别人都去抢金银，他去把秦朝的律令图书收了起来。<strong>后来刘邦打仗、定天下、收户口，靠的都是这批东西。</strong>项羽那边什么都不知道。</p>
<p><strong>什么情况还要继续惕：</strong>如果你上面那个人本身就不稳，那就不能松劲。你自己心里有底，但对外还是要谨慎。</p>
<h3 id="p-九五-有孚挛如-富以其邻-有了就分出去">九五 · 有孚挛如，富以其邻 —— 有了就分出去</h3>
<blockquote class="pw-quote"><strong>九五：有孚挛如，富以其邻。</strong><br>象曰：有孚挛如，不独富也。</blockquote>
<p><strong>你现在在这个位置：你手上终于有点东西了，但你身边的人还紧着。</strong></p>
<p>「挛如」是紧紧拉住的样子。「富以其邻」是<strong>把富分给邻居</strong>。</p>
<p>孔颖达注：「五居尊位，不疑于二，来而不距。」——九五跟九二互相拉着，<strong>「不独富也」，不一个人发财</strong>。</p>
<p>这个阶段的动作：<strong>把你手上最值钱的那样东西，分一部分给正在跟你做同一件事的人。</strong></p>
<p>可能是你的客户资源，可能是你的方法论，可能是你试错试出来的那几条经验。挑那个对你成本最低、对他价值最高的。</p>
<p><strong>小畜的时候，你攒的不该只是钱，是愿意跟你一起走的人。</strong></p>
<p>范仲淹做官之后设义庄，买田千亩，接济族里穷的人。<strong>这事他办了几十年，范家的义庄一直办到清末。</strong></p>
<p><strong>什么情况不能分：</strong>如果这个东西分出去会让你自己撑不住，那就不分。<strong>先保住自己，才有下一轮可以分。</strong></p>
<h3 id="p-上九-既雨既处-雨下了-就停">上九 · 既雨既处 —— 雨下了，就停</h3>
<blockquote class="pw-quote"><strong>上九：既雨既处，尚德载，妇贞厉。月几望，君子征凶。</strong><br>象曰：既雨既处，德积载也。君子征凶，有所疑也。</blockquote>
<p><strong>你现在在这个位置：熬了很久的那件事，终于成了。所有人都说该趁热打铁。</strong></p>
<p>「既雨既处」——雨下了，也该停了。「月几望」——月亮快要圆了。<strong>快圆，就是还没圆，也正要开始亏。</strong></p>
<p>象传给了四个字：「有所疑也。」——上面开始怀疑你了。</p>
<p>这一爻是整卦的落点：<strong>你等来的那个东西，本身就是一个信号——该收了。</strong></p>
<p>孔颖达注：上九「以阴之長，能畜正刚健」，是压着别人往前走的那股力量。<strong>这股力量用到极致，就是「妇贞厉」「君子征凶」。</strong></p>
<p>这个阶段的动作：<strong>做成之后，主动收一步。</strong></p>
<p>不追加投入，不要更大的位置，不把摊子铺开。<strong>把这次的果实落袋、落地、落实。</strong>让跟着你的人先拿到。</p>
<p>具体：把这次的复盘点做完，把该分的分完，把该沉淀的流程写下来。然后<strong>再决定要不要开下一局</strong>——不是接着干，是重新决定。</p>
<p>商鞅变法十年，秦国大治。他本人被封为商君，出门「后车十数，从车载甲」。<strong>有人劝他功成身退，他没退。</strong>秦孝公一死，他被车裂。</p>
<p><strong>什么情况还可以再走一段：</strong>如果你这一轮攒下的是本事和班底，不是位置和名声，那可以接着走。<strong>能接着走的人，靠的是带得走的东西。</strong></p>
<h3 id="p-最后-云不下雨-也是天气">最后：云不下雨，也是天气</h3>
<p>小畜卦的大象说：「风行天上，小畜；君子以懿文德。」</p>
<p>懿是修美。<strong>雨没下来的时候，你去修那些雨下来了会用到的东西。</strong></p>
<p>小畜最后给你的一句话：</p>
<blockquote class="pw-quote">没成的时候别人看你是白忙，你自己得清楚：你攒的不是这个结果，是能接住下一个结果的那个自己。</blockquote>
  `,
  lvlv: `
<p>有一类场合，你一进去就知道自己是食物链下层。</p>
<p>比如你第一次跟那个大客户吃饭，比如你刚进一个新团队，周围全是你听说过的名字。</p>
<p>你说话之前要在心里过一遍，笑之前要看一眼别人的表情。<strong>你每一步都像踩在什么活的东西上面。</strong></p>
<p>履卦讲的就是这个。履是踩、是走、也是礼。卦辞第一句：<strong>「履虎尾，不咥人，亨。」</strong>——踩着老虎尾巴，老虎没咬你。</p>
<p>老虎就是那个比你强的东西，可能是人，可能是规矩，可能是整个环境。<strong>它随时能咬你，但它没咬——这一卦讲的就是为什么没咬，以及怎么才能一直不咬。</strong></p>
<p>六个爻，是六种在强者面前走路的姿态。<strong>越往后越清楚：真正让你安全的不是本事，是分寸。</strong></p>
<h3 id="p-初九-素履往-别装-装了就露">初九 · 素履往 —— 别装，装了就露</h3>
<blockquote class="pw-quote"><strong>初九：素履，往无咎。</strong><br>象曰：素履之往，独行愿也。</blockquote>
<p><strong>你现在在这个位置：你刚到一个新地方，或者刚进一个新圈子。你在琢磨该怎么表现。</strong></p>
<p>「素履」——素是没染色的布。<strong>用本色走你的路。</strong></p>
<p>孔颖达注：「处履之始，而用质素，故往而无咎。若不以质素，则有咎也。」——<strong>不素，就有咎。</strong></p>
<p>象传更妙：「独行愿也。」别人都还讲究点排场，只有你简简单单一身。<strong>这不叫不合群，这叫守着自己的愿。</strong></p>
<p>这个阶段的动作就一条：<strong>进新环境的前三个月，不要添置任何「看起来像这里的人」的东西。</strong></p>
<p>不换行头、不学话术、不买那个大家都报的班、不用那套听起来很专业的词。<strong>你越像这里的人，这里的人越看得出你不像。</strong></p>
<p>真到了要学的时候，学的是做事的标准，不是腔调。</p>
<p>汉初叔孙通给刘邦制礼，之前先去鲁地找儒生。<strong>有两个儒生不肯来，说天下刚定，死者未葬、伤者未起，不该这时候兴礼乐。</strong>叔孙通笑他们不知时变——但那两个儒生守的是自己的素。</p>
<p><strong>什么情况该换行头：</strong>如果这个场合的规矩是硬性的——比如必须正装、必须有某个资质——那就照办。素不是邋遢，是不多添。</p>
<h3 id="p-九二-履道坦坦-幽人贞吉-不声不响的人走得最稳">九二 · 履道坦坦，幽人贞吉 —— 不声不响的人走得最稳</h3>
<blockquote class="pw-quote"><strong>九二：履道坦坦，幽人贞吉。</strong><br>象曰：幽人贞吉，中不自乱也。</blockquote>
<p><strong>你现在在这个位置：你已经走顺了，但你还不是那个被看见的人。</strong></p>
<p>「履道坦坦」——路是平的。「幽人」是安静自守的人。</p>
<p>孔颖达注九二：「以阳处阴，履于谦退。」他还讲了一句很关键的：「履道尚谦，不喜处盈。」——<strong>这条路讲究的是谦退，不喜欢满。</strong></p>
<p>「隐显同」——在外面和在里面，心态一样。<strong>没人看的时候你是这样，有人看的时候你还是这样。</strong></p>
<p>这个阶段的动作：<strong>把你顺的那部分藏起来。</strong></p>
<p>不要在群里说你这个月的数据，不要在饭桌上讲你认识谁，不要让别人从你嘴里知道你走得很顺。<strong>你不是要骗人，是不给那些还在难处的人添堵。</strong></p>
<p>第二条：<strong>把你顺的原因写下来。</strong>哪几步是判断对了，哪几步是运气。<strong>顺的时候最容易把运气当本事，后面就摔。</strong></p>
<p>萧何在秦末一直管后勤，从来不争军功。刘邦定天下论功，把他排第一，功臣们不服。<strong>这时候大家才发现，这个一直不吭声的人，手里握着整个国家的账本和户口。</strong></p>
<p><strong>什么情况必须亮相：</strong>如果资源是靠自荐分的，你不说话就轮不到你，那就说话。标准很简单：<strong>这里的人是不是靠「会哭」拿到东西的。</strong></p>
<h3 id="p-六三-眇能视-跛能履-别用半桶水去趟深水">六三 · 眇能视，跛能履 —— 别用半桶水去趟深水</h3>
<blockquote class="pw-quote"><strong>六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。</strong><br>象曰：眇能视，不足以有明也。跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。</blockquote>
<p><strong>你现在在这个位置：有个机会超出你的能力范围了。但你舍不得，你想试试。</strong></p>
<p>「眇能视」——眼睛瞎了一只，还能看见点。「跛能履」——腿瘸了，还能走两步。</p>
<p>象传把话挑明了：<strong>「不足以有明也」「不足以与行也」。</strong>看得见，但看不清；走得动，但走不远。</p>
<p>「武人为于大君」——一个武夫想做君王的事。孔颖达注得辛辣：「以六三之微，欲行九五之志，顽愚之甚。」</p>
<p>这个阶段的动作：<strong>对着这个机会，写两栏——「我会的」和「这活实际需要的」。</strong></p>
<p>写完你就能看见缺口有多大。缺口一条能补，可以上。缺口三条，就是这一爻说的「咥人，凶」。</p>
<p><strong>如果非要上，带一个人。</strong>带一个在缺口那块有经验的人，哪怕分他一半。</p>
<p>赵括他爹赵奢活着的时候，赵括跟他谈兵事，赵奢说不过他。赵奢跟妻子说：<strong>「兵，死地也，而括易言之。」</strong>——打仗是要死人的事，这小子说得太轻巧了。</p>
<p><strong>什么情况可以硬上：</strong>如果这次输了不伤根本，而且你能在做的过程中学到东西，那就上。<strong>这一爻凶的是拿命去赌的人，不是拿学费去学的人。</strong></p>
<h3 id="p-九四-履虎尾-愬愬-怕-是这时候最对的状态">九四 · 履虎尾，愬愬 —— 怕，是这时候最对的状态</h3>
<blockquote class="pw-quote"><strong>九四：履虎尾，愬愬终吉。</strong><br>象曰：愬愬终吉，志行也。</blockquote>
<p><strong>你现在在这个位置：你离那个最关键的位置很近了。你知道自己说错一句话就完了。</strong></p>
<p>「愬愬」是恐惧的样子。跟六三同样是「履虎尾」，六三被咬了，九四没有。</p>
<p>差别在这里：<strong>六三不知道自己不行，九四知道自己随时会出事。</strong></p>
<p>孔颖达注：「逼近五之尊位，是履虎尾近其危也。以阳承阳，处嫌隙之地，故愬愬危惧也。」——<strong>离得太近，位置太敏感。</strong></p>
<p>这个阶段的动作：<strong>把你手上所有含糊的东西，全部弄明白。</strong></p>
<p>口头承诺全部落成文字，私下约定全部走正式流程，别人让你通融的事一律回「这个我不能定」。<strong>这个时候你越死板越安全。</strong></p>
<p>第二条：<strong>不要在背后议论你上面的人。</strong>哪怕你说的全是好话。</p>
<p>第三条：<strong>留着你的怕。</strong>很多人一到这个位置就想表现得从容，一从容就出事。</p>
<p>卫青做大将军的时候，姐姐是皇后，外甥是太子。他每次出征回来，都把功劳分给部下，从不自己请赏。<strong>汉武帝要给他三个儿子封侯，他推辞，说功劳是将士们的。</strong></p>
<p><strong>什么情况可以放松：</strong>如果你跟上面那个人的关系已经稳到不需要防，那就别端着。<strong>但「稳」的标准是他会主动告诉你坏消息，不是他见了你笑。</strong></p>
<h3 id="p-九五-夬履-贞厉-你说了算-就是你最危险的时候">九五 · 夬履，贞厉 —— 你说了算，就是你最危险的时候</h3>
<blockquote class="pw-quote"><strong>九五：夬履，贞厉。</strong><br>象曰：夬履贞厉，位正当也。</blockquote>
<p><strong>你现在在这个位置：这件事你拍板。没人能拦你。</strong></p>
<p>「夬」是决断。「夬履」是果断地走。「贞厉」——<strong>你做得对，但你很危险。</strong></p>
<p>象传给的理由只有四个字：「位正当也。」<strong>就是因为你在那个位置上。</strong></p>
<p>孔颖达注得更直白：「履道恶盈，而五以阳居尊，故危厉也。」他补了一句解释：「当处九五之位，不得不决断其理，不得不有其贞厉。」</p>
<p><strong>你必须决断，而决断本身就带着危险。</strong></p>
<p>这个阶段的动作：<strong>给你自己装一个刹车。</strong></p>
<p>具体做法：<strong>凡是要动到人的决定，强制隔一夜。</strong>今天定的事，明天再签。这不是拖延，是给自己一个后悔的机会。</p>
<p>第二条：<strong>指定一个人，专门说反话。</strong>每次开会让他先说不同意的部分。<strong>这个人不能是你讨厌的人，也不能是怕你的人。</strong></p>
<p>第三条：<strong>一年至少听一次完全外行的人怎么说。</strong>你的位置越高，能跟你说真话的人越少。</p>
<p>秦始皇统一天下之后，什么事都自己批，「衡石量书，日夜有呈，不中呈不得休息」。<strong>他做得对，也做得狠，秦朝十五年就没了。</strong></p>
<p><strong>什么情况必须当场拍：</strong>如果局面正在失控——有人在闹、事在恶化——那就当场定，别隔夜。<strong>刹车是给正常行驶准备的。</strong></p>
<h3 id="p-上九-视履考祥-回头看看你走过的路">上九 · 视履考祥 —— 回头看看你走过的路</h3>
<blockquote class="pw-quote"><strong>上九：视履考祥，其旋元吉。</strong><br>象曰：元吉在上，大有庆也。</blockquote>
<p><strong>你现在在这个位置：一段路走完了。你还想接着往前走。</strong></p>
<p>「视履考祥」——把你走过的路看一遍，检验吉凶的征兆。「其旋元吉」——旋是回转。<strong>你回过头去看，反而大吉。</strong></p>
<p>孔颖达注：「上九处履之极，履道已成，故视其所履之行，善恶得失，考其祸福之徵祥。」</p>
<p>这一爻是整卦唯一的「元吉」。<strong>而它给的动是「回头」。</strong></p>
<p>这个阶段的动作：<strong>做一次完整的复盘，写下来。</strong></p>
<p>哪几步走对了，哪几步走错了，哪几次是运气。<strong>尤其要写出那些「当时觉得对、事后看是错」的</strong>——那些才是你的东西。</p>
<p>写完不要马上用。放一个月再看一遍。<strong>你看第二遍的时候，会看出第一遍看不出的规律。</strong></p>
<p>张良跟刘邦走完这一路之后，说自己「以三寸舌为帝者师，封万户，位列侯，此布衣之极，于良足矣」。<strong>他退了，去学辟谷。</strong>韩信没退。</p>
<p><strong>什么情况不用回头：</strong>如果这段路你走得浑浑噩噩、纯靠运气，那复盘也理不出东西。这时候要做的是<strong>再看一遍你手上的牌</strong>，而不是回忆。</p>
<h3 id="p-最后-老虎不咬你-靠的不是胆子">最后：老虎不咬你，靠的不是胆子</h3>
<p>履卦的大象说：「上天下泽，履；君子以辨上下，定民志。」</p>
<p><strong>天在上面，泽在下面，各在各的位置上。</strong>这一卦叫履，也叫礼。</p>
<p>履卦最后给你的一句话：</p>
<blockquote class="pw-quote">在强者面前，你能走多远，不取决于你多能干，取决于你知不知道自己站在哪儿。</blockquote>
  `,
  tai: `
<p>你现在过得不错。</p>
<p>手上的事在往上走，团队听话，家里也没什么事。你晚上躺下的时候不用想明天要怎么办，因为明天跟今天差不多。</p>
<p><strong>这种时候人会松。</strong>松不是错，但泰卦想跟你聊的是另一件事。</p>
<p>泰是通。上面是地，下面是天——<strong>天本来在上，现在跑到下面去了；地本来在下，现在跑到上面去了。</strong>两个位置调换了一下，气就通了。</p>
<p>卦辞说：「小往大来，吉亨。」小的走了，大的来了。</p>
<p>但泰卦最有意思的不是它多吉，是它<strong>在最好的时候给了最重的一句警告</strong>，在九三那一爻：<strong>「无平不陂，无往不复。」</strong></p>
<p>没有一直平的路，没有只去不回的。</p>
<p>泰卦六个爻，是顺境里的六个动作。<strong>从「带着人一起走」到「城墙塌回壕沟」。</strong></p>
<h3 id="p-初九-拔茅茹-以其汇-你上来的时候带谁了">初九 · 拔茅茹，以其汇 —— 你上来的时候带谁了</h3>
<blockquote class="pw-quote"><strong>初九：拔茅茹，以其汇，征吉。</strong><br>象曰：拔茅征吉，志在外也。</blockquote>
<p><strong>你现在在这个位置：你这边形势在变好，机会开始多了。你正准备往前走一步。</strong></p>
<p>「拔茅茹」——拔茅草，根是连着的，拔一根带起一串。「以其汇」是同类一起走。</p>
<p>孔颖达注：「初九欲往于上，九二、九三皆欲上行，己去则从，而似拔茅举其根相牵茹也。」</p>
<p>这个阶段的动作：<strong>你想动的时候，先想清楚带谁。</strong></p>
<p><strong>带那种拔一根能带一串的人</strong>——不是人脉广，是<strong>他一动，他下面的人愿意跟着动</strong>。</p>
<p>具体怎么判断：这个人要走的时候，他的团队会不会问他「你去哪、我能跟吗」。会，就是这种人。</p>
<p>第二条更实在：<strong>你要动之前，先把你最核心的两三个人单独说一声。</strong>不要让他们从别人嘴里知道。</p>
<p>刘邦被项羽封到汉中，很多将领跑了。<strong>萧何去追韩信，刘邦以为萧何也跑了，气得不行。</strong>萧何回来第一句话是「臣不敢亡也，臣追亡者」——他追的是那个能带着大家走出去的人。</p>
<p><strong>什么情况自己走：</strong>如果你要去的那个地方暂时容不下第二个人，那就先自己去，站稳了再接人。<strong>这时候要说清楚，别让人以为你甩了他们。</strong></p>
<h3 id="p-九二-包荒-用冯河-顺的时候-容得下难看的">九二 · 包荒，用冯河 —— 顺的时候，容得下难看的</h3>
<blockquote class="pw-quote"><strong>九二：包荒，用冯河，不遐遗，朋亡，得尚于中行。</strong><br>象曰：包荒得尚于中行，以光大也。</blockquote>
<p><strong>你现在在这个位置：你手上有点权力了，来找你的人开始各式各样。</strong></p>
<p>「包荒」是包容荒秽的东西。「用冯河」——冯河是徒步涉水，是莽撞的人，这种人也容得下。「不遐遗」是远的也不漏掉。「朋亡」是不搞小圈子。</p>
<p>孔颖达注：「用心弘大，无所疏远弃遗于物。得中无偏，所在皆纳，无私于朋党之事。」</p>
<p>这个阶段的动作，就是这一爻给的四个词，一个一个对着做：</p>
<p><strong>包荒</strong>：把那些你看不上的、笨的、难搞的人留着用。<strong>顺境里你最容易只留顺眼的人。</strong></p>
<p><strong>用冯河</strong>：敢冲的人你先别嫌他毛躁，给他一件具体的事去冲。</p>
<p><strong>不遐遗</strong>：那个很久没联系的老同事、那个在你没钱时借过你钱的人，主动联系一次。</p>
<p><strong>朋亡</strong>：<strong>不组小圈子。</strong>这事最难。你顺的时候，围过来的人会自动形成一圈，圈外的人就慢慢远了。</p>
<p>刘邦入关中，秦王子婴投降，诸将说杀了他。刘邦说「怀王遣我，固以能宽容」，把人交给吏官看管。<strong>他要的是关中的人心，不是一时痛快。</strong></p>
<p><strong>什么情况可以清人：</strong>如果有些人的存在正在破坏规矩，那就清。<strong>包荒包的是能力差和脾气怪，不是包底线。</strong></p>
<h3 id="p-九三-无平不陂-无往不复-最好的一条路-也没那么">九三 · 无平不陂，无往不复 —— 最好的一条路，也没那么长</h3>
<blockquote class="pw-quote"><strong>九三：无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。</strong><br>象曰：无往不复，天地际也。</blockquote>
<p><strong>你现在在这个位置：一切都在往上走，你已经习惯了这种顺。</strong></p>
<p>「无平不陂」——没有只平不斜的路。「无往不复」——没有只去不回的。</p>
<p>孔颖达注九三：「处天地相交之际，将各分复其所处。乾体初虽在下，今将复归于上，坤体初虽在上，今欲复归于下。」——<strong>天要回到上面去，地要回到下面去。交接就在这一爻。</strong></p>
<p><strong>泰卦最好的位置就是这里，而这里也正是转折点。</strong></p>
<p>这个阶段的动作就两个字：<strong>「艰贞」</strong>——在最舒服的时候，做最难的那部分事。</p>
<p>具体是三件：</p>
<p><strong>第一，把资源往那些还没见效的地方分一点。</strong>新产品、新人、新市场。顺境是唯一你有余粮做这个的时候。</p>
<p><strong>第二，把账上留足。</strong>顺的时候人容易把现金全投出去。<strong>留够十八个月。</strong></p>
<p><strong>第三，跟你的核心团队明说：「会有不顺的时候，到时候按这个方案办。」</strong>把预案讲在明处。</p>
<p>「勿恤其孚，于食有福」——不用操心别人信不信你。你把该做的做了，饭是有得吃的。</p>
<p>李斯在秦朝做到丞相，儿子回咸阳，百官都去送行，车马千乘。李斯自己叹了口气，说了一句「物禁大盛」。<strong>他知道，但他没退。</strong></p>
<p><strong>什么情况可以继续冲：</strong>如果你现在这个上升期才刚刚开始，行业的天花板还远得很，那就冲。<strong>这句警告说的是「没有永远的平」，不是「明天就翻车」。</strong></p>
<h3 id="p-六四-翩翩-不富以其邻-不靠钱也能把人聚过来">六四 · 翩翩，不富以其邻 —— 不靠钱也能把人聚过来</h3>
<blockquote class="pw-quote"><strong>六四：翩翩，不富以其邻，不戒以孚。</strong><br>象曰：翩翩不富，皆失实也。不戒以孚，中心愿也。</blockquote>
<p><strong>你现在在这个位置：风向开始变了。你手上那点资源优势在减弱。</strong></p>
<p>「翩翩」是轻快地飞。「不富以其邻」——<strong>不靠财物，也能让邻居跟着你</strong>。「不戒以孚」——不用打招呼，他们自己就信你。</p>
<p>孔颖达注：「众阴皆失其本实所居之处，今既见命，翩翩乐动，不待财富，并悉从之。」</p>
<p>这个阶段的动作：<strong>把你能给的东西，从钱换成别的。</strong></p>
<p>钱会花完，位置会变。但有些东西给出去了还在：<strong>一个判断、一个人情、一次引荐、一句「我信你能行」。</strong></p>
<p>具体做：这段时间不要靠加钱留人。<strong>靠把话说清楚、靠把功劳分明白、靠在他最难的时候出现。</strong></p>
<p>李广带兵，史书上写他「得赏赐辄分其麾下，饮食与士共之」。他打了四十多年仗，家里没有余财。<strong>他最后自杀的时候，天下认识他的和不认识他的，都为他流泪。</strong></p>
<p><strong>什么情况就得用钱：</strong>如果对手正在拿钱挖你的人，那你也得加。<strong>这时候谈情怀是耍流氓。</strong></p>
<h3 id="p-六五-帝乙归妹-以祉元吉-高位的人主动低一下">六五 · 帝乙归妹，以祉元吉 —— 高位的人主动低一下</h3>
<blockquote class="pw-quote"><strong>六五：帝乙归妹，以祉元吉。</strong><br>象曰：以祉元吉，中以行愿也。</blockquote>
<p><strong>你现在在这个位置：你是位置高的那一方，但你需要另一方配合。</strong></p>
<p>「帝乙归妹」——帝乙是商王，他把妹妹嫁下去。<strong>一个君王，把自家的人往下嫁。</strong></p>
<p>孔颖达注：「女处尊位，履中居顺，降身应二。」——<strong>位置在尊，姿态往下。</strong></p>
<p>这一爻给的解法是：<strong>你主动降一格。</strong></p>
<p>具体到能做的：你把决策权分一部分出去，把署名让出去，把那个露脸的机会让出去，你亲自去对方的地盘谈一次。</p>
<p><strong>注意「以祉」这两个字</strong>——你做这个动作，是为了把事办成（祉是福），不是为了表演谦让。<strong>表演出来的降格，对方一眼就看穿。</strong></p>
<p>汉文帝跟匈奴和亲，把宗室的女子嫁过去。<strong>这事史书上写得不好看，但它换来了边境几年的安静。</strong></p>
<p><strong>什么情况不能降：</strong>如果对方要的是你的原则或者你的核心利益，那降了就守不住了。<strong>降姿态可以，降底线不行。</strong></p>
<h3 id="p-上六-城复于隍-勿用师-塌的时候-别硬撑">上六 · 城复于隍，勿用师 —— 塌的时候，别硬撑</h3>
<blockquote class="pw-quote"><strong>上六：城复于隍，勿用师。自邑告命，贞吝。</strong><br>象曰：城复于隍，其命乱也。</blockquote>
<p><strong>你现在在这个位置：事情开始塌了。你想出手挽救，但你发现每次出手都更糟。</strong></p>
<p>「城复于隍」——城墙倒回壕沟里。城墙是靠下面的土撑着的，下面的土一松，城就塌回原来挖土的那个坑。</p>
<p>孔颖达注：「今上下不交，臣不扶君，君道倾危。」象传给的原因是三个字：<strong>「其命乱也。」</strong>——你的命令系统乱了。</p>
<p>这一爻给的动作特别反直觉：<strong>「勿用师。」——别打，别硬来。</strong></p>
<p>不是投降，是<strong>承认这个时候你已经指挥不动了</strong>，再下命令只会暴露这一点。</p>
<p>具体做三件事：</p>
<p><strong>第一，别再发大命令。</strong>只处理一件一件的小事，把已经乱掉的那摊子先稳住一小块。</p>
<p><strong>第二，把你手上最要紧的资产转移出去。</strong>人、资料、现金、关系。</p>
<p><strong>第三，准备好那个「重新开始」的方案。</strong>什么时候用得上，你心里要清楚。</p>
<p>秦二世的时候，陈胜吴广起兵，使者回来报告，二世大怒，把使者下狱。后来使者就改口说「群盗，郡守尉方逐捕，今尽得，不足忧」。<strong>二世很高兴。</strong>到章邯说「盗已至，众强」的时候，已经晚了。</p>
<p><strong>什么情况必须出手：</strong>如果乱的只是局部，你的核心还在，那就集中力量先掐住那一个点。<strong>上六说的是整个命令系统乱了，不是某件事办砸了。</strong></p>
<h3 id="p-最后-泰不是让你躺着">最后：泰不是让你躺着</h3>
<p>泰卦的大象说：「天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。」</p>
<p>「财成」是裁剪成就，「辅相」是辅助。<strong>天和地交在一起的时候，人是不能闲着的，得去调。</strong></p>
<p>泰卦最后给你的一句话：</p>
<blockquote class="pw-quote">顺境不是奖励，是你唯一有时间做长线的那段窗口。你在这儿偷的懒，都会在下一步变成债。</blockquote>
  `,
  pi: `
<p>你最近有点憋。</p>
<p>不是能力不够，也不是不努力。是<strong>这里的人不看这些</strong>。你交上去的东西没人接，你提的建议没人理，你干成的活没人提。</p>
<p>反倒是那种会说、会来事、会站队的人，一路顺。</p>
<p>你开始怀疑是不是该改一改自己。改什么呢？改成他们那样？</p>
<p>否卦讲的就是这个。否是闭塞。上面是天，下面是地——<strong>天在上面，地在下面，各自归位，谁也不碰谁。</strong>泰是天地调了个位置所以通了，否是它们各回各位所以堵了。</p>
<p>大象给的一句话是整卦的纲领：<strong>「君子以俭德辟难，不可荣以禄。」</strong>——收敛起来，别去贪那个眼前的荣华。</p>
<p>否卦六个爻，是坏环境里的六个动作。<strong>从「别动」到「等到它塌」。</strong></p>
<h3 id="p-初六-拔茅茹-以其汇-贞吉-想走也别带头">初六 · 拔茅茹，以其汇，贞吉 —— 想走也别带头</h3>
<blockquote class="pw-quote"><strong>初六：拔茅茹，以其汇，贞吉，亨。</strong><br>象曰：拔茅贞吉，志在君也。</blockquote>
<p><strong>你现在在这个位置：你身边有几个人也想走。你们私下聊过好几次了。</strong></p>
<p>这一爻跟泰卦的初九长得几乎一样，都是「拔茅茹，以其汇」。<strong>但方向反了。</strong></p>
<p>泰卦说的是「带着人一起往上走」；否卦说的是<strong>「你不动，别人也不会动」</strong>。</p>
<p>孔颖达注：「居否之初，处顺之始，未可以动，动则入邪，不敢前进。己若不进，余皆从之。」</p>
<p>这个阶段的动作：<strong>你先别动，也别说要走。</strong></p>
<p>你只要在这个位子上坐住，跟你一样心思的那几个人就还有主心骨。<strong>你一动，他们要么跟着乱，要么被当成你的人清掉。</strong></p>
<p>象传给了理由：「志在君也。」——<strong>你的心思是在把这个地方弄好，不是跑。</strong>这个姿态很重要，它让你在后面的每一步都不亏心。</p>
<p><strong>什么情况可以走：</strong>如果你走了能带他们去更好的平台，而且你确定那边接得住——那就走，明着走，把人带走。<strong>这不叫带头跑，这叫另起炉灶。</strong></p>
<h3 id="p-六二-包承-小人吉-大人否-要么忍-要么扛">六二 · 包承，小人吉，大人否 —— 要么忍，要么扛</h3>
<blockquote class="pw-quote"><strong>六二：包承，小人吉，大人否，亨。</strong><br>象曰：大人否亨，不乱群也。</blockquote>
<p><strong>你现在在这个位置：你在这个环境里还能过得去。你要不要顺着他们的规矩来。</strong></p>
<p>「包承」是包着、承着，顺着上面的意思来。</p>
<p>这一爻给了一个双答案：<strong>「小人吉，大人否，亨。」</strong> 小人这么干，过得挺好；大人这么干，不行——但大人不这么干，反而通。</p>
<p>孔颖达注：「若大人用此包承之德，能否闭小人之吉，其道乃亨。」<strong>你守住不顺着来，等于把这条路堵住了，路才通。</strong></p>
<p>这个阶段的动作：<strong>在那些不影响原则的事上，顺；在影响原则的事上，一次都不顺。</strong></p>
<p>具体分法：流程、格式、称呼、开会怎么坐——全顺。数据、承诺、责任归属、要不要签字——一次都不顺。</p>
<p><strong>你会发现，不顺的那几次会很难受，但从此你在这个环境里有了一小块自己的地。</strong></p>
<p>「不乱群也」——你不顺，那些还在看的人就知道，原来可以不顺。</p>
<p><strong>什么情况全顺着来：</strong>如果你现在连饭都吃不上，那就先吃饱。<strong>但你要清楚这是过渡，别把这个当成活法。</strong></p>
<h3 id="p-六三-包羞-装久了-你自己都认不出自己">六三 · 包羞 —— 装久了，你自己都认不出自己</h3>
<blockquote class="pw-quote"><strong>六三：包羞。</strong><br>象曰：包羞，位不当也。</blockquote>
<p><strong>你现在在这个位置：你已经在顺着来了，而且顺得挺熟练。你偶尔会觉得有点恶心。</strong></p>
<p>「包羞」——包着羞耻。这一爻是六爻里最短的一爻，就两个字，加一句象传：<strong>「位不当也。」</strong> 位置不对。</p>
<p>孔颖达注：「群阴俱用小人之道包承于上，以失位不当，所包承之事，唯羞辱己。」——<strong>你顺着做的事，一件件都在羞辱你自己。</strong></p>
<p>这一爻不给你解法，它给你一个照镜子的机会。</p>
<p>这个阶段的动作：<strong>把你最近半年做的、觉得别扭但做了的事，列出来。</strong></p>
<p>列的时候不要辩解，不要写「当时也是没办法」。就写事实。</p>
<p><strong>列完你就知道，你离那个自己讨厌的人还有多远。</strong></p>
<p>还有一条：<strong>别在这个位置上待太久。</strong>这一爻最难受的不是羞耻，是<strong>它会让你习惯羞耻</strong>。</p>
<p>李斯在沙丘跟赵高合谋，改了秦始皇的遗诏，逼死扶苏，立了胡亥。<strong>那一刻他知道自己干了什么。</strong>他后来在狱中上书自陈功劳，还是没保住命。</p>
<p><strong>什么情况不用这么想：</strong>如果那些别扭的事只是「不符合你的风格」，不涉及对错，那就不用上纲上线。<strong>这一爻说的是羞耻，不是不习惯。</strong></p>
<h3 id="p-九四-有命无咎-机会来的时候-你得接得住">九四 · 有命无咎 —— 机会来的时候，你得接得住</h3>
<blockquote class="pw-quote"><strong>九四：有命无咎，畴离祉。</strong><br>象曰：有命无咎，志行也。</blockquote>
<p><strong>你现在在这个位置：上面有人开始注意到你了，或者局势有松动的迹象。</strong></p>
<p>「有命」——接到命令、接到机会。「畴离祉」——同类跟着一起沾光。孔颖达注：「言九四命初，身既无咎，初既被命，附依祉福。」</p>
<p>这个阶段的动作：<strong>机会来的时候，先把你的东西亮出来，别先要条件。</strong></p>
<p>你之前半年一直憋着，那半年你应该攒下了点什么——一份方案、一套数据、一个能落地的办法。<strong>现在就是你把它拿出来的时候。</strong></p>
<p>第二条：<strong>带上跟你一起憋的那些人。</strong>「畴离祉」讲的就是这个。<strong>你一个人拿到了，是运气；你把同类带上了，是资本。</strong></p>
<p>第三：<strong>别急着翻旧账。</strong>不要在这个时候说「我之前就提过，你们不听」。这句话说出来，机会就变味了。</p>
<p>汉文帝即位前，代国的郎中令张武劝他别去，说朝里那帮人都是跟着高帝打天下的老将，「此其意非止欲为大王也」。<strong>中尉宋昌说这是天命所归，劝他去。文帝带了六个人进长安，接住了这个位置。</strong></p>
<p><strong>什么情况先谈条件：</strong>如果这个「命」是要你去顶一个必死的坑，那当然要先谈。<strong>标准是：这件事做成了，功劳算谁的；做不成，责任算谁的。</strong></p>
<h3 id="p-九五-休否-其亡其亡-系于苞桑-最稳的时候-要天">九五 · 休否，其亡其亡，系于苞桑 —— 最稳的时候，要天天想着会倒</h3>
<blockquote class="pw-quote"><strong>九五：休否，大人吉。其亡其亡，系于苞桑。</strong><br>象曰：大人之吉，位正当也。</blockquote>
<p><strong>你现在在这个位置：你已经是这个环境里能说上话的人了。你在收拾这个烂摊子。</strong></p>
<p>「休否」——把否塞的局面休止掉。「其亡其亡，系于苞桑」——<strong>老想着「要亡了要亡了」，反而像拴在桑树根上一样牢。</strong></p>
<p>孔颖达注：「在道消之世，居于尊位而遏小人，必近危难，须恒自戒慎其意，常惧其危亡。」</p>
<p>这个阶段的动作：<strong>给你自己定一个「随时准备背书」的习惯。</strong></p>
<p>具体三件：</p>
<p><strong>第一，凡是关键的决定，你都要有一个「如果明天被翻过来，我拿什么自证」的答案。</strong>留记录、留依据、留时间线。</p>
<p><strong>第二，你手里要有一个人是完全不靠这个体系活的。</strong>他不在你的利益链上，所以他能跟你说真话。</p>
<p><strong>第三，定期做一次「最坏情况推演」。</strong>如果明天你被换掉，这个摊子会怎么散，你的东西还剩多少。</p>
<p><strong>「其亡其亡」不是消极，是让你在顺的时候不松手。</strong></p>
<p>诸葛亮在《出师表》里跟刘禅说「今天下三分，益州疲弊，此诚危急存亡之秋也」。<strong>那时候蜀汉刚打完夷陵，是最弱的时候。他不是吓唬人，是让整个朝廷保持紧张。</strong></p>
<p><strong>什么情况可以松一松：</strong>如果你已经把所有关键位置都换成了自己人，上面也明确支持你，那就别天天绷着。<strong>绷久了，团队会觉得你不信他们。</strong></p>
<h3 id="p-上九-倾否-先否后喜-熬到了-就别再忍">上九 · 倾否，先否后喜 —— 熬到了，就别再忍</h3>
<blockquote class="pw-quote"><strong>上九：倾否，先否后喜。</strong><br>象曰：否终则倾，何可长也。</blockquote>
<p><strong>你现在在这个位置：那个压着你的东西，开始松了。</strong></p>
<p>「倾否」——把否塞的局面推翻。「先否后喜」——开始是堵的，后来是通的。象传反问一句：<strong>「何可长也。」</strong>——这种情况怎么可能长久。</p>
<p>这一爻是整卦的出口。它告诉你：<strong>堵是堵不完的。</strong></p>
<p>这个阶段的动作：<strong>先把位置站好，再动手。</strong></p>
<p>具体说：风向一变，会有很多人同时动。这时候不要急着表态，不要急着站队，也不要急着去踩那些原来是上位者的人。</p>
<p><strong>第一件事是把你手上的东西接住，第二件事才是往前走。</strong></p>
<p>还有：<strong>别去清算。</strong>清算很爽，但会把本来要倒向你的中间派吓回去。<strong>扫屋子的时候别把家具也砸了。</strong></p>
<p>汉宣帝即位之后，霍光还在，朝政全在他手上。宣帝什么都顺着，等到霍光死了，他才一步一步把霍家的权收回来。<strong>霍家谋反被杀，宣帝没有搞大规模的株连。</strong></p>
<p><strong>什么情况还要继续忍：</strong>如果你觉得「松了」只是因为对手暂时分心，那还不是倾否。<strong>真倾否的标志是：原来跟着他的人都开始找退路了。</strong></p>
<h3 id="p-最后-否不是绝境-是一段天气">最后：否不是绝境，是一段天气</h3>
<p>否卦的大象说：「天地不交，否；君子以俭德辟难，不可荣以禄。」</p>
<p><strong>别在冬天播种，也别在冬天觉得自己废了。</strong></p>
<p>否卦最后给你的一句话：</p>
<blockquote class="pw-quote">环境不认你的时候，你不用改造环境，也不用改造自己。你只要别让它把你改了，等它自己过去。</blockquote>
  `,
  tongren: `
<p>你翻手机通讯录，两千多个联系人。真出事那天，你能打出去的电话不超过三个。</p>
<p>更难受的是另一件事：你发现你混的那个圈子，正在把你往下拽。里面的人互相捧着，说的话都一样，看外面的世界都带一层滤镜。你待得越久，越走不出去。</p>
<p>同人卦讲的就是这件事：你跟谁站在一起。</p>
<p>「同人」两个字，是跟人相同、跟人合到一块儿去。听着像讲人脉，其实讲的是<strong>你的边界划在哪儿</strong>。划在门里，你能护住的就门里那几个人；划到野外，天下的人才可能跟你走。</p>
<p>天火同人，上乾下离。天在上面，火苗往上窜，两个东西方向一致——这是同心之象。孔颖达说得很直接：「用心无私，处非近狭，远至於野，乃得亨进。」</p>
<p>心不偏私，站的地方不狭窄，一直远到旷野上，路才通。</p>
<p>我把六个位置拆开说。你看哪一条最像你现在的处境。</p>
<h3 id="p-初九-同人于门-无咎-先出这个门">初九 · 同人于门，无咎 —— 先出这个门</h3>
<blockquote class="pw-quote"><strong>初九：同人于门，无咎。</strong><br>象曰：出门同人，又谁咎也。</blockquote>
<p><strong>你现在在这个位置：你刚到一个新地方，或者刚从一个旧圈子里出来。你手上没有队伍，但也没包袱。</strong></p>
<p>这一爻给的指令最简单：<strong>出门</strong>。</p>
<p>「于门」就是在门口，还没走远。这一爻的妙处在于它说的是「门」不是「野」——你现在不需要一步跨到旷野，你只需要从屋里走到门外。</p>
<p>具体动作：<strong>每周主动约一个不在你现有圈子里的人，喝一次东西。</strong>不是加微信，是见面。加微信是存号码，见面才是认识人。</p>
<p>选人标准就一条：<strong>他做的事你听不懂，但他讲的时候你有兴趣。</strong>你都听得懂，那你们就在一个圈里，一个圈里的人给不了新东西。</p>
<p>还有一条更重要的：别挑。这一爻是「出门皆同」，谁碰上都能聊。你现在最需要的是撒开面，不是挑精品。</p>
<p>孔颖达注这爻说「心无系吝，含弘光大」——心里没有拴着的、舍不得的东西。刚起步的人最容易犯的错是舍不得旧关系，出去一趟还惦记着原来那帮人怎么看自己。</p>
<p>战国时的苏秦，第一次游说失败回家，嫂子不给他做饭。他没在家门口跟家里人置气，他去把《阴符》读了一年，然后出的门是往燕国、赵国去的门。<strong>他换的不是衣服，是门外那批人。</strong></p>
<p><strong>什么情况不用出门：</strong>如果你现在的团队正在打一场硬仗，缺一个人就崩，那先打完。守城的时候开城门是找死。</p>
<h3 id="p-六二-同人于宗-吝-只跟自己人抱团">六二 · 同人于宗，吝 —— 只跟自己人抱团</h3>
<blockquote class="pw-quote"><strong>六二：同人于宗，吝。</strong><br>象曰：同人于宗，吝道也。</blockquote>
<p><strong>你现在在这个位置：你的圈子很稳，而且很舒服。里面都是熟人，说话不用解释，互相都帮衬。</strong></p>
<p>这一爻是全卦最狠的一句告诫：<strong>吝</strong>。</p>
<p>吝不是凶，是「小气」「走窄了」。孔颖达说「和同於人在於宗族，不能弘闊，是鄙吝之道」——你只跟自家人合，合不开阔，这条路越走越窄。</p>
<p>而且这一爻在六二，是得位得中的好位置。<strong>位置越好，抱团越危险。</strong></p>
<p>具体自查三条：</p>
<p>- 你最近半年认识的新朋友，有没有一个不在你原来圈子里？</p>
<p>- 你团队招人的时候，是不是先从熟人和老部下里找？</p>
<p>- 你听到一个反对意见，第一反应是「他不是咱们这伙的」还是「他说的有没有道理」？</p>
<p>有一条中了，你就在「宗」里。</p>
<p>东汉的党锢之祸，根子就在这儿。李膺、陈蕃那批名士互相标榜，清流自居，天下士人非入其门便无出路。他们说的未必不对，可他们已经把「同人」缩成了「同志」。<strong>黄巾一起，宦官一动手，这伙人一夜之间全成了靶子。</strong></p>
<p><strong>什么情况可以死守小圈子：</strong>如果你的圈子是核心技术的持有者，或者你们做的事必须绝对保密、不能外传。这种时候圈子就是护城河。但你要清楚这是权宜，不是长久之道。</p>
<h3 id="p-九三-伏戎于莽-三岁不兴-埋伏三年-一场空">九三 · 伏戎于莽，三岁不兴 —— 埋伏三年，一场空</h3>
<blockquote class="pw-quote"><strong>九三：伏戎于莽，升其高陵，三岁不兴。</strong><br>象曰：伏戎于莽，敌刚也。三岁不兴，安行也。</blockquote>
<p><strong>你现在在这个位置：你心里有个人，你惦记着他手上的东西。你在暗处做准备，等着哪天把他顶掉。</strong></p>
<p>「伏戎于莽」是把兵藏在草丛里，「升其高陵」是爬到高处看对方。这两句画的是一个<strong>准备打架的人</strong>的样子。</p>
<p>结果呢？「三岁不兴」——三年都动不了。</p>
<p>孔颖达把这层说透了：九三想抢六二，可上面是九五。九五刚健，九三打不过。所以只能藏着、等着，等着等着三年就过去了。<strong>敌强，你就不敢动；不敢动，你就只能耗。</strong></p>
<p>这一爻最值钱的地方在于：它不骂你，它给你算账。</p>
<p><strong>这三年的成本你算过没有？</strong>你为了防一个人，花了多少心思在他身上？他发的每条朋友圈你都看，他跟谁吃饭你都打听，他的方案你逐字地抠。这些时间要是拿去干自己的事，你早就上去了。</p>
<p>「安行也」——孔颖达说「安」是个语辞，等于说「何」。都三年不动了，你还能往哪儿走？</p>
<p>三国时的钟会，灭蜀之后盯着司马昭的位置，在成都跟姜维密谋。他做的事和九三一模一样：先按兵，再看路，等时机。<strong>从入蜀到被杀，前后不过几个月，他连第一年都没熬过去。</strong></p>
<p><strong>什么情况该动手：</strong>如果你已经确定了对方的软肋，而且你有把握一次拿下、有把握善后，那就别伏着了。但你要先问自己：我是在等时机，还是在等一个我不敢承认永远不会来的时机？</p>
<h3 id="p-九四-乘其墉-弗克攻-吉-爬上墙头-又下来了">九四 · 乘其墉，弗克攻，吉 —— 爬上墙头，又下来了</h3>
<blockquote class="pw-quote"><strong>九四：乘其墉，弗克攻，吉。</strong><br>象曰：乘其墉，义弗克也。其吉，则困而反则也。</blockquote>
<p><strong>你现在在这个位置：你已经出手了，或者说你已经摆出了要出手的架势。然后你发现打不下去。</strong></p>
<p>「乘其墉」是登上城墙。你上去了，位置有了，动手的条件也够。</p>
<p>但「弗克攻」——打不下来。</p>
<p>这一爻的含义全在象传六个字：<strong>困而反则</strong>。困住了，回头了，回到规矩上来了。<strong>就因为这个回头，它断了个「吉」。</strong></p>
<p>这不太像《周易》里的吉。它不是说打赢了吉，是说<strong>打不下去，然后住手，吉</strong>。</p>
<p>孔颖达解释得很硬：「三欲求二，其事已非。四又效之……違義傷理，無所不與，雖復乘墉，不能攻三也。」九三抢人是错的，九四跟着抢也是错的。错事不顺，因为「众所不从」。</p>
<p>具体到今天就是：<strong>你已经把话说出去了，已经把关系摆开了，现在发现自己在理上站不住。收手。</strong></p>
<p>收手的动作要快，而且要有一句明确的话：「这事是我考虑不周，到此为止。」别用暗示收场，暗示等于没收。</p>
<p>汉初的韩信，拿下齐地之后派人去跟刘邦要「假齐王」。刘邦当场骂了出来，张良、陈平在桌子底下踩他的脚。刘邦立刻改口，说「要当就当真的，当什么假的」，然后封了。<strong>他上墙了，发现打不下去，一句话就下来了。</strong></p>
<p><strong>什么情况必须往上攻：</strong>如果对方是个反复无常、你今天退他就明天进的人，而事情已经牵扯到你的底线——那就别反则。对上这种人，收手等于把自己交出去。</p>
<h3 id="p-九五-先号咷而后笑-大师克相遇-先哭-后笑">九五 · 先号咷而后笑，大师克相遇 —— 先哭，后笑</h3>
<blockquote class="pw-quote"><strong>九五：同人，先号咷而后笑，大师克相遇。</strong><br>象曰：同人之先，以中直也。大师相遇，言相克也。</blockquote>
<p><strong>你现在在这个位置：你知道对的人是谁，可中间隔着一堆人。你们想合到一块儿，合不拢。</strong></p>
<p>「先号咷而后笑」——先嚎啕大哭，然后笑出来。这六个字里有一整段历程。</p>
<p>真正的合，是要过一道坎的。孔颖达说得不留情：「不能使物自歸己……必以大師與三、四戰克，乃得與二相遇。」你没法让人自动归附，必须打一场，打赢了才能见面。</p>
<p>这一爻有一个非常现代的读法：<strong>「大师克相遇」这五个字，说的不是外交，是实力。</strong></p>
<p>你跟那个人能坐到一张桌子上，靠的是你把挡在中间的东西清掉了。清掉挡路的东西，是要花力气的。</p>
<p>具体怎么做：</p>
<p>- <strong>先找出你俩之间隔的到底是人还是事。</strong>是人的话，那个人为什么挡着？是他自己的利益，还是他替别人挡？</p>
<p>- <strong>一场一场地清，别一起开战。</strong>九五这一爻说的是「大师」，不是「多师」。集中力量打一场。</p>
<p>- <strong>打完别翻旧账。</strong>「后笑」的意思就是真笑出来。你赢了还把中间人拿出来说事，那就笑不成了。</p>
<p>唐太宗和魏征，一开始是敌人。魏征给李建成出主意，劝他早点除掉李世民。玄武门之后李世民把魏征叫来问：「你为什么离间我兄弟？」魏征答：「太子要是听我的，就没有今天这事。」李世民没杀他，改用他。<strong>中间那个人没了，剩下的两个人才合得上。</strong></p>
<p><strong>什么情况不必打这一场：</strong>如果挡在中间的那个人，本身没有恶意，只是位置在那儿——那先谈，别急着动手。有些人只是站在门框里，你请他挪一下就行。</p>
<h3 id="p-上九-同人于郊-无悔-站在城外">上九 · 同人于郊，无悔 —— 站在城外</h3>
<blockquote class="pw-quote"><strong>上九：同人于郊，无悔。</strong><br>象曰：同人于郊，志未得也。</blockquote>
<p><strong>你现在在这个位置：你已经不在局里了。你没得罪谁，也没站到谁那边，你只是走得比较远。</strong></p>
<p>「于郊」是城外。比「门」远，比「野」还不到。这一爻的判词是「无悔」——不是吉，也不是凶，是<strong>没什么可后悔的</strong>。</p>
<p>象传补了一句很凉的：「志未得也」。你想合的那件事，没成。</p>
<p>这是全卦唯一一个承认「没做到」的位置。前面九三埋伏、九四上墙、九五开打，都还在争。到了上九，你不在争了。</p>
<p>这一爻的意义在于：<strong>它给退场留了一个体面的说法。</strong></p>
<p>孔颖达说得挺有意思：「雖陽在於外，遠於內之爭訟，故無悔吝。」你在外头，离里面那些争斗远，所以没什么可后悔。</p>
<p>具体怎么做：</p>
<p>- <strong>别把自己说成是受伤的人。</strong>你就是没成，不是被谁害了。这两种说法给人的分量完全不同。</p>
<p>- <strong>留着关系，别删人。</strong>郊外的人最大的价值是没有敌人。你将来要是再想进去，门还开着。</p>
<p>- <strong>把这段时间用来做一件只有你能做的事。</strong>「志未得」不等于「志已灭」，只是这件事暂时不在这里成。</p>
<p>《周易正義》引了楚昭王亡弓的故事。昭王出游丢了弓，手下要去找，他说「楚人亡弓，楚人得之，何必找」。孔子听说了，说「惜乎，其志不大也——为什么不说人亡弓、人得之，何必分楚」。孔颖达引这一段是要说：你的边界划在「楚」，你就只能是郊外的一个楚人。</p>
<p><strong>什么情况该重新进城：</strong>如果当初让你出城的那个理由已经消失了——那个人调走了，那件事结了，那个位置换了人——那就进城。郊外是用来待的，不是用来住的。</p>
<h3 id="p-最后-把门槛拆了-把院墙留在原地">最后：把门槛拆了，把院墙留在原地</h3>
<p>同人卦往下接的是大有卦。跟人合得起来，人才会往你这儿来。</p>
<p>这两卦连着看，意思很清楚：<strong>先有同人，才有大有。</strong></p>
<p>初爻的「门」、二爻的「宗」、上爻的「郊」，全卦一直在讲边界。边界画在哪儿，你的世界就有多大。</p>
<p>孔颖达在解释全卦的时候引了一句很有意思的话：凡是在同人之世做不到通达的，最后一定要用兵。他不是在吓唬人，他是在说一个规律——<strong>合不来的地方，早晚要打。</strong></p>
<p>同人卦最后给你的一句话：</p>
<blockquote class="pw-quote">别问你认识多少人。问你出事的时候，有几个人的电话你敢打——那几个人之外的所有人，才是你真正该去认识的人。</blockquote>
  `,
  dayou: `
<p>你账上第一次有了一笔真金白银。或者你的公司第一次不需要你天天盯着也能转。</p>
<p>按说该松口气。可你反而睡不着了。你半夜会想：这东西是怎么来的？还能来多久？身边这些人，谁是冲钱来的？</p>
<p>这种感觉有个名字，叫「大有」。</p>
<p>大有是「大获所有」。火天大有，上离下乾——火在天上，光照万物。全卦卦辞只有两个字：「元亨」。这是《周易》里最高的评价之一。</p>
<p>但这一卦的六个爻，一个都没在讲怎么挣钱。<strong>它们全在讲怎么守。</strong></p>
<p>孔颖达在开篇就点出来了：「既能大有，則其物大得亨通。」有了，才谈得上后面的事。</p>
<p>我把六个位置拆开说。你挑一个最像自己的。</p>
<h3 id="p-初九-无交害-匪咎-艰则无咎-刚到手-别张扬">初九 · 无交害，匪咎，艰则无咎 —— 刚到手，别张扬</h3>
<blockquote class="pw-quote"><strong>初九：无交害，匪咎，艰则无咎。</strong><br>象曰：大有初九，无交害也。</blockquote>
<p><strong>你现在在这个位置：你刚拿到一笔大的。可能是第一桶金，可能是第一次升到关键位置，可能是一门生意刚跑通。</strong></p>
<p>这时候最容易出的事，不是有人来偷你，是<strong>你自己开始飘</strong>。</p>
<p>「无交害」是还没有招来祸害。「匪咎」是眼下不算错。「艰则无咎」——你要把心收住、把事情往难处想，才没事。</p>
<p>孔颖达说得很直白：初九「不能履中謙退」，虽然眼前没出事，「久必有凶」。你不在中位上，又刚有了钱，行为又冲——这叫「满而不溢」，满了却没有溢出来，可你已经在边缘上了。</p>
<p>具体动作就三条：</p>
<p>- <strong>这笔钱三个月内不动。</strong>不投资、不借人、不换车、不请客。让它在那儿放着。</p>
<p>- <strong>把「最坏的打算」写下来一页纸。</strong>如果这笔钱全没了，你的生活会变成什么样？写完之后你会发现，其实没那么可怕——不那么可怕的时候，人就不容易乱花。</p>
<p>- <strong>别在朋友圈里露。</strong>这不是低调的修养，这是成本控制。你露一次，就多十个来找你的人，其中八个你不想给。</p>
<p>楚汉相争的时候，刘邦先入关中。他进了秦宫，看见宫室帷帐狗马重宝妇女，想住下来。樊哙劝他，他不听。张良说：秦朝就是因为这些亡的，你刚进来就享用它，这叫「助桀为虐」。<strong>刘邦封了宫室府库，还军霸上。</strong></p>
<p><strong>什么情况可以马上花：</strong>如果这笔钱对应着一个明确的、时间窗只有一两个月的机会，而且你算过最坏结果也能接受，那就投。放着不动是纪律，不是教条。</p>
<h3 id="p-九二-大车以载-有攸往-无咎-你得有辆大车">九二 · 大车以载，有攸往，无咎 —— 你得有辆大车</h3>
<blockquote class="pw-quote"><strong>九二：大车以载，有攸往，无咎。</strong><br>象曰：大车以载，积中不败也。</blockquote>
<p><strong>你现在在这个位置：有件大事落到你肩上了。别人交给你的时候，语气是信任的，但你自己心里清楚这分量。</strong></p>
<p>「大车以载」——大车装着东西往前走。</p>
<p>孔颖达注这一爻注得特别实在：「大車謂牛車也。載物既多，故云任重。車材彊壯，故不有傾危。」</p>
<p>牛车，装得多，走得慢，但车板结实，不会翻。</p>
<p>这一爻的重点不在「载」，在「车材彊壯」四个字。<strong>你接得住多少，取决于你这辆车是什么料做的。</strong></p>
<p>具体怎么办：</p>
<p>- <strong>先量一次车。</strong>把这件事需要的能力拆成五到七项，一项一项给自己打分。有一项明显是零，那就先去补这一项，或者找一个补这一项的人。</p>
<p>- <strong>重量要均匀。</strong>「积中不败」——东西堆在正中间才不倒。你把最重的活放在你最弱的那一环上，车就偏了。</p>
<p>- <strong>不要超载。</strong>别人夸你能力强，你就多接，这是刚拿到「大有」的人最容易犯的错。车装到车轴响，就是快断了。</p>
<p>秦末的萧何，刘邦在前面打仗，他在后面管粮草、管户口、管律令。这份活又重又不出彩，刘邦几次被打散，萧何每次都能把人和粮重新凑齐。<strong>他这辆牛车从来没跑快过，可从来没散过架。</strong></p>
<p><strong>什么情况该拒：</strong>如果你算下来这件事要用的那项能力，你手里没有人、短期内也招不到，那就直说不行。接不住的活，接了比不接伤害大得多。</p>
<h3 id="p-九三-公用亨于天子-小人弗克-该往上送的-往上送">九三 · 公用亨于天子，小人弗克 —— 该往上送的，往上送</h3>
<blockquote class="pw-quote"><strong>九三：公用亨于天子，小人弗克。</strong><br>象曰：公用亨于天子，小人害也。</blockquote>
<p><strong>你现在在这个位置：你手上有一块能自己说了算的资源。你可以在里面自己分，也可以往上交一部分。</strong></p>
<p>「公用亨于天子」——公侯拿自己的东西去献给天子。「亨」在这里是「享」，进献的意思。</p>
<p>这一爻的位置很微妙。孔颖达说九三「與五同功」，跟天子同一个级别做事，「威權之盛，莫盛於此」。<strong>你的权力大到跟老板差不多了，这时候你要做的就是往上送。</strong></p>
<p>「小人弗克」——格局小的人做不到这件事。象传更狠，说「小人害也」，做不到就是害。</p>
<p>具体怎么送：</p>
<p>- <strong>送的不是钱，是知情权。</strong>你手上那块东西的真实数字，主动报上去。老板最怕的不是你赚了，是你赚了他不知道。</p>
<p>- <strong>送的时候要给对方一个台阶。</strong>别说「这是我孝敬您的」，说「这块业务今年的情况我整理了一下，想跟您对一下」。同样是送，一个像行贿，一个像汇报。</p>
<p>- <strong>留够自己的。</strong>全交是自保过度，别人反而看轻你。交出那种你不交就会被人拿来说事的部分。</p>
<p>春秋时的范蠡，帮越王勾践灭了吴国，功成之后给文种留了一封信，说「飞鸟尽，良弓藏」，然后自己走了，改名换姓去做生意。文种没走，留下来接受封赏。<strong>范蠡把该交的交了，文种把该交的留下了。</strong></p>
<p><strong>什么情况不用送：</strong>如果这块资源是你自己投钱、自己担风险做出来的，而上面的位置本来就该你来坐——那不用献。大有卦讲的是有而不骄，不是有而让人。</p>
<h3 id="p-九四-匪其彭-无咎-别显得太多">九四 · 匪其彭，无咎 —— 别显得太多</h3>
<blockquote class="pw-quote"><strong>九四：匪其彭，无咎。</strong><br>象曰：匪其彭无咎，明辨晳也。</blockquote>
<p><strong>你现在在这个位置：你混在中间层，上面有个强势的老板，旁边有个跟你平级但权更重的人。你夹在当中。</strong></p>
<p>「匪其彭」——「匪」是非，「彭」是旁。别去沾旁边那个人的光，也别把自己搞得太显眼。</p>
<p>孔颖达把这爻的处境说得很清楚：「既失其位，上近至尊之威，下比分權之臣，可謂危矣。」</p>
<p>位置没坐正，上面是老板的威压，旁边是一个正在分权的同僚。这是全卦最难受的位置。</p>
<p><strong>这时候你唯一能做的就是：明确站队，而且是往老板那边站。</strong></p>
<p>不是让你去告密，是让你<strong>不要脚踩两只船</strong>。旁边那个人现在正红，跟着他看起来更划算，可你站过去就是他的人，老板迟早要清他。</p>
<p>具体做法：</p>
<p>- <strong>所有汇报都走正式通道。</strong>不要私下给老板递消息，也不要绕过流程给同僚承诺。</p>
<p>- <strong>别人拉你进小群，你回一句「这个我在大群里同步一下」。</strong>一句话，立场就清楚了。</p>
<p>- <strong>不评论那位同僚。</strong>老板问起，只讲事实。讲事实的人在两边都安全。</p>
<p>汉文帝时的周勃和陈平，一个是太尉，一个是丞相，都是诛吕的功臣，权都很重。陈平后来主动把右丞相的位置让给周勃，自己退到左边，还称病。<strong>他不是怕周勃，他是看出来文帝会先动周勃。</strong>后来周勃果然下狱，陈平没事。</p>
<p><strong>什么情况可以跟旁边的人走近：</strong>如果那位同僚跟老板的关系是公开的同盟，不是竞争关系，那就没问题。判断标准很简单：看他们两个人最近一次公开不同调出在什么时候。有过，就是竞争。</p>
<h3 id="p-六五-厥孚交如-威如-吉-交心-也得有威">六五 · 厥孚交如，威如，吉 —— 交心，也得有威</h3>
<blockquote class="pw-quote"><strong>六五：厥孚交如，威如，吉。</strong><br>象曰：厥孚交如，信以发志也。威如之吉，易而无备也。</blockquote>
<p><strong>你现在在这个位置：你是这个摊子的主心骨。你手里有资源，下面的人靠你吃饭。</strong></p>
<p>大有卦走到六五，是全卦的正位。柔居尊位，手里又有实在的东西。</p>
<p>这一爻给了两个字，缺一个都不行。<strong>一个是「孚」，一个是「威」。</strong></p>
<p>「厥孚交如」——讲诚信，跟人真诚交往。「威如」——还得有威严。</p>
<p><strong>这两个东西听起来是矛盾的，其实是配套的。</strong>孔颖达讲得很好：「既誠且信，不言而教行，所為之處，人皆畏敬。」你诚而且信，不用说话别人就照着做，你在的地方别人自然敬你。</p>
<p>象传的后半句最妙：「易而無備」。<strong>简单平易，不设防备。</strong>你不处处设防，别人反而畏你。</p>
<p>具体怎么做：</p>
<p>- <strong>钱上的事说清楚，人上的事说软。</strong>分钱别含糊，分完了再怎么讲感情都行；钱上含糊了，后面全白讲。</p>
<p>- <strong>该翻脸的时候要翻。</strong>「威如」不是天天板着脸，是<strong>关键的那一次你不退</strong>。一个从没翻过脸的人，翻脸也没人怕。</p>
<p>- <strong>少设规矩，多给准话。</strong>规矩越多，公司越小。你给准话，人就有底。</p>
<p>刘邦入关，废了秦朝那一整套严苛的法令，只留三章。<strong>他不是宽厚，他是知道刚接手的时候，规矩越多越乱。</strong></p>
<p><strong>什么情况只用威不用孚：</strong>如果你接手的是一支已经散了架的队伍，有人正在观望、有人在准备走——这时候先立规矩，立完再谈感情。顺序错了，你说的每句好话都会被当成软弱。</p>
<h3 id="p-上九-自天祐之-吉无不利-富了之后-心还得是干净">上九 · 自天祐之，吉无不利 —— 富了之后，心还得是干净的</h3>
<blockquote class="pw-quote"><strong>上九：自天祐之，吉无不利。</strong><br>象曰：大有上吉，自天祐也。</blockquote>
<p><strong>你现在在这个位置：你已经不在具体的位置上了。钱有了，事有人办，你甚至可以说自己已经退下来了。</strong></p>
<p>这一爻是全卦唯一一个提到「天」的。「自天祐之，吉无不利」——上天保佑他，吉，没有不利。</p>
<p>孔颖达把这句话拆成三样东西，讲得很漂亮：</p>
<p>一，他上面是六五，六五是讲诚信的，<strong>他在一个讲诚信的位置上</strong>。</p>
<p>二，他以刚乘柔，<strong>他懂顺从的道理</strong>。</p>
<p>三，他不被财物牵累，志气高，<strong>他敬重贤人</strong>。</p>
<p>三样都做到了，天都帮他，那就没有什么不帮他的了。</p>
<p>关键在第三条：「不以物累於心」。<strong>钱到了这个份上，最重要的是它不能变成你心里的东西。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>把一件最重要的东西交给别人。</strong>不是交出控制权，是交出一件你原来必须亲自拍板的事。交出去，你就知道地球照样转。</p>
<p>- <strong>花钱的标准改成「这件事值不值」。</strong>不再看贵不贵、划不划算。这一条听着奢侈，其实是最省钱的——按价值花钱的人，不会被便宜货拖住。</p>
<p>- <strong>找一个比你年轻、比你懂行、你听着还有点儿不舒服的人，定期跟他聊。</strong>你不舒服的地方，就是你已经僵住的地方。</p>
<p>范蠡离开越国之后，在陶地做生意，成了巨富，人称陶朱公。他三次赚到大钱，又三次把家财散给穷朋友和远房兄弟。<strong>他不是不爱钱，他是知道钱在他手上停留太久，就要开始收利息了。</strong></p>
<p><strong>什么情况不必散财：</strong>如果你的产业是要传给下一代的，那就别散。散财是这一爻给个人的出路，不是给家族的规矩。分清楚这两件事。</p>
<h3 id="p-最后-有-是最难的功课">最后：有，是最难的功课</h3>
<p>大有后面接的是谦卦。</p>
<p>这个排序是有心的：<strong>有了以后还不飘，才叫谦。</strong></p>
<p>大有卦六个爻，讲的全是怎么对待手上的东西。初爻别张扬，二爻量自己的车，三爻往上送，四爻别跟着红人走，五爻诚和威都要，上爻心里别被钱占住。</p>
<p>孔颖达在象传那边说了一句很重的话：「遏惡揚善，順天休命。」压住坏的，抬举好的，顺着天意过日子。</p>
<p>大有卦最后给你的一句话：</p>
<blockquote class="pw-quote">你手上那点东西，是用来做事的，不是用来证明你配得上的。你一旦要拿它证明什么，它就开始变成负担了。</blockquote>
  `,
  qian2: `
<p>开会的时候你提了个方案，所有人都说好。散会以后，方案上署的是别人的名字。</p>
<p>你干了三个人的活，年底评优的时候，领导念的是另一个人的名字。你坐在台下鼓掌。</p>
<p>这种人身边总有一个。可能就是你。</p>
<p>谦卦讲的就是这个位置。</p>
<p>地山谦，上坤下艮——一座山埋在地底下。山是高的，地是平的，可现在山在下面。<strong>这是谦卦全部的意思。</strong></p>
<p>《周易》六十四卦，只有谦卦六爻的爻辞全都带「吉」或「无咎」。孔颖达在开篇就说了：「謙為諸行之善，是善之最極。」谦是所有行为里最好的那一种，好到了顶。</p>
<p>但他又说了一件很多人没注意的事：谦卦的卦辞里没有「元亨利贞」，也没有「吉」。为什么？</p>
<p>孔颖达的问答很妙：元是万物之首，你都谦退了，怎么当首？利贞是干正事的，你用谦下人，怎么去正别人？所以这四个字都没有。<strong>谦卦不需要说吉，因为它的吉是明摆着的。</strong></p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初六-谦谦君子-用涉大川-吉-谦到底">初六 · 谦谦君子，用涉大川，吉 —— 谦到底</h3>
<blockquote class="pw-quote"><strong>初六：谦谦君子，用涉大川，吉。</strong><br>象曰：谦谦君子，卑以自牧也。</blockquote>
<p><strong>你现在在这个位置：你刚起步，没什么资本。你唯一有的就是态度。</strong></p>
<p>「谦谦」是谦了又谦，叠字。这一爻在山的最底下，本来就在最低处，还要再谦。</p>
<p>象传给了四个字：<strong>卑以自牧</strong>。「牧」是养。用卑微来养自己。</p>
<p>这句话得拆开看。它不是让你装孙子，是让你<strong>把谦当成一种日常的修行，像吃饭睡觉一样天天做</strong>。</p>
<p>具体做什么：</p>
<p>- <strong>每天主动做一件别人不愿意做的杂事。</strong>不是为了讨好谁，是为了让自己记住自己的位置。</p>
<p>- <strong>别人夸你的时候，只回一句「运气好」，别接着往下讲。</strong>你一接着讲，前面那句谦就白说了。</p>
<p>- <strong>把「我不太懂」这四个字练熟。</strong>这不是示弱，是给自己留信息入口。你说懂，别人就不讲了；你说不太懂，别人才愿意多说两句。</p>
<p>「用涉大川」——用这个态度去过大河。刚起步的人过河，靠不了船，只能靠别人愿意搭你一把。</p>
<p>韩信年轻的时候，在淮阴街头被一个屠夫拦住，让他要么拔剑，要么从裤裆底下钻过去。韩信看了他一会儿，趴下钻了。<strong>当时街上的人都笑他。他后来当了大将军，把那个屠夫找来，给了个官做。</strong></p>
<p><strong>什么情况不用谦：</strong>如果对方正在试探你的底线，一次两次可以，第三次还谦就是示弱了。谦谦是养德，不是养人欺负你。</p>
<h3 id="p-六二-鸣谦-贞吉-名声自己会响">六二 · 鸣谦，贞吉 —— 名声自己会响</h3>
<blockquote class="pw-quote"><strong>六二：鸣谦，贞吉。</strong><br>象曰：鸣谦贞吉，中心得也。</blockquote>
<p><strong>你现在在这个位置：你的好名声开始传出去了。有人在外面替你说好话，你自己都没提过。</strong></p>
<p>「鸣谦」——谦到了发声音。</p>
<p>这一爻的有意思之处在于：<strong>这个声音不是你发出来的。</strong>孔颖达说「處正得中，行謙廣遠」，你处在正位上又守中，谦行得广、走得远，所以名声就传出去了。</p>
<p>象传的「中心得也」是钥匙：<strong>你心里是真的这么想的，所以才响。</strong>装出来的谦不出声，或者出了声也难听。</p>
<p>具体怎么做：</p>
<p>- <strong>名声来了别接手。</strong>有人说「听说你特别厉害」，你回一句「都是同事帮忙」，然后换话题。接手名声的人，接下来就得一直供着它。</p>
<p>- <strong>这时候最容易出的错是加码。</strong>名声一起来，人就忍不住再演一遍。你已经不用演了。</p>
<p>- <strong>把名声换成实的东西。</strong>有人因为你的名声来找你，接下来谈的要是具体的事、具体的条件，别再谈感觉。</p>
<p>东汉的冯异，是光武帝刘秀手下的名将。打了胜仗，别的将领都坐在一起论功，他一个人躲在树底下，军中叫他「大树将军」。<strong>刘秀后来专门因为这个更重用他。</strong>他的名声不是自己喊的，是别人替他喊的。</p>
<p><strong>什么情况要主动出声：</strong>如果你所在的这个地方，资源是靠自荐分配的，而你的名声传不上去——那就得说。判断标准是：这里的人是不是靠「会哭」拿到东西的？是，你不哭就是放弃。</p>
<h3 id="p-九三-劳谦-君子有终-吉-干了活-还谦">九三 · 劳谦，君子有终，吉 —— 干了活，还谦</h3>
<blockquote class="pw-quote"><strong>九三：劳谦，君子有终，吉。</strong><br>象曰：劳谦君子，万民服也。</blockquote>
<p><strong>你现在在这个位置：活是你干的，苦是你吃的，可你既没有争，也没有抱怨。你还在干。</strong></p>
<p>「劳谦」两个字是全卦最重的。<strong>又劳又谦。</strong></p>
<p>九三是全卦唯一的阳爻，所有阴爻都归它。「上下無陽以分其民，上承下接，勞倦於謙也」——上面下面都没有别的阳爻来替你分担，你上面要应付、下面要照应，谦得都累了。</p>
<p><strong>这是全卦最累的位置，也是评价最高的位置。</strong></p>
<p>象传只给了四个字：<strong>万民服也</strong>。人心服了。</p>
<p>具体怎么做：</p>
<p>- <strong>继续干，但把账记清楚。</strong>这一爻不是让你当哑巴。你自己心里要有一本账：哪件事是你做的，哪次是你让的。这本账不给别人看，只给你自己看。</p>
<p>- <strong>让功劳的时候，只让一次话，别让两次。</strong>第一次说「这是大家的功劳」，是谦。第二次又说，就变成了挑剔别人的分配，反而难看。</p>
<p>- <strong>找一个信得过的人替你说。</strong>谦的人自己不喊，但得有人喊。张良有刘邦，萧何有夏侯婴。</p>
<p>周公辅佐成王，摄政七年。管叔、蔡叔在外面散布谣言说他要篡位，他也没停下来辩解，他接着干。<strong>等成王长大了，他把政权交回去，自己站到臣子的位置上。</strong>七年里他做的是天子的活，交出去的是一句怨言都没有。</p>
<p><strong>什么情况不用劳谦：</strong>如果这份功劳关系到你的岗位、职称、能不能留下来，那就该要。让功劳是给有余力的人准备的，你位置都不稳，让出去的就是饭碗。</p>
<h3 id="p-六四-无不利-撝谦-上下都要谦">六四 · 无不利，撝谦 —— 上下都要谦</h3>
<blockquote class="pw-quote"><strong>六四：无不利，撝谦。</strong><br>象曰：无不利撝谦，不违则也。</blockquote>
<p><strong>你现在在这个位置：你夹在中间。上面有领导，下面有干活的人，两边都得照顾。</strong></p>
<p>「撝谦」，「撝」是挥手、指挥的意思。<strong>挥着手还保持谦。</strong></p>
<p>孔颖达把这层讲得最清楚：「處三之上而用謙焉，則是自上下下之義。承五而用謙順，則是上行之道。」</p>
<p>你在九三之上，往下用谦，这是从上往下的谦；你承着六五，往上用谦，这是从下往上的谦。<strong>两个方向都做到，才叫「无不利」。</strong></p>
<p>这是全卦最实用的一个位置。大多数人只做到一边：对上客气，对下摆脸；或者对下随和，对上顶撞。</p>
<p>具体怎么做：</p>
<p>- <strong>对下谦，要给实在的东西。</strong>不是态度好，是分钱、分资源、分露脸的机会。只给态度的谦，下面的人看得出来。</p>
<p>- <strong>对上谦，要给准确的信息。</strong>不是奉承，是把真实情况报上去。报喜不报忧的谦，是坑。</p>
<p>- <strong>两边的话要一致。</strong>你在会上跟领导说的，和会后跟下属说的，不能是两套。这种事传得比你想的快。</p>
<p>周公的儿子伯禽去封鲁国，周公教他一段话，大意是：我是文王的儿子、武王的弟弟、成王的叔叔，地位不算低了吧，可我洗一次头要三次握住头发出来见客，吃一顿饭要三次吐出来出来见客，就这样还怕漏掉天下的贤人。</p>
<p><strong>什么情况可以不两边都谦：</strong>如果你已经明确被授权去整顿这个夹层，那就要立规矩。整顿的时候对下客气，等于让规矩作废。</p>
<h3 id="p-六五-不富以其邻-利用侵伐-无不利-不靠钱-也能">六五 · 不富以其邻，利用侵伐，无不利 —— 不靠钱，也能带人</h3>
<blockquote class="pw-quote"><strong>六五：不富以其邻，利用侵伐，无不利。</strong><br>象曰：利用侵伐，征不服也。</blockquote>
<p><strong>你现在在这个位置：你在这个位置上是靠人望，不是靠钱。而且下面有人不服你。</strong></p>
<p>这一爻是谦卦里最反直觉的一条。</p>
<p>前面五爻都在讲谦，到了六五，突然讲起了「侵伐」——出兵讨伐。</p>
<p><strong>谦不是没脾气。</strong>孔颖达讲得干脆：「居謙履順，必不濫罰無罪。若有驕逆不服，則須伐之。」</p>
<p>你谦，所以你不会乱罚没罪的人。但如果有谁骄横不服，那就得打。<strong>谦的前提是不欺负人，不是被人欺负。</strong></p>
<p>「不富以其邻」——「以」是用。一般人得靠财物周济邻里，才能用得上人家。六五处在尊位，用谦和顺，邻居自己就来归附，<strong>根本不用花钱。</strong></p>
<p>这一爻给的组合是：<strong>人望 + 出手。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先礼。</strong>把不服的那个人的问题当面讲清楚，给他一次机会，而且让所有人都知道你给了这次机会。</p>
<p>- <strong>再兵。</strong>他还不改，就动手，而且要当着大家动。这一仗不是打给他看的，是打给观望的那些人看的。</p>
<p>- <strong>打完别清算到底。</strong>「無不利」说的是出手得当，不是要斩草除根。</p>
<p>春秋时的楚庄王，问鼎中原之前，先在国内平了若敖氏的叛乱。他没有一上来就杀，而是先给了对方机会，对方动手了他才反手一击。<strong>平完之后他成了霸主，谦名和威名同时立住了。</strong></p>
<p><strong>什么情况不该出手：</strong>如果那个人只是嘴上不服、行动上配合，那就别动他。谦卦这一爻打的是「不服」的动作，不是「不服」的表情。</p>
<h3 id="p-上六-鸣谦-利用行师-征邑国-名声在外-人不在内">上六 · 鸣谦，利用行师，征邑国 —— 名声在外，人不在内</h3>
<blockquote class="pw-quote"><strong>上六：鸣谦，利用行师，征邑国。</strong><br>象曰：鸣谦，志未得也。可用行师，征邑国也。</blockquote>
<p><strong>你现在在这个位置：你在这个圈子外面，名声很大。里面的事你插不上手，说了也没人真听。</strong></p>
<p>又是「鸣谦」，但跟六二那个不一样。</p>
<p>六二的鸣谦是「中心得也」——心里真有，所以响。</p>
<p>上六的鸣谦是「志未得也」——你心里想做的事没做成。</p>
<p>孔颖达说得很直：「上六最處於外，不與內政，不能於實事而謙，但有虛名聲聞之謙。」</p>
<p><strong>你在外面，你不参与里面的事，你没法在实事上谦，只有虚名上的谦。</strong></p>
<p>这一爻给的出路是「利用行师，征邑国」——往外面去打，去征讨那些边远的城邑。</p>
<p><strong>核心的意思是：里面的局你进不去，那就往外打。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>承认你不在局里。</strong>别再往里挤了，挤进去也是被人当枪使。</p>
<p>- <strong>去找那些还没人管的、边上的事。</strong>边缘的地方往往没人竞争，你名声在外反而是优势。</p>
<p>- <strong>别拿虚名当实力。</strong>「志未得」这三个字是提醒：你现在响，是因为别人听说，不是因为你做到了。</p>
<p>孔子周游列国十四年，到处有人尊敬他，可没有一个国君真让他执政。他最后没在任何一个朝廷里做成事，他回去整理了《诗》《书》，教了三千个学生。<strong>里面那扇门一直没给他开，他就在外面另外开了一片地。</strong></p>
<p><strong>什么情况该重回局内：</strong>如果当初挡着你的人走了，或者上面换了思路，那就回去。里面的资源是外面的十倍。</p>
<h3 id="p-最后-山埋在地里-不是山没了">最后：山埋在地里，不是山没了</h3>
<p>谦卦后面接的是豫卦。</p>
<p>「有大而能謙必豫」——有了大东西还能谦，才能和乐。</p>
<p>谦卦六个爻，从最底下的「谦谦」，到中间的「劳谦」，到上面的「鸣谦」，讲的是一个完整的过程：<strong>先把自己放低，然后在低处把事做成，最后名声会自己找到你。</strong></p>
<p>孔颖达在彖传那边有句话，把这卦的分量说尽了：「天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。」</p>
<p>天减掉满的补给谦的，地把满的流到谦的那儿去，鬼神祸害满的福佑谦的，人讨厌满的喜欢谦的。四重都是同一个方向。</p>
<p>但还有一句要记牢：谦卦六五、上六两爻都讲用兵。<strong>谦不是不争，是不骄。</strong></p>
<p>谦卦最后给你的一句话：</p>
<blockquote class="pw-quote">你不用去证明你比这个位置高。你把手上的事做到别人张口就有你的名字，位置自己会让开。</blockquote>
  `,
  yu: `
<p>你今年特别顺。项目成了，钱到账了，领导在会上点了你的名，团队里没人跟你唱反调。</p>
<p>晚上回到家，你瘫在沙发上刷手机。刷到凌晨两点。</p>
<p>这种状态已经持续了三个星期。你也没觉得有什么不对——项目做完了，歇歇怎么了。</p>
<p>豫卦讲的就是这段时间。</p>
<p>「豫」这个字有两个意思。一个是和乐、高兴；一个是预备、提前准备。这两个意思放在一个字里，本身就在提醒你：<strong>乐和备是一回事。</strong></p>
<p>雷地豫，上震下坤——雷从地底下打上来，万物振奋。这是欢悦之象。</p>
<p>但豫卦的卦辞给得不客气，只有五个字：「利建侯行师。」适合封诸侯、适合出兵打仗。<strong>在一个看着最和乐的卦里，讲的全是动员和行动。</strong></p>
<p>孔颖达说得很透：「逸豫之事不可以常行，時有所為也。」舒服这件事不能常态地来，只在某些时候才能有。</p>
<p>这一卦的六个爻，讲的是顺境里的六种人。你找找自己是哪一种。</p>
<h3 id="p-初六-鸣豫-凶-得意就喊出来">初六 · 鸣豫，凶 —— 得意就喊出来</h3>
<blockquote class="pw-quote"><strong>初六：鸣豫，凶。</strong><br>象曰：初六鸣豫，志穷凶也。</blockquote>
<p><strong>你现在在这个位置：事情刚成了个开头，你已经到处在说了。</strong></p>
<p>「鸣豫」——高兴到了发出声音。</p>
<p>初六是全卦最底下的一爻，位置最低，可它上面正应着九四。九四是全卦唯一的阳爻，所有人的快乐都由它来。<strong>初六离它最近，所以高兴得最早，也最响。</strong></p>
<p>《周易》里带「凶」的爻不少，断得这么干脆的不多。象传补了三个字：「志穷凶也」——<strong>你的心气就这么点，一下就到底了。</strong></p>
<p>孔颖达说得更直接：「逸樂之極，過則淫荒。獨得於樂，所以凶也。」</p>
<p>具体到这个位置该干什么：</p>
<p>- <strong>把「成了」这两个字咽回去。</strong>不是不让你高兴，是让你把高兴换个地方放——放在心里，或者放在记事本上。</p>
<p>- <strong>立刻找下一个问题。</strong>这一爻的凶险不在乐，在「志穷」。你得意的那一刻，通常就是你脑子空掉的那一刻。</p>
<p>- <strong>复盘，别庆祝。</strong>把这次做成的原因写下来，写得越具体越好。写完你就不那么想庆祝了，因为你看见了里面有多少是运气成分。</p>
<p>官渡之后，曹操的谋士许攸来投，献了火烧乌巢的计。事成之后许攸在邺城街上喊曹操的小名，说「阿瞒，要不是我，你进不了这个门」。<strong>没多久许攸就被杀了。</strong></p>
<p><strong>什么情况可以喊：</strong>如果喊出来能直接换来你要的东西——比如能拿到投资、能签到人——那就喊。这是宣传，不是得意。判断标准是：你喊完之后，手上有没有多出实在的东西。</p>
<h3 id="p-六二-介于石-不终日-贞吉-高兴的时候-人得是硬">六二 · 介于石，不终日，贞吉 —— 高兴的时候，人得是硬的</h3>
<blockquote class="pw-quote"><strong>六二：介于石，不终日，贞吉。</strong><br>象曰：不终日贞吉，以中正也。</blockquote>
<p><strong>你现在在这个位置：周围人都在放松，你隐隐觉得有点不对，但说不上来哪儿不对。</strong></p>
<p>「介于石」——耿介得像块石头。</p>
<p>「不终日」——不用等一整天。</p>
<p>这两句合起来的意思很硬：<strong>你像石头一样有原则，一发现苗头不对，当天就撤。</strong></p>
<p>孔颖达的解释是：「知幾事之初始，明禍福之所生，不苟求逸豫，守志耿介似於石。然見幾之速，不待終竟一日。」</p>
<p>看出事情的初始苗头，明白祸福从哪儿生出来，不随便贪图舒服，守志像石头一样硬。看到征兆的速度快，等不了一整天。</p>
<p>这是全卦最著名的一爻。蒋介石的名字就从这儿来的——中正、介石，都是从这一爻取的。</p>
<p>具体怎么做：</p>
<p>- <strong>当你第一次觉得「这样下去不行」的时候，当天就做一个动作。</strong>不用做大的，做一个小的也行：把那个饭局推掉，把那个群退了，把那笔预算停了。</p>
<p>- <strong>给自己划一条线，写下来。</strong>比如「这个月的招待费超过 X 就停」。写下来之前，这条线是感觉；写下来之后，它是规矩。</p>
<p>- <strong>别跟人商量。</strong>这一爻讲的是见几而作。你跟一群人商量，他们正在兴头上，商量的结果一定是你被说服。</p>
<p>楚汉相争时，刘邦进了咸阳宫想住下来享受。樊哙劝他出去住，刘邦不听。张良跟他说了一句话：「忠言逆耳利于行，毒药苦口利于病。愿沛公听樊哙言。」<strong>刘邦当天就封了宫室，还军霸上。</strong>他没有等第二天。</p>
<p><strong>什么情况可以放松：</strong>如果你确定这件事没有时间窗口、没有人在盯着，那就放松。介如石不是让你当苦行僧，是让你在该硬的时候硬。</p>
<h3 id="p-六三-盱豫-悔-迟有悔-往上凑的那张脸">六三 · 盱豫，悔。迟有悔 —— 往上凑的那张脸</h3>
<blockquote class="pw-quote"><strong>六三：盱豫，悔。迟有悔。</strong><br>象曰：盱豫有悔，位不当也。</blockquote>
<p><strong>你现在在这个位置：你在迎合一个你其实不太服气的人，就因为他现在红。</strong></p>
<p>「盱」是仰视的样子，张目上视，讨好地看着上面。孔颖达说「睢盱者，喜說之貌」——一副讨好的欢笑相。</p>
<p>这一爻的判词是两个「悔」连着来，很难受。</p>
<p>第一个「悔」是：你现在这么凑上去，将来要后悔。</p>
<p>第二个「悔」是：你要是一直不动、拖下去，也要后悔。</p>
<p><strong>孔颖达把这两句话讲清楚了：「若睢盱之求豫，則悔吝也」；「若遲停不求於豫，亦有悔也」。</strong></p>
<p>凑上去不对，不凑也不对。位置卡在中间，进退都不是。</p>
<p><strong>这一爻真正要你做的判断是：这个人到底值不值得跟。</strong>判断完就动手，别拖。</p>
<p>具体怎么做：</p>
<p>- <strong>看他怎么对待已经没用的旧人。</strong>这是最准的一把尺子。他现在对你客气，是因为你还有用。</p>
<p>- <strong>看他红了之后有没有变。</strong>他上次升职之后，跟以前的同事还吃饭吗？</p>
<p>- <strong>决定之后快刀。</strong>要跟就认真跟，别一边凑一边嫌弃；不跟就退出来，退的时候别留一条腿在里面。</p>
<p>唐玄宗前期的宰相姚崇，跟张说不对付。张说被贬之后，有一次想通过岐王走门路回来。姚崇知道了，没有马上去告发，他等到玄宗问起的时候才说，说完张说就被贬到相州去了。<strong>姚崇做的判断准，出手也快。</strong></p>
<p><strong>什么情况可以慢慢来：</strong>如果这个人自己也还在位置上不稳，那就别急着表态。观望不是拖延，是在等一个明确的信号。</p>
<h3 id="p-九四-由豫-大有得-勿疑-朋盍簪-大家的快乐-是">九四 · 由豫，大有得。勿疑，朋盍簪 —— 大家的快乐，是从你这儿来的</h3>
<blockquote class="pw-quote"><strong>九四：由豫，大有得。勿疑，朋盍簪。</strong><br>象曰：由豫大有得，志大行也。</blockquote>
<p><strong>你现在在这个位置：一群人的奔头跟你有关。事情能不能成、大家能不能分到，看你的。</strong></p>
<p>九四是全卦唯一的阳爻，其他五个阴爻都往它这儿来。「由豫」——由他而豫。</p>
<p>「大有得」——他会得到很多。「勿疑，朋盍簪」——别猜疑，朋友们会像发簪束发一样聚拢过来。</p>
<p>孔颖达注「簪」是「疾也」——快。你不猜疑别人，别人就快快地聚过来。</p>
<p><strong>这一爻的关键词是「勿疑」。</strong></p>
<p>全卦五个阴爻，各有各的心思，有的是真心跟，有的是来蹭的。九四站在中间，最容易做的事就是挨个猜。</p>
<p>具体怎么做：</p>
<p>- <strong>定一次规矩，然后不改。</strong>分钱的方式、升迁的标准，公开说一次，说完了就执行。人聚过来是因为看见了规矩，不是因为看见了你的笑脸。</p>
<p>- <strong>对蹭的人别当场翻脸。</strong>「朋盍簪」聚的是人。人来了，里面有几个不干活的，这是成本。你为了清掉这几个人把气氛搞坏了，不划算。</p>
<p>- <strong>有疑问直接问，别猜。</strong>你心里对某个人有怀疑，直接找他谈一次。猜疑是消耗最大的一种活动。</p>
<p>刘邦在汉中，萧何追韩信回来，说这个人「国士无双」，你要想争天下就必须用他。刘邦当天就拜韩信为大将，而且按萧何说的，筑坛、具礼，正式拜。<strong>他没有犹豫，也没有先去查韩信的底细。</strong></p>
<p><strong>什么情况必须清人：</strong>如果有人正在你聚起来的人里挖墙脚、另立山头，那就清。这一爻讲的是不猜疑，不是不管事。</p>
<h3 id="p-六五-贞疾-恒不死-坐在上面-可事情不是你说">六五 · 贞疾，恒不死 —— 坐在上面，可事情不是你说</h3>
<blockquote class="pw-quote"><strong>六五：贞疾，恒不死。</strong><br>象曰：六五贞疾，乘刚也。恒不死，中未亡也。</blockquote>
<p><strong>你现在在这个位置：名义上你是这个摊子的一把手。可真正说了算的是你下面那个人。</strong></p>
<p>这一爻是豫卦里最憋屈的位置。</p>
<p>「贞疾」——你会一直有病。「恒不死」——但死不了。</p>
<p>孔颖达解得很有画面：「四以剛動為豫之主，專權執制，非己所乘，故不敢與四專權。而又居中處尊，未可得亡滅之。」九四刚健，是全卦真正的主人，权力都在它手上。你不敢跟它争。可你居在中位、处在尊位，它也没法把你灭掉。</p>
<p><strong>这就是一个架空了的领导。</strong></p>
<p>而且这一爻断的是「恒不死」——这不是好消息，是<strong>长期消耗</strong>。</p>
<p>具体怎么办：</p>
<p>- <strong>先认清现实。</strong>你现在争不了。你手上没有可以直接调动的人和资源。</p>
<p>- <strong>守住那个位置本身。</strong>「中未亡也」，你还在中位上，这个位置本身就是资源。别自己先辞了。</p>
<p>- <strong>慢慢把人换过来。</strong>不是一次换一批，是一次换一个，而且给足理由——业务调整、岗位轮换、个人发展。给足理由的换人，对方拦不住。</p>
<p>- <strong>别跟九四正面冲突。</strong>你正面冲一次，输了就什么都没了。</p>
<p>汉宣帝刚即位的时候，霍光把持朝政，满朝都是霍家的人。宣帝跟霍光同坐一辆车，后来形容那种感觉叫「芒刺在背」。他什么都没做，霍光要还政他不要，霍光的人他一个不动。<strong>等霍光死了，霍家谋反，他一步步把权收回来，前后用了好几年。</strong></p>
<p><strong>什么情况该翻脸：</strong>如果九四已经不满足于掌权，开始动你的人、动你的位置，那「恒不死」就保不住了。这时候先动手的人活。</p>
<h3 id="p-上六-冥豫-成有渝-无咎-玩到看不见了">上六 · 冥豫，成有渝，无咎 —— 玩到看不见了</h3>
<blockquote class="pw-quote"><strong>上六：冥豫，成有渝，无咎。</strong><br>象曰：冥豫在上，何可长也。</blockquote>
<p><strong>你现在在这个位置：你自己也知道有点过了。作息乱了，事情拖了，人也变懒了，但你停不下来。</strong></p>
<p>「冥豫」——冥是昏暗。玩到昏天暗地，看不见东西了。</p>
<p>孔颖达讲得很惨：「處動豫之極，極豫盡樂，乃至於冥昧之豫而成就也。如俾晝作夜，不能休己，滅亡在近。」</p>
<p>舒服到了极致，变成了昏暗的舒服，还成了习惯。把白天当晚上，停不下来，灭亡就在眼前。</p>
<p>但这一爻的判词是「无咎」。为什么？因为后面还有三个字：<strong>「成有渝」</strong>。</p>
<p>「渝」是变。<strong>已经这样了，还能改。</strong></p>
<p>象传给的四个字是「何可长也」——这样能撑多久。这不是判决，是提醒。</p>
<p>具体怎么做：</p>
<p>- <strong>先改一件事，越小越好。</strong>不是让你明天开始五点起床、戒酒健身、重做计划。就是今天晚上十一点关手机。</p>
<p>- <strong>把手机从卧室拿出去。</strong>这是全卦实操性最强的一招。你不需要靠意志力，你只需要靠距离。</p>
<p>- <strong>找一个能盯着你的人。</strong>不是监督，是每周跟他说一次你这周干了什么。说不出东西，你自己会难受。</p>
<p>春秋时的齐桓公，晚年宠信易牙、竖刁、开方三个人。管仲临死前跟他说这三个人不能用。桓公听了，把三个人赶走了。<strong>可赶走之后他觉得吃饭没味道、睡觉不踏实，又把三个人叫回来了。</strong>他最后死在了宫里，尸体停了六十七天没人收。</p>
<p><strong>什么情况不用改：</strong>如果你刚完成一个大项目，就在恢复期，那这段时间的放松是必要的。判断标准是：你是在恢复，还是在逃避。恢复有终点，逃避没有。</p>
<h3 id="p-最后-雷声从地下起来-也是从地下结束">最后：雷声从地下起来，也是从地下结束</h3>
<p>豫卦后面接的是随卦。</p>
<p>「豫必有隨」——和乐之后，一定有人跟随。</p>
<p>豫卦六个爻，从初六的「鸣豫」喊出来，到上六的「冥豫」昏过去，中间夹着一个六二的「介于石」。<strong>全卦只有一个位置是清醒的，就是那个不高不低、还没被卷进去的六二。</strong></p>
<p>孔颖达在彖传里讲了一句很硬的话：「聖人以順動，則刑罰清而民服。」顺着规律动，刑罚就清简，人就服。顺不是躺，顺是知道什么时候该动。</p>
<p>豫卦最后给你的一句话：</p>
<blockquote class="pw-quote">顺境不是让你歇的地方，是让你提前把下一次难的时候要用的东西备好的地方。雷声响的时候没人听劝，雷声停的时候才有。</blockquote>
  `,
  sui: `
<p>你换了老板。</p>
<p>新老板很能打，跟着他干的人这两年都起来了。你也就跟着过去了。待遇涨了点，title 好听点，团队里的人都挺服他。</p>
<p>半年后你发现一件事：你越来越习惯用他的口气说话了。他的判断你不问了，他的方向你不看了，他说什么你就做什么。</p>
<p>这种感觉挺舒服的。舒服到你没觉得有问题。</p>
<p>随卦讲的就是这件事。</p>
<p>泽雷随，上兑下震——上面是泽，下面是雷。雷藏在泽底下，是随时蛰伏的样子。兑是悦，震是动。动而悦，人心自然跟着走。</p>
<p>但随卦的卦辞给得很有意思：「元亨，利贞，无咎。」四个字后面还挂了个尾巴——无咎。</p>
<p>孔颖达在这四个字上花了很多笔墨，他说得很直：「以苟相從，涉於朋黨，故必須四德乃無咎。」</p>
<p>苟且地跟着人走，就会卷进朋党。<strong>必须有元亨利贞这四样，才能无咎。</strong>《周易》里能把「无咎」挂在四德后面的卦不多，随卦是其中一个。</p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初九-官有渝-贞吉-出门交有功-位置变了-圈子得">初九 · 官有渝，贞吉。出门交有功 —— 位置变了，圈子得跟着变</h3>
<blockquote class="pw-quote"><strong>初九：官有渝，贞吉。出门交有功。</strong><br>象曰：官有渝，从正吉也。出门交有功，不失也。</blockquote>
<p><strong>你现在在这个位置：你刚换了一个环境。旧的关系还在，新的关系还没建立起来。</strong></p>
<p>「官有渝」——「官」在这里指心里执掌的那个东西，也就是你的主意、你的立场。「渝」是变。<strong>你的位置变了。</strong></p>
<p>孔颖达说初九「既無其應，無所偏系，可隨則隨」。</p>
<p><strong>这一爻的运气在于：你现在还没有被谁绑住。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>出门。</strong>这一爻给的指令就是「出门交有功」。你换到新地方，第一件事是走出去认识人，不是坐在工位上等活。</p>
<p>- <strong>别老跟原来那拨人混。</strong>这不是不念旧，是你在新地方需要一个新网络。你每天中午还跟老同事吃饭，三个月后你在新团队里还是外人。</p>
<p>- <strong>带着判断去交，不带立场。</strong>「唯正是從」——对的就跟，不论是谁说的。你新来，还没有资格挑人，先把信息面打开。</p>
<p>韩信从项羽那边跑到刘邦这边，一开始只当了个管粮仓的小官，还差点因为连坐被杀。他跑的时候没有顾虑项羽那边的情面。<strong>他换的不只是老板，是整套关系网。</strong></p>
<p><strong>什么情况别急着出门：</strong>如果你到的是一个讨论敏感、派系分明的环境，先看清谁跟谁，再出去交。乱交比不交更麻烦。</p>
<h3 id="p-六二-系小子-失丈夫-抱住了小的-丢掉了大的">六二 · 系小子，失丈夫 —— 抱住了小的，丢掉了大的</h3>
<blockquote class="pw-quote"><strong>六二：系小子，失丈夫。</strong><br>象曰：系小子，弗兼与也。</blockquote>
<p><strong>你现在在这个位置：有个眼前的人对你挺好，给的东西也实在。可你心里知道，远处还有个人可能更重要。</strong></p>
<p>「小子」是初九，位置低。「丈夫」是九五，位置高。</p>
<p>六二在初九上面，离初九近，一伸手就够得着。九五呢，远，而且不一定看得上你。</p>
<p><strong>你抱住了初九，就抓不住九五。</strong></p>
<p>象传给的理由是四个字：<strong>弗兼与也</strong>——没法两个都要。</p>
<p>具体怎么做：</p>
<p>- <strong>先算清楚这两个人三年后大概在哪。</strong>不是现在谁对你好，是三年后谁还在这个牌桌上。</p>
<p>- <strong>别贪图眼前的舒服。</strong>初九给你的可能是实实在在的照顾：帮你说话、给你活干、带你吃饭。这些东西很暖，也很黏。</p>
<p>- <strong>选定了就断干净。</strong>这一爻最忌讳的是脚踩两只船。你跟初九走近，就别私下找九五；你想跟九五，就得慢慢从初九的圈子里退出来。</p>
<p>陈平从项羽那边投奔刘邦，走的时候是单身一个人渡河过去的。在船上船夫看他像个有钱人，想谋财害命，他把衣服全脱了让船夫看，证明自己没钱。<strong>他连衣服都不要了，就是要把旧的一层全脱掉。</strong></p>
<p><strong>什么情况可以两个都留：</strong>如果这两个人本身是一伙的，上面那个明确让下面那个带你，那就不冲突。判断标准是：他们两个人之间有没有过公开的矛盾。</p>
<h3 id="p-六三-系丈夫-失小子-随有求得-利居贞-抱住了大">六三 · 系丈夫，失小子。随有求得，利居贞 —— 抱住了大的，小的松了</h3>
<blockquote class="pw-quote"><strong>六三：系丈夫，失小子。随有求得，利居贞。</strong><br>象曰：系丈夫，志舍下也。</blockquote>
<p><strong>你现在在这个位置：你往上靠了一个更厉害的人。原来那帮跟你平级的、或者不如你的，你顾不上他们了。</strong></p>
<p>六三跟六二正好相反。六二抱住下面的，六三抱住上面的。</p>
<p>「随有求得」——你跟着他，要什么有什么。孔颖达说「己往隨於四，四不能逆己，是三之所隨，有求而皆得也」，你往上跟，上面的人不会拒绝你，你要的都给你。</p>
<p><strong>但后半句是「利居贞」。</strong></p>
<p>有了好处，还要守住正。这一爻的危险在于：你靠上去了，容易开始拿上面的势去压原来的人。</p>
<p>具体怎么做：</p>
<p>- <strong>别抛弃下面的人，只跟他们保持距离。</strong>「志舍下也」，你的心思是往下舍的，但别当着人家的面舍。你原来带的人，走的时候要交接清楚、要交代明白。</p>
<p>- <strong>要东西的时候走明路。</strong>往上跟的人最容易出的问题是私下要资源。私下要来的东西，来路不清，将来出事的时候也没人替你说话。</p>
<p>- <strong>守住你在小事上的信誉。</strong>这一爻的「贞」不在大是大非，在你答应过的小事。</p>
<p>《史记》里的李斯，原本是楚国上蔡的一个小吏，跟荀子学帝王之术，然后投奔秦国。他从吕不韦的门客做起，一路做到丞相。<strong>他跟对了人，也得到了所有想要的。可他在沙丘那一次，为了保住位置，跟赵高一起改了遗诏，把扶苏换成了胡亥。</strong>那一次他把「贞」丢了。</p>
<p><strong>什么情况可以舍下：</strong>如果你下面那批人自己出了问题——在混、在内斗、在拖你后腿——那舍掉是对的。往上走的人不能背着一堆包袱。</p>
<h3 id="p-九四-随有获-贞凶-有孚在道-以明-何咎-跟得太">九四 · 随有获，贞凶。有孚在道，以明，何咎 —— 跟得太好，也是罪</h3>
<blockquote class="pw-quote"><strong>九四：随有获，贞凶。有孚在道，以明，何咎。</strong><br>象曰：随有获，其义凶也。有孚在道，明功也。</blockquote>
<p><strong>你现在在这个位置：你跟着老板，功劳太大了。你手下的人越来越多，别人开始绕过老板直接找你。</strong></p>
<p>这一爻是全卦最凶险的地方。</p>
<p>「随有获」——跟着人走，得到了很多。「贞凶」——就算你是正当得到的，也凶。</p>
<p><strong>这是一个非常反常识的判断：你做对了，你还是凶。</strong></p>
<p>孔颖达把原因说得很直白：「居于臣地，履非其位，以擅其民，失其臣道。」你是臣的位置，可你掌握了本属于君的人心。</p>
<p><strong>你的问题不在你做了什么，在你手上有了什么。</strong></p>
<p>解药在「有孚在道以明」六个字：<strong>诚信、走正道、把事情摆到明处。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>主动把功劳报上去。</strong>你手上的数字、你带的人、你做的事，主动让老板掌握。他不问你也报。</p>
<p>- <strong>让人知道你的权力是他给的。</strong>用人、调人、定事，能公开说的都公开说一次，讲清楚这是老板授权的。</p>
<p>- <strong>别搞私人恩惠。</strong>你自己掏钱请客、自己许诺好处，这些看起来是善缘，实际上是在替老板做人情。</p>
<p>- <strong>该让的位置让。</strong>如果有个岗位是给你准备但你发现老板有点犹豫，那就主动推掉。</p>
<p>诸葛亮在蜀汉是丞相，录尚书事，益州牧，政事无大小都由他决定。刘禅说过「政由葛氏，祭则寡人」。<strong>但诸葛亮一生没碰过一件事：他没有把刘禅废掉，也没有让自己家里人在关键位置上扎堆。</strong>他死后，儿子诸葛瞻的官位是一步步正常上来的。</p>
<p><strong>什么情况不用这么小心：</strong>如果老板明确说了这块给你、人由你带、盈亏由你担，那你就是在自己的地盘上。授权明确的收获，不算「随有获」。</p>
<h3 id="p-九五-孚于嘉-吉-跟善意的人-跟善意的事">九五 · 孚于嘉，吉 —— 跟善意的人，跟善意的事</h3>
<blockquote class="pw-quote"><strong>九五：孚于嘉，吉。</strong><br>象曰：孚于嘉吉，位正中也。</blockquote>
<p><strong>你现在在这个位置：你是被跟的那个人。下面一群人看着你，你的每个动作都是信号。</strong></p>
<p>九五是随卦的君位。「孚于嘉」——「嘉」是善。你信任的是善的东西。</p>
<p>孔颖达说：「履中居正，而處隨世，盡隨時之義，得物之誠信。」处在中正的位置上，又赶上随的时代，能尽到顺时的道理，得到别人的真心。</p>
<p><strong>这一爻的重点在于：你信什么，就有什么样的人来。</strong></p>
<p>你信能力，来的是能人。你信忠诚，来的是听话的。你信关系，来的是一群攀关系的。</p>
<p>具体怎么做：</p>
<p>- <strong>公开表扬的时候，说清楚你看重的是什么。</strong>别泛泛地说「大家辛苦了」。说「小张这次把一个不可能的时间点守住了，我看重这个」。</p>
<p>- <strong>赏罚的口径全年一致。</strong>你在这个季度奖励了什么，下个季度就还得奖励什么。口径一变，人就乱了。</p>
<p>- <strong>对最会说话的那个人，多问一句「具体怎么做的」。</strong>顺着你说的人，多半没有具体的东西。</p>
<p>汉文帝即位之后，有人献千里马给他。他说：我出行的时候前面有鸾旗，后面有属车，一天走五十里，我一个人骑千里马能去哪儿。<strong>他把马退回去了，还下了一道诏书说以后不许献。</strong>他信的是节俭，所以文景之世来的都是务实的人。</p>
<p><strong>什么情况可以信人胜过信规矩：</strong>如果是极小的一支队伍，你们都知根知底，那就别搞太多条文。人少的团队，规矩越多越生分。</p>
<h3 id="p-上六-拘系之-乃从维之-王用亨于西山-绑来的人-">上六 · 拘系之，乃从维之。王用亨于西山 —— 绑来的人，绑不住</h3>
<blockquote class="pw-quote"><strong>上六：拘系之，乃从维之。王用亨于西山。</strong><br>象曰：拘系之，上穷也。</blockquote>
<p><strong>你现在在这个位置：你是最后一个还没表态的人。别人都跟了，就你没动。</strong></p>
<p>「拘系之」——把他捆起来。「乃从维之」——再用绳子拴紧。</p>
<p><strong>捆起来，拴紧了，他才跟。</strong></p>
<p>这一爻里有个很硬的东西。《周易正義》对这句的疏解是：「隨道巳成而特不從，故須拘系之，乃始從也。」</p>
<p>大家都跟了，就你不跟，那就只能捆你。</p>
<p>但后面还跟着一句：「王用亨于西山。」孔颖达解释西山是险阻之处，说的是王者需要用兵打通险阻的道路才能把人拴住，<strong>这「非是意在好刑」——不是因为他喜欢用刑。</strong></p>
<p>具体怎么办，分两种情况：</p>
<p><strong>如果你是那个要捆人的：</strong></p>
<p>- <strong>先问问自己，他为什么不跟。</strong>用绳子之前，用一次嘴。上六已经是你最后的机会了。</p>
<p>- <strong>捆了之后要用，也要防。</strong>被迫跟来的人，心不在你这里。用他，但别把后背交给他。</p>
<p>- <strong>捆的时候要有个说法。</strong>「王用亨于西山」——你是为了打通道路，不是为了出气。这个说辞得站得住。</p>
<p><strong>如果你是那个被捆的：</strong></p>
<p>- <strong>你要知道，捆到你身上就代表你没有别的选择了。</strong>上六的位置是「上穷也」，路到头了。</p>
<p>- <strong>划清楚哪些能答应、哪些不能。</strong>捆是捆你的行动，不该捆你的判断。答应的时候把边界讲明。</p>
<p>周武王伐纣，伯夷、叔齐扣马而谏，说「父死不葬，爰及干戈，可谓孝乎」。左右的人想杀了他们，姜太公说「此义人也」，把他们扶开了。<strong>这两个人后来不食周粟，饿死在首阳山。他们从头到尾没有跟。</strong></p>
<p><strong>什么情况必须捆：</strong>如果这个人掌握着关键的东西，而他的不跟会带来直接的损害——那就捆。留着他不是宽容，是对其他人的不负责。</p>
<h3 id="p-最后-跟人走的时候-手里得留一根线">最后：跟人走的时候，手里得留一根线</h3>
<p>随卦后面接的是蛊卦。</p>
<p>「以喜隨人者，必有事」——因为高兴而跟着人走的，一定会出事。</p>
<p>随卦六个爻，前面四爻都在讲「跟着谁」，到了九五翻过来讲「被跟的人该做什么」，上六又讲「不跟的人怎么办」。</p>
<p><strong>一整卦讲的都是关系，没一爻在讲你自己。</strong></p>
<p>这就是随卦最难的地方。孔颖达在彖传那边有一句话可以收尾：「隨之所施，唯在於時。」跟这件事，用在哪里，全看时候。</p>
<p>随卦最后给你的一句话：</p>
<blockquote class="pw-quote">跟对人只是第一步。真正的本事是：你跟着他走，但你手里一直攥着一根线，那根线连着的是你自己的判断。</blockquote>
  `,
  gu: `
<p>你接手了一个部门。或者一个厂子，一个门店，一个团队。</p>
<p>前任走得挺突然。你翻开账本、翻开流程、翻开工位上的交接单，越看越心惊。该招的人没招，该换的设备没换，欠的款拖了两年，几个老员工之间的关系像一锅粥。</p>
<p>你去问前任。前任说：这些事我当年也想动，一动就是一堆麻烦，就先放着了。</p>
<p>这一放，就是五年。</p>
<p>蛊卦讲的就是这件事。</p>
<p>「蛊」这个字的本义，是器皿放久了生虫。山风蛊，上艮下巽——风被山挡住，进不去，出不来，郁在那儿，久了就腐了。</p>
<p>但蛊卦的卦辞给得很高：「元亨，利涉大川。」</p>
<p><strong>在一片腐败之象里，《周易》给了最高评价。</strong>孔颖达说不含糊：「蠱者事也。有事營為，則大得亨通。有為之時，利在拯難。」</p>
<p>有事可做，就能大通。该干事的时代，好处在于救难。</p>
<p><strong>烂摊子不是灾难，是机会。</strong>这话听着像鸡汤，可它是蛊卦的第一句。</p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初六-干父之蛊-有子-考无咎-厉终吉-接烂摊子-">初六 · 干父之蛊，有子，考无咎，厉终吉 —— 接烂摊子，先接手那份心</h3>
<blockquote class="pw-quote"><strong>初六：干父之蛊，有子，考无咎，厉终吉。</strong><br>象曰：干父之蛊，意承考也。</blockquote>
<p><strong>你现在在这个位置：你刚接手。烂摊子摆在那儿，所有人都在看你怎么动第一刀。</strong></p>
<p>「干父之蛊」——「干」是整治、是担当。「父之蛊」是父辈留下的烂账。</p>
<p>「有子，考无咎」——有这么一个儿子，死去的父亲就没有过错了。</p>
<p>「厉终吉」——有危险，最后吉。</p>
<p><strong>这一爻最要紧的是象传那四个字：「意承考也」。</strong></p>
<p>承接的是父亲的<strong>心意</strong>，不是父亲的做法。</p>
<p>孔颖达讲得很清楚：「凡堪幹父事，不可小大損益一依父命，當量事制宜以意承考而已。」</p>
<p>你接手父辈的事，不能大大小小都照他的原话来，得衡量事情来定，<strong>接的是他的用意</strong>。</p>
<p>具体怎么做：</p>
<p>- <strong>先问「他当年想干成什么」，再问「他为什么没干成」。</strong>第一个问题的答案你要继承，第二个问题的答案你要推翻。</p>
<p>- <strong>第一刀砍在流程上，不砍在人上。</strong>砍人会引起抵抗，砍流程不会。而且流程的毛病往往就是人的毛病的原因。</p>
<p>- <strong>前三个月只做一件事：把真实情况摸清楚。</strong>别急着改革。这一爻的「厉」就是危险，危险来自你还没看清就动手。</p>
<p>霍光辅政，接手的是汉武帝晚年那一堆烂账：赋税重、刑罚严、民怨深、国库空。他没有推翻武帝的路线，他做的是把武帝晚年那道「轮台罪己诏」的意思接着往下走——<strong>罢劳役、轻赋税、与民休息。</strong>他承接的是武帝最后想明白的那个东西。</p>
<p><strong>什么情况可以不管前任的想法：</strong>如果前任是被赶走的，而且他做的事本身就是问题——那就别谈承接。这时候你要做的是切割，越干净越好。</p>
<h3 id="p-九二-干母之蛊-不可贞-有些账-不能硬来">九二 · 干母之蛊，不可贞 —— 有些账，不能硬来</h3>
<blockquote class="pw-quote"><strong>九二：干母之蛊，不可贞。</strong><br>象曰：干母之蛊，得中道也。</blockquote>
<p><strong>你现在在这个位置：你要动的是长辈，或者是你的老上级，或者是一个你得罪不起的人留下的规矩。</strong></p>
<p>「干母之蛊」——母之蛊跟父之蛊不同。父是刚的，母是柔的。</p>
<p>「不可贞」——「贞」在这里是固守、硬来的意思。<strong>你不能硬来。</strong></p>
<p>孔颖达说得坦白：「婦人之性難可全正，宜屈己剛，不可固守貞正。」你得把自己那股刚劲儿弯下来，不能死守着你认为对的那个道理。</p>
<p><strong>这一爻说的是分寸。</strong></p>
<p>同样是在整治积弊，初六和九三面对的是「父」，可以刚；九二面对的是「母」，必须柔。</p>
<p>具体怎么做：</p>
<p>- <strong>别用「这是为了你好」开场。</strong>这句话一出口，对方就进入了防守状态。换成「这件事我拿不准，想请您帮我看看」。</p>
<p>- <strong>一次只动一件事。</strong>对长辈的改革，一次动太多，她会觉得你在否定她的一辈子。</p>
<p>- <strong>把新做法包装成她的老办法。</strong>「这个做法其实就是您当年说的那个意思，我把它写细了一点。」这不是骗人，这是给人台阶。</p>
<p>- <strong>留一件她的东西不动。</strong>办公室的摆设、每周的例会、某个老规矩——留一件。这件东西是她的位置。</p>
<p>唐太宗要立长孙无忌、房玄龄这些人，长孙皇后几次拦着，说不要让自己的娘家人掌权。太宗没有硬顶，他听了。<strong>皇后死后，他才把长孙无忌用到极致。</strong>他在这件事上用的是柔，不是刚。</p>
<p><strong>什么情况必须硬：</strong>如果「母之蛊」已经涉及合规、安全、法律，那就没有柔的余地。这时候不当面顶，改成书面报、层级报，让规矩来出面。</p>
<h3 id="p-九三-干父之蛊-小有悔-无大咎-动手太猛-会疼一">九三 · 干父之蛊，小有悔，无大咎 —— 动手太猛，会疼一下</h3>
<blockquote class="pw-quote"><strong>九三：干父之蛊，小有悔，无大咎。</strong><br>象曰：干父之蛊，终无咎也。</blockquote>
<p><strong>你现在在这个位置：你已经开始动了，而且动得不小。有人在背后说你翻脸不认人。</strong></p>
<p>「小有悔，无大咎」——会有一点后悔，但没有大的过错。</p>
<p>孔颖达说九三的问题在于「以剛幹事而無其應」——你用刚的手段干事，可你上面没有一个接应你的人。<strong>你一个人扛着往前推。</strong></p>
<p><strong>这一爻给的判决是：可以。</strong>悔是小悔，咎是没有大咎。象传更明确：「终无咎也。」</p>
<p>具体怎么做：</p>
<p>- <strong>认下「小有悔」。</strong>别去解释自己为什么必须这么做。解释就变成了辩解，辩解会让人觉得你心虚。</p>
<p>- <strong>把大动作拆成小动作发。</strong>一次宣布十项改革，人心会散。一周发一项，节奏就稳了。</p>
<p>- <strong>每次动完，给被影响的人一个出口。</strong>调到别的岗位、给一笔补偿、给一个过渡期。你不需要人人满意，你需要没有人在暗中攒劲。</p>
<p>- <strong>找一个在上面替你说话的人。</strong>九三的毛病就是「无其应」。你自己找不到，就认个领导当靠山，把改革挂到他名下。</p>
<p>商鞅在秦国变法，徙木立信、废井田、开阡陌、行县制，一次比一次狠。他动的时候秦孝公在上面顶着，所以推得下去。<strong>孝公一死，商鞅就被车裂了——因为他的上面没人了。</strong></p>
<p><strong>什么情况要慢下来：</strong>如果反对的人不是被改革损害的人，而是跟你没关系的一批人，那你的改革就伤到了不该伤的地方。这时候停一停，改一改再发。</p>
<h3 id="p-六四-裕父之蛊-往见吝-拖着不办-是最贵的选项">六四 · 裕父之蛊，往见吝 —— 拖着不办，是最贵的选项</h3>
<blockquote class="pw-quote"><strong>六四：裕父之蛊，往见吝。</strong><br>象曰：裕父之蛊，往未得也。</blockquote>
<p><strong>你现在在这个位置：你看见了问题，你也知道该动。可你觉得现在不是时候，先放一放。</strong></p>
<p>「裕父之蛊」——「裕」是宽、是纵容。<strong>你宽纵了父辈留下的这些问题。</strong></p>
<p>孔颖达说得很直：「體柔當位，幹不以剛，而以柔和能容裕父之事也。」你性情柔，又在位置上，你不用刚的手段去治，反而用柔和的态度包容了这些问题。</p>
<p>结果：「往见吝」——往前走，会碰上一堆难堪。</p>
<p><strong>这一爻是全卦最需要警惕的一条，因为它长得最像「稳重」。</strong></p>
<p>它会告诉你：现在团队刚稳定；现在提这个会得罪人；等我先把业绩做起来再动。</p>
<p>具体自查：</p>
<p>- <strong>这个问题你第一次发现是什么时候？</strong>如果超过三个月你还没动手，你就在「裕」。</p>
<p>- <strong>你有没有把「等条件成熟」当成一个理由用过三次往上？</strong>三次之后，它就不是理由了，是借口。</p>
<p>- <strong>你有没有在心里给它找过一个说法？</strong>比如「这也不是什么大问题」「行业里都这样」。找了，就是「裕」。</p>
<p>汉元帝的时候，外戚和宦官的问题已经很明显了，萧望之、周堪这些人都提出来要整治。元帝性格柔，每次都说好，每次都被宦官弘恭、石显几句话拦下来。<strong>他在位十六年，这个问题一天都没解决。到他儿子成帝的时候，王氏外戚已经尾大不掉，最后王莽篡了汉。</strong></p>
<p><strong>什么情况可以缓一缓：</strong>如果这个问题不在你的权责范围内，动了要越权，那就先报上去，别自己扛。这种情况下的「缓」是合规，不是拖延。</p>
<h3 id="p-六五-干父之蛊-用誉-干成了-功劳还得给出去">六五 · 干父之蛊，用誉 —— 干成了，功劳还得给出去</h3>
<blockquote class="pw-quote"><strong>六五：干父之蛊，用誉。</strong><br>象曰：干父用誉，承以德也。</blockquote>
<p><strong>你现在在这个位置：你是这件事的主事人，但上面还有一个名义上的负责人，或者前任还挂着名。</strong></p>
<p>「干父之蛊，用誉」——整治父辈的烂摊子，得到的是声誉。</p>
<p>孔颖达讲：「以柔處尊，用中而應，以此承父，用有聲譽。」你柔、处尊位、守中道，用这个来承接父辈，所以有声誉。</p>
<p>象传说的「承以德也」是重点：<strong>承接用的是德，不是威。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>公开说话的格式是：「这是前任打下的底子，咱们把几个环节补上了」。</strong>把「补」说成「补」，不要说「纠正」。</p>
<p>- <strong>功劳要分三份：</strong>一份给前任留个面子，一份给现在干活的人，一份留给你自己。全给自己，你下次推行什么都推不动。</p>
<p>- <strong>该署名的署名。</strong>「用誉」不是让你当无名英雄。你在报告上、在会议上都要有你的名字，只是别说成你一个人的功劳。</p>
<p>- <strong>留一份完整的记录。</strong>你把原来的状况、你做了什么、现在什么状况，全部写下来存档。这份东西现在没用，将来有用。</p>
<p>唐玄宗刚即位的时候，接手的是武则天晚年到中宗、睿宗这几十年留下的乱局：官场臃肿、政变频繁、佛寺占了大量土地人口。他用姚崇，姚崇提了十条，他条条答应。<strong>姚崇改革的时候，每一条都要先跟玄宗说清楚这跟先帝的哪条政策是一脉的。</strong>他做的是新事，用的是旧名。</p>
<p><strong>什么情况不用分功：</strong>如果前任已经明确被定性为失败者，你还要给他留面子，会让人怀疑你的立场。这种时候要切割得干净，把功劳记给现在干活的人。</p>
<h3 id="p-上九-不事王侯-高尚其事-有些摊子-你不必接">上九 · 不事王侯，高尚其事 —— 有些摊子，你不必接</h3>
<blockquote class="pw-quote"><strong>上九：不事王侯，高尚其事。</strong><br>象曰：不事王侯，志可则也。</blockquote>
<p><strong>你现在在这个位置：这个摊子你也看到了，你也有能力动。可你不打算接了。</strong></p>
<p>「不事王侯，高尚其事」——不去侍奉王侯，把自己的事看得很高。</p>
<p>孔颖达说上九「最處事上，不復以世事為心，不系累於職位」——他站在所有事情的最上面，不再把世间的事放在心上，不被职位拴住。</p>
<p><strong>这是蛊卦给的最后一条出路：你可以不干。</strong></p>
<p>象传给了三个字给出路背书：「志可则也」——他的志向可以当法则。</p>
<p>具体怎么做：</p>
<p>- <strong>先判断这是不是真话。</strong>你要问自己：我是真的不认同这件事，还是我只是怕难、怕得罪人？后者叫逃，不叫高。</p>
<p>- <strong>不接的时候把话说清楚。</strong>别说「我能力不够」这种场面话。说你真实的想法：方向不对、条件不够、你的做法跟他们的不一样。</p>
<p>- <strong>退出来之后别站远处指指点点。</strong>「高尚其事」的意思是你的心思在别处，不是在批评处。</p>
<p>- <strong>留一条路回来。</strong>除非你已经彻底翻脸，否则别把关系弄死。世上的事转得快。</p>
<p>范蠡辅佐越王勾践二十多年，灭吴之后他跟勾践辞行，说「君行令，臣行意」，然后就走了。他给文种留了一句话：「飞鸟尽，良弓藏；狡兔死，走狗烹。」<strong>范蠡走了，改名叫陶朱公，去做生意；文种留下了，被勾践赐死。</strong></p>
<p><strong>什么情况必须接：</strong>如果这个摊子你不接就没人接，而且它塌了会伤到很多人——那就接。上九是给有余地的人准备的出路，不是给所有人。</p>
<h3 id="p-最后-生虫的地方-也是能长出东西的地方">最后：生虫的地方，也是能长出东西的地方</h3>
<p>蛊卦后面接的是临卦。</p>
<p>「有事而後可大」——有了要办的事，然后才可能做大。</p>
<p>蛊卦六个爻，全都围绕一件事：<strong>「干」还是「不干」，以及怎么干。</strong></p>
<p>初六承接，九二柔和，九三猛一点，六四宽纵是错，六五分功，上九可以不干。</p>
<p>孔颖达在彖传里有一句解释「先甲三日，后甲三日」的话特别实在：新令发下去，人还不熟，你得在发令之前讲三天，发令之后再讲三天，讲完还不改，才能罚。</p>
<p><strong>改革真正的成本不在方案，在说服。</strong></p>
<p>蛊卦最后给你的一句话：</p>
<blockquote class="pw-quote">烂摊子不是别人留给你的包袱，是别人不敢动、留给你的机会。你要做的不是把它盖住，是戴上手套，一件一件往外掏。</blockquote>
  `,
  lin: `
<p>你刚上任。</p>
<p>会上你说话，所有人都在记。你定的方案，没人问为什么。你提的名字，人事那边当天就走流程。</p>
<p>这种感觉很好。好到你开始觉得，这就是常态了。</p>
<p>临卦讲的就是这段时间。</p>
<p>地泽临，上坤下兑——地在泽的上面。地比泽高，从上往下看着泽，这是上位者临下的样子。</p>
<p>「临」这个字有两个意思。一个是居高临下地看着、管着；一个是亲自到场。</p>
<p><strong>两个字都要有。</strong></p>
<p>临卦的卦辞给得很高：「元亨利贞。」《周易》里四德俱全的卦不多，临卦是其中之一。因为下面两个阳爻正在往上长，阳气渐盛，这是最好的时候。</p>
<p>但卦辞的最后一句是一把刀：<strong>「至于八月有凶。」</strong></p>
<p><strong>阳气刚起来的时候，就要先想到它退下去的那天。</strong></p>
<p>孔颖达说得很直：「以物盛必衰，陰長陽退……聖人作《易》以戒之也。」</p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初九-咸临-贞吉-靠感-不靠压">初九 · 咸临，贞吉 —— 靠感，不靠压</h3>
<blockquote class="pw-quote"><strong>初九：咸临，贞吉。</strong><br>象曰：咸临贞吉，志行正也。</blockquote>
<p><strong>你现在在这个位置：你刚开始管人。你手上没什么权威，但你想让人听你的。</strong></p>
<p>「咸临」——「咸」是感。<strong>用感化的方式去临下。</strong></p>
<p>这一爻的重点在「感」字上。你刚上来，位置是新的，人也是新的。你手上没有积累下来的威，也没有欠过谁的人情。</p>
<p><strong>你唯一有的东西，是你自己。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先做一件让人看得见的具体事。</strong>不是开会，是干活。你上手把一件别人拖着没做的事做了，比讲十次话管用。</p>
<p>- <strong>把标准亮出来，而且要自己先做到。</strong>你说这个季度不许迟到，你自己先三个月不迟到。</p>
<p>- <strong>记住每个人的名字和他们手上在办的事。</strong>这件事很土，但效果比任何管理技巧都直接。</p>
<p>孔颖达说这一爻「有感之而臨，志行得正」——你感化别人来管，是因为你的志是正的。<strong>感化不是技巧，是底色。</strong>你心里不正，感出来的是假的，人一眼能看出来。</p>
<p>刘邦进关中，第一件事是约法三章，第二件事是封府库、还军霸上。<strong>他没有急着立威，他先让关中的人看见他不拿东西、不扰民。</strong>后来楚汉相争，关中的粮和兵源源不断地往他那儿送。</p>
<p><strong>什么情况别讲感化：</strong>如果这里已经乱到没人听指挥，那就先立法度。乱的场子里谈感化，等于告诉所有人你现在可以乱来。</p>
<h3 id="p-九二-咸临-吉-无不利-感化可以做-但命令不能全">九二 · 咸临，吉，无不利 —— 感化可以做，但命令不能全听</h3>
<blockquote class="pw-quote"><strong>九二：咸临，吉，无不利。</strong><br>象曰：咸临，吉无不利，未顺命也。</blockquote>
<p><strong>你现在在这个位置：你跟上面那个人的关系还不错，他信任你。可有些事他让你做，你心里觉得不对。</strong></p>
<p>这一爻跟初九同为「咸临」，但多了一句「无不利」，而且象传里藏了一个大转折——<strong>「未顺命也」。</strong></p>
<p>孔颖达把这层挖出来了：「二雖與五相應，二體是剛，五體是柔，兩雖相感，其志不同。若純用剛往，則五所不從；若純用柔往，又損己剛性，必須商量事宜，有從有否，乃得無不利也。」</p>
<p><strong>你跟上面的意见不完全一致。全听他的，你办不成事；全都顶他，你办不下去。得商量。</strong></p>
<p>「未顺命」不是让你抗命，是让你<strong>不要什么都顺</strong>。</p>
<p>这是临卦最难拿捏的一爻。孔颖达说这是「君臣上下献可替否之义」——你觉得对的就献上去，觉得不对的就顶回来。</p>
<p>具体怎么做：</p>
<p>- <strong>分清楚哪些是方向，哪些是方法。</strong>方向听他的，方法上要有你的主张。</p>
<p>- <strong>反对的时候给替代方案。</strong>「这个做不了」是顶撞，「这个这么做行不行」是商量。</p>
<p>- <strong>反对要私下提，执行要公开做。</strong>你私下提了，他改了，你在会上要第一个执行，让所有人看见你们是一条心。</p>
<p>- <strong>把不同意的地方写下来。</strong>过一段时间回头看，你就知道你的判断到底准不准。</p>
<p>魏征跟唐太宗就是这样。太宗要去泰山封禅，魏征拦，说现在户口未复、仓廪尚虚，封禅是给外邦看的排场，不是当务之急。<strong>太宗没去。</strong>魏征一辈子顶了太宗两百多次，太宗说他是一面镜子。</p>
<p><strong>什么情况必须全听：</strong>如果命令涉及合规、安全、法律红线，那就没有商量的余地，照做，或者走。这一爻讲的是方法上的不同调，不是底线上的不同调。</p>
<h3 id="p-六三-甘临-无攸利-既忧之-无咎-靠甜言蜜语管人">六三 · 甘临，无攸利。既忧之，无咎 —— 靠甜言蜜语管人，管不住</h3>
<blockquote class="pw-quote"><strong>六三：甘临，无攸利。既忧之，无咎。</strong><br>象曰：甘临，位不当也。既忧之，咎不长也。</blockquote>
<p><strong>你现在在这个位置：你手里其实没什么硬东西，你靠的是好话、人情、笑脸。</strong></p>
<p>「甘临」——「甘」是甜。用甜的东西去临下。</p>
<p>孔颖达解释得毫不留情：「甘美諂佞也。履非其位，居剛長之世，而以邪說臨物。」你不在正位上，又赶上阳气正在长的时候，你用谄媚的话去管人。</p>
<p><strong>结论是「无攸利」——一点好处都没有。</strong></p>
<p>但这一爻留了一个口子：「既忧之，无咎。」「既」是尽。<strong>你要是能把这个危险想透，就没有错。</strong></p>
<p>象传补了一句「咎不长也」——错不会长久。</p>
<p>具体怎么做：</p>
<p>- <strong>先把「好好先生」这个身份摘掉。</strong>你不敢批评人、不敢定标准、不敢拒绝，底下的人嘴上说你好，心里不服你。</p>
<p>- <strong>定一条硬规矩，并且执行第一次。</strong>不用多，一条就够。谁碰谁承担后果，第一次必须执行。</p>
<p>- <strong>把讨好换成信息。</strong>你不给好处，就给大家准确的信息：上面要什么、现在在哪、下一步去哪。信息是最便宜的权威。</p>
<p>- <strong>承认自己在讨好谁。</strong>你自己心里清楚，你对哪几个人特别好，是因为你怕他们。把他们找出来。</p>
<p>汉元帝刘奭做太子的时候就以「宽仁好儒」闻名，即位之后对群臣和宦官都很客气，谁说话他都说好。宦官弘恭、石显专权，他明明知道，还是不忍心下手。<strong>他一生都在当好人，汉室也从他手上开始走下坡。</strong></p>
<p><strong>什么情况可以靠人情：</strong>如果是小团队、老班底，大家在一起很多年，那讲人情是对的。判断标准是：你讲的这个人情，是不是用来代替该做的事。是，就错了。</p>
<h3 id="p-六四-至临-无咎-亲自到位">六四 · 至临，无咎 —— 亲自到位</h3>
<blockquote class="pw-quote"><strong>六四：至临，无咎。</strong><br>象曰：至临无咎，位当也。</blockquote>
<p><strong>你现在在这个位置：你不需要指挥谁，你的任务是亲自到那个关键的地方去。</strong></p>
<p>「至临」——「至」是到。<strong>亲自到场。</strong></p>
<p>孔颖达说六四「履順應陽，不畏剛長，而己應之」——它顺着走，迎着上面的阳，不怕阳气长。</p>
<p>这一爻跟前面三爻不同。前面都在讲怎么管人，这一爻讲的是<strong>你自己到位。</strong></p>
<p>象传给的「位当也」，讲的就是这个位置对了。</p>
<p>具体怎么做：</p>
<p>- <strong>找到那个「你不到就出问题」的地方。</strong>每个组织都有这么一两个点，通常是最前端或者最末端。你去待一段时间。</p>
<p>- <strong>去了不要说，先看。</strong>你一到场就开始指点，所有人都会开始表演给你看。先待三天再说。</p>
<p>- <strong>带回一个具体的改动。</strong>不是一份调研报告，是一件事。你把看到的第一个堵点当场解决掉。</p>
<p>- <strong>别常驻。</strong>「至临」是到这个位置，不是占住这个位置。你待太久，下面的人就没有主见了。</p>
<p>汉宣帝的时候，渤海郡闹饥荒，盗贼很多。朝廷派龚遂去做太守。龚遂到任之后，没有先调兵，他一个人单车到了郡界，解散了追捕盗贼的官吏，然后开仓放粮、劝民农桑。<strong>他到的是现场，不是衙门。</strong></p>
<p><strong>什么情况不用亲自到：</strong>如果这件事有比你更专业的人在做，你去了反而是干扰。至临是到关键的地方，不是到所有的地方。</p>
<h3 id="p-六五-知临-大君之宜-吉-用脑子管-不是用腿管">六五 · 知临，大君之宜，吉 —— 用脑子管，不是用腿管</h3>
<blockquote class="pw-quote"><strong>六五：知临，大君之宜，吉。</strong><br>象曰：大君之宜，行中之谓也。</blockquote>
<p><strong>你现在在这个位置：你管的人多了，事情杂了。你发现你一天只有二十四小时，忙不过来。</strong></p>
<p>「知临」——「知」通「智」。<strong>用智慧去临下。</strong></p>
<p>这一爻是全卦最高的一爻。孔颖达讲得极漂亮：「處於尊位，履得其中，能納剛以禮，用建其正，不忌剛長而能任之。」</p>
<p>处在尊位上，守中道，能用礼来接纳刚强的人，让他们各就其位。<strong>不因为下面有能干的人而忌惮，反而放手用他们。</strong></p>
<p>结果就是：「聰明者竭其視聽，知力者盡其謀能。」聪明人把他的见闻都用上，有本事的人把他的谋略都用上。</p>
<p><strong>这一爻的功夫在心胸，不在方法。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>列出三个人：比你聪明的、比你懂业务的、比你能镇的。</strong>你有没有真的在用他们，还是只是供着？</p>
<p>- <strong>把「这事我来办」这句话戒掉。</strong>你说一次，就有一个人不用想了。</p>
<p>- <strong>定标准，不定做法。</strong>你告诉他要什么结果，别告诉他怎么走。</p>
<p>- <strong>容忍下属比你做得好看。</strong>这一点最难。你做得到，你的盘子就比你自己大得多。</p>
<p>刘邦在洛阳宫摆酒问群臣，说我为什么能得天下，项羽为什么失天下。有人说是因为他赏罚分明。刘邦说：运筹帷幄我不如张良，镇国家、抚百姓、给馈饷我不如萧何，连百万之军、战必胜攻必取我不如韩信。<strong>这三个人都是人杰，我能用他们，所以取天下。</strong></p>
<p><strong>什么情况必须自己上手：</strong>如果是紧急的、错了就全盘皆输的事，先自己盯到稳，再交出去。知临是常态，不是所有时候。</p>
<h3 id="p-上六-敦临-吉-无咎-到最后-厚道一点">上六 · 敦临，吉，无咎 —— 到最后，厚道一点</h3>
<blockquote class="pw-quote"><strong>上六：敦临，吉，无咎。</strong><br>象曰：敦临之吉，志在内也。</blockquote>
<p><strong>你现在在这个位置：你已经不在管事的核心了。你在边上，看着下一拨人在忙。</strong></p>
<p>「敦临」——「敦」是厚。<strong>用敦厚的心去临下。</strong></p>
<p>上六在坤卦的最上面，位置最高，离下面的事最远。</p>
<p>孔颖达说：「敦厚而為臨，志在助賢。」<strong>它的心思在帮那些贤能的人。</strong></p>
<p>象传的「志在内也」——心还在里面。你不在了，但你还在意。</p>
<p>具体怎么做：</p>
<p>- <strong>不插手，但给资源。</strong>你手上还有的东西：人脉、经验、信誉。这些东西给出去，比给意见有用。</p>
<p>- <strong>只对一个人提意见，不对所有人提。</strong>你给所有人提意见，就是干扰。</p>
<p>- <strong>有人做得不如你的时候，忍住。</strong>你当年也是这么过来的。</p>
<p>- <strong>当那个兜底的人。</strong>底下的人知道上面有人在，出手会稳一些。</p>
<p>萧何死后，曹参接任丞相。曹参什么事都不改，全按萧何定的来，人称「萧规曹随」。<strong>曹参不是不作为，他是知道萧何那一套已经跑通了，他改就是添乱。</strong>他在位三年，天下安定。</p>
<p><strong>什么情况不能敦厚：</strong>如果底下的人正在走歪路，你还在那儿厚道地看着，那不是敦厚，是失职。敦临的前提是方向正确。</p>
<h3 id="p-最后-八月会来-你得先知道">最后：八月会来，你得先知道</h3>
<p>临卦后面接的是观卦。</p>
<p>「物大然後可觀」——东西大了，然后才值得看。</p>
<p>临卦六个爻，从初九的感化，到九二的商量，到六三的讨好，到六四的到场，到六五的用人，到上六的厚道。<strong>它讲的是一整条路。</strong></p>
<p>但全卦最重的一句在卦辞里，不在这六个爻里：「至于八月有凶。」</p>
<p>孔颖达说，从临卦的建丑之月，到否卦的建申之月，中间正好八个月。三阴既盛，三阳方退，小人道长，君子道消。</p>
<p><strong>你手上那点势，是有保质期的。</strong></p>
<p>临卦最后给你的一句话：</p>
<blockquote class="pw-quote">你现在说话算数，不是因为你厉害，是因为时候到了你身上。趁着还算数，把该立的规矩立了，该带的人带出来。八月一到，你手上有什么，就只剩什么。</blockquote>
  `,
  guan: `
<p>你去参加了一场行业会。</p>
<p>台上那个人讲了四十分钟，PPT 做得一般，数据也不新。可你注意到一件事：全场没人在看手机。</p>
<p>他讲的东西，你有一半不认同。可你就是想听他把话说完。</p>
<p>散场的时候你在电梯里想：这个人到底强在哪儿？</p>
<p>观卦讲的就是这件事。</p>
<p>风地观，上巽下坤——风在地上吹，无所不至。这是遍观之象。</p>
<p>「观」在这卦里有两层。一层是自上而下地看：看民情、看形势、看人。一层是自下而上地看：看一个人值不值得跟，看一种做法值不值得学。</p>
<p><strong>两层其实是一件事：你看到的，和你被看到的，是同一件事的两面。</strong></p>
<p>观卦的卦辞用了一个祭祀的画面：「盥而不荐，有孚颙若。」</p>
<p>「盥」是灌酒降神那一下，「荐」是后面摆供品那一套。孔颖达说得很清楚：「可觀之事，莫過宗廟之祭盥，其禮盛也。」</p>
<p><strong>最打动人的，是诚意刚显、仪式还没铺开的那一下。</strong></p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初六-童观-小人无咎-君子吝-小孩看热闹">初六 · 童观，小人无咎，君子吝 —— 小孩看热闹</h3>
<blockquote class="pw-quote"><strong>初六：童观，小人无咎，君子吝。</strong><br>象曰：初六童观，小人道也。</blockquote>
<p><strong>你现在在这个位置：你刚进这个圈子，你看什么都新鲜，但你其实什么都没看懂。</strong></p>
<p>「童观」——像小孩子一样看。</p>
<p>小孩子看东西有个特点：<strong>看热闹，不看门道。</strong>谁嗓门大谁厉害，谁被围着谁厉害，谁穿得好谁厉害。</p>
<p>孔颖达说初六「處於觀時而最遠朝廷之美觀，是柔弱不能自進，無所鑒見」——它离核心最远，柔弱得走不进去，什么也鉴别不出来。</p>
<p><strong>但这一爻对小人说「无咎」，对君子说「吝」。</strong></p>
<p>为什么？因为一个跑腿的人只懂看热闹，没关系；一个要担事的人还只懂看热闹，那就要命了。<strong>「吝」是走窄了。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>承认自己在童观。</strong>这是最重要的一步。大多数人在这个阶段的错不是看得浅，是以为自己看得深。</p>
<p>- <strong>找一个人，把他的话当参照。</strong>你看不懂的时候，先看一个你信得过的人怎么看这件事。不是照抄他的判断，是看他注意什么。</p>
<p>- <strong>少下结论，多记事实。</strong>你现在的判断八成是错的，但事实不会错。你把今天看到的细节写下来，一年后回看，你会知道谁在裸泳。</p>
<p>- <strong>别急着站队。</strong>看不懂的时候站队，是替别人的判断买单。</p>
<p>刘邦刚起兵的时候，身边是一批沛县的兄弟。他看不出谁行谁不行，他就做了一件事：<strong>谁说的都应，谁给的都收，然后看结果。</strong>慢慢地，张良、陈平这些人从一堆人里显出来了。</p>
<p><strong>什么情况不用深究：</strong>如果你在这件事里只是个过路的，那就继续童观。不是所有事都值得你看懂。</p>
<h3 id="p-六二-窥观-利女贞-门缝里看人">六二 · 窥观，利女贞 —— 门缝里看人</h3>
<blockquote class="pw-quote"><strong>六二：窥观，利女贞。</strong><br>象曰：窥观女贞，亦可丑也。</blockquote>
<p><strong>你现在在这个位置：你只能通过一个很窄的口子了解外面。可能是一个中间人，可能是一个群，可能是某个人转述的消息。</strong></p>
<p>「窥观」——从门缝里往外看。</p>
<p>孔颖达讲六二「既是陰爻，又處在卦內，性又柔弱，唯闚竊而觀」——你性子柔，又在里面，只能偷着往外看。</p>
<p>卦辞说「利女贞」，意思是这个样子适合女子的贞守。象传补了一句更狠的：「亦可丑也。」</p>
<p><strong>能守，但难看。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先列出你的信息源有几个。</strong>如果只有一个，或者都是同一个圈子里的人转的，那你就在窥观。</p>
<p>- <strong>找第二个源，而且要跟第一个源立场不同的。</strong>这一点最关键。你不需要新源更准确，你只需要它不一样。</p>
<p>- <strong>自己去看一眼原始的东西。</strong>别只看别人的转述。去看原文、去现场、去问直接相关的人。</p>
<p>- <strong>别把「我听说」当成判断的依据。</strong>你可以说「我听说」，但你不能基于「我听说」做决定。</p>
<p>东汉末年的何进，想诛杀宦官，何太后不同意。袁绍给他出的主意是召外兵进京逼太后。<strong>何进得到的所有信息都来自他身边那一小圈人。</strong>陈琳劝他，说这是「倒持干戈，授人以柄」，他不听。他进了宫，被宦官杀了，董卓进了洛阳。</p>
<p><strong>什么情况可以只看眼前：</strong>如果你的位置本来就只需要处理手上这一摊事，那门缝里看够了。<strong>关键是你要知道自己在门缝里。</strong></p>
<h3 id="p-六三-观我生-进退-看自己-决定进退">六三 · 观我生，进退 —— 看自己，决定进退</h3>
<blockquote class="pw-quote"><strong>六三：观我生，进退。</strong><br>象曰：观我生进退，未失道也。</blockquote>
<p><strong>你现在在这个位置：你卡在一个不上不下的地方。往前走有风险，往后退不甘心。</strong></p>
<p>「观我生」——「生」在这里是「动出」，就是你做出来的事。<strong>看你自己做出来的东西。</strong></p>
<p>六三在下卦的最上面，是「有可進之時」；又在上升的门口，是「可退之地」。孔颖达说「時可則進，時不可則退，觀風相幾」。</p>
<p><strong>这一爻是前面两爻的解药。</strong>童观是看不见，窥观是看得窄。观我生是<strong>转过头来看自己</strong>。</p>
<p>具体怎么做：</p>
<p>- <strong>把你手上做成的事列出来，只写事实。</strong>写「我做了什么、什么结果、谁认」，不要写「我学到了什么」。这一条能筛掉一大半的自我感动。</p>
<p>- <strong>看你的时间都花在哪儿了。</strong>把上周的时间按类分一下。你会发现你的行为跟你说的方向经常对不上。</p>
<p>- <strong>找一个你信任的人，让他用三个词形容你。</strong>不解释，不辩解，记下来。</p>
<p>- <strong>然后决定进退。</strong>判断标准很简单：<strong>如果继续做下去，你手上的东西会变多还是会变少？</strong></p>
<p>曾国藩在江西打仗那几年，屡战屡败，被革了兵权，回家守制。他在家里待了一年多，把自己这些年写给别人的信、写过的奏折、犯过的错全部翻了一遍。他后来跟人说，那一年多他最大的收获是看出来自己「太自傲、太自是」。<strong>再出来的时候，他待人接物的方式变了。</strong></p>
<p><strong>什么情况不用自省：</strong>如果你正处在必须往前冲的阶段，那就冲。观我生是用来定方向的，不是用来天天照镜子的。</p>
<h3 id="p-六四-观国之光-利用宾于王-去看最好的">六四 · 观国之光，利用宾于王 —— 去看最好的</h3>
<blockquote class="pw-quote"><strong>六四：观国之光，利用宾于王。</strong><br>象曰：观国之光，尚宾也。</blockquote>
<p><strong>你现在在这个位置：你有机会接触到这个行业里最好的一批人，或者最好的一个地方。</strong></p>
<p>「观国之光」——看一个国家的光景。「利用宾于王」——适合去做君王的宾客。</p>
<p>孔颖达说六四「最近至尊」，它离最高的位置最近，所以能看到最好的东西。</p>
<p><strong>这一爻给的是一条最快的成长路径：去最好的地方，看最好的人怎么做。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>去之前定一个问题。</strong>你现在最想不通的那件事是什么？去就是为了找这个答案。不带问题去看，你看的全是别人的排场。</p>
<p>- <strong>看流程，不看结论。</strong>结论你早就知道，流程你才不知道。他们开会怎么开、决策怎么定、吵架怎么吵——这些才是光。</p>
<p>- <strong>找机会说一句话。</strong>「利用宾于王」是去做客，做客也要留下印象。在会上问一个好问题，比在场外递十张名片有用。</p>
<p>- <strong>回来之后三天内写一份东西。</strong>写给自己看。过了一个星期，细节全忘了。</p>
<p>孔子到周的都城去，问礼于老子。老子跟他讲了一段话，大意是：你提到的那些人，骨头都烂了，只剩下话还在。君子得其时则驾，不得其时则蓬累而行。<strong>孔子回来之后，跟弟子说「吾今日见老子，其犹龙邪」。</strong>他去看了一趟，看见的不是礼，是另一种活法。</p>
<p><strong>什么情况不必去：</strong>如果你现在的阶段是把手上的活做扎实，那别老往外跑。观国之光是给你打开视野的，不是给你逃避手上的事的。</p>
<h3 id="p-九五-观我生-君子无咎-看下面的人-就知道你是什">九五 · 观我生，君子无咎 —— 看下面的人，就知道你是什么样</h3>
<blockquote class="pw-quote"><strong>九五：观我生，君子无咎。</strong><br>象曰：观我生，观民也。</blockquote>
<p><strong>你现在在这个位置：你是这个摊子的负责人。你想知道自己做得怎么样。</strong></p>
<p>又是「观我生」，但九五的观我生跟六三不一样。</p>
<p>六三看的是自己的行为，九五看的是<strong>下面人的状态</strong>。</p>
<p>象传四个字把这层挑明了：<strong>观民也。</strong></p>
<p>孔颖达说：「九五居尊，為觀之主。四海之內，由我而觀，而教化善，則天下有君子之風；教化不善，則天下著小人之俗……有君子之風著，則無咎也。」</p>
<p><strong>下面是什么风气，就是上面是什么人。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>看三种人：</strong>混得最好的、最不受待见的、刚走的那批。这三种人的样子就是你的样子。</p>
<p>- <strong>问一个反向的问题：</strong>在我这里，什么样的人升得最快？答案如果是「会来事儿的」，那你嘴上说的和实际奖励的是两回事。</p>
<p>- <strong>听坏消息的渠道要单设。</strong>你在这个位置上，好消息会自己找上来，坏消息会自己绕开你。</p>
<p>- <strong>看离职面谈记录。</strong>那是最真实的一份材料，比任何调研都准。</p>
<p>唐太宗有一次问魏征，说为什么历史上有些君主一开始明白，后来就糊涂了。魏征答：因为「初则竭诚以待下，既得志则纵情以傲物」。太宗又问他，现在朝中什么事做得不好。魏征说了十条。<strong>太宗把这些都记下来，贴在墙上。</strong></p>
<p><strong>什么情况不用看民：</strong>如果你刚接手，下面还没有形成稳定的风气，那先别急着下结论。等三个月再看。</p>
<h3 id="p-上九-观其生-君子无咎-你被看着">上九 · 观其生，君子无咎 —— 你被看着</h3>
<blockquote class="pw-quote"><strong>上九：观其生，君子无咎。</strong><br>象曰：观其生，志未平也。</blockquote>
<p><strong>你现在在这个位置：你已经不在这个位置上了，但你还在大家的视线里。</strong></p>
<p>「观其生」——看他的作为。上九在所有事情的最上面，它成了一个被观察的对象。</p>
<p>孔颖达说：「最處上極，高尚其志……為天下觀其巳之道。」</p>
<p><strong>你是被天下看着的那个人。</strong></p>
<p>象传的「志未平也」是这一爻最微妙的地方。孔颖达解释：「特處異地，為無所觀，不為平易。和光流通，志未與世俗均平。」</p>
<p>你已经不在局里了，但你心里还没放平。<strong>世上没有你担心的那些事了，可你自己还有挂虑。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>接受你是被看的。</strong>你已经退下来了，但你说的话还有人听。这个事实改不了。</p>
<p>- <strong>少评论。</strong>你评一句，别人就要揣摩十句。你越到后面，越要惜字。</p>
<p>- <strong>把位置让干净。</strong>该交的印章、该退的群、该辞的职务，一件不留。留一件，就有一堆人拿你当挡箭牌。</p>
<p>- <strong>给自己找一件新的、具体的事做。</strong>「志未平」的解法不是把志压下去，是把它换个地方放。</p>
<p>范蠡在越国灭吴之后走了，去了齐国，改名换姓做生意。齐国人发现他能干，请他做卿相。他做了几年，感叹说「居家则致千金，居官则至卿相，此布衣之极也。久受尊名，不祥」，然后<strong>把家财散给朋友乡邻，又换了地方。</strong></p>
<p><strong>什么情况可以继续站着：</strong>如果你的经验还有人在用，而且人家是真的需要，那就站着。上九讲的是慎重，不是消失。</p>
<h3 id="p-最后-你站在哪里看-就决定你能看到什么">最后：你站在哪里看，就决定你能看到什么</h3>
<p>观卦后面接的是噬嗑卦。</p>
<p>「可觀而後有所合」——看清楚之后，才谈得上合到一块儿。</p>
<p>观卦六个爻，从童观看到窥观，从观我生看到观国之光，最后到观其生。<strong>它是一整条视野扩展的路。</strong></p>
<p>孔颖达在彖传那里讲了一个很重的意思：「聖人以神道設教，而天下服矣。」圣人用那种看不见的东西来设教，天下就服了。</p>
<p><strong>最好的管理是不出声的。</strong>下面的人看着你做，就跟着做了。</p>
<p>观卦最后给你的一句话：</p>
<blockquote class="pw-quote">你想让别人变成什么样，最省事的办法不是去说他们，是让他们看见你。而这个「看见」，中间隔多远都挡不住。</blockquote>
  `,
  shike: `
<p>有个员工，你已经忍了他一年半。</p>
<p>能力有，脾气也有。活干得还行，但每次都要在会上跟你顶一句。客户投诉过两次，同事私下抱怨过很多次。你每次想说，到了嘴边又咽回去——招人难，项目紧，再忍忍吧。</p>
<p>这个「再忍忍」，你说了七次了。</p>
<p>噬嗑卦讲的就是这件事。</p>
<p>「噬」是咬，「嗑」是合。嘴里有个东西梗着，上下牙合不上，<strong>必须把它咬碎，才能合。</strong></p>
<p>火雷噬嗑，上离下震——上面是火，是明；下面是雷，是动。雷电交加，明察加上威动，这是执法的象。</p>
<p>噬嗑卦的卦辞只有五个字：「亨。利用狱。」</p>
<p><strong>适合断狱。</strong>《周易》里说得这么直接的卦不多。</p>
<p>孔颖达把「噬嗑」这两个字解得非常实在：「物在於口，則隔其上下，若齧去其物，上下乃合而得亨也。」</p>
<p>东西在嘴里，上下就隔开了。咬掉它，上下就合了，就通了。</p>
<p><strong>这一卦的重点不在狠，在「明」。</strong>雷电两个字，雷是威，电是明。<strong>没有明的威，是乱杀。</strong></p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初九-屦校灭趾-无咎-趁早-给他脚上戴个东西">初九 · 屦校灭趾，无咎 —— 趁早，给他脚上戴个东西</h3>
<blockquote class="pw-quote"><strong>初九：屦校灭趾，无咎。</strong><br>象曰：屦校灭趾，不行也。</blockquote>
<p><strong>你现在在这个位置：有个人刚犯了点小错。小到你觉得说出来显得自己小气。</strong></p>
<p>「屦校灭趾」——「校」是木枷，「屦校」是把枷戴在脚上，「灭趾」是枷大到把脚趾都遮住了。</p>
<p><strong>把脚给他锁上，让他走不了歪路。</strong></p>
<p>孔颖达把这一爻的道理讲得最透：「凡過之所始，必始於微，積而不已，遂至於著。罰之所始，必始於薄刑。薄刑之不已，遂至於誅。」</p>
<p>过错都是从微小的地方开始的，积起来就变大了。惩罚都是从轻的开始的，轻的不管就变成杀头。</p>
<p><strong>这一爻给的判决是「无咎」。它不是罚你，它是救你。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>当场说，不要攒。</strong>攒到年底绩效面谈的时候一起说，那是清算，不是管理。当场说，是提醒。</p>
<p>- <strong>说的时候对事不对人。</strong>「这个报告的数字咱们核对一下」比「你做事就是不细心」有用十倍。</p>
<p>- <strong>给对方一个明确的改法。</strong>「下次提前一天给我」——这种话比「你要注意」有用。</p>
<p>- <strong>小错必须有个后果，哪怕只是口头一句。</strong>没有后果的提醒，就是没有提醒。</p>
<p>周朝有个规矩，叫「三宥」：对犯了小错的人，先宽恕三次，三次不改才用刑。<strong>但宽恕的这三次，每一次都是明确说过、明确记过的。</strong>不是装作没看见。</p>
<p><strong>什么情况可以再宽一次：</strong>如果这是这个人的第一次，而且他平时表现确实好，那就再给一次。但这一次必须是明确说了的，不是默默放过。</p>
<h3 id="p-六二-噬肤灭鼻-无咎-咬得太深-但咬对了">六二 · 噬肤灭鼻，无咎 —— 咬得太深，但咬对了</h3>
<blockquote class="pw-quote"><strong>六二：噬肤灭鼻，无咎。</strong><br>象曰：噬肤灭鼻，乘刚也。</blockquote>
<p><strong>你现在在这个位置：你要处理一件错事，而犯错的人服气。可你出手的时候，比该出手的重了一点。</strong></p>
<p>「噬肤」——咬柔软的皮肉，最省力。「灭鼻」——咬得太深，把鼻子都陷进去了。</p>
<p>孔颖达说：「膚是柔脆之物，以喻服罪受刑之人也。」肤代表那些认罪服软的人。「乘剛而刑，未盡順道，噬過其分」——你性子刚，用刑的时候过了分寸。</p>
<p><strong>但这一爻的判决是「无咎」。</strong></p>
<p>为什么？因为「用刑得其所疾，謂刑中其理」——<strong>你刑中了那个理。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>该重的时候要重，但要知道自己重了。</strong>这一爻不是让你道歉，是让你心里有数。</p>
<p>- <strong>罚完就把事放下。</strong>你重了，对方认了，事情结了。你接下来如果因为心里过意不去而对这个人特别好，那才是真的坏规矩。</p>
<p>- <strong>把标准往回校一校。</strong>这次重了，下次同类的事就按这次的减一点。你心里得有一把越来越准的尺子。</p>
<p>- <strong>对认错的人，罚完之后给他机会。</strong>「无咎」的意思是这件事就这样了。你不追究，但也不补偿。</p>
<p>汉文帝时，有人偷了高庙里的玉环，廷尉张释之判了弃市。文帝大怒，说要族诛。张释之说：按律盗宗庙服御物就是弃市。如果偷个玉环就族诛，那将来有人挖了祖坟，你用什么刑？<strong>文帝最后同意了张释之的判决。</strong>他重了，但没过头。</p>
<p><strong>什么情况不要从重：</strong>如果对方认错的同时，已经有人因为你这次的处理受到了牵连，那就轻一点。惩罚的目的是止住它，不是扩大它。</p>
<h3 id="p-六三-噬腊肉-遇毒-小吝-无咎-咬硬肉-还崩了牙">六三 · 噬腊肉，遇毒，小吝，无咎 —— 咬硬肉，还崩了牙</h3>
<blockquote class="pw-quote"><strong>六三：噬腊肉，遇毒，小吝，无咎。</strong><br>象曰：遇毒，位不当也。</blockquote>
<p><strong>你现在在这个位置：你要处理一个人或者一件事，可你自己在这个局里的位置不够硬，或者你自己也不干净。</strong></p>
<p>「噬腊肉」——腊肉又硬又韧，咬不动。「遇毒」——不但咬不动，还中了毒。</p>
<p>孔颖达说：「三處下體之上，失政刑人，刑人不服。若齧其臘肉，非但難齧，亦更生怨咎。」</p>
<p>你处理人，人不服你，反过来还给你添了麻烦。</p>
<p><strong>「小吝，无咎」——有点难看，但没有大错。</strong></p>
<p>象传把原因点出来了：「位不当也」。<strong>你的问题不在你做的事，在你站的位置。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先停下。</strong>有毒的时候别硬咬。停下来看看毒从哪儿来。</p>
<p>- <strong>检查自己的手。</strong>你自己手上有没有同类的问题？有的话先处理自己，再来处理别人。你处理别人的时候被翻出旧账，是最难看的场面。</p>
<p>- <strong>换个方式。</strong>自己不出面，让制度出面。开会定标准，然后按标准执行，你只是执行者之一。</p>
<p>- <strong>找人背书。</strong>把你上面的那个人请到台前来。他站一次台，你的位置就不一样了。</p>
<p>唐中宗的时候，武三思和韦后专权，张柬之等五个大臣发动神龙政变，逼武则天退位。事后这五个人都封了王，可他们管不住武三思。<strong>张柬之每次上奏要治武三思，中宗都不接。</strong>几年之后这五个人全被流放，死在路上。他们手里的刀不够硬，位置也不对。</p>
<p><strong>什么情况可以硬咬：</strong>如果你确实在这个位置上，你有名正言顺的权责，那就咬。位不当的时候硬咬是找死，位当的时候不咬是失职。</p>
<h3 id="p-九四-噬干胏-得金矢-利艰贞-吉-咬到带骨头的">九四 · 噬干胏，得金矢。利艰贞，吉 —— 咬到带骨头的</h3>
<blockquote class="pw-quote"><strong>九四：噬干胏，得金矢，利艰贞，吉。</strong><br>象曰：利艰贞吉，未光也。</blockquote>
<p><strong>你现在在这个位置：你碰到一个硬茬。这个人有背景、有资源、有一批人。你动他，代价不小。</strong></p>
<p>「干胏」是带骨头的干肉。这是全卦最难咬的东西。</p>
<p>「得金矢」——金是刚，矢是直。<strong>你咬不动它，但你从里面得到了一样东西：刚直。</strong></p>
<p>孔颖达讲：「雖刑不能服物，而能得其剛直也。」</p>
<p><strong>你没赢，可你赢了另一样东西——你证明了自己是直的。</strong></p>
<p>「利艰贞，吉」——在艰难里守住正，吉。</p>
<p>象传补了三个字：<strong>「未光也」。</strong>光还没照到。你做的这件事，现在还没显出好处来。</p>
<p>具体怎么做：</p>
<p>- <strong>把「赢」这个目标换成「正」。</strong>你赢不了他，但你可以让所有人看见你不怕他。这两件事的价值不一样。</p>
<p>- <strong>准备长期。</strong>「艰」这个字的意思是过程会很难。做好一年、两年的准备，别指望一季度解决。</p>
<p>- <strong>留证据。</strong>这件事你不当场赢，就会在别的地方见分晓。你手上的东西要全，时间、事实、在场的人。</p>
<p>- <strong>别指望这次就收工。</strong>「未光也」，意思是这件事的意义不在这件事本身。</p>
<p>汉宣帝要收拾霍氏的时候，霍家的势力遍布朝堂，连皇后都是霍家的人。宣帝做的第一件事不是动手，是忍——霍光要还政他不要，霍家的人他一个不动。<strong>他在等，等霍家自己犯错。</strong>霍家谋反的事一露，他一次清干净。</p>
<p><strong>什么情况该放手：</strong>如果这个硬茬背后是更大的、你暂时碰不了的局面，而且你咬下去会伤到不该伤的人——那就先放着。记下来，等。</p>
<h3 id="p-六五-噬干肉-得黄金-贞厉-无咎-咬得动-但得小">六五 · 噬干肉，得黄金。贞厉，无咎 —— 咬得动，但得小心</h3>
<blockquote class="pw-quote"><strong>六五：噬干肉，得黄金，贞厉，无咎。</strong><br>象曰：贞厉无咎，得当也。</blockquote>
<p><strong>你现在在这个位置：你手上有权，你处理的事情不好办。但你能办，只是每一步都得掂量。</strong></p>
<p>「噬干肉」——比腊肉软，比鲜肉硬。</p>
<p>「得黄金」——黄是中，金是刚。<strong>你既守中了，又有刚性。</strong></p>
<p>孔颖达说：「以居於中是黃也，以柔乘剛是金也。既中而行剛，能行其戮。」</p>
<p>你在中位上，你又用刚的手段，所以你能执行下去。「貞厲無咎」——守正、有危险、没有错。</p>
<p><strong>这一爻的判词是一个很微妙的组合：可以做，但要一直提着心。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>每个判决都要写理由。</strong>不是写给对方，是写给你自己将来。你在这个位置上，最怕的不是做错，是过两年自己也说不清当初为什么。</p>
<p>- <strong>程序要完整。</strong>该走的三步不能省成两步。你省掉的每一步，将来都会变成别人的把柄。</p>
<p>- <strong>尺度要跟过去的案例对得上。</strong>同类的错，去年怎么处理，今年不能差太多。<strong>一致性比严厉更重要。</strong></p>
<p>- <strong>给对方面子。</strong>能私下谈的别公开，能内部处理的别通报。你留了他的面子，他就不容易跟你拼命。</p>
<p>汉宣帝的时候，京兆尹赵广汉治京畿，手段很硬，豪强都怕他。他也处理过很多权贵的案子。<strong>他后来因为一次程序上的问题被腰斩。</strong>他做的事有很多是对的，可他有一次把程序走漏了。</p>
<p><strong>什么情况可以快刀：</strong>如果这件事有明确的时间窗口，拖着会出更大的事，那就快刀。快刀的前提是你手上的证据足够硬。</p>
<h3 id="p-上九-何校灭耳-凶-到这一步-说什么都晚了">上九 · 何校灭耳，凶 —— 到这一步，说什么都晚了</h3>
<blockquote class="pw-quote"><strong>上九：何校灭耳，凶。</strong><br>象曰：何校灭耳，聪不明也。</blockquote>
<p><strong>你现在在这个位置：你已经警告过一个人很多次了。他每一次都没当回事。</strong></p>
<p>「何校」——「何」是荷，扛着。枷从脚上搬到肩膀上了。「灭耳」——枷大到把耳朵都遮住了。</p>
<p>象传给的三个字是这一爻的判词：<strong>「聪不明也」——耳朵不好使。</strong></p>
<p>孔颖达讲得更不留余地：「惡積不改，故罪及其首。」恶积起来不改，所以罪到了头上。</p>
<p><strong>这一爻是初九的终局。</strong></p>
<p>初九是「屦校灭趾」——脚上戴个木枷，还能走路。</p>
<p>上九是「何校灭耳」——肩上扛着木枷，听不见了。</p>
<p><strong>同一副枷，从脚上爬到肩上，中间隔的就是那些一次次没被当回事的小错。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>如果这个人是你的下属：</strong>该处理就处理，不要再给第八次机会了。你给的每一次机会，都在告诉团队里其他人：标准是可以破的。</p>
<p>- <strong>如果这个人是你自己：</strong>现在立刻停下来。找一个你最信的人，让他跟你说实话，你听了之后不要辩解。</p>
<p>- <strong>处理的时候要有个说法。</strong>对上对下都要说清楚：为什么到这一步、前面给过几次机会、接下来怎么办。</p>
<p>- <strong>处理完，把这件事封存。</strong>不要再拿出来当例子讲。反复讲的人，是在用别人的错给自己立威。</p>
<p>商纣王的时候，微子、箕子、比干都劝过他。微子劝了几次走了，箕子装疯被囚，比干强谏被剖心。<strong>纣王到最后也没听进去一个字。</strong>牧野一战，他自焚于鹿台。</p>
<p><strong>什么情况还能给一次机会：</strong>如果你从来没明确说过这是错，那不能怪他。<strong>「何校灭耳」的前提是前面已经说过很多次了。</strong></p>
<h3 id="p-最后-把东西咬碎-上下才合得上">最后：把东西咬碎，上下才合得上</h3>
<p>噬嗑卦后面接的是贲卦。</p>
<p>「物不可以苟合而已，故受之以賁」——东西不能随随便便就合上，所以要有修饰。</p>
<p>噬嗑讲的是除梗，贲讲的是文饰。<strong>先要把挡路的东西咬掉，再谈好不好看。</strong></p>
<p>噬嗑卦六个爻，从初九脚上的一副小枷，到上九肩上的一副大枷，中间是腊肉、干肉、带骨头的肉。<strong>它是一条越来越硬的曲线。</strong></p>
<p>但全卦最重要的是象传里那四个字：<strong>「明罚敕法」</strong>。</p>
<p>先把规则讲清楚，再谈惩罚。<strong>没有讲清楚的罚，是不教而诛。</strong></p>
<p>噬嗑卦最后给你的一句话：</p>
<blockquote class="pw-quote">你嘴里含着的那件事，不会自己化掉。它只会越含越硬，从鲜肉含成腊肉，从腊肉含成干肉。<strong>趁它还软的时候咬。</strong></blockquote>
  `,
  bi2: `
<p>你花了两周做那份 PPT。</p>
<p>配色调了三版，动画顺了两遍，每一页的字号都对齐到像素。讲完那天全场鼓掌，老板说「做得真漂亮」。</p>
<p>三个月后你回头看，那个项目黄了。做漂亮的那份 PPT，没人再打开过。</p>
<p>贲卦讲的就是这件事。</p>
<p>「贲」是装饰、是文采。山火贲，上艮下离——山下面有火。火光照着山，把山上的草木照出颜色来，这就是贲。</p>
<p>但贲卦的卦辞给得很克制：「亨。小利有攸往。」</p>
<p><strong>通，但只适合小有前往。</strong></p>
<p>孔颖达说得很明白：「以剛上文柔，不得中正，故不能大有所往。」</p>
<p>装饰这个东西，不能当大事使。</p>
<p><strong>贲卦全卦讲的就是一个分寸问题：形式和内容，哪个在前面。</strong></p>
<p>我把六个位置拆开说。</p>
<h3 id="p-初九-贲其趾-舍车而徒-该走路的时候别坐车">初九 · 贲其趾，舍车而徒 —— 该走路的时候别坐车</h3>
<blockquote class="pw-quote"><strong>初九：贲其趾，舍车而徒。</strong><br>象曰：舍车而徒，义弗乘也。</blockquote>
<p><strong>你现在在这个位置：有个机会能让你显得很好看——一个好听的职位、一次露脸的场合、一个来路不太正的便利。</strong></p>
<p>「贲其趾」——装饰你的脚。脚在最下面，是走路用的，不是用来好看的。</p>
<p>「舍车而徒」——<strong>放弃车子，走路。</strong></p>
<p>孔颖达说得非常干脆：「乃棄於不義之車，而從有義之徒步。」</p>
<p><strong>那辆车是不义的，所以他走路。</strong></p>
<p>象传把理由讲得只剩四个字：<strong>「义弗乘也」——从道理上讲，不该坐。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>问一句：这个东西是我挣来的，还是别人给的？</strong>给的也能要，但你要知道它是给的。</p>
<p>- <strong>走路这件事本身有价值。</strong>你走出来的路，别人收不走。你坐车来的，车一停你就没了。</p>
<p>- <strong>装饰要装饰在能用的地方。</strong>把精力花在你真要走的那条腿上，不是花在车上。</p>
<p>- <strong>拒绝的时候不用说理由。</strong>说得越多越像演。「我不坐，我走过去」就够了。</p>
<p>东汉的严光，是刘秀年轻时的同学。刘秀当了皇帝之后，把他请到洛阳，想让他做谏议大夫。严光夜里跟刘秀睡一张床，把脚搁在刘秀肚子上。<strong>后来他坚决不做官，回了富春江钓鱼。</strong>那辆车他看得见，他不坐。</p>
<p><strong>什么情况可以坐车：</strong>如果那辆车是公器，是为了办事的效率，那就坐。义弗乘讲的是来路不正的好处，不是讲所有的便利。</p>
<h3 id="p-六二-贲其须-胡子长在脸上才好看">六二 · 贲其须 —— 胡子长在脸上才好看</h3>
<blockquote class="pw-quote"><strong>六二：贲其须。</strong><br>象曰：贲其须，与上兴也。</blockquote>
<p><strong>你现在在这个位置：你自己没什么可展示的，你的价值在于跟对一个东西，然后跟着它一起起来。</strong></p>
<p>「贲其须」——装饰你的胡须。</p>
<p>胡须这个比喻非常准。孔颖达说：「須是上須於面，六二常上附於三，若似賁飾其須也。」</p>
<p><strong>胡子长在脸上才好看。把它剪下来放在桌上，就是一堆毛。</strong></p>
<p>六二是阴爻，它自己不动，它附在九三上。</p>
<p>象传的「与上兴也」——<strong>跟上上面一起兴起。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先选对那个「脸」。</strong>你附着的那个东西，得是一张真脸，不是一个假人。判断标准：它自己有没有在长。</p>
<p>- <strong>附上去之后，别自己乱动。</strong>这一爻是阴爻，阴的意思是不主动。你在这个阶段主动，会把关系搞乱。</p>
<p>- <strong>把你的能力用在衬托上。</strong>你把一个好东西讲清楚了、做出彩了，这个功劳跑不掉。</p>
<p>- <strong>别抢镜。</strong>胡须抢了脸的镜，那是病。</p>
<p>张良一生跟刘邦。他不带兵、不占城、不管钱粮，他做的是出主意。刘邦说「运筹策帷帐中，决胜千里外，子房功也」。<strong>张良的价值全在刘邦这张脸上。</strong>刘邦没了，张良也就退了。</p>
<p><strong>什么情况不用附着：</strong>如果你依附的那个人自己都快倒了，那就别附。判断标准很简单：他最近半年是在往上走还是往下走。</p>
<h3 id="p-九三-贲如濡如-永贞吉-好看-还要经得住看">九三 · 贲如濡如，永贞吉 —— 好看，还要经得住看</h3>
<blockquote class="pw-quote"><strong>九三：贲如濡如，永贞吉。</strong><br>象曰：永贞之吉，终莫之陵也。</blockquote>
<p><strong>你现在在这个位置：你现在正红。你做的方案有人夸，你说的话有人听，你的样子大家都觉得好看。</strong></p>
<p>「贲如」是华饰的样子，「濡如」是润泽的样子。</p>
<p><strong>又华丽，又润泽。</strong>孔颖达说「居得其位，與二相比，和合文飾，而有潤澤」。</p>
<p>但这一爻的后半句给了两个字：<strong>永贞。</strong></p>
<p>「其美如此，長保貞吉，物莫之陵」——美到这个程度，要长久地守住正才能吉，<strong>那样就没有什么东西能压过你。</strong></p>
<p>象传的「终莫之陵也」是关键：<strong>没有人能凌驾你。</strong>但这个「莫之陵」的前提是「永贞」。</p>
<p>具体怎么做：</p>
<p>- <strong>红的时候最该做的事是加产能，不是加曝光。</strong>你被夸一次，就把那份东西再做深一层。</p>
<p>- <strong>把「好看」拆成能验证的东西。</strong>你的方案被人夸，就去找三个用户问一句：你具体喜欢哪儿？答案如果是「说不上来，就是感觉好」，那你还没到永贞。</p>
<p>- <strong>别停止输入。</strong>人在最红的时候最不想学东西，因为学东西会让你显得不专业。</p>
<p>- <strong>警惕那批只夸你的人。</strong>只夸不提问题的人，是在消费你，不是在帮你。</p>
<p>汉武帝时的司马相如，靠一篇《子虚赋》被武帝赏识，后来又写了《上林赋》，辞采华丽，一时无两。<strong>可他一辈子没能进入决策核心。</strong>他的赋是真好，但赋是好东西里的装饰品。同期的主父偃、张汤，文字远不如他，位置比他高得多。</p>
<p><strong>什么情况可以只求好看：</strong>如果是纯消费类的产品、纯传播类的内容，好看本身就是价值。你的判断标准是：这个东西的购买理由里，有多少是形式。</p>
<h3 id="p-六四-贲如皤如-白马翰如-匪寇婚媾-到底要不要打">六四 · 贲如皤如，白马翰如。匪寇婚媾 —— 到底要不要打扮，你犹豫</h3>
<blockquote class="pw-quote"><strong>六四：贲如皤如，白马翰如。匪寇婚媾。</strong><br>象曰：六四，当位疑也。匪寇婚媾，终无尤也。</blockquote>
<p><strong>你现在在这个位置：你在纠结要不要按这个地方的规矩来。有人告诉你该怎么穿、怎么说、怎么表现，你不确定。</strong></p>
<p>「贲如皤如」——「皤」是素白。<strong>要么华丽，要么素净，你在两边摇。</strong></p>
<p>「白马翰如」——白马跑得飞快。<strong>你想过去，又在等。</strong></p>
<p>孔颖达说得很清楚：「六四有應在初，欲往從之，三為已難，故已猶豫。或以文絜，故賁如也；或守質素，故皤如也。」</p>
<p><strong>你心里想归附的是初九那个质朴的东西，可中间有三挡着。</strong></p>
<p>「匪寇婚媾」——那不是强盗，那是来娶亲的。<strong>把来的人看清楚。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>先判断挡在中间的那个东西是什么。</strong>是一个人的面子，是一条不成文的规矩，还是一个你真绕不过去的门槛？</p>
<p>- <strong>别在中间站着。</strong>犹豫就是这一爻的处境。你要么按他们的规矩来，要么退回去守住你原来的样子。<strong>站在中间最消耗。</strong></p>
<p>- <strong>试探一次。</strong>做一次素净的版本，看有没有人真的扣你的分。多数时候，你担心的那些规矩没人真的在管。</p>
<p>- <strong>把选择的标准定下来：</strong>这个地方是要看形式，还是要看结果？要形式，你就按形式来；要结果，你把结果摆出来就行。</p>
<p>汉初的叔孙通，为刘邦制定朝仪。他先去鲁地找了三十个儒生，有两个人不肯来，说他「所为不合古」。叔孙通笑他们说「若真鄙儒也，不知时变」。<strong>他按当天的需要做了简易的朝仪，而不是照搬三代的古礼。</strong>他不是不知道古礼好看，他是知道那个时候要的不是好看。</p>
<p><strong>什么情况该守素：</strong>如果你所处的环境就是靠作品说话的——研究、技术、手艺——那就守素。这种地方你花在形式上的每一分，都是浪费。</p>
<h3 id="p-六五-贲于丘园-束帛戋戋-吝-终吉-该省的省-别">六五 · 贲于丘园，束帛戋戋。吝，终吉 —— 该省的省，别嫌寒酸</h3>
<blockquote class="pw-quote"><strong>六五：贲于丘园，束帛戋戋。吝，终吉。</strong><br>象曰：六五之吉，有喜也。</blockquote>
<p><strong>你现在在这个位置：你手上有预算，也有权力把这个场面办得很漂亮。可你在犹豫要不要办那么大。</strong></p>
<p>「贲于丘园」——「丘园」是草木丛生的质朴之地。<strong>把你那点装饰的心思，花在质朴的地方。</strong></p>
<p>「束帛戋戋」——「戋戋」是少的样子。<strong>就一小束帛，很少。</strong></p>
<p>「吝，终吉」——<strong>显得寒酸，最后是吉。</strong></p>
<p>孔颖达把这一爻的深意挖得很透。他说六五是「为饰之主」，处在最该讲究排场的位置上。如果他把装饰花在宫室车马衣服上，「则大道损害」。<strong>花在质素的地方，那个盛才是最大的。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>问一句：这笔钱花出去，谁会真的受益？</strong>买更好的设备、加更高的工资、给客户降一点价——这些是丘园。装修会议室、换前台的花、给高管配车——这些是束帛。</p>
<p>- <strong>接受「吝」这个评价。</strong>你这么做，一定有人说你抠。这一爻提前把话给你了：会显得吝。</p>
<p>- <strong>把省下来的东西指给人看。</strong>你不说，别人只看见你抠；你说了，别人看见你在往哪儿投。</p>
<p>- <strong>别省在关键客户身上。</strong>「丘园」是质朴，不是失礼。分清楚这两件事。</p>
<p>汉文帝想修一座露台，叫工匠算了一下，要花百金，相当于十户中等人家的家产。<strong>他说：我住在先帝的宫里都觉得惭愧，还修什么露台。</strong>他穿的是粗丝，宠妃的衣服不许拖地，帷帐不许绣花。文景之世攒下的家底，给汉武帝打匈奴用了。</p>
<p><strong>什么情况必须花：</strong>如果这笔钱是要在关键场合立信任、给承诺的，那就得花，而且要花得让人看见。这时候省，省掉的是信用。</p>
<h3 id="p-上九-白贲-无咎-最高的装饰-是不装饰">上九 · 白贲，无咎 —— 最高的装饰，是不装饰</h3>
<blockquote class="pw-quote"><strong>上九：白贲，无咎。</strong><br>象曰：白贲无咎，上得志也。</blockquote>
<p><strong>你现在在这个位置：你已经有资格讲究了。可你发现，你越简，效果越好。</strong></p>
<p>「白贲」——<strong>用白色来装饰。</strong></p>
<p>白色在装饰里是最特别的一种：它什么颜色都不是，可它什么都能配。</p>
<p>孔颖达说：「處飾之終，飾終則反素，故在其質素，不勞文飾。」</p>
<p><strong>装饰到了尽头，就要返回素净。到了这个份上，不用再费劲去装饰了。</strong></p>
<p>象传给的是「上得志也」——<strong>在上面反而得志。</strong>他终于做成了他想做的事。</p>
<p>具体怎么做：</p>
<p>- <strong>砍掉一半。</strong>你的方案、你的报告、你的办公室、你的日程表，砍掉一半。砍完之后你会发现效率反而高了。</p>
<p>- <strong>把「加」换成「减」。</strong>这一条最难练。人的本能是往上加，加内容、加功能、加话术。练减法要练很久。</p>
<p>- <strong>看一个人的素颜。</strong>你想了解一家公司，就看它不给外人看的那一面。你想了解一个人，就看他累的时候的样子。</p>
<p>- <strong>允许事情有点粗糙。</strong>什么都打磨到完美，成本会吃掉所有的利润。</p>
<p>《周易正義》里有句话很妙：「守志任真，得其本性。」守住本心，随它真实的样子，回到它本来是什么。</p>
<p><strong>什么情况不能素：</strong>如果是第一次见面、第一次提案、第一次公开亮相，那就该好好做。白贲是给已经立住的人准备的。<strong>你没立住的时候素，叫不讲究。</strong></p>
<h3 id="p-最后-装饰是给内容加的-不是替内容">最后：装饰是给内容加的，不是替内容</h3>
<p>贲卦前面是噬嗑，后面是剥卦。</p>
<p>《序卦》里有一句话把这一卦的位置说尽了：「致飾然後亨則盡矣，故受之以剝。」</p>
<p><strong>把装饰做到极致，通就走到头了，接下来就是剥落。</strong></p>
<p>贲卦六个爻，从初九的「舍车而徒」，到六五的「束帛戋戋」，到上九的「白贲」，一路都在<strong>往回收</strong>。</p>
<p>全卦最反直觉的地方在这里：<strong>这卦讲装饰，可它给的答案越来越素。</strong></p>
<p>贲卦最后给你的一句话：</p>
<blockquote class="pw-quote">你包装的每一样东西，都在替你说话。可你包装得越多，你自己说话的声音就越小。做到最后你会发现，最好的那层包装，是你自己本身。</blockquote>
  `,
  bo: `
<p>有个做技术的朋友，去年被裁了。他复盘的时候说了一句我记到现在的话：「其实前年就有征兆了。」</p>
<p>前年的征兆是什么？他负责的那块业务，被拆走了两个小组。他没在意，因为他的活没变。</p>
<p>去年的征兆是，他汇报的那条线，从 CTO 改成了某个总监。他也没在意，因为工资照发。</p>
<p>到今年，整个部门砍掉，他才反应过来。</p>
<p>剥卦讲的就是这件事：<strong>衰败从来不是一次性事件，是一层一层往下剥的。</strong></p>
<p>剥卦是山地剥，五个阴爻在下面，一个阳爻在最上头。阴气一层层往上长，阳气一层层被削掉。</p>
<p>它讲的不是「你要完了」，它讲的是<strong>你在第几层的时候看出来的</strong>。看出来得早，你还有余量；看出来得晚，你就只能接受结果。</p>
<p>我下面按六层说。你找一个最像自己的。</p>
<h3 id="p-初六-剥床以足-蔑贞凶-就是有点不对劲">初六 · 剥床以足，蔑贞凶 —— 就是有点不对劲</h3>
<blockquote class="pw-quote"><strong>初六：剥床以足，蔑贞凶。</strong><br>象曰：剥床以足，以灭下也。</blockquote>
<p><strong>你现在在这个位置：说不上哪里不对，就是有点怪。所有人都在说没事，你也就跟着说没事。</strong></p>
<p>床先从床脚开始烂，这是剥卦最狠的一个比喻。床脚烂了，你躺上去一点感觉都没有。</p>
<p>这个阶段的动作只有一条：<strong>建一个本子，只记事实，不记感受。</strong></p>
<p>日期、谁说了什么、什么变了。不用分析，不用下判断，就记。因为人在这个阶段最大的敌人是自己的解释能力——你太会给自己找台阶了。</p>
<p>判断标准在这里：<strong>同一类事，三个月内出现三次，那就不是意外。</strong></p>
<p>一次是巧合，两次是运气差，三次就是趋势。趋势这个词的意思很朴素：它还会来第四次。</p>
<p>萧何月下追韩信，追回来之后刘邦还是只给了韩信一个治粟都尉。韩信那阵子干得挺好，账目清楚，粮草没出过岔子。可他从治粟都尉到登坛拜将之前，中间隔着的那些日子，就是「剥床以足」——床脚在响，没人听见。</p>
<p><strong>什么情况可以不管：</strong>如果这事跟钱、跟位置、跟人身安全都不沾边，先放着。什么风吹草动都记，人会变成疑神疑鬼的，那比迟钝更耽误事。还有一种，那个「不对劲」其实来自你自己——同事业绩好你心里发酸，那不叫征兆。</p>
<h3 id="p-六二-剥床以辨-蔑贞凶-现在轮到你认识的人了">六二 · 剥床以辨，蔑贞凶 —— 现在轮到你认识的人了</h3>
<blockquote class="pw-quote"><strong>六二：剥床以辨，蔑贞凶。</strong><br>象曰：剥床以辨，未有与也。</blockquote>
<p><strong>你现在在这个位置：出事的不再是抽象的消息，是你认识的人。你的搭子被调走了，隔壁组被合并了。</strong></p>
<p>辨是床身和床脚之间的那个接缝。剥到这儿，已经往上走了一格。</p>
<p>这个阶段的动作：<strong>把你手上的活，做一次「可交接化」处理。</strong></p>
<p>意思是，你负责的那摊事，写成一份别人能看懂的东西。数据在哪、联系人在哪、哪个环节最容易卡。不是为了走，是为了让你自己知道——你手里到底攥着什么。</p>
<p>大多数人在这个阶段慌，是因为他们发现自己其实是可替代的，而且替代起来并不难。这个发现很疼，但它是真的。</p>
<p>然后做第二件事：<strong>给三个人发消息。</strong></p>
<p>不是求人，是问一句「你们那边最近怎么样」。信息在这一层比能力值钱。你在六二的位置上，唯一能提前拿到六四消息的办法，就是多问几个人。</p>
<p>晁错削藩，削到楚王、赵王的时候，朝里那批人还是照常上朝，该喝酒喝酒。等到吴楚七国一起反，告示贴出来，很多人才知道自己的封地已经不在名单上了。接缝处的响动，从来传不到最里面那间屋子。</p>
<p><strong>什么情况不用动：</strong>如果被调走的那个人跟你根本不在一条线上，那是别人的事。看热闹要有个限度，公司里的大多数变动，跟你的饭碗没有直接关系。</p>
<h3 id="p-六三-剥之-无咎-全都在往下走-你偏往上走">六三 · 剥之，无咎 —— 全都在往下走，你偏往上走</h3>
<blockquote class="pw-quote"><strong>六三：剥之，无咎。</strong><br>象曰：剥之无咎，失上下也。</blockquote>
<p><strong>你现在在这个位置：周围人都在找退路，都在说丧气话。你心里有个声音说，好像还能再撑一撑。</strong></p>
<p>剥卦六个爻里，只有六三这一爻是无咎的。原因很有意思：六三是阴爻，但它是唯一一个跟上面那个阳爻（上九）有呼应的。</p>
<p>翻译成人话：<strong>一圈人都在往下剥，你是唯一一个还往上看的。</strong></p>
<p>象传说「失上下」——你跟上下都不一路了。这不是夸你清高，这是在告诉你代价：你在这个阶段会有点孤独。</p>
<p>具体动作：<strong>在所有人收缩的时候，挑一件小事做到最好。</strong></p>
<p>不是喊口号，是挑一件具体的、能拿出结果的小事。别人砍预算，你把那件小事做到挑不出毛病。</p>
<p>为什么这一招有用？因为衰退期里，大家都在削减，做得好的人反而变少了。你的对手不是市场，是其他也在收缩的人。</p>
<p>刘备在当阳被曹操追着跑的时候，手下的人都劝他扔下百姓快走。他没扔，带着十几万走得慢吞吞的。这一趟他差点没命。</p>
<p>可也就是这一趟，让荆州的人记住了他。这一爻是：<strong>风雨飘摇的时候你干的那件傻事，日后会被人想起来。</strong></p>
<p><strong>什么情况别这么干：</strong>如果这家公司已经在走清算流程、发不出工资，那你就别做傻事了，赶紧找下家。六三讲的是「局面还能救」，不是「局面没救了」。分辨标准：下个月的工资还发不发得出。</p>
<h3 id="p-六四-剥床以肤-凶-已经贴到肉了">六四 · 剥床以肤，凶 —— 已经贴到肉了</h3>
<blockquote class="pw-quote"><strong>六四：剥床以肤，凶。</strong><br>象曰：剥床以肤，切近灾也。</blockquote>
<p><strong>你现在在这个位置：事情已经落到你身上了。降薪、调岗、被穿小鞋、被边缘化——具体到你自己了。</strong></p>
<p>肤就是皮肉。剥到这儿，刀已经贴到身上了。</p>
<p>这一爻的爻辞只有一个字：凶。没有「可以」「如果」，没有商量。剥卦剥到六四，就是灾难已经发生了。</p>
<p>所以这一层不讲怎么避免，讲<strong>怎么止损</strong>。三条：</p>
<p><strong>一，认账要快。</strong> 别再花时间去证明这不公平。它确实不公平，但公平不是你现在能拿到的东西。</p>
<p><strong>二，别在这儿找尊严。</strong> 被降职之后，很多人第一反应是在会上硬顶几句，证明自己还行。这个动作收益是零，成本是你把剩下的路也堵死。</p>
<p><strong>三，把现金流算清楚。</strong> 手上有几个月的生活费，能撑多久，能接受降到什么程度。数字比情绪可靠。</p>
<p>韩信从齐王被徙为楚王，再从楚王被贬为淮阴侯，两次都是「剥床以肤」。他第一次没反应，第二次到长安之后开始称病不朝。</p>
<p>他做的既不是认账，也不是止损，是憋着。憋着这一条，最后通到长乐宫。</p>
<p><strong>什么情况还得扛：</strong>如果这次降职只是暂时的，而且上面明确给了时间表和回头路径，那可以扛。判断标准是六个字：<strong>有没有具体承诺。</strong>「你先委屈一下，以后再说」不算承诺，「到明年三月这个项目做起来，你回原岗」才算。</p>
<h3 id="p-六五-贯鱼-以宫人宠-把次序理顺">六五 · 贯鱼，以宫人宠 —— 把次序理顺</h3>
<blockquote class="pw-quote"><strong>六五：贯鱼，以宫人宠，无不利。</strong><br>象曰：以宫人宠，终无尤也。</blockquote>
<p><strong>你现在在这个位置：你在一个中间层，上面在压，下面在乱。你得让大家先别打起来。</strong></p>
<p>六五是尊位，但它是个阴爻。剥卦到这一层，是五阴一阳里最接近顶上的那一阴。它做的不是救局，是<strong>理顺次序</strong>。</p>
<p>贯鱼，是把鱼穿成串，一条挨一条。宫人宠，是说像宫里的妃嫔一样受宠，但不越位、不生事。</p>
<p>这一爻给的动作非常具体：<strong>在这个位置上，你要做的是排顺序，不是抢位置。</strong></p>
<p>谁先谁后，谁报给谁，什么先做什么后做。把这个东西明确下来，大家就不打架了。</p>
<p>为什么这一爻说是「无不利」？因为衰退期最大的消耗不是外部压力，是内部互撕。你能让这一群人有序地领东西、有序地干活，这个价值在平时看不出来，在乱的时候极其值钱。</p>
<p>丙吉做汉宣帝的丞相，出门碰上群殴死人的事他不管，碰上牛喘气他停下车问。别人笑他该管不管，他说斗殴是京兆尹的事，牛喘气关系节气收成，那是三公该操心的。<strong>这一爻讲的就是这个：分清哪件事归谁，比你亲自去干每一件更重要。</strong></p>
<p><strong>什么情况可以越位：</strong>如果底下已经没人管事了，空着的位置你不接，局面就散了。这时候接过来，不叫抢。判断标准：你接过来之后，是有人不服，还是大家松一口气。</p>
<h3 id="p-上九-硕果不食-君子得舆-留一颗种子">上九 · 硕果不食，君子得舆 —— 留一颗种子</h3>
<blockquote class="pw-quote"><strong>上九：硕果不食，君子得舆，小人剥庐。</strong><br>象曰：君子得舆，民所载也。小人剥庐，终不可用也。</blockquote>
<p><strong>你现在在这个位置：事情已经败了。你在收拾残局，或者在决定留下什么。</strong></p>
<p>剥卦只有一个阳爻，就在最上面。五个阴爻剥了一路，剥到这里，剥不动了。</p>
<p>硕果不食——树上还挂着一颗大果子，没人吃。</p>
<p>这就是剥卦留给你的唯一一句好话：<strong>局面再烂，只要还剩一颗种子，就不算彻底结束。</strong></p>
<p>具体怎么做三件事：</p>
<p><strong>一，保住那颗种子。</strong> 种子是什么？可能是那一个还没走的骨干、那一份没外流的核心资料、那一段还没断的关系。</p>
<p>你要清楚它是什么，然后单独给它做保护。</p>
<p><strong>二，换算口碑。</strong> 象传说「君子得舆」，舆是车，是众人抬着你走。衰退期你怎么对下面的人，事后会成倍还回来。</p>
<p>厚下安宅——大象传这四个字，就是给这一层写的。</p>
<p><strong>三，别把最后那点家当也分了。</strong> 小人剥庐——把房顶的茅草都拆下来分了，最后大家一起淋雨。</p>
<p>勾践在会稽山被围，剩五千人。他做的事是派文种去贿赂吴国太宰伯嚭，保住越国不灭。地没了大半，人剩五千，可国还在。</p>
<p><strong>这就是硕果不食。</strong> 二十年后，这颗果子长回来了。</p>
<p><strong>什么情况可以放弃：</strong>如果那颗种子本身是烂的——比如这个项目从根上就是错的，或者这个人已经靠不住了——那就别硬留。留烂种子，只会让你舍不得走。判断标准：三年后，你愿不愿意为它再投一次。</p>
<h3 id="p-最后-剥到最下面-就该往回长了">最后：剥到最下面，就该往回长了</h3>
<p>剥卦后面就是复卦。剥尽了，阳气就回来了。这个次序不是安慰，是规律。</p>
<p>你回头看会发现，剥卦六层里最关键的分水岭是六三。前面三层，你都还有得选；到了六四，「凶」字就写在那里了。</p>
<p>所以你真正要练的本事，是<strong>在床脚响的时候听见</strong>。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别问事情会不会变坏。问你现在是在第几层。</blockquote>
  `,
  fu: `
<p>一个人戒了酒。不是第一次戒，是第五次。</p>
<p>前四次他都撑不过一个月。这一次他撑了两年，现在还在撑。</p>
<p>我问他前四次和这一次有什么不一样，他想了想说：「前面四次我都是喝到住院才戒的。这一次是我自己觉得该停了。」</p>
<p>区别就在这儿。</p>
<p>复卦讲的就是这件事：<strong>你能不能在小错的时候回头。</strong></p>
<p>复卦是地雷复，一阳在最下面，五个阴在上面。雷藏在地底下，阳气刚刚动起来——弱得很，一冒头就能被掐死。可它就是要往上长。</p>
<p>「七日来复」，七天一个循环，阳气去了还会回来。这是天地的节律，改不了。</p>
<p>但节律归节律，<strong>你在哪个位置回头，是你自己的事。</strong> 复卦六爻，从「不远复」到「迷复」，就是一个人回头早晚的六个档次。</p>
<p>我下面按六档说。</p>
<h3 id="p-初九-不远复-无祗悔-元吉-刚走偏就回头">初九 · 不远复，无祗悔，元吉 —— 刚走偏就回头</h3>
<blockquote class="pw-quote"><strong>初九：不远复，无祗悔，元吉。</strong><br>象曰：不远之复，以修身也。</blockquote>
<p><strong>你现在在这个位置：你刚做错了一件事，或者刚说错了一句话。事情不大，但你心里知道不对。</strong></p>
<p>复卦六个爻里，只有初九是元吉，大吉。为什么？因为它走得最近就回头了。</p>
<p>象传给了四个字：「以修身也」。修身不是修炼成圣人，是<strong>改得快</strong>。</p>
<p>这个阶段的具体动作：<strong>在二十四小时之内，把那个「不对」说出口。</strong></p>
<p>不是长篇检讨，就是一句：「昨天那个事，我想了一下，是我不对。」</p>
<p>二十四小时是个硬指标。过了这个窗口，你会发现说出口的成本每天都在涨。第一天说，是坦诚；第七天说，是被逼的；一个月后说，是别有用心。</p>
<p>还有一个动作：<strong>别把「回头」搞成仪式。</strong> 有人一犯错就大动干戈，写检讨、立规矩、发长文。动静越大，下次越难回头，因为你把自己架起来了。</p>
<p>汉武帝晚年下轮台诏，说「曩者，朕之不明」，把前面几十年穷兵黩武的账认了，然后停下来，封丞相为富民侯，改搞农业。这已经不算「不远复」了，账太大，人死了大半。但他在还有一口气的时候认了，汉朝就没跟着他一起崩。</p>
<p><strong>什么情况不用回头：</strong>如果那件事你其实没做错，只是对方嗓门大，那就别乱认。乱认账的人，信用掉得比犯错还快。判断标准：<strong>夜里自己一个人的时候，你觉得对不对。</strong></p>
<h3 id="p-六二-休复-吉-跟着对的人改">六二 · 休复，吉 —— 跟着对的人改</h3>
<blockquote class="pw-quote"><strong>六二：休复，吉。</strong><br>象曰：休复之吉，以下仁也。</blockquote>
<p><strong>你现在在这个位置：你自己还没想清楚，但你身边有个人，走的路是对的。你想跟上他。</strong></p>
<p>「休」是美、是好的意思。休复就是<strong>往好的那边靠</strong>。</p>
<p>象传解释得更直白：「以下仁也」——你愿意待在好人下面。</p>
<p>这一爻的重点不在自己身上，在<strong>你选谁当参照</strong>。</p>
<p>具体动作：<strong>找出那个「活得比你对」的人，然后别问他怎么做的，看他怎么做。</strong></p>
<p>问是没用的，人一开口就会美化自己。看他怎么花钱、怎么对待帮不上忙的人、出事的时候第一句话说什么。这三件事比他自己讲的准十倍。</p>
<p>第二条：<strong>别只看他做对的那一面。</strong> 很多人把偶像当成一面旗，只学高光的部分。真正该学的是他怎么处理难堪的场面——那才是他立得住的地方。</p>
<p>孟母三迁讲的就是这个。一开始住墓地旁边，孟子学人家哭丧；搬到市集，孟子学人家吆喝杀猪；最后搬到学宫旁边，孟子学的是揖让进退。孟母没跟孟子讲过一句大道理，她做的事是换地方。</p>
<p><strong>什么情况别跟着走：</strong>如果那个人只是职位高、赚钱多，那不叫「仁」。位置和品行是两回事。判断标准：<strong>他不在场的时候，别人怎么评价他。</strong></p>
<h3 id="p-六三-频复-厉-无咎-改了又犯-犯了再改">六三 · 频复，厉，无咎 —— 改了又犯，犯了再改</h3>
<blockquote class="pw-quote"><strong>六三：频复，厉，无咎。</strong><br>象曰：频复之厉，义无咎也。</blockquote>
<p><strong>你现在在这个位置：你已经失败过好几次了。你自己都快不信自己了。</strong></p>
<p>频复，是反复地回头。改了又犯，犯了再改。</p>
<p>爻辞给的是「厉，无咎」——有危险，但没有过错。</p>
<p>这句话为什么重要？因为大多数人是在这一步放弃的。想想看：你说了三次要早睡，三次都没做到，第四次你就不说了，因为不好意思。</p>
<p>可复卦告诉你：<strong>反复改，不是无咎的反面，反复改本身就是无咎。</strong></p>
<p>象传补了一句「义无咎也」——从道理上讲，你没有错。方向对，就是没错。</p>
<p>具体动作两条：</p>
<p><strong>一，把目标砍到小得可笑。</strong> 你改不掉，通常不是因为你意志力差，是因为目标定得太大。戒酒改不成，先改成「这周只喝一次」。</p>
<p><strong>二，记录次数，不记录成败。</strong> 你这个月回头了几次，就是几次。</p>
<p>别算「第几次失败了」，算「第几次回来了」。这两个算法的结果一样，感受完全不同。</p>
<p>曾国藩在长沙练兵，靖港一仗输得跳了江，被捞上来；接着湖口又输，又跳了一次，又被捞上来。他前后两次上书请罪，两次都在折子里说自己「屡战屡败」。改成「屡败屡战」这四个字，不是文字游戏，就是他真实的活法。</p>
<p><strong>什么情况必须停：</strong>如果这件事你已经反复了十几次，而且每次的失败都一模一样，那问题不在意志力，在你根本没搞懂为什么会失败。这时候停下改，先去搞清楚原因。</p>
<h3 id="p-六四-中行独复-一个人回头">六四 · 中行独复 —— 一个人回头</h3>
<blockquote class="pw-quote"><strong>六四：中行独复。</strong><br>象曰：中行独复，以从道也。</blockquote>
<p><strong>你现在在这个位置：周围人都在往一个方向走，你觉得那个方向不对，可你只有一个人。</strong></p>
<p>中行独复——走在队伍中间，只有你一个人掉头。</p>
<p>这一爻爻辞里没有吉凶，只有四个字。象传也只说「以从道也」。</p>
<p>不写吉凶，是因为这一爻的结果不在当下。你掉头的那一刻，看到的是：别人往前走，你往回走，你落后了。</p>
<p>这个阶段最难的不是判断，是<strong>忍受看起来的落后</strong>。</p>
<p>具体动作：</p>
<p><strong>一，把理由写下来，存好。</strong> 你独复的时候会被质疑，理由要提前想清楚。写在纸上，因为人在被围攻的时候，脑子是会乱的。</p>
<p><strong>二，找一个同类，哪怕只有网上认识的一个。</strong> 独行最难的部分不是路远，是没人确认你没疯。</p>
<p><strong>三，别去劝别人。</strong> 你这时候去拉人，只会把你自己也拖住。</p>
<p>屈原在楚国待到最后。楚怀王客死秦国，顷襄王接着听子兰的，屈原在江边一路走一路说，说了很多年。</p>
<p>他没有跟任何人一起走，他就是自己一个人。一个国的人都往一个方向去，只有他往另一个方向走。</p>
<p><strong>什么情况别硬撑：</strong>如果反对你的是一整片懂行的人，而你只是凭直觉，那先别急着独行。判断标准：<strong>你能不能说清楚自己是根据什么判断的。</strong> 说不清，那就不是独复，是赌气。</p>
<h3 id="p-六五-敦复-无悔-认了-踏实改">六五 · 敦复，无悔 —— 认了，踏实改</h3>
<blockquote class="pw-quote"><strong>六五：敦复，无悔。</strong><br>象曰：敦复无悔，中以自考也。</blockquote>
<p><strong>你现在在这个位置：你不争了。你承认自己前面走错了，现在想踏踏实实把日子过回去。</strong></p>
<p>敦，是厚、是老实。敦复就是<strong>老老实实回头</strong>。</p>
<p>到六五这一层，回头已经没有戏剧性了。没有顿悟，没有痛哭，就是你每天干该干的事。</p>
<p>爻辞给的是「无悔」——不是吉，是无悔。</p>
<p>这两个字的份量：<strong>无悔的意思是你不再跟自己算账了。</strong></p>
<p>象传「中以自考」说得明白：自己考自己。不看别人怎么评，你自己知道现在对不对。</p>
<p>具体动作：</p>
<p><strong>一，把生活里最基础的三件事定死。</strong> 睡几点、吃什么、什么时候动一动。回头这种事，最后都落在这些最土的地方。</p>
<p><strong>二，别回头去修补那些补不了的关系。</strong> 敦复是你自己往前走，不是把所有旧账都结清。有些账结不清。</p>
<p><strong>三，接受你现在的位置比跌倒前低。</strong> 很多人回不了头，是想回到原地。</p>
<p>回不到。你只能从这儿重新走。</p>
<p>重耳流亡十九年，从狄到卫，从齐到曹，从宋到郑到楚，最后到秦。他回国即位的时候已经六十二岁。</p>
<p>这十九年里他没有一次是要打回去，他就是在过流亡的日子——娶妻、结交、等时机。<strong>敦复讲的不是复仇，是过日子。</strong></p>
<p><strong>什么情况不用这么老实：</strong>如果你犯的错是伤过别人的，那你得先把该赔的赔了，再谈踏实。自己踏实了，别人还在疼，那不叫回头。</p>
<h3 id="p-上六-迷复-凶-走远了就不认路了">上六 · 迷复，凶 —— 走远了就不认路了</h3>
<blockquote class="pw-quote"><strong>上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。</strong><br>象曰：迷复之凶，反君道也。</blockquote>
<p><strong>你现在在这个位置：你已经错得有点久了。你知道不对，但你已经不知道从哪回头了。</strong></p>
<p>迷复——迷了路，回不去。</p>
<p>复卦这一爻是全卦唯一的凶，而且凶得极重：用行师终有大败，十年不克征。十年都缓不过来。</p>
<p>这一爻真正说的是：<strong>回头的窗口是有期限的。</strong></p>
<p>初九回头，代价是一句话。上六回头，代价是十年。</p>
<p>具体怎么做：</p>
<p><strong>一，先停。</strong> 迷复的人最常做的动作是加速——因为停下来就要面对，所以他们用更忙、更狠来盖住。停是唯一的第一步。</p>
<p><strong>二，找一个外面的人。</strong> 你自己在里面绕了太久，看路的能力已经坏了。这个人不能是你的下属，也不能是靠你吃饭的人。</p>
<p><strong>三，接受十年这个数字。</strong> 别指望三个月翻身。把预期降到十年，你才走得动。</p>
<p>项羽从垓下突围到乌江，亭长把船停在岸边，说江东虽小，地方千里，众数十万，也够称王了。</p>
<p>项羽笑了一下说，我带八千子弟渡江而西，今天没有一个人回来，我有什么脸见江东父老。他把马送了人，回头跟汉军打，杀了几百人，然后自刎。他不是没船，他是回不去了。</p>
<p><strong>什么情况还能救：</strong>如果那个「错」还没伤到别人、还没变成不可逆的事实，那就还有救。判断标准：<strong>有没有人因为你现在的做法，已经付出了不可挽回的代价。</strong> 有，就别谈回头了，先谈补救。</p>
<h3 id="p-最后-一阳来复-就一个字-弱">最后：一阳来复，就一个字，弱</h3>
<p>复卦这一卦，最容易被误读。</p>
<p>很多人看到「一阳来复」，以为是在讲春天来了、好日子要开始了。真读进去，它讲的是一根刚冒头的嫩芽。</p>
<p><strong>嫩芽最需要的不是阳光，是别再踩它。</strong></p>
<p>大象传给的四个字特别实在：「至日闭关」。</p>
<p>冬至那天关城门、停商旅、君主不巡视。在阳气刚生的那一刻，什么都不做。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">改过这件事，贵的不是决心，是早。</blockquote>
  `,
  wuwang: `
<p>一个人被车撞了。绿灯，斑马线，走得很规矩。</p>
<p>撞他的是个酒驾的。他在医院躺了四个月。</p>
<p>他出院之后有很长一段时间想不通。他想不通的不是「为什么是我」，他想不通的是——我什么都做对了，凭什么。</p>
<p>这个问题，《周易》在两千多年前就答过了。</p>
<p>无妄卦讲的是：<strong>这世上有一部分灾祸，跟你的对错没关系。</strong></p>
<p>无妄是「不妄」，就是不虚妄、不胡来。天雷无妄，天下打雷，万物都吓了一跳，各自老实待着。</p>
<p>这一卦的前半段讲你怎么做事不惹祸，后半段讲你怎么面对躲不开的祸。<strong>后半段才是它真正的分量。</strong></p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-无妄-往吉-别带心思">初九 · 无妄，往吉 —— 别带心思</h3>
<blockquote class="pw-quote"><strong>初九：无妄，往吉。</strong><br>象曰：无妄之往，得志也。</blockquote>
<p><strong>你现在在这个位置：你要去做一件事，这件事本身是对的。你有点犹豫，怕别人多想。</strong></p>
<p>初九是元吉那一档吗？不是，它就是「往吉」——去，就吉。</p>
<p>这一爻给的动作特别简单：<strong>去做，别铺垫。</strong></p>
<p>不解释动机，不提前打招呼，不发朋友圈预告。你越想让人理解你，动作就越变形。真做事的人身上有一种笨——他不太会包装。</p>
<p>判断标准在这儿：<strong>如果你的动机需要解释三句才讲得清，那这件事你就别做。</strong></p>
<p>因为需要解释的动机，往往连你自己都还没想清楚。</p>
<p>刘邦进咸阳，诸将都去抢金帛财物，萧何一个人跑到丞相府和御史府，把律令图书全收了。当时没人觉得这件事重要，抢钱的人还在笑他傻。四年之后，刘邦能知道天下要塞、户口多少、民间疾苦，靠的就是这批东西。</p>
<p><strong>什么情况要先说：</strong>如果这件事会动到别人的利益、会让人措手不及，那就得打招呼。无妄不等于莽撞。判断标准：<strong>你不说，对方会不会觉得被偷袭。</strong></p>
<h3 id="p-六二-不耕获-不菑畬-只问耕耘">六二 · 不耕获，不菑畬 —— 只问耕耘</h3>
<blockquote class="pw-quote"><strong>六二：不耕获，不菑畬，则利有攸往。</strong><br>象曰：不耕获，未富也。</blockquote>
<p><strong>你现在在这个位置：你在做一件长期的事。你还没看到结果，你开始算这活儿值不值。</strong></p>
<p>不耕获，是种地的时候不去盘算收成。不菑畬，是开荒的时候不去惦记那块熟田。</p>
<p>这一句是全卦最实用的一句。它讲的是<strong>把注意力从结果挪回过程</strong>。</p>
<p>为什么？你注意力放在收成上，你就会做那些能快速见效的动作——催熟、抢跑、抄近路。这些动作在短期内会赢，长期会把你那块地种坏。</p>
<p>具体动作两条：</p>
<p><strong>一，给你的工作定一个「过程指标」，而不是结果指标。</strong> 结果你控制不了，过程你能控制。写东西的人，把「今天写八百字」当目标；做销售的，把「今天打二十个电话」当目标。</p>
<p><strong>二，别提前庆祝。</strong> 象传这儿的四个字特别妙：「未富也」。你还没富呢，先干活。</p>
<p>李冰修都江堰，前后干了几十年。他自己没看到全功，他儿子接着干。</p>
<p>鱼嘴、飞沙堰、宝瓶口这三件东西，定下来之后两千多年没大改。修的人没机会验收，也没机会庆祝。</p>
<p><strong>什么情况要盯着结果：</strong>如果你手上是一份有明确交付期限的活，那过程自由是假的。对方要的是东西，不是你的努力。</p>
<p>判断标准：<strong>这活是给谁做的。</strong> 给自己长本事的，盯过程；给别人交差的，盯结果。</p>
<h3 id="p-六三-无妄之灾-或系之牛-锅从天上来">六三 · 无妄之灾，或系之牛 —— 锅从天上来</h3>
<blockquote class="pw-quote"><strong>六三：无妄之灾，或系之牛，行人之得，邑人之灾。</strong><br>象曰：行人得牛，邑人灾也。</blockquote>
<p><strong>你现在在这个位置：这事跟你没关系，可账记在你头上了。</strong></p>
<p>有人把牛拴在路边，过路的人顺手牵走了。牛是那个村里的人丢的，可被抓去问话、赔钱、挨骂的是全村的人。</p>
<p>这一爻描写的，就是<strong>责任分配的不讲理</strong>。</p>
<p>注意它写的不是「有妄之灾」，是无妄之灾。你没做错。</p>
<p>这种时候该干什么？<strong>先分清两件事：你的冤，和你的损失。</strong></p>
<p>冤是情绪，损失是事实。绝大多数人在这个位置上把全部力气花在证明冤上，最后冤也没洗清，损失还扩大了。</p>
<p>具体动作：</p>
<p><strong>一，第一时间留证据。</strong> 时间、地点、在场的人、你说的原话。这个东西不是为了打官司，是为了让将来任何一次翻旧账，你手里有东西。</p>
<p><strong>二，找那个真正得利的人。</strong> 爻辞里是「行人」——牵牛的人。锅通常不是凭空掉下来的，是有人把它挪过来的。</p>
<p><strong>三，认下眼前这一份，但把话说清楚。</strong> 认账不等于认罪。你可以赔这个钱，同时说清楚这不是我的错。</p>
<p>韩信被杀的时候，罪名是谋反。他有没有谋反这件事，从他被抓进长乐宫那天起就已经不重要了。</p>
<p>吕后要的是他死，萧何写的那封信是那根拴牛的绳子。韩信真正的问题，是他从齐王到淮阴侯这一路上，从来没把「别人怕他」这件事算进账里。</p>
<p><strong>什么情况必须喊到底：</strong>如果这一口锅会毁掉你的职业信誉、会被写进档案、会影响你以后找活，那就得喊到底。别的都可以忍，只有信誉不能。</p>
<h3 id="p-九四-可贞-无咎-守着你手上那点东西">九四 · 可贞，无咎 —— 守着你手上那点东西</h3>
<blockquote class="pw-quote"><strong>九四：可贞，无咎。</strong><br>象曰：可贞无咎，固有之也。</blockquote>
<p><strong>你现在在这个位置：外面很乱，各种消息乱飞。你手上有点东西，但你不知道守不守得住。</strong></p>
<p>爻辞就四个字：可贞，无咎。你可以守住，就没错。</p>
<p>象传补的那一句是关键：「固有之也」——<strong>你手上这东西本来就是你自己的。</strong></p>
<p>这一爻给的动作：<strong>划一条不可退的线。</strong></p>
<p>你这几年攒下的东西，哪一样是绝不能让的？客户、技术、信誉、还是那几个人。</p>
<p>把线划出来，然后所有决策就从这条线反推。</p>
<p>具体一点：<strong>列出三样不能让的东西，写下来。</strong> 谈判的时候、被劝的时候、心软的时候，拿出这张纸看。</p>
<p>为什么是「固有之」重要？因为一个人在慌乱里最容易把本来就属于自己的东西当成筹码交出去，还觉得自己很大方。</p>
<p>田单守即墨，燕军围了好几年。他手上没有援兵，没有粮草，只有一座城和城里的人。</p>
<p>他做的事情是：把自己的妻妾编进队伍，把能吃的东西全拿出来分。他不谈条件，他不突围，他就守着这一座城。<strong>守到燕昭王死，守到乐毅被换掉。</strong></p>
<p><strong>什么情况可以让：</strong>如果守这个东西的代价是拖垮其他更重要的东西，那就让。比如为了一单生意把人累垮，为了一句话把关系搞僵。判断标准：<strong>守它的成本，是不是已经超过它的价值。</strong></p>
<h3 id="p-九五-无妄之疾-勿药有喜-别乱吃药">九五 · 无妄之疾，勿药有喜 —— 别乱吃药</h3>
<blockquote class="pw-quote"><strong>九五：无妄之疾，勿药有喜。</strong><br>象曰：无妄之药，不可试也。</blockquote>
<p><strong>你现在在这个位置：你摊上一件不是你招来的麻烦。你很想做点什么，哪怕做点什么心里能舒服一点。</strong></p>
<p>无妄之疾，勿药有喜。不是你自己招来的病，别吃药，自己会好。</p>
<p>这是全卦最狠的一句。</p>
<p>因为人在这个时候的本能就是<strong>乱动</strong>。开个会、放个话、找个人、换个方向——这些动作的收益是「我在努力」，成本是「本来会自己好的事被你搞坏了」。</p>
<p>象传说得更绝：<strong>「无妄之药，不可试也」。</strong> 不是「慎重」，是「不可试」。</p>
<p>药这种东西，试错成本太高。</p>
<p>具体怎么判断该不该吃药？三个问题：</p>
<p><strong>一，这个麻烦有没有自己消退的路径？</strong> 有，就等。</p>
<p><strong>二，我这个动作，是在解决它，还是在缓解我的焦虑？</strong> 后者居多，就不做。</p>
<p><strong>三，等一个月，代价是什么？</strong> 一个月后代价不变，那就等一个月。</p>
<p>汉文帝刚即位的时候，南越王赵佗自立称帝，打也不划算，封也不合适。</p>
<p>文帝做的事是：把赵佗在中原的祖坟修好，把他的亲戚封了官，然后派陆贾去送了一封信。信里姿态放得很低。</p>
<p>赵佗看完就把帝号去掉了。汉文帝没动一兵一卒。</p>
<p><strong>什么情况必须吃药：</strong>如果这个病是会恶化的，拖延等于放弃，那就得下药。判断标准：<strong>这件事放着不管，一个月后是原样，还是更糟。</strong> 更糟就得动。</p>
<h3 id="p-上九-无妄-行有眚-别硬闯">上九 · 无妄，行有眚 —— 别硬闯</h3>
<blockquote class="pw-quote"><strong>上九：无妄，行有眚，无攸利。</strong><br>象曰：无妄之行，穷之灾也。</blockquote>
<p><strong>你现在在这个位置：你没做错任何事，但你已经被推到了尽头。你想再争一次。</strong></p>
<p>无妄之行，行有眚。</p>
<p>这一爻和初九用的是同一个词——无妄。初九是「往吉」，上九是「行有眚」。同样是无妄，结果反过来了。</p>
<p>差别在位置。初九在底下，往上走是生路；上九在顶上，再往前就是悬崖。</p>
<p>象传四个字：「穷之灾也」。穷不是穷困，是走到头了。</p>
<p>所以这一爻的动作是：<strong>停。</strong></p>
<p>这句听起来像废话。难的地方在于——<strong>一个人被冤枉到最后，最难的就是停手。</strong></p>
<p>因为停手意味着你接受了那个冤枉。你会觉得，我一停就等于认了。</p>
<p>爻辞告诉你：认不认是你的事，行不行是另一回事。到这儿再动，动的每一下都是损失。</p>
<p>蒙恬死在阳周。他手里有三十万大军，扶苏已经死了，赵高派的使者来让他自尽。</p>
<p>他说了一句「恬罪固当死矣」，然后讲修长城、开直道，大概是动了地脉。他没有反，他把刀拿起来自尽了。</p>
<p>他手里有兵，他真反了也许能撑一阵。可他停住了，蒙家三代在秦为将，他不想把它变成叛乱。</p>
<p><strong>什么情况还可以动：</strong>如果你手上还有牌，而且这张牌打出去能改变局面，那就打。判断标准：<strong>你现在动，是能改变结果，还是只是不想认输。</strong> 后者就停。</p>
<h3 id="p-最后-该做的做完-剩下的交给运气">最后：该做的做完，剩下的交给运气</h3>
<p>无妄卦这一卦，最难懂的是它把两件事放在了一起：<strong>做事不要胡来</strong>，和<strong>胡来不胡来跟你会不会倒霉无关</strong>。</p>
<p>前半句让你自律，后半句让你别自责。</p>
<p>这两句合起来才是完整的态度：<strong>对自己能控制的部分极严，对自己控制不了的部分认了。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">你只负责不妄为。灾祸归谁管，不归你管。</blockquote>
  `,
  daxu: `
<p>我认识一个做投资的，四十岁那年把所有仓位清了。</p>
<p>不是看空，是他发现自己二十年来一直在做同一件事：赚了钱就找下一个机会，从来没有停下来过。账户数字在涨，人越来越空。</p>
<p>他清仓之后做的第一件事，是把过去十年的每一笔亏损交易翻出来，一条一条写原因。写了一整年。</p>
<p>第二年他重新开始投，规模比以前小得多，收益比前二十年都好。</p>
<p>大畜卦讲的就是这件事：<strong>积攒分两种，一种越攒越散，一种越攒越厚。</strong></p>
<p>大畜是山天大畜，山在上面，天在下面。天那么大，藏在山里面。这是《周易》里最夸张的一个比喻——装得下的，比看得见的大得多。</p>
<p>卦辞讲「不家食吉，利涉大川」：有本事的人不该窝在家里自己吃饭，要出来做事，要能过大河。</p>
<p>所以大畜不是让你囤，是让你<strong>攒到能用出去</strong>。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-有厉-利已-有危险就先停">初九 · 有厉，利已 —— 有危险就先停</h3>
<blockquote class="pw-quote"><strong>初九：有厉，利已。</strong><br>象曰：有厉利已，不犯灾也。</blockquote>
<p><strong>你现在在这个位置：你想往前推一步，但你心里那个警报响了。</strong></p>
<p>「已」是停止。有危险，利于停下。</p>
<p>注意爻辞的写法——它没说「有危险，小心点」，它说「利已」，利于停。这是一个动作指令，不是一个提醒。</p>
<p>这个阶段的具体动作：<strong>停三天。</strong></p>
<p>不是永远停，是给自己设一个三天的冷却期。三天之内不做决定、不发消息、不签字。</p>
<p>判断标准在这儿：<strong>你这三天里，是越想越想做，还是慢慢没那么想做了。</strong> 前者可能是真机会，后者一定是一时上头。</p>
<p>还有一个更硬的指标：<strong>你能不能把这个决定讲给一个不会顺着你说的人听，而不心虚。</strong></p>
<p>刘邦进了咸阳宫，看见宫里的帷帐狗马、重宝妇女，想住下来。樊哙劝他出去住，他不听。</p>
<p>张良说了一句：「秦为无道，故沛公得至此。夫为天下除残贼，宜缟素为资。」</p>
<p>刘邦听完就出去了。这就是「有厉，利已」——他已经一脚踏进去了，停住了。</p>
<p><strong>什么情况别停：</strong>如果这个窗口非常短、过了今天就没了，那就别等三天。判断标准：<strong>这个决定是不是可逆的。</strong> 可逆的先做，不可逆的先停。</p>
<h3 id="p-九二-舆说輹-主动把车卸了">九二 · 舆说輹 —— 主动把车卸了</h3>
<blockquote class="pw-quote"><strong>九二：舆说輹。</strong><br>象曰：舆说輹，中无尤也。</blockquote>
<p><strong>你现在在这个位置：你在往一个方向走，但路上出了点状况。车走不动了。</strong></p>
<p>说，通「脱」。輹是车轴上的那个部件。舆说輹，就是车轴脱了，车不能走了。</p>
<p>初九是「有危险，停下来」，九二是<strong>车已经坏了，你不得不停</strong>。</p>
<p>这两爻的差别很重要。初九是主动，九二是被动。</p>
<p>九二真正讲的是：<strong>被迫停下的时候，你的反应是什么。</strong></p>
<p>大多数人的反应是修车、催车、换车。九二告诉你，象传给的是「中无尤也」——你停下这件事，没有过错。</p>
<p>具体动作三条：</p>
<p><strong>一，先搞清楚是轴坏了还是路坏了。</strong> 这两个的修法完全不同。路坏了要绕，轴坏了要修，分不清就瞎折腾。</p>
<p><strong>二，别在停下的时候乱花钱。</strong> 停下来的时候人容易急，一急就容易被人割。</p>
<p><strong>三，把停下当信息。</strong> 车坏了是一个信号，可能告诉你这趟不该走，也可能告诉你该换一辆。</p>
<p>周文王被商纣囚在羑里，前后七年。七个年头里他什么都干不了，出不去的门，见不到的人。</p>
<p>他在那里做的事是推演八卦，把伏羲的八卦扩成六十四卦。出来的时候，他带出来的是一整套东西。<strong>被迫停下来的那七年，成了他一辈子最厚的一层。</strong></p>
<p><strong>什么情况不能停：</strong>如果这件事一停就直接出局，而且出局之后没有第二次机会，那车坏了也得推着走。判断标准：<strong>停下来之后，你还有没有下一趟车。</strong></p>
<h3 id="p-九三-良马逐-利艰贞-路通了-别撒欢">九三 · 良马逐，利艰贞 —— 路通了，别撒欢</h3>
<blockquote class="pw-quote"><strong>九三：良马逐，利艰贞。曰闲舆卫，利有攸往。</strong><br>象曰：利有攸往，上合志也。</blockquote>
<p><strong>你现在在这个位置：卡了很久的事突然通了。你憋着一股劲，想一口气跑完。</strong></p>
<p>良马逐，好马在追。前两爻堵着的东西通了，九三可以跑起来了。</p>
<p>但爻辞马上跟了三个字：利艰贞。<strong>时机对的时候，尤其要能吃苦、能守正。</strong></p>
<p>最后还有一句更实在的：曰闲舆卫。闲是练习，舆是车，卫是护卫。翻译过来就是——<strong>平时要把车马和防卫练熟。</strong></p>
<p>这一句是全卦最像大白话的一句。它说：跑道通了，你要检查的是你的车和马，不是你的心情。</p>
<p>具体动作：<strong>在顺境里补短板。</strong></p>
<p>人在顺的时候最讨厌听「补短板」，因为顺的时候感觉不到疼。等不顺了再补，来不及。</p>
<p>判断标准很简单：<strong>这波机会里，哪个环节是你现在最没底的？</strong> 就从那个环节开始练。</p>
<p>田单火牛破燕之后，齐国七十多城一下收回。齐襄王入临淄，田单被封安平君，功高得没法再高。</p>
<p>那时候他最该做的是练兵、修政、稳住人心。可他很快就被齐王猜忌，跑去了赵国。顺风的时候没把底盘弄扎实。</p>
<p><strong>什么情况可以撒欢跑：</strong>如果这波机会是限时的，而且误了就没有第二波，那就全力跑，短板的事以后再说。判断标准：<strong>这个机会还有没有下一次。</strong></p>
<h3 id="p-六四-童牛之牿-元吉-趁小的时候管住">六四 · 童牛之牿，元吉 —— 趁小的时候管住</h3>
<blockquote class="pw-quote"><strong>六四：童牛之牿，元吉。</strong><br>象曰：六四元吉，有喜也。</blockquote>
<p><strong>你现在在这个位置：你手上有个刚起步的事，或者一个刚入行的年轻人。他还小，问题也小。</strong></p>
<p>童牛之牿——小牛还没长角的时候，先给它套上木枷。</p>
<p>这一爻是全卦最吉的一爻，元吉。原因就在那个「童」字。</p>
<p><strong>同样的动作，早做和不早做，结果差得远。</strong></p>
<p>牛角长出来了你再去套，那叫制服；牛角没长出来你就套上，那叫规矩。前者费力且有血，后者省力且无怨。</p>
<p>具体动作三条：</p>
<p><strong>一，规矩在第一天定。</strong> 新人的第一条规矩、新项目的第一版流程、新关系的第一次边界。第一次不立，后面要花的力气是十倍。</p>
<p><strong>二，把「牿」做小。</strong> 木枷不能太大，太大牛受不了。管理动作要轻，轻到对方感觉不到你在管。</p>
<p><strong>三，这个动作的目的是让他长角，不是让他没角。</strong> 很多人把约束做成了压制，结果养出一头不会顶的牛。</p>
<p>《管子》里讲，管仲治齐，一开始做的不是大开大合的改革，是先定了几条最基础的规矩：四民分业、士农工商各安其居。这几条东西从齐桓公刚即位就定下，一直用到桓公死。<strong>先套小枷，再放大牛。</strong></p>
<p><strong>什么情况别急着管：</strong>如果这个人或这件事你还完全看不懂，那就先看，别急着定规矩。定错了的规矩比没有规矩更麻烦。判断标准：<strong>你能不能说清楚，这条规矩是防什么的。</strong></p>
<h3 id="p-六五-豮豕之牙-吉-治住了那头野猪">六五 · 豮豕之牙，吉 —— 治住了那头野猪</h3>
<blockquote class="pw-quote"><strong>六五：豮豕之牙，吉。</strong><br>象曰：六五之吉，有庆也。</blockquote>
<p><strong>你现在在这个位置：你手上有个已经长大的麻烦。硬碰碰不动，你只能想别的办法。</strong></p>
<p>豮豕，是阉过的猪。之牙，是它的獠牙。</p>
<p>野猪最难对付的不是牙，是它的凶性。你把它的牙拔了，它还会用身体撞你；你把它的凶性去了，牙在那儿也不咬人。</p>
<p><strong>这一爻讲的是：对付养成气候的东西，要治它的性，不是治它的形。</strong></p>
<p>具体怎么做：</p>
<p><strong>一，找到它的「性」在哪。</strong> 那家刺头公司凭什么横？那个老油条凭什么能扛？</p>
<p>查清楚他的能量是从哪来的。</p>
<p><strong>二，把那个来源切掉。</strong> 不是跟他吵，是让他吵不动了。他背后的资源断了、他的信息渠道堵了、他的靠山调走了，他自己就变成一头普通猪。</p>
<p><strong>三，别去拔牙。</strong> 拔牙是一个正面对抗的动作，成本高，还容易见血。</p>
<p>汉景帝时候，晁错要削藩，硬削，结果七国之乱。</p>
<p>到了汉武帝，主父偃出的是推恩令——不削，让诸侯把封地分给所有儿子。几年之后，大国自动变成了小国，小国变成了侯。同样的目标，一个拔牙，一个去性。</p>
<p><strong>什么情况必须硬碰：</strong>如果这个东西已经伤到人、已经越线，那就别再绕了。绕着走会让它以为你没底线。判断标准：<strong>它有没有在继续扩大。</strong></p>
<h3 id="p-上九-何天之衢-亨-路通了">上九 · 何天之衢，亨 —— 路通了</h3>
<blockquote class="pw-quote"><strong>上九：何天之衢，亨。</strong><br>象曰：何天之衢，道大行也。</blockquote>
<p><strong>你现在在这个位置：你攒了很多年。现在机会来了，或者你终于知道这些东西怎么用了。</strong></p>
<p>何天之衢——担负起通天的大道。</p>
<p>上九是大畜的顶点。前面五爻都在讲怎么攒、怎么止、怎么管，到这儿讲的是<strong>用</strong>。</p>
<p>卦辞那句「不家食吉，利涉大川」，落到上九才真正兑现。</p>
<p>具体动作：</p>
<p><strong>一，把你攒的东西拿出来对一次账。</strong> 你这些年攒下来的，哪几样是真的，哪几样早就过期了。攒久了的人常常没发现有些东西已经发霉。</p>
<p><strong>二，做那个你以前不敢做的决定。</strong> 上九讲的是「道大行」——你可以走大道了。这时候该干的不是再攒一点，是把事做大。</p>
<p><strong>三，把这个位置让出一部分给年轻人。</strong> 路通了的意思是大家都能走，不是你一个人走。</p>
<p>孔子周游列国十四年，到处碰壁，回到鲁国的时候已经六十八岁。他在外面没做成官，回来之后开始整理《诗》《书》，删定《春秋》。</p>
<p>前面十四年是攒，后面几年是用。他一辈子没有当上宰相，可他那几年的东西，让后来两千年的人都得从他这儿过。</p>
<p><strong>什么情况别急着用：</strong>如果你攒的东西还没成型，硬拿出来用会砸招牌。判断标准：<strong>现在这一套，能不能经得住一个懂行的人问三个问题。</strong></p>
<h3 id="p-最后-大畜的-大-在藏的那个部分">最后：大畜的「大」在藏的那个部分</h3>
<p>大畜和小畜的差别，不在攒多少，在<strong>藏什么</strong>。</p>
<p>小畜攒的是力量、是人脉、是钱。大畜攒的是德、是学问、是能托付的人。</p>
<p>大象传给的方法特别笨：「多识前言往行，以畜其德」。多看看前人在类似处境里干了什么。</p>
<p>这个方法笨，但它有用。因为你能踩的坑，前人基本都踩过。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">攒本事的人不着急用，急着用的人攒不下本事。</blockquote>
  `,
  yi: `
<p>一个三十五岁的人跟我说，他这几年最大的变化是：话变少了，饭量也变少了。</p>
<p>他以前是饭局上的中心。谁有难处找他，他都能给出主意；谁组的局，他都能撑起场子。现在他推掉大部分饭局，晚上回家吃一碗面。</p>
<p>我问他为什么。他说：「我发现我说的话，一大半是不用说的。我吃的饭，一小半是身体需要的。」</p>
<p>颐卦讲的就是这个。颐是下巴，是嘴。卦象上艮下震，上面不动，下面在动——就是一张嘴在嚼东西。</p>
<p>卦辞说「观颐，自求口实」。<strong>看一个人怎么养活自己，就知道他是什么人。</strong></p>
<p>这一卦只有两条规矩，大象传里写得明明白白：<strong>慎言语，节饮食。</strong></p>
<p>一进一出。进来的叫饮食，出去的叫言语。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-舍尔灵龟-观我朵颐-眼馋别人碗里的">初九 · 舍尔灵龟，观我朵颐 —— 眼馋别人碗里的</h3>
<blockquote class="pw-quote"><strong>初九：舍尔灵龟，观我朵颐，凶。</strong><br>象曰：观我朵颐，亦不足贵也。</blockquote>
<p><strong>你现在在这个位置：你手上有自己的东西，但你眼睛盯着别人的。</strong></p>
<p>灵龟是古人用来占卜的，龟壳上有纹路，能看出吉凶。这里说的灵龟，是你自己本来有的那份明白。</p>
<p>朵颐是下巴在动，是在嚼东西的样子。看着别人吃，自己流口水。</p>
<p>爻辞的判词只有一个字：凶。</p>
<p>这个凶不是说你会挨饿，是说<strong>你把自己最值钱的东西丢了，去换一个别人正在吃的东西。</strong></p>
<p>具体动作：<strong>数一遍你手上有什么。</strong></p>
<p>不是数钱，是数那些别人拿不走的东西：你的判断力、你的手艺、你的关系、你对某件事的懂。写下来，写十条。</p>
<p>写完之后你会发现，你眼馋的那个东西，通常是可以用这里面的某几条换来的。<strong>你不需要羡慕，你需要交换。</strong></p>
<p>判断标准在这儿：<strong>你羡慕的那个东西，是因为它真的好，还是因为它在你手上没有。</strong></p>
<p>苏秦第一次出去游说，跑了一圈回来，家里人对他爱答不理，「妻不下纴，嫂不为炊，父母不与言」。他没去羡慕别人的富贵，他做的是把自己关起来，把《阴符》读了一遍又一遍。一年之后他再出去，佩六国相印。</p>
<p><strong>什么情况可以眼馋：</strong>如果那个东西确实是好东西，而且你现在手上的东西一时半会儿够不着它，那就去学。判断标准：<strong>你眼馋的是它的结果，还是它的做法。</strong> 前者是贪，后者是学。</p>
<h3 id="p-六二-颠颐-拂经-于丘颐-该往上找-你偏往下求">六二 · 颠颐，拂经，于丘颐 —— 该往上找，你偏往下求</h3>
<blockquote class="pw-quote"><strong>六二：颠颐，拂经，于丘颐，征凶。</strong><br>象曰：六二征凶，行失类也。</blockquote>
<p><strong>你现在在这个位置：你需要帮助，但你去找的那个人，找错了。</strong></p>
<p>颠是倒。拂经是违背常理。丘是高处。</p>
<p>合起来：<strong>你把上下的次序搞反了，你去向一个不该求的人求东西。</strong></p>
<p>这个位置的动作很具体：<strong>停下来，重新看一眼你该向谁开口。</strong></p>
<p>大多数人在求人的时候犯的错，是找最近的那个，而不是找最对的那个。</p>
<p>判断标准是这一条：<strong>这个人有没有能力给你，以及愿不愿意给。</strong></p>
<p>有能力不愿意给的，你开口就是白丢面子；没能力愿意给的，你开口就是给对方添麻烦。</p>
<p>六二爻辞里用的是「征凶」——你要是就这么去了，凶。</p>
<p>伍子胥从楚国逃出来，先投宋，宋国内乱；投郑，郑国杀了太子建；最后才一路跑到吴国。他前面两次投靠都是「于丘颐」——找的近，但找错了。真正让他翻盘的是吴王阖闾，那才是能给他东西的人。</p>
<p><strong>什么情况就得向下求：</strong>如果你要的是人手、是具体执行，那往下找是对的。判断标准：<strong>你要的是资源，还是力气。</strong> 资源往上，力气往下。</p>
<h3 id="p-六三-拂颐-贞凶-十年勿用-靠讨好换饭吃">六三 · 拂颐，贞凶，十年勿用 —— 靠讨好换饭吃</h3>
<blockquote class="pw-quote"><strong>六三：拂颐，贞凶，十年勿用，无攸利。</strong><br>象曰：十年勿用，道大悖也。</blockquote>
<p><strong>你现在在这个位置：你在靠迎合一个人换东西。你知道不对，但这样来钱快。</strong></p>
<p>拂颐是违背了颐养之道。爻辞给的判词极重：十年勿用，无攸利。</p>
<p>十年。这是《周易》里最长的惩罚期之一。</p>
<p>这一爻讲的是<strong>用讨好换生存</strong>这条路的代价。</p>
<p>为什么代价这么大？因为讨好这件事是有复利的——你讨好一次，别人对你的定价就低一分。低到某个程度，你就再也卖不出别的价钱了。</p>
<p>具体动作：<strong>测一下你的东西是从哪来的。</strong></p>
<p>你的收入、你的位置、你的机会，有多少是因为你行，有多少是因为某人喜欢你。</p>
<p>这个比例不用算得精确，凭直觉给个大致数就行。低于三七开，你就得警惕了。</p>
<p>易牙是齐桓公的厨子。桓公说没吃过人肉，易牙就把自己儿子煮了给桓公吃。</p>
<p>管仲临死前跟桓公说，人情没有不爱自己儿子的，这个人连儿子都能不要，你指望他爱你？桓公没听。管仲死后，易牙把桓公锁在宫里，活活饿死。</p>
<p><strong>什么情况可以做小伏低：</strong>如果是暂时的、有期限的、而且你知道自己在干什么，那可以。判断标准：<strong>你有没有一个说停就停的时间点。</strong> 没有，就是滑进去了。</p>
<h3 id="p-六四-颠颐-吉-虎视眈眈-其欲逐逐-养人要有虎相">六四 · 颠颐，吉。虎视眈眈，其欲逐逐 —— 养人要有虎相</h3>
<blockquote class="pw-quote"><strong>六四：颠颐，吉。虎视眈眈，其欲逐逐，无咎。</strong><br>象曰：颠颐之吉，上施光也。</blockquote>
<p><strong>你现在在这个位置：你手上有资源，你要往下分。但下面的人开始拿你当软柿子。</strong></p>
<p>六二也是颠颐，判词是凶；六四也是颠颐，判词是吉。</p>
<p>同样的动作，差别在<strong>你在什么位置上做</strong>。</p>
<p>六四在上面，它往下养人是应该的。但爻辞紧跟着两句极生动的描写：虎视眈眈——像老虎一样盯着；其欲逐逐——欲望深沉而持续。</p>
<p>翻译过来：<strong>你给东西的时候，眼神不能是软的。</strong></p>
<p>为什么？因为你一软，接受的人就不觉得这是恩，觉得这是你应该的。这次的恩，变成了下次的义务。</p>
<p>具体动作三条：</p>
<p><strong>一，给的时候把条件说清楚。</strong> 什么时候给、给多少、换什么。</p>
<p><strong>二，别一次性给足。</strong> 给足了他就不需要你了，也没动力了。</p>
<p><strong>三，保持距离。</strong> 别跟被养的人称兄道弟，那是另一码事。</p>
<p>范蠡帮勾践灭了吴，功成之后泛舟五湖，跑到齐国做生意，成了陶朱公。</p>
<p>他做生意有一句话：「贵出如粪土，贱取如珠玉。」意思是一样东西贵的时候要舍得卖，贱的时候要敢买。这是虎视眈眈——他从不心软。</p>
<p><strong>什么情况必须软：</strong>如果对方是来投奔你的、已经没退路了，那就别再端着。判断标准：<strong>他还有没有别的选择。</strong> 没有，你端着就是欺负人。</p>
<h3 id="p-六五-拂经-居贞吉-不可涉大川-你得靠人-别硬撑">六五 · 拂经，居贞吉，不可涉大川 —— 你得靠人，别硬撑</h3>
<blockquote class="pw-quote"><strong>六五：拂经，居贞吉，不可涉大川。</strong><br>象曰：居贞之吉，顺以从上也。</blockquote>
<p><strong>你现在在这个位置：你在一个需要担事的位置上，可你手上没有实权，或者没有底气。</strong></p>
<p>六五是君位，但它是阴爻。阴在君位，意思是<strong>你有名分，没实力</strong>。</p>
<p>拂经——不合常规。这个位置本来该是阳爻来坐。</p>
<p>爻辞给的是「居贞吉，不可涉大川」：<strong>守着这一摊，吉；想干大事，不行。</strong></p>
<p>这一爻最实用的地方在于它承认了局限。</p>
<p>你在这个位置上，动作就两个：<strong>守，和靠。</strong></p>
<p>守是别乱动，别搞大动作。靠是顺着上面那个人，把事做成。</p>
<p>具体一点：<strong>把你想干的事，包装成上面想干的事。</strong></p>
<p>这不是投机，这是苟全。你自己的实力不够的时候，你只能借力。</p>
<p>汉惠帝在位的时候，实权在吕后手里。惠帝做的事情是守着，不折腾，也不跟母亲硬顶。他死得早，在位七年，没打过仗，没搞过大工程，也没被废。</p>
<p>曹参当丞相，天天喝酒，惠帝问他，他说「陛下自察圣武孰与高帝？」惠帝说不如。</p>
<p>曹参说「高帝与萧何定天下，法令既明，今陛下垂拱，参等守职，遵而勿失，不亦可乎？」这就是居贞。</p>
<p><strong>什么情况可以涉大川：</strong>如果上面那个人信任你，而且明确授权给你，那就可以动。判断标准：<strong>出了事之后，有没有人替你兜。</strong></p>
<h3 id="p-上九-由颐-厉吉-利涉大川-天下靠你养">上九 · 由颐，厉吉，利涉大川 —— 天下靠你养</h3>
<blockquote class="pw-quote"><strong>上九：由颐，厉吉，利涉大川。</strong><br>象曰：由颐厉吉，大有庆也。</blockquote>
<p><strong>你现在在这个位置：很多人的饭碗系在你身上。你是那个真正拍板给东西的人。</strong></p>
<p>由颐——天下由此而得养。</p>
<p>上九是全卦最有分量的一爻。它讲的是<strong>责任</strong>。</p>
<p>「厉吉」两个字连在一起，意思是：有危险，但结果是吉的。</p>
<p>这一爻的分量在于：<strong>你养的人越多，你越不能倒。</strong></p>
<p>具体动作三条：</p>
<p><strong>一，把分配规则公开。</strong> 你一个人定谁多谁少，早晚有人不服。规则公开了，不服的人是对规则不服，不是对你。</p>
<p><strong>二，别掏空自己去养。</strong> 你倒了，靠你的人都得散。给自己留一份。</p>
<p><strong>三，找到下一个「由颐」的人。</strong> 你不可能一直养下去。</p>
<p>信陵君窃符救赵之后，留在赵国十年不敢回魏。后来秦国打魏国，魏王请他回去，他回去做了上将军，率五国之兵破秦军于河外。</p>
<p>那时候他就是「由颐」——五国的人都指着他。可秦国人一使反间计，魏王就夺了他的兵权。他从此称病不朝，天天喝酒，四年后死了。</p>
<p><strong>什么情况可以卸担子：</strong>如果你发现自己已经没能力再养这群人了，那早点说，让别人接。判断标准：<strong>你现在给出去的东西，质量有没有下降。</strong></p>
<h3 id="p-最后-嘴是唯一一个两个方向都开的器官">最后：嘴是唯一一个两个方向都开的器官</h3>
<p>颐卦的道理，说到底就一句：<strong>你每天往嘴里放什么，往外说什么，决定了你是个什么人。</strong></p>
<p>这两件事都不难，难的是每天都做对。</p>
<p>大象传给的办法最朴素：<strong>慎言语，节饮食。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">管住嘴不是忍着不说话，是别什么都往里塞。</blockquote>
  `,
  daguo: `
<p>一栋楼的梁弯了，不是因为梁不够粗。</p>
<p>是因为两头的柱子太细。</p>
<p>大过卦的卦辞只有三个字：栋桡。栋是房梁，桡是弯曲。上面是泽，下面是木，泽水没过了树——水大过了头。</p>
<p>这一卦四个阳爻挤在中间，上下各一个阴爻。中间太刚太实，两头太虚太软。重量全压在中间，两头撑不住。</p>
<p><strong>大过讲的是非常时期。</strong></p>
<p>不是平常的日子。平常的日子有平常的办法，非常的日子没有。</p>
<p>大过卦的分量在于：它承认有些时候你必须做过头的动作，同时警告你——过头的动作会要命。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-藉用白茅-无咎-小心到过分">初六 · 藉用白茅，无咎 —— 小心到过分</h3>
<blockquote class="pw-quote"><strong>初六：藉用白茅，无咎。</strong><br>象曰：藉用白茅，柔在下也。</blockquote>
<p><strong>你现在在这个位置：你要去做一件有点冒险的事。你心里没底，但非做不可。</strong></p>
<p>白茅是一种很干净的草。古人祭祀的时候，把祭器放在白茅上，怕碰坏了，怕沾了土。</p>
<p>一个陶罐放在一堆草上，这在平时看着多余。但爻辞说：无咎。</p>
<p><strong>过分小心，在这个时候不算毛病。</strong></p>
<p>这一爻给的道理很实在：<strong>当你对局面没有把握的时候，把冗余做足。</strong></p>
<p>具体到能照做的：</p>
<p><strong>一，这件事最坏的结果是什么，写下来。</strong> 写在纸上，不要只在脑子里过。</p>
<p><strong>二，为最坏的结果准备一个垫子。</strong> 钱、时间、后路。这个垫子宁可厚，不要薄。</p>
<p><strong>三，把动作放慢一倍。</strong> 大过的时候，快就是险。</p>
<p>刘邦赴鸿门宴之前，先跟项伯结了儿女亲家。到了鸿门，一进门就谢罪，说自己跟将军并肩作战，没想到先入关了。</p>
<p>他带了樊哙，把张良留在外面。每一个环节都是白茅。<strong>他没打算打，他打算活。</strong></p>
<p><strong>什么情况不用这么小心：</strong>如果这件事的失败成本很低，重来一次就行，那就别搞这么多铺垫。判断标准：<strong>最坏的结果，你扛不扛得住。</strong></p>
<h3 id="p-九二-枯杨生稊-老夫得其女妻-老树发新芽">九二 · 枯杨生稊，老夫得其女妻 —— 老树发新芽</h3>
<blockquote class="pw-quote"><strong>九二：枯杨生稊，老夫得其女妻，无不利。</strong><br>象曰：老夫女妻，过以相与也。</blockquote>
<p><strong>你现在在这个位置：你自己有点老了、有点疲了。但有个新的人、新的东西进来了。</strong></p>
<p>枯杨生稊。稊是杨树新长的嫩芽。一棵枯了的杨树，重新发了芽。</p>
<p>老夫得其女妻，是说老头娶了个年轻媳妇。爻辞给的判词是「无不利」。</p>
<p>这一爻讲的是一种很特别的组合：<strong>衰的和壮的搭在一起。</strong></p>
<p>九二是阳爻，但它在阴位上。本该是阴的地方，来了个阳——这就叫「过」。</p>
<p>具体动作：</p>
<p><strong>一，把你手上快枯的那部分，交给新的人接手。</strong> 经验在你身上，力气在他身上。</p>
<p><strong>二，别怕人家说你靠年轻人。</strong> 靠得住就是本事。</p>
<p><strong>三，给新人真东西。</strong> 资源、位置、署名。只给名分不给东西，芽长不出来。</p>
<p>管仲临终前，齐桓公问他谁可以接相位。管仲说竖刁、易牙、开方这三个人不能用，隰朋可以。隰朋年纪比管仲小不少，桓公也用了。</p>
<p>管仲死，隰朋接任。这就是枯杨生稊——<strong>老的那棵树还在，新芽先冒出来。</strong></p>
<p><strong>什么情况不该搭：</strong>如果你只是想让年轻人给你抬轿子、干脏活，那就别搭。判断标准：<strong>你给出去的东西，是不是他真能带走的。</strong></p>
<h3 id="p-九三-栋桡-凶-一个人扛-扛不住">九三 · 栋桡，凶 —— 一个人扛，扛不住</h3>
<blockquote class="pw-quote"><strong>九三：栋桡，凶。</strong><br>象曰：栋桡之凶，不可以有辅也。</blockquote>
<p><strong>你现在在这个位置：所有的重量都压在你一个人身上。你觉得撑得住，但你其实已经弯了。</strong></p>
<p>九三和卦辞「栋桡」用的是同一句话，但判词是凶。</p>
<p>象传解释得很狠：「不可以有辅也」——<strong>没人能帮你。</strong></p>
<p>不是没人想帮，是这个结构决定了他帮不上。因为你太刚了，你把该分出去的东西全攥在手里。</p>
<p>具体动作：</p>
<p><strong>一，把你手上那件「只有你能干」的事，拆成三步。</strong> 第一步给别人，第二步给别人，第三步留给自己。</p>
<p><strong>二，看你的身体。</strong> 这个阶段的人通常已经开始失眠、颈椎疼、脾气大。这是梁在叫。</p>
<p><strong>三，找一个替补。</strong> 不是找个人来分担，是找个人来接。</p>
<p>诸葛亮最后一次北伐，出斜谷，屯五丈原。司马懿坚守不出。</p>
<p>诸葛亮派使者去下战书，司马懿不问军事，只问诸葛亮的饮食和睡眠。使者说，诸葛公早起晚睡，罚二十杖的事都亲自过问，吃得很少。</p>
<p>司马懿说：「孔明食少事烦，其能久乎？」几个月后诸葛亮死在五丈原。</p>
<p><strong>什么情况可以独扛：</strong>如果这件事只剩最后一个月、而且成了就彻底结束，那就扛过去。判断标准：<strong>这个状态还有没有尽头。</strong></p>
<h3 id="p-九四-栋隆-吉-有它吝-把梁真正挺起来">九四 · 栋隆，吉，有它吝 —— 把梁真正挺起来</h3>
<blockquote class="pw-quote"><strong>九四：栋隆，吉，有它吝。</strong><br>象曰：栋隆之吉，不桡乎下也。</blockquote>
<p><strong>你现在在这个位置：你已经在支柱子的位置上了。承不承得住，就看这一步。</strong></p>
<p>栋隆，房梁隆起来了。吉。</p>
<p>九三的梁是弯的，九四的梁是隆的。区别在哪？象传说「不桡乎下也」——<strong>它没有向下弯。</strong></p>
<p>九四和九三都是阳爻，位置差不多，差别在于九四「以阳处阴」，它懂得往柔的方向走一点。</p>
<p>这个「柔」不是软弱，是<strong>把力分出去</strong>。</p>
<p>具体动作三条：</p>
<p><strong>一，把承重点分散。</strong> 一根梁承重，还是三根梁承重，结果完全不同。</p>
<p><strong>二，建制度，别建人望。</strong> 你在，事能成；你不在，事也能成。这才是隆。</p>
<p><strong>三，注意「有它吝」。</strong> 「它」是别的牵扯。你一旦被别的事分心，梁就白隆了。</p>
<p>萧何做汉朝丞相，刘邦在外打仗，萧何在关中管后方，粮草兵员从来没断过。他自己不领兵，不打仗，就守着这一摊。</p>
<p>刘邦几次派人来慰问他，他门客提醒他：这是不放心你。萧何于是把子弟送到前线去当兵，把家产捐出来。<strong>这根梁能隆起来，就靠它知道自己站在中间，不往上争。</strong></p>
<p><strong>什么情况别分权：</strong>如果这件事涉及生死、错了全盘皆输，那就自己盯死。判断标准：<strong>交出去之后，出错的代价谁承担。</strong></p>
<h3 id="p-九五-枯杨生华-老妇得其士夫-好看-但不长久">九五 · 枯杨生华，老妇得其士夫 —— 好看，但不长久</h3>
<blockquote class="pw-quote"><strong>九五：枯杨生华，老妇得其士夫，无咎无誉。</strong><br>象曰：枯杨生华，何可久也。老妇士夫，亦可丑也。</blockquote>
<p><strong>你现在在这个位置：有一件事看着又热闹起来了。你在享受这个回光返照。</strong></p>
<p>九二是枯杨生稊——生的是芽，芽能长成树。</p>
<p>九五是枯杨生华——生的是花，花开完就落。</p>
<p>爻辞给的是「无咎无誉」。没过错，也没赞誉。</p>
<p><strong>这四个字是全卦最难受的判词。</strong> 不是凶，是白干。</p>
<p>具体怎么识别自己在哪一爻？</p>
<p><strong>看你手上这件事的「新」，是真的在长，还是只是在亮。</strong></p>
<p>判断标准三条：</p>
<p><strong>一，这个热闹是在往里进东西，还是只在往外发？</strong> 只在往外发的是花。</p>
<p><strong>二，半年之后，它还在不在？</strong></p>
<p><strong>三，你是在种它，还是在收它？</strong></p>
<p>唐玄宗开元盛世到天宝年间，表面上长安是全世界最热闹的地方。</p>
<p>可天宝年间的热闹，是花钱买来的热闹：募兵制代替府兵制，节度使掌兵又掌财。安史之乱一来，整个架子就散了。开元是稊，天宝是华。</p>
<p><strong>什么情况可以享受一下：</strong>如果这件事本身就是一次性的、你也不指望它长久，那就享受。判断标准：<strong>你有没有把它当成长期的依靠。</strong></p>
<h3 id="p-上六-过涉灭顶-凶-无咎-淹死了-但没错">上六 · 过涉灭顶，凶，无咎 —— 淹死了，但没错</h3>
<blockquote class="pw-quote"><strong>上六：过涉灭顶，凶，无咎。</strong><br>象曰：过涉之凶，不可咎也。</blockquote>
<p><strong>你现在在这个位置：你知道这一步过去可能会没命，但你还是得过去。</strong></p>
<p>过涉灭顶——趟水过去，水没过了头顶。</p>
<p>爻辞给的是「凶，无咎」。凶，但没错。</p>
<p><strong>这四个字是大过卦的收尾，也是它的筋骨。</strong></p>
<p>象传解释：「不可咎也」。<strong>这不能怪他。</strong></p>
<p>上六讲的是：有些事，你明知代价，还是得做。这时候的判断标准变了——不看结果，看该不该。</p>
<p>具体动作两条：</p>
<p><strong>一，做之前，把该交代的交代清楚。</strong> 把话讲到，东西放好，别让活着的人替你收烂摊子。</p>
<p><strong>二，做的时候，别再算成本。</strong> 既然决定了，就干到底，半路回头才是最亏的。</p>
<p>崖山海战，陆秀夫背着八岁的宋帝赵昺跳海。南宋那时候已经没有可守之地，张世杰的船队被围在崖山，断了淡水，士兵喝海水吐得站不起来。</p>
<p>陆秀夫先把自己的妻儿赶下海，然后背上皇帝。他不是没算过，他算过了。</p>
<p><strong>什么情况不值得跳：</strong>如果这件事的成败跟你的命不成比例——比如为了一个面子、一口气、一个别人都不在乎的东西——那就别跳。判断标准：<strong>你死了之后，这件事有人接着干吗。</strong> 没有，就是白死。</p>
<h3 id="p-最后-非常时期-只在非常的时候用">最后：非常时期，只在非常的时候用</h3>
<p>大过卦最怕的是被误读成「要拼」。</p>
<p>不是要拼，是<strong>在梁已经弯了的时候，你还得撑着把它撑完</strong>。</p>
<p>大象传给的两句是「独立不惧，遁世无闷」。一个人在非常时期，要有一个人站着不害怕的本事。</p>
<p>但这一卦有个前提，写在爻辞里：大过是「过」。它是过头，是反常。</p>
<p><strong>过头的东西不能变成常态。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">撑得住的时候别硬撑，撑不住的时候别怕撑。</blockquote>
  `,
  kan: `
<p>一个人跟我说，他这两年没有一件事是顺的。</p>
<p>父亲生病，公司裁员，孩子上学出问题，房子的贷款出了差错。他说：「我不是扛不住一件事，我是扛不住它们一起来。」</p>
<p>这就是坎卦。</p>
<p>坎是水，是坑，是险。坎卦上下都是坎，水一浪接一浪地来。卦名前面还加了一个字，叫「习坎」——习是重复，也是练习。</p>
<p><strong>重复的险，和练习。</strong></p>
<p>这一卦最容易被读成苦情戏。真读进去你会发现，它讲的其实是<strong>怎么在险里活下去</strong>。</p>
<p>卦辞里有一句要紧的：「维心亨」。外面再乱，心里要通。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-习坎-入于坎窞-凶-掉进了最底下那个坑">初六 · 习坎，入于坎窞，凶 —— 掉进了最底下那个坑</h3>
<blockquote class="pw-quote"><strong>初六：习坎，入于坎窞，凶。</strong><br>象曰：习坎入坎，失道凶也。</blockquote>
<p><strong>你现在在这个位置：你已经掉下去了。而且你掉的是最底下那层，上面还压着。</strong></p>
<p>窞是坑里的小坑。坎卦初六本来就在最底下，它又往下掉了一层。</p>
<p>爻辞的判词是「凶」。没有什么可商量的。</p>
<p>这一爻不讲怎么出去，讲<strong>怎么不再往下掉</strong>。</p>
<p>具体动作三条：</p>
<p><strong>一，停止一切主动动作。</strong> 你现在做的每一个「努力」，都可能是在往下挖。</p>
<p><strong>二，先把最基本的东西保住。</strong> 吃饭、睡觉、不欠新的钱。这个阶段谈翻身是奢侈的。</p>
<p><strong>三，告诉至少一个人。</strong> 不是求救，是不让自己一个人待在这个坑里。</p>
<p>「失道凶也」这四个字，象传写得很直接：你掉下来，是因为你走错了路。这个时候最该做的是搞清楚哪一步走错了，而不是急着往上爬。</p>
<p>赵括代廉颇守长平，一上任就改守为攻，全线出击。秦将白起诈败后退，把赵军引出来，然后断其粮道、分割包围。</p>
<p>赵军四十六天没粮，赵括亲自带兵突围，被射死。<strong>他做的每一个动作都是在往下挖。</strong></p>
<p><strong>什么情况可以挣扎一下：</strong>如果你还不知道自己为什么掉下来，那就别动；如果你想清楚了原因，那可以试一个小动作。判断标准：<strong>你现在做的这个动作，是在解决问题，还是在缓解焦虑。</strong></p>
<h3 id="p-九二-坎有险-求小得-别指望一步出去">九二 · 坎有险，求小得 —— 别指望一步出去</h3>
<blockquote class="pw-quote"><strong>九二：坎有险，求小得。</strong><br>象曰：求小得，未出中也。</blockquote>
<p><strong>你现在在这个位置：你还在险里，但你已经稳住了。你没在往下掉，可你也没出去。</strong></p>
<p>爻辞说「求小得」——<strong>求小的收获。</strong></p>
<p>象传补一句「未出中也」：你还没出去，因为你还在中间。</p>
<p>这一爻的分量在于它给了险境里最实用的一条策略：<strong>把目标降到最小。</strong></p>
<p>为什么？因为大目标在险境里是毒药。你一想「我要在三个月内翻盘」，你就必然做出冒险的动作；冒险的动作在这个阶段就是自杀。</p>
<p>具体怎么操作：</p>
<p><strong>一，这周只定一件能做完的小事。</strong> 小到你觉得有点可笑。</p>
<p><strong>二，把它做完，记下来。</strong> 你需要的是「我还能做成事」这个证据，不是那件事本身。</p>
<p><strong>三，别跟人比进度。</strong> 你在坎里，别人在岸上，比不了。</p>
<p>勾践在吴国当马前卒的时候，做的就是「求小得」。他给夫差尝粪便诊病，被放回国之后，十年生聚、十年教训。</p>
<p>他回国第一年没干别的，就是让老百姓生孩子，生男孩赏酒一壶狗一条，生女孩赏酒一壶猪一头。他把复国拆成了无数件极小的事。</p>
<p><strong>什么情况该赌一把：</strong>如果小步走的代价是坐以待毙——比如你的资源正在快速耗尽——那就得赌。判断标准：<strong>慢慢走，来得及吗。</strong></p>
<h3 id="p-六三-来之坎坎-险且枕-入于坎窞-勿用-进退都是">六三 · 来之坎坎，险且枕，入于坎窞，勿用 —— 进退都是坑</h3>
<blockquote class="pw-quote"><strong>六三：来之坎坎，险且枕，入于坎窞，勿用。</strong><br>象曰：来之坎坎，终无功也。</blockquote>
<p><strong>你现在在这个位置：往前走是险，往后退也是险。你在原地不敢动。</strong></p>
<p>「来之坎坎」——来也是坎，去也是坎。六三夹在上下两个坎之间。</p>
<p>「险且枕」——枕是搁置不安的意思，你躺着都不安稳。</p>
<p>爻辞最后两个字是「勿用」。别动。</p>
<p>六三和初六都掉进了坎窞，但六三的处境更难受：初六是掉下去了，六三是还没掉但随时会掉。</p>
<p>象传的判词是「终无功也」——<strong>你在这里折腾，最后都是白折腾。</strong></p>
<p>具体动作：</p>
<p><strong>一，把「不动」当成一个正式的决定。</strong> 不是拖，是决定先不动。写下来，告诉自己到什么时候再评估。</p>
<p><strong>二，这段时间只做不消耗的事。</strong> 学点东西、养身体、把关系维护住。</p>
<p><strong>三，盯着那个会变的东西。</strong> 一定有一个条件变了，局面才会变。找出它，等它。</p>
<p>项羽在鸿门宴之后，把刘邦封到汉中。刘邦当时想跟项羽拼命，周勃、灌婴、樊哙都拦。萧何说了一句：「虽王汉中之恶，不犹愈于死乎？」</p>
<p>刘邦就去了。到了汉中，他烧了栈道。<strong>进退都是坎的时候，他选了退，而且退得很彻底。</strong></p>
<p><strong>什么情况必须动：</strong>如果不动就等于输——比如有个期限马上到，过了就彻底没机会——那就在两个险里挑一个小的。判断标准：<strong>哪个损失你能承受。</strong></p>
<h3 id="p-六四-樽酒簋贰-用缶-纳约自牖-险里交朋友-别讲">六四 · 樽酒簋贰，用缶，纳约自牖 —— 险里交朋友，别讲排场</h3>
<blockquote class="pw-quote"><strong>六四：樽酒簋贰，用缶，纳约自牖，终无咎。</strong><br>象曰：樽酒簋贰，刚柔际也。</blockquote>
<p><strong>你现在在这个位置：你在险里，你需要一个盟友。但你现在拿不出什么像样的东西。</strong></p>
<p>樽酒，一壶酒。簋贰，两碗饭。用缶，用瓦罐装。纳约自牖，从窗户递进去。</p>
<p>这四个短句读下来，画面就出来了。没有礼器，没有仪仗，没有正门。</p>
<p>这一句写得很具体：<strong>一壶酒两碗饭，用瓦罐盛着，从窗口送进去。</strong></p>
<p>为什么不走正门？因为情况特殊，因为正式渠道走不通。</p>
<p>这一爻讲的是<strong>在险境里结成同盟的要领：诚恳比排场重要。</strong></p>
<p>具体动作：</p>
<p><strong>一，用你真实有的东西去谈，别装。</strong> 你现在装一次大的，下次就圆不上了。</p>
<p><strong>二，走那条不正式的路。</strong> 不要等流程，不要等正式场合，找一个能私下说话的机会。</p>
<p><strong>三，把话说得短。</strong> 险境里没有时间听长篇大论。</p>
<p>刘邦被项羽围在荥阳的时候，派韩信去打齐。韩信打下齐之后派人来要假齐王的封号。刘邦当时正被围得难受，骂了一句，张良在旁边踩他的脚。</p>
<p>刘邦马上改口，说大丈夫平定诸侯，要做就做真王，做什么假的，当场就派张良去封韩信为齐王。<strong>这一壶酒递得及时。</strong></p>
<p><strong>什么情况该讲形势：</strong>如果你手上确实有对方想要的东西，那就摆出来。判断标准：<strong>你给的，是不是他现在最缺的。</strong></p>
<h3 id="p-九五-坎不盈-祗既平-无咎-水快平了-撑住">九五 · 坎不盈，祗既平，无咎 —— 水快平了，撑住</h3>
<blockquote class="pw-quote"><strong>九五：坎不盈，祗既平，无咎。</strong><br>象曰：坎不盈，中未大也。</blockquote>
<p><strong>你现在在这个位置：你已经在出去了。水还没退干净，但已经没那么深了。</strong></p>
<p>坎不盈——水没满上来。祗既平——快要平了。</p>
<p>这一爻是无咎，不是吉。为什么不是吉？象传说「中未大也」——<strong>你还在中间，还没强大起来。</strong></p>
<p>九五在尊位，却是无咎。这个评价不高。它讲的是：<strong>出险的过程比你想的长。</strong></p>
<p>具体动作：</p>
<p><strong>一，别提前庆功。</strong> 险境刚缓和的时候，人的第一反应是松一口气，然后就开始犯浑。水位还没降到你脚踝，你就开始蹦，会再摔一次。</p>
<p><strong>二，把这段时间攒的经验固化下来。</strong> 你是怎么熬过来的？哪些动作有用？</p>
<p>写下来。下次还会用到。</p>
<p><strong>三，别去报复。</strong> 在险里的时候你没工夫记仇，现在有了。</p>
<p>周勃、陈平灭诸吕，迎立代王刘恒。刘恒进长安之前，先派宋昌去探路，到了高陵又停下，再派宋昌进城。</p>
<p>进了城之后，当天晚上就任命宋昌为卫将军，张武为郎中令，把皇宫的卫队换成人。他没有急着改元、没有急着清算，他先把最要紧的两件事——兵符和宫禁——拿到手上。<strong>坎不盈的意思，就是水位没退，别先光脚。</strong></p>
<p><strong>什么情况可以放松：</strong>如果险的源头已经彻底消失，那就放松。判断标准：<strong>那个让你陷入险境的根源，还在不在。</strong></p>
<h3 id="p-上六-系用徽纆-寘于丛棘-三岁不得-被绑住了">上六 · 系用徽纆，寘于丛棘，三岁不得 —— 被绑住了</h3>
<blockquote class="pw-quote"><strong>上六：系用徽纆，寘于丛棘，三岁不得，凶。</strong><br>象曰：上六失道，凶三岁也。</blockquote>
<p><strong>你现在在这个位置：你已经被困住了。不是你不想走，是你走不了。</strong></p>
<p>徽纆是绳子，丛棘是荆棘丛里围起来的牢。</p>
<p>爻辞给的时间是三年。三岁不得。</p>
<p>上六是坎卦的尽头。险到了尽头，反而变成了<strong>囚</strong>。</p>
<p>这一爻讲的是：<strong>有些险你自己走不出来，得靠外面。</strong></p>
<p>具体动作三条：</p>
<p><strong>一，承认你需要被救。</strong> 这一爻最难的就在这。前面五爻都是自己想办法，到这儿得开口。</p>
<p><strong>二，找到那个能开口的人。</strong> 谁有权限放你出来？谁有资格替你说一句话？</p>
<p><strong>三，把这三年过好。</strong> 象传最后留了一句：「三岁之后可以免也」。时间本身是解法之一。</p>
<p>司马迁受了宫刑之后，被关在牢里。他在《报任安书》里写「身非木石，独与法吏为伍，深幽囹圄之中」。</p>
<p>他那时候没打算出去，他打算把《史记》写完。他熬了几年，出狱之后做了中书令，然后接着写。<strong>他被绑住的那几年，就是那部书成型的那几年。</strong></p>
<p><strong>什么情况不用等：</strong>如果你自己还有一点力气并且方向是清楚的，那就别等人来救。判断标准：<strong>你现在缺的是能力，还是缺的是一个许可。</strong></p>
<h3 id="p-最后-水不跟坑讲条件">最后：水不跟坑讲条件</h3>
<p>坎卦的大象传给的是六个字：「常德行，习教事」。</p>
<p>常德行，是平常的操守不要变。习教事，是把本事练熟。</p>
<p>这两件事在顺境里看不出价值，在险里就是命。</p>
<p>水的样子最能看出这件事：它遇到坑不会绕，它填进去，填满了继续往前走。</p>
<p><strong>它不抱怨，也不停。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">险不会一次走完。你只要每次都比上次深一点就行。</blockquote>
  `,
  li: `
<p>一个人升职了，从管十个人变成管三百个人。</p>
<p>他上任第一件事，是把公司的所有流程重做了一遍。第二件事，是把三个老部门合并成两个。第三件事，是每周开一次全员会，自己讲一个小时。</p>
<p>半年后他被调去一个虚职。上面的评价是四个字：动静太大。</p>
<p>离卦讲的就是这件事。</p>
<p>离是火，也是「丽」——附着。日月附在天上，百谷附在地上。<strong>火这种东西，必须附着在别的东西上才能烧。</strong></p>
<p>它不能自己待着。</p>
<p>所以离卦真正的题目不是「怎么发光」，是<strong>怎么发光而不把自己烧掉</strong>。</p>
<p>卦辞给的办法是三个字：畜牝牛。养一头母牛——柔顺、能负重、不顶人。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-履错然-敬之-无咎-刚上场-脚步乱">初九 · 履错然，敬之，无咎 —— 刚上场，脚步乱</h3>
<blockquote class="pw-quote"><strong>初九：履错然，敬之，无咎。</strong><br>象曰：履错之敬，以辟咎也。</blockquote>
<p><strong>你现在在这个位置：你刚开始干一件新事，手忙脚乱，什么都想抓。</strong></p>
<p>履错然——脚步交错混乱的样子。这个描写很准，新人上场就是这样：两只脚不知道先迈哪一只。</p>
<p>爻辞给的解法只有一个字：<strong>敬。</strong></p>
<p>不是恭敬别人，是<strong>认真对待手里的事。</strong></p>
<p>具体动作：</p>
<p><strong>一，把你要做的事列出来，然后砍掉一半。</strong> 脚步乱是因为东西太多。</p>
<p><strong>二，找一件最小的事，做到最好是。</strong> 不是做完，是做好。</p>
<p><strong>三，遇到不懂的，当场问。</strong> 这个阶段问问题不丢人，过了这个阶段才丢人。</p>
<p>象传给的是「以辟咎也」——避开过错。初九是在最底下，你还没有犯错的本钱。</p>
<p>韩信登坛拜将之后做的第一件事，不是打仗，是跟刘邦分析项羽。他说项羽有三个毛病：匹夫之勇、妇人之仁、失天下之心。</p>
<p>他说刘邦该做的是反其道而行——任天下武勇、以天下城邑封功臣、以义兵从思东归之士。<strong>这是他上场后的第一次亮相，他没有急着打一仗证明自己。</strong></p>
<p><strong>什么情况可以乱一点：</strong>如果你做的事本来就是新的、没人干过，那乱是正常的。判断标准：<strong>你乱的是手法，还是方向。</strong> 手法可以乱，方向不能乱。</p>
<h3 id="p-六二-黄离-元吉-站稳中间那道光">六二 · 黄离，元吉 —— 站稳中间那道光</h3>
<blockquote class="pw-quote"><strong>六二：黄离，元吉。</strong><br>象曰：黄离元吉，得中道也。</blockquote>
<p><strong>你现在在这个位置：你已经上手了。有人开始认可你，你也有了一点话语权。</strong></p>
<p>黄是五色之中，土的颜色，不扎眼。黄离就是<strong>中道的光明。</strong></p>
<p>这一爻是离卦里评价最高的一爻：元吉。</p>
<p>为什么？因为它既亮，又不刺眼。</p>
<p>具体动作三条：</p>
<p><strong>一，把你的判断标准写清楚，然后按标准办事。</strong> 你在这个阶段最大的价值是「可预测」。别人知道你会怎么判，才敢把事情交给你。</p>
<p><strong>二，别抢话。</strong> 有能力的人在会上最容易犯的错，是别人还没说完就接上。</p>
<p><strong>三，留一手。</strong> 你有十分的把握，说七分。</p>
<p>萧何进咸阳收图籍，这件事做得特别「黄」。那么多人在抢金银，他抢的是一堆竹简，看着最不风光。</p>
<p>可这堆东西正是他后来做丞相的本钱。<strong>他没打算让人看见，他打算让人用得上。</strong></p>
<p><strong>什么情况该亮：</strong>如果这件事需要你站出来定调，没人站出来就会乱，那就亮。判断标准：<strong>你不说话，是不是真的没人能说。</strong></p>
<h3 id="p-九三-日昃之离-不鼓缶而歌-太阳开始偏西了">九三 · 日昃之离，不鼓缶而歌 —— 太阳开始偏西了</h3>
<blockquote class="pw-quote"><strong>九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。</strong><br>象曰：日昃之离，何可久也。</blockquote>
<p><strong>你现在在这个位置：你已经过了最好的时候。你自己也知道。</strong></p>
<p>日昃是太阳偏西。爻辞给了两条路：<strong>要么敲着瓦罐唱歌，要么就哀叹。</strong></p>
<p>前者是吉，后者是凶。</p>
<p>这一爻写得特别有人味。它说的是：<strong>盛极而衰是必然的，问题是你用什么姿势接受。</strong></p>
<p>「鼓缶而歌」是什么样的画面？一个老人，敲着瓦罐子唱歌。不体面，不庄重，但自在。</p>
<p>具体动作：</p>
<p><strong>一，把「我老了」这件事说出来。</strong> 你一旦说出来，它就变成事实而不是恐惧。</p>
<p><strong>二，换一种方式参与。</strong> 从亲自上场变成出主意、变成托人。</p>
<p><strong>三，找一件跟你的位置无关、纯粹你喜欢的事。</strong> 鼓缶而歌就是这个意思。</p>
<p>汉武帝晚年，太子刘据死于巫蛊之祸。他后来建了思子宫，又在轮台下了罪己诏。</p>
<p>他说「曩者，朕之不明」，然后封丞相车千秋为富民侯，改搞农业，不再打仗。他做的事不是继续证明自己对，是<strong>认了这个日昃。</strong></p>
<p><strong>什么情况该硬撑：</strong>如果这件事还没人接得住、你一走就散，那就再撑一阵。判断标准：<strong>有没有人能接。</strong></p>
<h3 id="p-九四-突如其来如-焚如-死如-弃如-烧得急-灭得">九四 · 突如其来如，焚如，死如，弃如 —— 烧得急，灭得快</h3>
<blockquote class="pw-quote"><strong>九四：突如其来如，焚如，死如，弃如。</strong><br>象曰：突如其来如，无所容也。</blockquote>
<p><strong>你现在在这个位置：你得到了一个不该这么快得到的东西。你上得急。</strong></p>
<p>爻辞连用四个「如」：来得很突然，烧得很旺，死得很快，被扔掉。</p>
<p><strong>这是《周易》里最惨的一爻。</strong></p>
<p>象传四个字：「无所容也」——<strong>没地方放你。</strong></p>
<p>这一爻讲的是<strong>越级上位的人</strong>。九三还在日昃，九四突然就到了君位旁边。位置上去了，底子没跟上。</p>
<p>具体动作：</p>
<p><strong>一，减动作。</strong> 你上位之后想做的事，砍掉三分之二。你现在做的每一个大动作，都会被记成本钱不够还硬撑。</p>
<p><strong>二，把原来的上级照顾好。</strong> 你越级了，那个人还在。怎么处理他，决定了你能待多久。</p>
<p><strong>三，找一个老的、稳的人做搭档。</strong> 你需要一个「不突然」的形象。</p>
<p>霍光死后，霍山、霍云、霍禹接着掌权。霍禹从一个中郎将直接做到了大司马，可他没有霍光那份资历。</p>
<p>汉宣帝一步一步把霍家的人从要害位置上挪走，先调兵权，再调宫禁。霍家发现不对，想反，还没动就被一锅端。<strong>突如其来，就有焚如。</strong></p>
<p><strong>什么情况可以接：</strong>如果这个位置是你一步步干上来的，那就接。判断标准：<strong>下面的人服不服。</strong> 不是嘴上服，是出事的时候愿不愿意跟你走。</p>
<h3 id="p-六五-出涕沱若-戚嗟若-吉-哭出来是对的">六五 · 出涕沱若，戚嗟若，吉 —— 哭出来是对的</h3>
<blockquote class="pw-quote"><strong>六五：出涕沱若，戚嗟若，吉。</strong><br>象曰：六五之吉，离王公也。</blockquote>
<p><strong>你现在在这个位置：你在一个挺高的位置上，但你心里害怕。</strong></p>
<p>涕沱若，眼泪流得哗哗的。戚嗟若，一边哭一边叹气。</p>
<p>爻辞的判词是：吉。</p>
<p><strong>这一爻看着最不像吉，其实是全卦最懂事的一爻。</strong></p>
<p>六五是阴爻在君位。它知道自己坐在一个自己撑不满的位置上，它害怕，它哭。</p>
<p>为什么哭是吉？<strong>哭出来，你就知道自己几斤几两。</strong></p>
<p>怕，就不会乱来；怕，就会找人帮忙。</p>
<p>具体动作：</p>
<p><strong>一，把你的担心说出来。</strong> 跟你的核心搭档说，不是跟所有人说。说出来的担心会变成方案，憋着的担心会变成事故。</p>
<p><strong>二，主动找人辅佐。</strong> 你缺什么就找什么，别硬装全能。</p>
<p><strong>三，别装。</strong> 你一装，那些本来想帮你的人就转身了。</p>
<p>刘备托孤的时候跟诸葛亮说：「若嗣子可辅，辅之；如其不才，君可自取。」他哭了。这一哭把诸葛亮钉死在了蜀汉。</p>
<p>刘备知道自己儿子不行，他也知道诸葛亮行，他把这层窗户纸捅破了，反而是最安全的做法。</p>
<p><strong>什么情况不能露怯：</strong>如果对面是随时会扑上来的人，那就别把怕露出来。判断标准：<strong>你哭给谁看。</strong></p>
<h3 id="p-上九-王用出征-有嘉折首-获匪其丑-只打那个带头">上九 · 王用出征，有嘉折首，获匪其丑 —— 只打那个带头的</h3>
<blockquote class="pw-quote"><strong>上九：王用出征，有嘉折首，获匪其丑，无咎。</strong><br>象曰：王用出征，以正邦也。</blockquote>
<p><strong>你现在在这个位置：你得动手了。有个东西一直在坏你的事，你得处理掉。</strong></p>
<p>王用出征，君王出兵。有嘉折首，斩掉那个为首的。获匪其丑，不抓那些跟着的。</p>
<p>这一爻给的是<strong>处理麻烦的分寸</strong>。</p>
<p>具体三条：</p>
<p><strong>一，只打那个带头的。</strong> 头一掉，剩下的自己就散了。</p>
<p><strong>二，不扩大。</strong> 获匪其丑——别搞株连。一扩大，你就给自己制造了十个新的敌人。</p>
<p><strong>三，打完就收。</strong> 出征的目的是「正邦」，不是出气。</p>
<p>刘邦称帝之后，有人告韩信谋反。陈平给的办法是：天子巡狩会诸侯，韩信一定会来见，来的时候一个力士就能拿下他。</p>
<p>刘邦照办，韩信被抓，贬为淮阴侯。刘邦没有杀韩信，也没有查他的部下。<strong>这是折首，不是屠城。</strong></p>
<p><strong>什么情况要一起清：</strong>如果那个团伙里的人个个都能顶事、个个都跟你结了死仇，那就不能只打头。判断标准：<strong>头掉了之后，剩下的会不会再长出一个头。</strong></p>
<h3 id="p-最后-火得有个东西接着">最后：火得有个东西接着</h3>
<p>离卦的大象传讲的是「继明照于四方」。</p>
<p>明两作——两重光明往上叠。日月交替，前一个落下，后一个升起。</p>
<p><strong>离卦最要紧的不是亮，是接得上。</strong></p>
<p>你一个人再亮，也就是那一段时间。你能不能找到下一个接着亮的人，决定这件事能走多远。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别只顾着烧。想清楚你烧的是谁家的柴。</blockquote>
  `,
  xian: `
<p>一个人跟我说她相亲的事。</p>
<p>见了七个，没一个有感觉。第八个见完，她回家路上给朋友发消息说「就他了」。</p>
<p>朋友问她为什么。她想了半天说：「他全程没夸过我一句。他就一直在问我问题，而且他真的在听。」</p>
<p>咸卦讲的就是这个。</p>
<p>咸是感，感应。泽山咸，山在上面，泽在下面。山上的水流下来润泽下面，下面的气升上去接上面的水汽。</p>
<p><strong>二气交感。</strong></p>
<p>但这一卦的卦辞里有一句特别反常的话：男下女。</p>
<p>艮是少男，兑是少女。少男在上面吗？不是，少男在下面。</p>
<p><strong>男的下女。</strong></p>
<p>这是《周易》里对两性关系最深刻的一句判断：<strong>真诚的感应，是从你把自己放低开始的。</strong></p>
<p>我下面按六爻说。咸卦六爻全部用人体取象，从脚趾一路往上，到嘴。</p>
<h3 id="p-初六-咸其拇-脚趾头动了一下">初六 · 咸其拇 —— 脚趾头动了一下</h3>
<blockquote class="pw-quote"><strong>初六：咸其拇。</strong><br>象曰：咸其拇，志在外也。</blockquote>
<p><strong>你现在在这个位置：你心里动了一下。就一下，很轻微，你自己都不太确定。</strong></p>
<p>拇是大脚趾。脚趾头动了，脚还没动，人还站着。</p>
<p>爻辞没有吉凶。为什么没有？因为<strong>这个阶段什么都还没发生。</strong></p>
<p>具体动作：</p>
<p><strong>一，什么也别做，先观察两周。</strong> 你现在动的是脚趾，不是腿。这时候冲出去，多半是误会。</p>
<p><strong>二，观察你自己。</strong> 两周之后，你还想不想。想，是真的；不想了，就是一时上头。</p>
<p><strong>三，别跟人讲。</strong> 讲出去，这件事就变成了一个你要维护的立场。</p>
<p>这一爻最重要的是不要抢跑。</p>
<p>司马相如弹《凤求凰》给卓文君听，是在酒席上。他没有当场求亲，也没有托人说媒。他就是弹了一首曲子，然后托人送了点东西。</p>
<p>真正让卓文君动的是那首曲子，也是后来的那些往来。<strong>脚趾头动的阶段，你只能看到脚趾头在动，别的什么都看不出来。</strong></p>
<p><strong>什么情况可以马上动：</strong>如果这是一个瞬间就会消失的机会——比如对方明天就要走了——那就动。判断标准：<strong>错过这次，还有没有下次。</strong></p>
<h3 id="p-六二-咸其腓-凶-居吉-小腿在动-你得按住">六二 · 咸其腓，凶，居吉 —— 小腿在动，你得按住</h3>
<blockquote class="pw-quote"><strong>六二：咸其腓，凶，居吉。</strong><br>象曰：虽凶居吉，顺不害也。</blockquote>
<p><strong>你现在在这个位置：你已经开始有动作了。你想找人、想打听、想表白、想试探。</strong></p>
<p>腓是小腿肚。小腿一动，人就要走了。</p>
<p>爻辞给的是「凶，居吉」——<strong>你一急就坏事，你按住就没事。</strong></p>
<p>这一爻和初六的差别很关键：初六是心动，六二是<strong>身动</strong>。</p>
<p>具体动作：</p>
<p><strong>一，把你想发的那条消息，存成草稿，放 24 小时。</strong> 24 小时之后还想发，再发。</p>
<p><strong>二，找个跟这事无关的事干两天。</strong> 手上有活的人，心就稳。</p>
<p><strong>三，去问一个不站你这边的人。</strong> 不是问该不该，是问他看出什么了。</p>
<p>象传说「顺不害也」——<strong>顺着你的本性，就不会被害。</strong> 阴性本来是静的，你躁起来才是反常。</p>
<p>《左传》里写重耳在齐国的时候，齐桓公把女儿嫁给了他。重耳在齐国待得很舒服，不想走了。他的随从在桑树下商量怎么把他弄走，被一个采桑的侍女听见了。</p>
<p>侍女告诉了重耳的夫人姜氏，姜氏把侍女杀了，然后跟重耳说，你走吧。重耳说我不走。</p>
<p>姜氏就灌醉他，把他装上车拉走了。<strong>重耳在齐国的这几年，就是「咸其腓」——心已经被焐热了，动不了了。</strong></p>
<p><strong>什么情况必须动：</strong>如果对方给了一个明确的、有期限的信号，那你就得动。判断标准：<strong>这个信号是给你一个人的，还是给所有人的。</strong></p>
<h3 id="p-九三-咸其股-执其随-往吝-大腿跟着别人走">九三 · 咸其股，执其随，往吝 —— 大腿跟着别人走</h3>
<blockquote class="pw-quote"><strong>九三：咸其股，执其随，往吝。</strong><br>象曰：咸其股，亦不处也。志在随人，所执下也。</blockquote>
<p><strong>你现在在这个位置：你自己拿不定主意，你在看别人怎么做。</strong></p>
<p>股是大腿。大腿不能自己动，得靠腰带着。</p>
<p>爻辞的判词是「往吝」——<strong>这么走下去，不好看。</strong></p>
<p>象传讲得特别直白：「志在随人，所执下也」。<strong>你的心思全在跟着别人，那你抓到的东西就很低。</strong></p>
<p>这一爻讲的是<strong>从众</strong>。</p>
<p>具体动作：</p>
<p><strong>一，把「别人都这么做」这句话从你的理由里删掉。</strong></p>
<p><strong>二，说出你自己的判断，哪怕说错。</strong> 说错了改，比不说强。</p>
<p><strong>三，找一件只有你在做的事。</strong> 什么都跟人一样，你就不存在了。</p>
<p>陈胜吴广起义之后，天下大乱，各地都有人起来。很多人是看着别人反了自己才反的。</p>
<p>刘邦起兵之前，是沛县的亭长，押送徒役去骊山，路上跑了一大半。他到了丰西泽中就停下来喝酒，把剩下的人都放了。</p>
<p><strong>这里面有一个关键：他是自己想反的，还是被人推着反的？</strong> 记载里说，「沛令恐，欲以沛应陈涉」，然后是萧何曹参去找刘邦。</p>
<p>刘邦回来的路上，沛县的人已经杀了沛令。这一爻的判词是吝，不是凶——从众不致命，但会让你一直拿不到最好的那份。</p>
<p><strong>什么情况可以跟：</strong>如果带头那个人的判断力明显比你强，而且他真的在担责任，那就跟。判断标准：<strong>出事了，是他扛还是大家扛。</strong></p>
<h3 id="p-九四-贞吉-悔亡-憧憧往来-朋从尔思-心思来来回">九四 · 贞吉，悔亡。憧憧往来，朋从尔思 —— 心思来来回回</h3>
<blockquote class="pw-quote"><strong>九四：贞吉，悔亡。憧憧往来，朋从尔思。</strong><br>象曰：贞吉悔亡，未感害也。憧憧往来，未光大也。</blockquote>
<p><strong>你现在在这个位置：你在纠结，来回摇摆。你想这个又想那个，谁都不想得罪。</strong></p>
<p>憧憧往来，是心里来来回回的样子。爻辞给的结果是：<strong>朋从尔思——只有你的小圈子跟你走。</strong></p>
<p>这一爻是全卦最出名的一句。它讲的是<strong>一个人心思不定的代价。</strong></p>
<p>爻辞先给了正面的答案：贞吉，悔亡。<strong>守正就吉，后悔就消。</strong></p>
<p>然后再给你看反面的样子。</p>
<p>具体动作：</p>
<p><strong>一，把你的真实判断写下来，不要写「看情况」。</strong></p>
<p><strong>二，选一个立场，接受失去一部分人。</strong></p>
<p><strong>三，别搞平衡。</strong> 平衡是最累的活，而且平衡的人最后两边都不信你。</p>
<p>项伯是项羽的叔父。鸿门宴之前，他连夜跑到刘邦营里，把事情告诉了张良。第二天鸿门宴上，项庄舞剑，项伯也拔剑起舞，用身体挡着刘邦。他这么做不是为了刘邦，是为了张良——张良救过他的命。</p>
<p><strong>他一个人在两边的中间来回走。</strong> 结果呢？刘邦得了天下，项伯被封为射阳侯，赐姓刘。可项羽死了，他的侄子死了。</p>
<p><strong>什么情况可以来回走：</strong>如果你两边都还没有承诺，那你在信息收集阶段，可以多听。判断标准：<strong>你有没有已经答应过谁。</strong></p>
<h3 id="p-九五-咸其脢-无悔-背上的感应">九五 · 咸其脢，无悔 —— 背上的感应</h3>
<blockquote class="pw-quote"><strong>九五：咸其脢，无悔。</strong><br>象曰：咸其脢，志末也。</blockquote>
<p><strong>你现在在这个位置：你已经在很高的位置上了。你不想再动感情，但你还是被牵动了。</strong></p>
<p>脢是背，是脊背上的肉。背上的感应，是<strong>你自己感觉不到，别人也看不出来。</strong></p>
<p>爻辞给的是「无悔」。不是吉，是无悔。</p>
<p>象传的判词是「志末也」——<strong>你的心志放在了末节上。</strong></p>
<p>这一爻讲的是<strong>位置上去了，感情就变成了软肋。</strong></p>
<p>具体怎么做：</p>
<p><strong>一，把私交和公事分开。</strong> 不是不来往，是来往的时候把该说的话说清楚。</p>
<p><strong>二，别让人摸到你的偏好。</strong> 你一有偏好，下面的人就会利用它。</p>
<p><strong>三，留一条真感情的出口。</strong> 全都封死，你会变成一台机器。</p>
<p>汉文帝的舅舅薄昭，是拥立文帝的功臣之一。文帝即位后封他为轵侯。</p>
<p>后来薄昭杀了朝廷的使者，文帝让大臣们陪他喝酒，暗示他自尽。薄昭不肯，文帝就让群臣穿着丧服去他家里哭。薄昭最后自杀了。</p>
<p><strong>文帝是被薄昭扶上去的，但薄昭踩了线。</strong> 这一爻讲的就是这个位置上的难：你欠的人情，不能拿国法还。</p>
<p><strong>什么情况可以讲私情：</strong>如果这件事不涉及规则、不涉及别人的利益，那私情归私情。判断标准：<strong>你这个动作，会不会让别人吃亏。</strong></p>
<h3 id="p-上六-咸其辅颊舌-只剩一张嘴">上六 · 咸其辅颊舌 —— 只剩一张嘴</h3>
<blockquote class="pw-quote"><strong>上六：咸其辅颊舌。</strong><br>象曰：咸其辅颊舌，滕口说也。</blockquote>
<p><strong>你现在在这个位置：你已经不太有实质的东西给人了，你只能靠说。</strong></p>
<p>辅是脸颊，颊是腮，舌是舌头。一整套说话的器官。</p>
<p>爻辞没有吉凶，但象传给了四个字：「滕口说也」——<strong>光靠嘴说。</strong></p>
<p>这一爻是全卦最轻的一爻，轻到连凶都算不上。</p>
<p>它讲的是：<strong>当一个人只剩下话术的时候，他已经空了。</strong></p>
<p>具体动作：</p>
<p><strong>一，检查一下你最近的变化里，有多少是「更好的说法」，有多少是「真的东西」。</strong></p>
<p><strong>二，把一句承诺换成一次行动。</strong></p>
<p><strong>三，如果发现自己整天在解释、在协调、在表态，那就该警惕了。</strong></p>
<p>苏秦佩六国相印，靠的就是一张嘴。他能让六国合纵，也能让齐国把燕国的城池还回去。可他最后在齐国被人刺杀，临死前跟齐王说，你把我车裂了，然后说我是燕国的间谍，凶手就会自己出来。</p>
<p>齐王照办，凶手果然出来了。<strong>他一辈子的本事在嘴上，最后一句话也是靠嘴办成的。</strong></p>
<p><strong>什么情况只能靠说：</strong>如果实的东西一时半会儿拿不出来，而你必须在场，那就得说。判断标准：<strong>你说完之后，有没有一件具体的事开始动。</strong> 没有，你就是在上六待着。</p>
<h3 id="p-最后-感应是两头的">最后：感应是两头的</h3>
<p>咸卦的大象传给的是四个字：<strong>「虚受人」。</strong></p>
<p>把自己的杯子倒空，才能接住别人的东西。</p>
<p>这一卦从头到尾讲的都是同一件事：<strong>你想让别人有反应，你自己得先动，而且是先往下动。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">感应不是把话说漂亮。是你先把自己放低。</blockquote>
  `,
  heng: `
<p>一个人开了一家店，开了十一年。</p>
<p>前三年亏，第四年平，第五年开始赚。第七年旁边开了两家一样的店，他没动。第九年疫情，关了四个月，他也没关店，就撑着。</p>
<p>现在第十一年，那两家都倒了，他还在。</p>
<p>我问他怎么撑过来的。他说了一句很没劲的话：「我也没干什么，就是每天都开门。」</p>
<p>恒卦讲的就是这件事。</p>
<p>恒，是久。但这个「久」不是死扛。</p>
<p>卦辞讲「利有攸往」，彖传解释这四个字用的是「终则有始」。<strong>结束就是开始。</strong></p>
<p>日月因为一直在动，所以能照很久。四时因为一直在变，所以能成万物。</p>
<p><strong>恒不是不变，是在变里守住那条线。</strong></p>
<p>大象传给的是五个字：「立不易方」。立定你的方向，不轻易换。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-浚恒-贞凶-无攸利-一上来就要最深">初六 · 浚恒，贞凶，无攸利 —— 一上来就要最深</h3>
<blockquote class="pw-quote"><strong>初六：浚恒，贞凶，无攸利。</strong><br>象曰：浚恒之凶，始求深也。</blockquote>
<p><strong>你现在在这个位置：你刚开始做一件事，或者刚开始跟一个人相处。你想一步到位。</strong></p>
<p>浚是深挖。浚恒，是一开始就要求挖到底。</p>
<p>爻辞给的是「贞凶，无攸利」。<strong>你这么坚持下去，凶，没有一样是有利的。</strong></p>
<p>象传四个字点得特别准：「始求深也」。<strong>你刚开始，就求深。</strong></p>
<p>这一爻讲的是<strong>新关系、新事业里的用力过猛。</strong></p>
<p>刚认识就要交心，刚入职就要改流程，刚开店就要做品牌。</p>
<p>具体动作：</p>
<p><strong>一，给你手上的新事定一个「第一年只做三件事」的清单。</strong></p>
<p><strong>二，别问「他到底怎么看我」，问「你俩这周过得怎么样」。</strong></p>
<p><strong>三，接受进度慢。</strong> 慢不是失败，快而散才是。</p>
<p>范增跟项羽，一开始就掏心掏肺。鸿门宴上他三次举起玉玦示意项羽下手，项羽没动，他当场就骂「竖子不足与谋」。</p>
<p>他把自己放在一个「你不听我就是你蠢」的位置上。后来陈平一个反间计，项羽就怀疑他了。<strong>他输在关系一开始就挖得太深。</strong></p>
<p><strong>什么情况可以快：</strong>如果这件事本来就是短期的、有明确期限的，那就别拖。判断标准：<strong>你想跟它处多久。</strong></p>
<h3 id="p-九二-悔亡-守住了中间">九二 · 悔亡 —— 守住了中间</h3>
<blockquote class="pw-quote"><strong>九二：悔亡。</strong><br>象曰：九二悔亡，能久中也。</blockquote>
<p><strong>你现在在这个位置：你在一个不太显眼的位置上，但你待得挺稳。</strong></p>
<p>爻辞只有两个字：悔亡。<strong>后悔消失了。</strong></p>
<p>象传给了三个字：「能久中也」——<strong>你能长时间守在中间。</strong></p>
<p>九二的位置很妙：它是个阳爻，住在阴位上。本来位置不对，应该是有悔的。可它无悔，因为它在下卦的中位。</p>
<p><strong>这一爻讲的是一种很高级的活法：位置不理想，但守得住，就没有后悔。</strong></p>
<p>具体动作：</p>
<p><strong>一，接受你现在这个位置。</strong> 不理想的岗位、不理想的名分、不理想的收入。</p>
<p><strong>二，把注意力放在「能不能一直干下去」上。</strong></p>
<p><strong>三，别天天看别人升得比你快。</strong></p>
<p>这一爻的判词平淡到极点，但它是恒卦六个爻里唯一没有毛病的。</p>
<p>曹参接萧何做丞相，做的所有事都是照萧何那一套。惠帝问他，他说：「高帝与萧何定天下，法令既明，今陛下垂拱，参等守职，遵而勿失，不亦可乎？」<strong>他在那个位置上待了三年，没改一条法令，没有后悔。</strong></p>
<p><strong>什么情况该动：</strong>如果你待的这个位置正在慢性杀死你——比如你三年没学到任何新东西——那就该动。判断标准：<strong>你现在做的事，跟三年前有什么不同。</strong></p>
<h3 id="p-九三-不恒其德-或承之羞-说变就变">九三 · 不恒其德，或承之羞 —— 说变就变</h3>
<blockquote class="pw-quote"><strong>九三：不恒其德，或承之羞，贞吝。</strong><br>象曰：不恒其德，无所容也。</blockquote>
<p><strong>你现在在这个位置：你最近变得有点快。你的态度、你的立场、你的说法，跟三个月前不一样了。</strong></p>
<p>爻辞说得很难听：「或承之羞」——<strong>你会招来羞辱。</strong></p>
<p>象传更狠：「无所容也」——<strong>没有地方能容下你。</strong></p>
<p>这一爻讲的是<strong>德不恒</strong>。</p>
<p>注意这里的「德」不是道德，是<strong>你的做派、你的原则、你的脾气</strong>。</p>
<p>具体动作：</p>
<p><strong>一，写三条你不变的东西。</strong> 什么情况下你都这么干。写下来，贴在自己看得见的地方。</p>
<p><strong>二，如果确实要变，说清楚为什么变。</strong> 变化不可怕，不明不白的变化才可怕。</p>
<p><strong>三，别在情绪里做决定。</strong> 心情好的时候答应的事，心情差的时候别推翻。</p>
<p>吕布一生换了三个主子：丁原、董卓，然后是自立。他跟丁原的时候认丁原做义父，跟董卓的时候又认董卓做义父，两个义父都被他杀了。</p>
<p>到了下邳被曹操围住，他想投降，曹操问刘备的意见。刘备说了一句：「明公不见布之事丁建阳及董太师乎？」曹操就把他杀了。<strong>这就是无所容。</strong></p>
<p><strong>什么情况可以改：</strong>如果原来的做法已经被证明是错的，那就改，而且要公开改。判断标准：<strong>你是被逼着改，还是想清楚了改。</strong></p>
<h3 id="p-九四-田无禽-地方不对-打不到东西">九四 · 田无禽 —— 地方不对，打不到东西</h3>
<blockquote class="pw-quote"><strong>九四：田无禽。</strong><br>象曰：久非其位，安得禽也。</blockquote>
<p><strong>你现在在这个位置：你很努力，也坚持了很久，但一直没有结果。</strong></p>
<p>田是打猎。田无禽，打猎打不到猎物。</p>
<p>象传给出原因：「久非其位」——<strong>你在一个不属于你的地方待了很久。</strong></p>
<p>这一爻的判词只有三个字，但它是恒卦里最疼的一句。</p>
<p>因为九二讲「能久中」，九四讲「久非其位」。<strong>同样是久，位置不同，结果完全不同。</strong></p>
<p>这一爻戳的是「坚持就是胜利」这句话的漏洞。</p>
<p>具体动作：</p>
<p><strong>一，问自己一个很难的问题：这三年，我的产出是零，还是只是低于预期？</strong> 零和低，是两个概念。</p>
<p><strong>二，如果是零，看方向。</strong> 你在挖的这块地到底有没有东西。</p>
<p><strong>三，给自己设一个期限和标准。</strong> 到什么时间，做到什么程度，达不到就走。</p>
<p>李广打了一辈子仗，从文帝到景帝到武帝，打了四十多年。他出击匈奴七十多次，可一直到死都没有封侯。「冯唐易老，李广难封」这句话流传了两千年。</p>
<p>武帝后来派卫青、霍去病出击，用的是骑兵长途奔袭的打法。李广擅长的是防守和近战。<strong>他一直在打猎，只是猎物已经换了地方。</strong></p>
<p><strong>什么情况该再等等：</strong>如果这件事有明显的积累效应——比如你的客户在变多、你的手艺在变好——那就再等。判断标准：<strong>你手里能拿来用的东西，比一年前多了吗。</strong></p>
<h3 id="p-六五-恒其德-贞-妇人吉-夫子凶-守着一条规矩">六五 · 恒其德，贞。妇人吉，夫子凶 —— 守着一条规矩</h3>
<blockquote class="pw-quote"><strong>六五：恒其德，贞。妇人吉，夫子凶。</strong><br>象曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。</blockquote>
<p><strong>你现在在这个位置：你已经找到了一套行之有效的做法。你在守它。</strong></p>
<p>爻辞给的是「妇人吉，夫子凶」。<strong>这个位置守成，女人吉，男人凶。</strong></p>
<p>这一句在今天的语境下要翻译一下：<strong>执行者守规矩是吉，决策者守规矩是凶。</strong></p>
<p>妇人在这儿的象是「从一而终」——跟着一个人走到底。夫子是「制义」——<strong>定规矩的那个人。</strong></p>
<p>定规矩的人只管守规矩，那谁来应变？</p>
<p>具体动作：</p>
<p><strong>一，分清你在这件事里是执行者还是决策者。</strong></p>
<p><strong>二，如果是决策者，给自己留一个每季度推翻一次的机会。</strong></p>
<p><strong>三，把「这事情以前就是这么办的」这句话从你的词库里删掉。</strong></p>
<p>诸葛亮治蜀，用法严。有人劝他学汉高祖约法三章宽一点，他说：「刘璋暗弱，蜀土人士，专权自恣。吾今威之以法，法行则知恩。」他这套办法在他手上是对的。</p>
<p>可到了姜维那一代，还照着这条路北伐，蜀国的国力撑不住。<strong>六五的吉，是诸葛亮的吉；六五的凶，是后来那些只会照抄的人的凶。</strong></p>
<p><strong>什么情况必须严：</strong>如果局面乱到需要有人来立规矩，那就严。判断标准：<strong>现在缺的是规矩，还是应变。</strong></p>
<h3 id="p-上六-振恒-凶-老是摇">上六 · 振恒，凶 —— 老是摇</h3>
<blockquote class="pw-quote"><strong>上六：振恒，凶。</strong><br>象曰：振恒在上，大无功也。</blockquote>
<p><strong>你现在在这个位置：你在这个位置上动得太频繁了。你自己觉得是在调整，别人看到的是乱。</strong></p>
<p>振是动、是摇。振恒，是<strong>把「动」变成了常态。</strong></p>
<p>爻辞给的是：凶。</p>
<p>象传四个字：「大无功也」。<strong>一点功劳都留不下。</strong></p>
<p>这一爻是恒卦的收尾，它讲的是<strong>朝令夕改的代价。</strong></p>
<p>前面五爻都在讲怎么守，上六讲的是<strong>你守不住，一直在变。</strong></p>
<p>具体动作：</p>
<p><strong>一，数一数你最近半年改了多少次方向。</strong> 超过三次，就是振恒。</p>
<p><strong>二，改了的东西，至少执行三个月再评估。</strong></p>
<p><strong>三，把你的决策频率降下来。</strong> 每周一次改成每月一次。</p>
<p>王莽新政就是一部振恒史。他即位之后改币制、改官名、改地名、改田制，几乎每年都在大改。他改币制改了四次，每次新钱出来老百姓还没认熟，又换新的。</p>
<p>到最后天下人不认他的钱，也不认他的政令。<strong>他不是不改，他是改得太勤。</strong></p>
<p><strong>什么情况必须快变：</strong>如果这个环境本身就是剧烈变化的，慢反而死。判断标准：<strong>你改的是方法，还是方向。</strong> 方法可以常改，方向不能常改。</p>
<h3 id="p-最后-恒不是不动-是不乱了">最后：恒不是不动，是不乱了</h3>
<p>恒卦最难懂的一点是它跟咸卦的关系。</p>
<p>咸讲感应，讲两个人怎么搭上。恒讲长久，讲搭上之后怎么处下去。</p>
<p>搭上靠的是把自己放低。处下去靠的是<strong>立不易方。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">长久这件事，拼的不是毅力，是你选的方向对不对。</blockquote>
  `,
  dun: `
<p>一个人辞了职，四十三岁。</p>
<p>他做得不差，年薪七位数，手下三十个人。可他说他每天上班的第一件事，是在车里坐十分钟才下车。</p>
<p>他跟我说，他想了两年才走。第一年舍不得，第二年放不下。到第三年，他发现自己已经不太会笑了。</p>
<p>他走的时候，交接做得特别干净。客户一个一个见，项目一个一个过，最后一个月他天天加班。老板挽留了三次，他都说谢谢。</p>
<p>遁卦讲的就是这件事。</p>
<p>遁是退避。天下有山，山再高也够不着天，天自己往远处走。</p>
<p><strong>注意这个意象：不是山把天赶走的，是天自己走的。</strong></p>
<p>卦辞说「亨，小利贞」——<strong>退避本身是通的</strong>，但在小处守正有利。</p>
<p>遁卦里没有一个是凶爻。这很不寻常。它整卦都在说：<strong>该走的时候走，是本事，不是失败。</strong></p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-遁尾-厉-勿用有攸往-走到最后面了">初六 · 遁尾，厉，勿用有攸往 —— 走到最后面了</h3>
<blockquote class="pw-quote"><strong>初六：遁尾，厉，勿用有攸往。</strong><br>象曰：遁尾之厉，不往何灾也。</blockquote>
<p><strong>你现在在这个位置：别人已经开始走了，你还在原地。你是队尾。</strong></p>
<p>遁尾——退避的时候跟在最后面。爻辞给的是「厉」，危险。</p>
<p>但后半句很有意思：「勿用有攸往」。<strong>别再往前走了。</strong></p>
<p>象传补了一句特别妙的：<strong>「不往何灾也」——你不去，哪来的灾？</strong></p>
<p>这一爻讲的是一种很常见的心态：<strong>别人都走了，我这时候走是不是太难看。</strong></p>
<p>具体动作：</p>
<p><strong>一，如果你已经落在队尾了，那就别再跟风跑。</strong> 你的处境跟他们不一样。</p>
<p><strong>二，先稳住手上那摊事。</strong> 队尾的人最容易被当成收拾残局的人。</p>
<p><strong>三，重新评估：你到底该不该走。</strong></p>
<p>前面的人走，可能是因为他们看到了什么。你落在后面，可能是因为你确实不该走，也可能是因为你迟钝。</p>
<p>判断标准就在这里：<strong>前面走的人，是不是比你更接近信息源。</strong></p>
<p>田横在韩信破齐之后自立为齐王，后来被灌婴打败，投了彭越。刘邦称帝，田横带着五百人逃到海岛上。刘邦派人来招他，说你来就封王，不来就派兵剿。</p>
<p>田横走到离洛阳三十里的地方，跟门客说：我当年跟刘邦一样南面称孤，现在他做了天子，我要去做他的臣子，这份耻辱我受不了。然后自刎。<strong>他是队尾那一个，他跑不动了。</strong></p>
<p><strong>什么情况必须走：</strong>如果留下意味着你要亲手做你认定是错的事，那就走，晚也要走。判断标准：<strong>这件事会不会让你改掉你不想改的东西。</strong></p>
<h3 id="p-六二-执之用黄牛之革-莫之胜说-拿牛皮绳把自己绑">六二 · 执之用黄牛之革，莫之胜说 —— 拿牛皮绳把自己绑住</h3>
<blockquote class="pw-quote"><strong>六二：执之用黄牛之革，莫之胜说。</strong><br>象曰：执用黄牛，固志也。</blockquote>
<p><strong>你现在在这个位置：该走的人都在走，但你要留下来。</strong></p>
<p>黄牛之革是牛皮绳，结实。说，通「脱」。这句的意思是：<strong>用牛皮绳把人捆住，谁也解不开。</strong></p>
<p>爻辞里没有任何吉凶，它描写的是一种姿态。</p>
<p>象传给了三个字：「固志也」——<strong>你的心志是定的。</strong></p>
<p>这一爻讲的是<strong>逆着人群留下。</strong></p>
<p>这需要理由。不是为了硬气，是真的有非留不可的东西。</p>
<p>具体动作：</p>
<p><strong>一，把留下来的理由写清楚。</strong> 而且这个理由不能是「我舍不得」。</p>
<p><strong>二，把你能守住的边界划出来。</strong></p>
<p><strong>三，别站在原地解释。</strong> 解释会让你看起来像在找台阶。</p>
<p>夷齐不食周粟，饿死在首阳山。他们从孤竹国出来，本来是要去西周的。</p>
<p>走到半路，碰上武王伐纣，他们拦住马说「父死不葬，爰及干戈，可谓孝乎？以臣弑君，可谓仁乎？」后来天下归周，他们躲进首阳山采薇而食。<strong>这是执之用黄牛之革——他们的志是固的。</strong></p>
<p><strong>什么情况不要硬留：</strong>如果你的理由只是面子、只是不服气，那就别留。判断标准：<strong>你留下来，是为了守住什么，还是为了证明什么。</strong></p>
<h3 id="p-九三-系遁-有疾厉-畜臣妾吉-想走走不掉">九三 · 系遁，有疾厉，畜臣妾吉 —— 想走走不掉</h3>
<blockquote class="pw-quote"><strong>九三：系遁，有疾厉，畜臣妾吉。</strong><br>象曰：系遁之厉，有疾惫也。畜臣妾吉，不可大事也。</blockquote>
<p><strong>你现在在这个位置：你想走，但你有牵挂。位置、钱、人、还有那些已经投进去的时间。</strong></p>
<p>系遁，是被绳子系住的退避。</p>
<p>爻辞给的是「有疾厉」——<strong>你会累出病来。</strong></p>
<p>象传说得特别传神：「有疾惫也」。<strong>不是受伤，是疲惫。</strong></p>
<p>这一爻是全卦最真实的。大多数人卡住，不是卡在「不知道」，是卡在「放不下」。</p>
<p>具体动作：</p>
<p><strong>一，把你放不下的东西列出来，标上价。</strong> 那些东西值多少，你愿意为它们留多久。</p>
<p><strong>二，把该做的事做小。</strong> 爻辞说「畜臣妾吉」——你能管好身边这一小摊，就是吉。这个阶段别搞大动作。</p>
<p><strong>三，给自己一个具体的期限。</strong></p>
<p>范蠡帮勾践灭了吴国之后，立刻就走。他走的时候给文种留了一封信，说「飞鸟尽，良弓藏；狡兔死，走狗烹。越王为人长颈鸟喙，可与共患难，不可与共乐。子何不去？」</p>
<p>文种没走，他只称病不朝。后来有人进谗言，勾践赐给他一把剑，让他自尽。<strong>文种就是系遁。</strong></p>
<p><strong>什么情况该被系住：</strong>如果你放不下的是你正在养的人——你的孩子、你的团队、你的病人——那就别硬走。判断标准：<strong>你走了，他们会怎么样。</strong></p>
<h3 id="p-九四-好遁-君子吉-小人否-走得漂亮">九四 · 好遁，君子吉，小人否 —— 走得漂亮</h3>
<blockquote class="pw-quote"><strong>九四：好遁，君子吉，小人否。</strong><br>象曰：君子好遁，小人否也。</blockquote>
<p><strong>你现在在这个位置：你有能力走，而且你走得起。走还是留，是你的选择。</strong></p>
<p>好遁的「好」，是恰好、是漂亮。</p>
<p>爻辞说：君子这么走，吉；小人这么走，不吉。</p>
<p>差别在哪？象传没展开，但意思清楚：<strong>同样的动作，心里装的东西不一样，结果就不一样。</strong></p>
<p>九四是有能力、有条件的人。这种人走，最容易被理解成撂挑子。</p>
<p>具体动作三条：</p>
<p><strong>一，把交接做完整。</strong> 走得漂亮的标志，是接手的人不骂你。</p>
<p><strong>二，别带走不该带的。</strong> 客户、数据、人。</p>
<p><strong>三，别在走的时候说狠话。</strong> 你说的话会留在别人嘴里比你留得久。</p>
<p>张良在刘邦称帝之后，说自己「以三寸舌为帝者师，封万户，位列侯，此布衣之极，于良足矣。愿弃人间事，欲从赤松子游耳」。他学辟谷，练导引，慢慢地从朝堂上退出去。</p>
<p>他没有跟谁闹翻，也没有要更多的东西。<strong>这就是好遁。</strong></p>
<p><strong>什么情况走得难看一点也没关系：</strong>如果那地方已经让你没法做人了，那就别管好不好看。判断标准：<strong>你的健康和底线，还在不在。</strong></p>
<h3 id="p-九五-嘉遁-贞吉-走得正确">九五 · 嘉遁，贞吉 —— 走得正确</h3>
<blockquote class="pw-quote"><strong>九五：嘉遁，贞吉。</strong><br>象曰：嘉遁贞吉，以正志也。</blockquote>
<p><strong>你现在在这个位置：你在一个很高的位置上退下来。所有人在看着你怎么退。</strong></p>
<p>嘉遁，是美好的退避。爻辞给的是贞吉。</p>
<p>九五和九四的差别：九四是「走得漂亮」，九五是<strong>「退得合乎道义」。</strong></p>
<p>具体动作：</p>
<p><strong>一，把位置交出去，而不是把位置悬着。</strong> 悬着的位置会让所有人都不敢动。</p>
<p><strong>二，退的时候守正。</strong> 不带走资源，不留后手。</p>
<p><strong>三，找一个说得出口的理由。</strong> 这个理由要能让对方体面地接受。</p>
<p>尧把天下让给舜，顺序是这样的：尧先让位给许由，许由不受，逃到箕山。尧又让给子州支父，也不受。最后才让给舜。</p>
<p>舜后来也让给善卷、石户之农，都不受，最后让给了禹。</p>
<p><strong>这一段里最要紧的是那些不接受的人。</strong> 他们退了，而这个退是被记下来的。九五讲的不是让位，是那个「辞让」的姿态。</p>
<p><strong>什么情况可以要个说法：</strong>如果你退是因为有人做了不地道的事，那你可以在退之前把这件事说清楚。判断标准：<strong>说了之后，是事情清楚，还是事情更乱。</strong></p>
<h3 id="p-上九-肥遁-无不利-走得一干二净">上九 · 肥遁，无不利 —— 走得一干二净</h3>
<blockquote class="pw-quote"><strong>上九：肥遁，无不利。</strong><br>象曰：肥遁无不利，无所疑也。</blockquote>
<p><strong>你现在在这个位置：你没有牵挂。你可以走得很远。</strong></p>
<p>肥遁的「肥」，是宽裕、是超然。</p>
<p>爻辞给的是「无不利」——<strong>没有一样不顺。</strong></p>
<p>象传给了四个字：「无所疑也」。<strong>你心里没有疑问。</strong></p>
<p>上九是遁卦的最高境界。它讲的不是怎么退，是<strong>退得彻底。</strong></p>
<p>具体动作：</p>
<p><strong>一，别留尾巴。</strong> 不挂顾问、不去站台、不接电话。</p>
<p><strong>二，别回来。</strong> 回来一次，前面所有的退都白退。</p>
<p><strong>三，去过你自己想过的日子。</strong></p>
<p>范蠡走了之后改了名字，叫鸱夷子皮，在海边种地，后来去了陶地做生意，十九年之中三致千金。他再也没有回过越国。<strong>他走得一干二净。</strong></p>
<p><strong>什么情况不要走绝：</strong>如果你只是暂时需要喘口气，那就别把关系剪断。判断标准：<strong>你是一时累，还是真的不想再碰。</strong></p>
<h3 id="p-最后-退一步-不是认输-是换个地方活">最后：退一步，不是认输，是换个地方活</h3>
<p>遁卦的大象传给了一句很难做到的话：<strong>「远小人，不恶而严」。</strong></p>
<p><strong>离小人远一点，但别表现出厌恶。</strong></p>
<p>为什么？因为你一表现出厌恶，就变成了对立；一变成对立，你就走不干净了。</p>
<p>遁卦最后一句「无所疑也」，讲的是最高标准。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">走这件事，怕的不是损失。怕的是你走的时候还在回头看。</blockquote>
  `,
  dazhuang: `
<p>一个人刚拿了融资，账上多了八千万。</p>
<p>他做的第一件事是招人，三个月从四十人扩到两百人。第二件事是租了一整层写字楼。第三件事是在行业大会上宣布，明年营收翻五倍。</p>
<p>第二年，营收没翻，人裁了一半。</p>
<p>他后来复盘，说了一句：「那会儿我手上钱多，我就觉得什么事都能办。」</p>
<p>大壮卦讲的就是这件事。</p>
<p>大壮是雷天大壮，雷在天上。四个阳爻往上走，阳气盛到极点。</p>
<p>卦辞只有两个字：<strong>利贞。</strong></p>
<p>就这么点。力量越大的时候，《周易》说的话越少。</p>
<p>彖传补了一句：「大者正也」。<strong>真正的强大在正，不在猛。</strong></p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-壮于趾-征凶-有孚-劲全在脚上">初九 · 壮于趾，征凶，有孚 —— 劲全在脚上</h3>
<blockquote class="pw-quote"><strong>初九：壮于趾，征凶，有孚。</strong><br>象曰：壮于趾，其孚穷也。</blockquote>
<p><strong>你现在在这个位置：你憋着一股劲，位置却最低。你特别想动。</strong></p>
<p>壮于趾，力量全在脚趾头上。</p>
<p>爻辞给的是「征凶，有孚」——<strong>你这么冲出去，凶，而且是肯定的凶。</strong></p>
<p>象传一句话点透：「其孚穷也」。<strong>你这份自信，底子是空的。</strong></p>
<p>这一爻讲的是<strong>位置低而气盛。</strong></p>
<p>具体动作：</p>
<p><strong>一，把你现在最想做的那个动作，推迟一个月。</strong> 一个月后还想做，再评估。</p>
<p><strong>二，找一个比你资深的人，把这个动作讲给他听。</strong> 只看反应，不听建议。</p>
<p><strong>三，把这股劲转成准备。</strong> 力气不用在该用的地方，就是浪费。</p>
<p>刘邦先入关中的时候，按楚怀王的约定，他应该做关中王。可他那时只有十万兵，项羽有四十万，驻在鸿门。</p>
<p>刘邦的反应是：还军霸上，封存府库，等项羽来。他没有堵函谷关——他本来堵了，被项羽攻破之后立刻就把关让开了。<strong>他那时候劲全在脚上，但他忍住了。</strong></p>
<p><strong>什么情况可以冲：</strong>如果这件事又快又小，试错成本很低，那就冲一下。判断标准：<strong>输了之后，你还能不能站在原地。</strong></p>
<h3 id="p-九二-贞吉-有劲不用">九二 · 贞吉 —— 有劲不用</h3>
<blockquote class="pw-quote"><strong>九二：贞吉。</strong><br>象曰：九二贞吉，以中也。</blockquote>
<p><strong>你现在在这个位置：你有实力了，但没有人给你舞台。你在中间待着。</strong></p>
<p>爻辞两个字：贞吉。</p>
<p>象传解释：「以中也」——<strong>因为你在中间。</strong></p>
<p>九二是大壮六爻里最安静的一个。它有力气，但是它不动。</p>
<p>具体动作三条：</p>
<p><strong>一，把「守正」变成具体的行为。</strong> 不该拿的不拿，不该说的不说，不该越的不越。</p>
<p><strong>二，练内功。</strong> 你有劲没处使的时候，是最好的练兵时间。</p>
<p><strong>三，别急着找舞台。</strong> 舞台会来找有准备的人。</p>
<p>周勃在吕后当政的时候，是太尉，管兵。可吕后把南北军的兵权都交给了吕家的人，周勃这个太尉是个空头衔。他没有硬抢，也没有发作，他就是等着。</p>
<p>等到吕后一死，他跑到北军，对着士兵喊：「为吕氏右袒，为刘氏左袒。」全军都脱了左边的袖子。<strong>他在九二这个位置上待了很多年。</strong></p>
<p><strong>什么情况必须出手：</strong>如果局面已经到了不动就来不及的时候，那就动。判断标准：<strong>你再等，还有没有机会。</strong></p>
<h3 id="p-九三-小人用壮-君子用罔-有力气的人不用力气">九三 · 小人用壮，君子用罔 —— 有力气的人不用力气</h3>
<blockquote class="pw-quote"><strong>九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。</strong><br>象曰：小人用壮，君子罔也。</blockquote>
<p><strong>你现在在这个位置：你的实力已经被所有人看见了。有人开始怕你。</strong></p>
<p>这一爻是大壮的分水岭。</p>
<p>「小人用壮」——没见识的人上手就用力气。</p>
<p>「君子用罔」——有见识的人把力气当成一张网，收着用。</p>
<p>爻辞后面跟着一个特别形象的比喻：<strong>羝羊触藩，羸其角。</strong> 公羊用角去顶篱笆，角卡在里面了。</p>
<p>这一爻讲的是<strong>力量用错地方的后果。</strong></p>
<p>具体动作：</p>
<p><strong>一，把你最近三个月用过的力气列一遍，看有多少是用于「让对方服」。</strong></p>
<p><strong>二，把那个动作换成一个不需要对手的动作。</strong> 不是打赢他，是做一件他做不了的事。</p>
<p><strong>三，主动降低别人对你的威胁感。</strong> 请他帮个你确实需要帮的忙，把功劳分出去。</p>
<p>韩信打下齐国之后，派人跟刘邦要假齐王的封号。刘邦当时被围在荥阳，气得骂人，张良踩他的脚，他立刻改口封真王。韩信这件事办得就是「用壮」。</p>
<p>后来刘邦夺他兵权，用的是「游云梦」这一招——不跟你打，请你来见我。<strong>刘邦用罔，韩信触藩。</strong></p>
<p><strong>什么情况必须用壮：</strong>如果对面就是吃硬不吃软，那就得亮一次。判断标准：<strong>你亮完之后，他会不会收敛。</strong></p>
<h3 id="p-九四-藩决不羸-壮于大舆之輹-篱笆自己倒了">九四 · 藩决不羸，壮于大舆之輹 —— 篱笆自己倒了</h3>
<blockquote class="pw-quote"><strong>九四：贞吉，悔亡。藩决不羸，壮于大舆之輹。</strong><br>象曰：藩决不羸，尚往也。</blockquote>
<p><strong>你现在在这个位置：卡住你的那个东西没了。路通了，你的力量终于有用处了。</strong></p>
<p>藩决不羸——篱笆开了，角没被卡住。</p>
<p>壮于大舆之輹——你的强，强在车轴上，那是承重的地方。</p>
<p><strong>这一爻对比九三，讲的是同一个人的不同阶段。</strong></p>
<p>九三的力量用在角上，九四的力量用在轴上。角是攻击的，轴是承重的。</p>
<p>换一句话说：九三想的是怎么赢，九四想的是怎么一直赢。这两件事需要的力气，方向完全不同。</p>
<p>具体动作：</p>
<p><strong>一，路通了的第一个动作，不是冲锋，是加固。</strong></p>
<p><strong>二，把资源投在能承重的地方。</strong> 人、流程、现金。</p>
<p><strong>三，别去追那个刚被你甩开的人。</strong> 追他是浪费。</p>
<p>周公东征，平定管蔡之乱之后，做的是营建洛邑、分封诸侯、制礼作乐。他没有接着打，他把打下来的地方变成了一个能运转的秩序。<strong>九四的力量用在轴上。</strong></p>
<p><strong>什么情况该追：</strong>如果那个对手还会回来，而且回来的时候更强，那就得追。判断标准：<strong>他还有没有还手的本钱。</strong></p>
<h3 id="p-六五-丧羊于易-无悔-主动把羊丢了">六五 · 丧羊于易，无悔 —— 主动把羊丢了</h3>
<blockquote class="pw-quote"><strong>六五：丧羊于易，无悔。</strong><br>象曰：丧羊于易，位不当也。</blockquote>
<p><strong>你现在在这个位置：你在一个偏软的位置上，但周围的力气都比你大。</strong></p>
<p>丧羊于易——在平易的地方把羊丢了。</p>
<p>羊在大壮卦里是「壮」的象征。丢羊，就是<strong>主动放掉那份强硬。</strong></p>
<p>爻辞给的是「无悔」。</p>
<p>象传解释：「位不当也」。<strong>你在这个位置上，本来就不该硬。</strong></p>
<p>六五是大壮卦里唯一的阴爻（除了上六），它在君位。这个位置需要的是柔，不是壮。</p>
<p>具体动作：</p>
<p><strong>一，在局面还没激化的时候，先让一步。</strong> 爻辞强调「于易」——要在平易的时候让，不要等到险难的时候让。</p>
<p><strong>二，把强硬换成规则。</strong></p>
<p><strong>三，别把让步说成让步。</strong> 说成「我改了个办法」。</p>
<p>汉文帝即位之初，对功臣集团非常客气。周勃做右丞相，上朝的时候很得意，文帝对他很恭敬。有人提醒周勃，说他功高震主，这样下去危险。周勃后来就辞了相。</p>
<p>文帝没有打压他，是周勃自己退的。<strong>汉文帝在这个位置上做的事，就是「丧羊于易」——他从不硬碰。</strong></p>
<p><strong>什么情况不能丢羊：</strong>如果退这一步会让对方得寸进尺，那就别退。判断标准：<strong>你退完之后，对方是停了，还是继续往前。</strong></p>
<h3 id="p-上六-羝羊触藩-不能退-不能遂-撞进去了">上六 · 羝羊触藩，不能退，不能遂 —— 撞进去了</h3>
<blockquote class="pw-quote"><strong>上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉。</strong><br>象曰：不能退，不能遂，不祥也。艰则吉，咎不长也。</blockquote>
<p><strong>你现在这个位置：你已经撞上去了。退不回来，也过不去。</strong></p>
<p>上六和九三用的是同一个比喻，但结果不同。</p>
<p>九三是「羸其角」——角卡住了。上六是「不能退，不能遂」——<strong>整个都卡住了。</strong></p>
<p>爻辞给的是「无攸利，艰则吉」。</p>
<p><strong>四个字是这一爻的活路：艰则吉。</strong></p>
<p>艰是什么？是承认难，是不装，是老老实实按最难的那条路走。</p>
<p>大部分人卡在藩里的原因只有一个：<strong>不肯承认自己错了。</strong> 承认之后，路是难走，但至少是条路。</p>
<p>具体动作三条：</p>
<p><strong>一，承认自己撞进去了。</strong> 别再说「我只是试试」。</p>
<p><strong>二，别硬拔。</strong> 硬拔会伤得更重。先让角松一点。</p>
<p><strong>三，跟对面谈。</strong> 到了这一步，只有对面能让你出去。</p>
<p>吴王夫差在黄池会盟的时候，越国打进了吴都。他回军之后跟越国讲和，勾践答应了。可夫差没有真正认账，他回去之后还是老样子。</p>
<p>九年后越国再打，吴国灭了，夫差自刎。他临终说：「吾悔不用子胥之言，自令陷此。」<strong>他卡在藩里十几年，一直没有走「艰」那条路。</strong></p>
<p><strong>什么情况可以硬拔：</strong>如果这个局面本来就撑不了多久，对面的篱笆自己会烂，那就等等。判断标准：<strong>耗下去，谁先撑不住。</strong></p>
<h3 id="p-最后-力气是个放大器">最后：力气是个放大器</h3>
<p>大壮卦最要紧的一句话，在象传里：<strong>「非礼弗履」。</strong></p>
<p>不合规矩的事，不要踩上去。</p>
<p>这一句放在大壮卦里，不是说教。它是个技术判断。</p>
<p><strong>因为力气是个放大器。</strong></p>
<p>规矩之内用力，是建设；规矩之外用力，是破坏。同样一份力气，结果差得很远。</p>
<p>而人在力气大的时候，恰恰最不喜欢被规矩管。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">有力气不用，是浪费。有力气乱用，是灾难。</blockquote>
  `,
  jin: `
<p>你在一个地方干了三年，活儿越干越重，位置一动不动。上个月部门提了一个人，比你晚来两年，平时看着也没你忙。</p>
<p>你心里那句话憋了很久：凭什么。</p>
<p>你甚至开始怀疑自己——是不是我不够会来事，是不是我该去说点什么。</p>
<p>晋卦讲的就是这件事：一个人往上走的时候，都会碰到什么。</p>
<p>上离下坤，太阳从地平线上升起来。光明不是一跃而出的，是一寸一寸爬上去的。卦辞说「康侯用锡马蕃庶，昼日三接」——有功的臣子被赏了成群的马，一天之内被君王召见三次。</p>
<p>注意这件事的顺序：先有功，后有赏。不是先被看见，再想办法做出功。</p>
<p>六个爻，是一段晋升路上的六道坎。你找一个最像自己的。</p>
<h3 id="p-初六-晋如-摧如-刚想上去就挨了一下">初六 · 晋如，摧如 —— 刚想上去就挨了一下</h3>
<blockquote class="pw-quote"><strong>初六：晋如，摧如，贞吉。罔孚，裕无咎。</strong><br>象曰：晋如摧如，独行正也。裕无咎，未受命也。</blockquote>
<p><strong>你现在在这个位置：你刚露出一点想往上走的意思，就被按了回来。可能是领导一句轻描淡写的话，也可能是一个本该给你的机会给了别人。</strong></p>
<p>「晋如，摧如」四个字，把那种感觉写透了。刚往上够一把，手就被打掉。</p>
<p>这个阶段只做一件事：<strong>别自证。</strong></p>
<p>「罔孚」是没人信你，「裕无咎」是宽着点、慢着点，就没事。象传给了理由——「未受命也」，你还没拿到那个任命，你没有位置，这时候你越解释越像急。</p>
<p>具体怎么做：想说的话先写下来，放三天。三天后你还想说，再挑一句最不情绪化的说。这三天里你要干的，是把手上那件事做出一个能拿给别人看的结果。</p>
<p>标准很简单：<strong>你现在解释的冲动有多强，你手上的东西就有多虚。</strong>活儿硬的人不急着解释，他不怕等。</p>
<p>商鞅入秦的时候，第一次见秦孝公讲帝道，孝公听得打瞌睡；第二次讲王道，还是不听；第三次讲霸道，孝公才往前挪了挪膝盖。<strong>他没抱怨过一句秦孝公不识货，他换了个说法再讲一遍。</strong></p>
<p><strong>什么情况可以破例：</strong>如果压你的人正在公开否定你的能力，而这话会影响别人对你的判断，那必须当场回一句，就一句，讲事实不讲委屈。剩下的时间照旧干活。沉默久了，别人会以为你默认了。</p>
<h3 id="p-六二-晋如-愁如-没人接你的话">六二 · 晋如，愁如 —— 没人接你的话</h3>
<blockquote class="pw-quote"><strong>六二：晋如，愁如，贞吉。受兹介福，于其王母。</strong><br>象曰：受兹介福，以中正也。</blockquote>
<p><strong>你现在在这个位置：你在往上走，可你心里发愁。上面没人替你说话，你干的事像是掉进了棉花里。</strong></p>
<p>「愁如」两个字很轻，但很真。有些人不怕累，怕的是累得没着落。</p>
<p>这个阶段的动作：<strong>把你在做的事，做成一件有名字的事。</strong></p>
<p>不是让你去邀功。是让你的活儿从「一堆活儿」变成一个「东西」。一个东西能被指认，一堆活儿不能。</p>
<p>给它一个说法、一个流程、一个可以重复用的模板。</p>
<p>举例子：你天天在补数据，那你把它做成一张每月自动出的表；你天天在救火，那你把它们归类成三种火，写清楚每种火怎么灭。名字一起，别人就能记住你。记不住你，谁都帮不了你。</p>
<p>「受兹介福，于其王母」——那个大福不是从上面直接掉下来的，是从一个你想不到的角落来的。注疏里说，六二往上没有应援，他能做的只有不改其德。守住了，福自己会来。</p>
<p>战国的时候，赵奢还只是个收田租的小官，平原君家不肯交租，他一口气杀了平原君家九个管事。平原君要杀他，他去讲了一通道理。<strong>平原君听完没杀他，转头把他推荐给了赵王。</strong></p>
<p>****荐他的不是赵王，是他的对头。</p>
<p><strong>什么情况要主动出击：</strong>如果这个地方的规则就是「会哭的孩子有奶吃」，那你不哭就是放弃。判断标准只有一条——这里的人是不是靠诉苦拿到资源的？是，你就去说；不是，你说了就掉价。</p>
<h3 id="p-六三-众允-悔亡-别一个人硬挤">六三 · 众允，悔亡 —— 别一个人硬挤</h3>
<blockquote class="pw-quote"><strong>六三：众允，悔亡。</strong><br>象曰：众允之志，上行也。</blockquote>
<p><strong>你现在在这个位置：你有点着急了，开始想走捷径，或者想越过某个环节直接够到上面。</strong></p>
<p>六三这一爻，原文只有四个字加两个字。「众允，悔亡」——大家都点头，你就没有悔恨。</p>
<p>这四个字里藏着一条很硬的规矩：<strong>在这个位置，你的口碑不是你自己攒的，是你周围的人替你攒的。</strong></p>
<p>六三不当位，本来该有悔；为什么悔亡了？因为「与众同信」。上面的人要提一个人，他不会只看你，他会去问跟你平级的那几个。</p>
<p>那几个人说你好，你就是好；他们说不清楚，你就说不清楚。</p>
<p>所以这一段该干的事很具体：<strong>去数一数，跟你同级的五个人里，有几个人会在背后替你说一句好话。</strong>三个以下，你现在的重点不是往上够，是回头补关系。</p>
<p>怎么补？不是请客吃饭，是让别人欠你一点顺手的人情，然后你从不提。</p>
<p>刘邦在沛县起事，萧何、曹参都是县里的吏，论职位都比刘邦高。<strong>起事的时候这两个人往后缩，一定推刘邦当头。</strong>他们不是谦让，是算过账——带头的人要担灭族的风险。</p>
<p>可这一推，刘邦后面所有的班底，都是这帮人。</p>
<p><strong>什么情况不用管众人：</strong>如果你的上面是一个只认结果、不看关系的人，那你讨好周围纯属浪费时间。这时候你要做的是把结果做到刺眼，让他没法绕过你。</p>
<h3 id="p-九四-晋如鼫鼠-什么都想要-什么都不精">九四 · 晋如鼫鼠 —— 什么都想要，什么都不精</h3>
<blockquote class="pw-quote"><strong>九四：晋如鼫鼠，贞厉。</strong><br>象曰：鼫鼠贞厉，位不当也。</blockquote>
<p><strong>你现在在这个位置：你上去了，但坐得不踏实。你心里清楚自己的位置和本事不完全对得上。</strong></p>
<p>鼫鼠是一种贪多的动物。古人说它「能飞不能过屋，能缘不能穷木，能游不能渡谷，能穴不能掩身，能走不能先人」——五样本事，样样稀松。</p>
<p>这一爻是六个爻里唯一一个明确的警告：<strong>「位不当也」。</strong></p>
<p>这个阶段最该做的动作是：<strong>砍掉你的枝干，只留一根主干。</strong></p>
<p>你现在手上有几个摊子？好好数一数。凡是你说不清「这件事除了我，还有谁能接手」的，都是你的枝干。</p>
<p>枝干越多，你越像鼫鼠。</p>
<p>具体判断：<strong>挑出那个只有你能干、且最能被人看见的，剩下全部交出去或者停掉。</strong>别怕停下来会失去什么，你现在拥有的东西本来就不牢。再拖，是等着别人帮你停。</p>
<p>李斯在秦朝做丞相，权力到顶。他明知赵高要改遗诏，明知扶苏比胡亥强，可他想保住自己那个位置，就跟赵高合了伙。<strong>他什么都想要——既要名声，又要权，又要命。</strong></p>
<p><strong>最后三样一样没留住，腰斩于咸阳。</strong></p>
<p><strong>什么情况可以继续兼着：</strong>如果你手上这几摊是一个系统里的不同环节，砍掉任何一个整个就转不动，那不是贪多，那是结构。这种情况你要做的不是砍，是找二把手，一人守一块。</p>
<h3 id="p-六五-失得勿恤-别算那点得失">六五 · 失得勿恤 —— 别算那点得失</h3>
<blockquote class="pw-quote"><strong>六五：悔亡，失得勿恤，往吉，无不利。</strong><br>象曰：失得勿恤，往有庆也。</blockquote>
<p><strong>你现在在这个位置：你已经在中间偏上的地方了，但你还在算小账——这一把亏了，那一把赚了。</strong></p>
<p>「失得勿恤」，就是别惦记得失。</p>
<p>这一爻说得特别痛快：往吉，无不利。没有任何附加条件。</p>
<p>为什么这一爻敢这么说？因为到了这个位置，你输不起的从来不是某一笔得失，是别人对你这个人的判断。<strong>你在小事上斤斤计较一次，你的分量就轻一分。</strong></p>
<p>具体动作：<strong>把接下来一个月你要跟人争的东西列出来，划掉那些金额小、但伤感情的。</strong>剩下两件非争不可的，认真争，争到底。</p>
<p>再补一条：这一爻是柔居尊位，靠的不是压人，是让人愿意跟着你。你要给出去的东西比你拿到的东西多一点点，这一点点就是你的信用。</p>
<p>汉文帝刚被拥立进京，大臣们劝他早立太子，他说自己德薄，先推让。周勃入朝，他亲自送到门口；有人上书告周勃谋反，他查清楚了就放人、还归还爵邑。<strong>他让出去的都是能算清的东西，换回来的是二十年的安稳。</strong></p>
<p><strong>什么情况必须计较：</strong>如果这件事关系到原则和底线，或者是别人在试探你的边界，那就一分不让。你可以不在乎钱，不能不在乎规矩——规矩一松，后面全是麻烦。</p>
<h3 id="p-上九-晋其角-到顶了还想顶">上九 · 晋其角 —— 到顶了还想顶</h3>
<blockquote class="pw-quote"><strong>上九：晋其角，维用伐邑，厉吉无咎，贞吝。</strong><br>象曰：维用伐邑，道未光也。</blockquote>
<p><strong>你现在在这个位置：你已经到顶了，上面没有位置了。你还在用力，但你能用的力，好像只剩下跟自己人较劲。</strong></p>
<p>「晋其角」——用角去顶。角是动物最后的手段，顶出去就没有余地了。</p>
<p>象传这四个字最狠：<strong>「道未光也」。</strong>说这条路其实并不光彩。</p>
<p>到了这个位置，外面已经没有可以扩的地方了。你要是还保持着上升期的打法，火力只能往内——开始整内部，开始挑下属的错，开始跟自己队伍里的人过不去。</p>
<p>这一段该干的事：<strong>把对外的进攻性收起来，转成对内的整理。</strong></p>
<p>具体三件：把混乱的流程理一遍，把不该留的人请走，把你这些年攒下的经验写下来给人看。这三件事都不涨你的位置，但能保住你已经拿到的。</p>
<p>反面例子是霍光。他辅政二十年，废过一个皇帝，立过两个。他生前没人敢动他，死后三年霍家满门被诛。</p>
<p><strong>他一生守臣子的本分，可他的权力太重，重到皇帝睡不着觉。</strong>到那一步，本分已经保不住他家里人了。</p>
<p><strong>什么情况可以再顶一次：</strong>如果局面已经烂到你不顶就全盘崩，那就顶，但要顶对外、顶那件最大的事，不能顶自己人。顶自己人是最没出息的一种用力。</p>
<h3 id="p-最后-晋是往上走-不是抢上去">最后：晋是往上走，不是抢上去</h3>
<p>晋卦六个爻，我数了一下，「晋如」这个词出现了四次。</p>
<p>四次里两次后面跟着的不是好话——一次是「摧如」，一次是「愁如」，还有一次直接变成了「鼫鼠」。</p>
<p>往上走这件事，本来就不体面。你会被按回来，会没人接你的话，会想抄近道，会在到顶之后还想再顶。</p>
<p>晋卦从头到尾没让你钻营过一次。它给的路径很笨：<strong>先有康侯的功，才有昼日三接的宠。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别盯着那个位置。把手上这件事做成一个别人绕不过去的东西，位置自己会来找你。</blockquote>
  `,
  mingyi: `
<p>你所在的部门，做事的人越来越少，会说话的人越来越多。</p>
<p>你提的建议，领导当场点头，然后就再没了消息。你看见有人在混，也看见有人在背锅，你看得很清楚，可你什么都不能说。</p>
<p>你开始想：是不是我该走。</p>
<p>明夷讲的就是这件事。「明入地中」——太阳落到地底下去了，光还在，只是照不出来。</p>
<p>这一卦跟晋卦正好相反。晋是明出地上，一路往上亮；明夷是明入地中，一路往下藏。</p>
<p>六个爻讲的是同一件事：<strong>光在暗处该怎么办。</strong>不是怎么把黑暗照亮——那一卦不叫明夷，那叫革命。</p>
<h3 id="p-初九-明夷于飞-垂其翼-低飞-别出声">初九 · 明夷于飞，垂其翼 —— 低飞，别出声</h3>
<blockquote class="pw-quote"><strong>初九：明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。</strong><br>象曰：君子于行，义不食也。</blockquote>
<p><strong>你现在在这个位置：你已经看明白这里不对劲了。你想走，但还没走，你还在观望。</strong></p>
<p>「垂其翼」三个字是这一爻的全部秘诀。鸟在暗处飞，不是收翅膀落地，是垂着翅膀低飞——<strong>还能飞，但不让人看见。</strong></p>
<p>这个阶段最要命的一件事，是你忍不住跟人讲你的判断。你觉得自己只是跟一个信得过的人说了两句，可这话会传，传出去之后，第一个被怀疑的人是你。</p>
<p>具体动作：<strong>把你的判断只写进自己的本子里。</strong>写清楚三件事——你看到了什么，你猜会发生什么，如果发生了你打算怎么办。写完就合上。</p>
<p>「三日不食」不是让你绝食，是说该走的时候，饿着肚子也走。象传给了理由：「义不食也」——不是没得吃，是不吃。</p>
<p>商纣王刚开始用象牙筷子的时候，箕子就叹气，说用了象牙筷，接下来就要玉杯，要玉杯就要吃熊掌豹胎，要穿锦衣住高台。<strong>他看出来了，可他没到处讲。</strong>后来微子去问他要不要走，他说的是：如果国家真到了不可救的地步，那我不走，我留下来。</p>
<p><strong>什么情况可以把话说透：</strong>如果你已经确定要走了，而且走的手续都办完了，那你可以跟一两个真正要带走的人交个底。人还在里面的时候不要交底，交底就是把自己交出去。</p>
<h3 id="p-六二-夷于左股-用拯马壮-伤得不重-快跑">六二 · 夷于左股，用拯马壮 —— 伤得不重，快跑</h3>
<blockquote class="pw-quote"><strong>六二：明夷，夷于左股，用拯马壮，吉。</strong><br>象曰：六二之吉，顺以则也。</blockquote>
<p><strong>你现在在这个位置：你已经挨了一下，但伤在「左股」——能走，不至于废。</strong></p>
<p>古人讲左是伤小的地方。你被压了、被边缘了、被抢了一次功劳，但你的核心本事还在，饭碗还在。</p>
<p>这一爻给的动作非常干脆：<strong>跑，而且要借助一匹壮马。</strong></p>
<p>「用拯马壮」——自己跑不快，就找个能带你跑的东西。落到今天，就是三样：一个能立刻接住你的新去处，一个愿意替你说话的中间人，一笔能让你撑半年的钱。</p>
<p>别自己闷头熬。象传判这一爻吉，给的评语是「顺以则也」——顺着规则走，不硬碰。</p>
<p>给你一条判断线：<strong>如果这件事伤到的是你的收入或身份，那不管多重都要立刻启动退路；如果伤到的只是面子，那就先把面子放下，留在原地继续攒本事。</strong></p>
<p>范蠡跟着勾践在吴国做了三年奴仆，回来之后一句怨言没有，埋头替越国练兵、攒钱、修城。等勾践灭吴，他当天就泛舟走了。<strong>他挨过的那三年是「左股」，他从来没让那三年变成要命的伤。</strong></p>
<p><strong>什么情况不用跑：</strong>如果挨这一下是因为你自己犯了错，那伤是自己招的，跑就是逃避。这种情况下先把错补上，补不上再谈走不走。</p>
<h3 id="p-九三-明夷于南狩-得其大首-要动手-就往大处动">九三 · 明夷于南狩，得其大首 —— 要动手，就往大处动</h3>
<blockquote class="pw-quote"><strong>九三：明夷于南狩，得其大首，不可疾贞。</strong><br>象曰：南狩之志，乃大得也。</blockquote>
<p><strong>你现在在这个位置：你手里有牌了。你不再是那个只能低飞的人，你开始想动一下。</strong></p>
<p>南方是光明的地方，「狩」是征伐。「得其大首」——一下打到那个最大的头目。</p>
<p>这一爻的关键词是「大首」和「不可疾贞」。</p>
<p><strong>大首：你要动，就动那个最根本的。</strong>跟同事争一个项目的署名，是小动作；把这条业务线的做法整体换掉，才叫南狩。选择动手的对象，比动手本身重要十倍。</p>
<p><strong>不可疾贞：不能急着把一切扳正。</strong>你把那个不对的人换掉之后，剩下那些人脑子里装的还是老一套。你一天改完，他们三天就给你改回来。</p>
<p>具体怎么做：<strong>换人之后，给你自己定一个一年期的节奏表。</strong>第一个季度只动一件事，第二季度再动一件。急不得。</p>
<p>周勃和陈平灭诸吕，动手之前先做的事是「交欢」——两个人本来有嫌隙，先握了手。然后他们才去动吕禄、吕产。<strong>动手那天晚上很快，可前面铺垫了几个月。</strong></p>
<p><strong>什么情况要快：</strong>如果对方正在集中力量准备对付你，那就不能等。这种情况下一击必须到底，留下一个尾巴，就是给自己留一个敌人。</p>
<h3 id="p-六四-入于左腹-获明夷之心-摸清他到底想什么">六四 · 入于左腹，获明夷之心 —— 摸清他到底想什么</h3>
<blockquote class="pw-quote"><strong>六四：入于左腹，获明夷之心，于出门庭。</strong><br>象曰：入于左腹，获心意也。</blockquote>
<p><strong>你现在在这个位置：你已经贴近权力中心了，你能看见那个说了算的人每天在想什么、怕什么。</strong></p>
<p>「入于左腹」——从左边进去，不走正门，不正面顶撞。「获明夷之心」——摸到了那个昏暗之人的心思。</p>
<p>这一爻是明夷全卦里最实用的一爻。</p>
<p>很多人到了这个位置会犯一个错：以为靠近了就能说话。你越近，你越要少说。你要做的是<strong>听懂他没说出口的那半句。</strong></p>
<p>他反复强调这件事重要，那这件事就有人在拿它做文章；他每次开会都问同一个数字，那那个数字有人给他使过坏；他忽然对一个平常人特别客气，那那个人背后有事。</p>
<p>摸清楚之后，动作只有两个字：<strong>避祸</strong>。「于出门庭」——门庭之外就停住，别往里走。</p>
<p>赵高在秦始皇面前伺候了二十多年，从不出错。他什么都知道，什么都不说。<strong>他等到始皇死在沙丘，才第一次出手。</strong></p>
<p><strong>什么情况要主动讲：</strong>如果你摸到的那件事会直接伤到你不该伤的人，或者涉及造假、违法，那不能装作不知道。这时候你不需要去对抗，你只需要不签字、不背书。</p>
<h3 id="p-六五-箕子之明夷-装糊涂-但心里不糊涂">六五 · 箕子之明夷 —— 装糊涂，但心里不糊涂</h3>
<blockquote class="pw-quote"><strong>六五：箕子之明夷，利贞。</strong><br>象曰：箕子之贞，明不可息也。</blockquote>
<p><strong>你现在在这个位置：你上面那个人很糟糕，可你走不了。可能是亲戚，可能是老领导，可能是你走不了的那个圈子。</strong></p>
<p>这一爻直接把箕子写进了爻辞。</p>
<p>纣王是箕子的亲侄子。纣王开始用象牙筷子，箕子劝；纣王酗酒，箕子劝；纣王杀了比干，剖了心。这时候微子走了，比干死了，箕子怎么办？</p>
<p>他选了第三条路：<strong>装疯。</strong></p>
<p>他披头散发，弹琴自娱，被纣王关了起来。他保住了命，保住了自己，等到武王灭商，他把《洪范》那套治国的大法讲给了周人听。</p>
<p>象传给了最要紧的一句：「明不可息也」——外面多黑都行，里面那点火不能灭。</p>
<p>具体怎么做，三条：</p>
<p><strong>一是别在外面显得比你的上级清醒。</strong>会议上不抢话，不纠正，不做那个唯一说真话的人。</p>
<p><strong>二是给自己留一件只有你知道的干净事。</strong>读的书、记的东西、帮的人——不用给谁看。</p>
<p><strong>三是把你看清楚的那些事写下来。</strong>不是为了告谁，是为了不让自己也被那套逻辑泡软。</p>
<p><strong>什么情况不要装：</strong>如果装下去要你亲手做一件亏心事，那就不能装。装疯的底线是不害人。越过了这条线，你保住的就不是自己，是共犯。</p>
<h3 id="p-上六-初登于天-后入于地-他也会有那一天">上六 · 初登于天，后入于地 —— 他也会有那一天</h3>
<blockquote class="pw-quote"><strong>上六：不明晦，初登于天，后入于地。</strong><br>象曰：初登于天，照四国也。后入于地，失则也。</blockquote>
<p><strong>你现在在这个位置：你是那个说了算的人，或者你眼看着某个人正在一路往下坠。</strong></p>
<p>上六是明夷里最暗的一爻，是「至暗之主」。</p>
<p>「初登于天，后入于地」——刚上来的时候，光能照到四方；到最后，掉进地里去了。</p>
<p>这一爻讲的是一条很朴素的规律：<strong>上位者失去光明，从来不是被别人夺走的，是他自己弄丢的。</strong>象传给的答案是三个字：「失则也」——把规矩丢了。</p>
<p>如果你现在的位置是那个说了算的人，这一段就一句话：</p>
<p><strong>去问一个最近不怎么说真话的人，他最怕你知道什么。</strong></p>
<p>不是让你去查他。是你身边已经没人敢跟你说实话了，你得自己去捞。</p>
<p>商纣王在鹿台，酒池肉林，他听得到的是「天命在我」。等周武王的兵到了牧野，他手下的奴隶倒戈，他跑回鹿台自焚。<strong>从他第一次用象牙筷子，到最后那把火，中间隔了很多年，每一年他都有机会停。</strong></p>
<p><strong>什么情况要主动退：</strong>如果你发现自己最近三个月做的每一件事都没人反对，那就该退了。没人反对不是因为你对了，是因为没人敢说了。</p>
<h3 id="p-最后-暗处最要紧的是别把自己也弄黑">最后：暗处最要紧的是别把自己也弄黑</h3>
<p>明夷讲的不是怎么赢。</p>
<p>它讲的是一个人在没法改变的环境里，怎么不带伤地活下来，怎么保住自己那点判断力。</p>
<p>六个爻给了六种活法：低飞、快跑、择机动手、摸清人心、装糊涂、看着对手坠下去。</p>
<p>有一条贯穿始终——<strong>「明不可息」。</strong>外面多暗，你心里那盏灯不能灭。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">在黑暗里不要急着点灯。先把自己揣好，等天亮。</blockquote>
  `,
  jiaren: `
<p>你妈又给你打电话，说你哥要借钱，让你先垫上，说一家人别算那么清。</p>
<p>你挂了电话没说话。这已经是第三次了。前两次的钱没人提过还。</p>
<p>你在公司也一样。你带的那几个人，出了事都找你，你从来没说过一句重话。你觉得自己是好说话，可你最近发现，他们出错的次数在变多。</p>
<p>家人卦讲的就是这件事：一个家、一个团队，为什么会从里面散掉。</p>
<p>上巽下离，风从火里生出来。火一烧，风就起了，风再吹火——这个卦画的是一股由内往外的劲。</p>
<p>卦辞只说三个字：「利女贞。」注疏里讲得直白，这一卦讲的是「女正位乎内，男正位乎外」——各人在各人的位置上。</p>
<p>位置一对，家就稳。位置一乱，钱再多也留不住。</p>
<h3 id="p-初九-闲有家-规矩要在第一天立">初九 · 闲有家 —— 规矩要在第一天立</h3>
<blockquote class="pw-quote"><strong>初九：闲有家，悔亡。</strong><br>象曰：闲有家，志未变也。</blockquote>
<p><strong>你现在在这个位置：刚开始。新组一个团队、新招一个人、刚结婚、刚接手一个部门。</strong></p>
<p>「闲」是栅栏，是把门拦住。有家之初，先把栅栏扎起来。</p>
<p>象传给的理由是「志未变也」——人心还没变的时候立规矩，最省力。等变了再立，那叫翻脸。</p>
<p>这个阶段的动作：<strong>在你还没有资格生气的时候，把丑话说在前面。</strong></p>
<p>具体到能做的事——新人第一天，说清楚三件事：什么必须报备，什么绝对不能碰，什么时候必须到。婚礼上别光敬酒，把家里的账怎么管讲明白。</p>
<p>判断标准只有一条：<strong>这条规矩，你现在说了对方会不会觉得你小题大做？会，那就现在说。</strong>等出了事再说，对方会觉得你在找茬。</p>
<p>刘邦进关中，跟老百姓约法三章，就三条，别的秦法全废。<strong>他不是来不及立法，是他知道这个节骨眼上，法越少，人来得越快。</strong></p>
<p><strong>什么情况不用立规矩：</strong>如果合作的是一锤子买卖，做完就散，那你把条款写进合同就行，不用费劲去管人心。栅栏是给长期关系用的。</p>
<h3 id="p-六二-无攸遂-在中馈-把手里那摊事做扎实">六二 · 无攸遂，在中馈 —— 把手里那摊事做扎实</h3>
<blockquote class="pw-quote"><strong>六二：无攸遂，在中馈，贞吉。</strong><br>象曰：六二之吉，顺以巽也。</blockquote>
<p><strong>你现在在这个位置：你不是拍板的那个，你是把事真正做成的那个人。你的名字很少出现在文件最上面。</strong></p>
<p>「无攸遂」是不要自作主张，「在中馈」是守着家里那口锅。</p>
<p>这一爻不是让人窝囊。注疏说得很实在：六二「履中居位」，位置刚好，该做的就是把自己那一摊管好。</p>
<p>翻译成今天的话：<strong>你不是决策者，你是那个让决策能落地的人。</strong>这个位置最值钱的能力，是把别人一句模糊的话变成一件能交付的事。</p>
<p>具体动作：把你要交付的东西定出标准——什么时候交、交成什么样、谁验收。标准的数量别超过三条。超过三条没人记得住。</p>
<p>再补一条：<strong>别越过你的上级去跟更上面的人搭话。</strong>六二的价值在于「顺以巽」，你把这个顺序守住了，你的位置就没人能拆。</p>
<p>萧何在刘邦的团队里管后勤，一直管到丞相。刘邦在前线一次次被打散，萧何一次次从关中给他送来兵和粮。<strong>刘邦查过他好几次，查完还是得用他——因为那摊事只有他撑得住。</strong></p>
<p><strong>什么情况可以越级：</strong>如果直接上级在造假或者在做违法的事，那必须往上报。这种情况下守规矩等于共犯。</p>
<h3 id="p-九三-家人嗃嗃-宁可严一点-别笑成一团">九三 · 家人嗃嗃 —— 宁可严一点，别笑成一团</h3>
<blockquote class="pw-quote"><strong>九三：家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。</strong><br>象曰：家人嗃嗃，未失也。妇子嘻嘻，失家节也。</blockquote>
<p><strong>你现在在这个位置：你是这个家、这个团队里说了算的人。你一开口，气氛就冷。</strong></p>
<p>「嗃嗃」是严厉的样子，「嘻嘻」是嬉笑的样子。</p>
<p>九三这一爻给了一个很硬的取舍：<strong>严厉会有悔、会有危，但还是吉；一味嬉笑，最后一定出问题。</strong></p>
<p>为什么？象传答得干脆——「失家节也」，分寸没了。</p>
<p>很多管理者怕伤和气，就用商量的口气办不该商量的事。时间一长，规矩就软了，软到最后没有一条能落地。</p>
<p>具体怎么做：<strong>把「对事严」和「对人暖」分开。</strong>事情的标准一寸不让，出了错的批评要具体到事，不评价人。批评完当天，跟他说一句跟工作无关的话。</p>
<p>给你一条线：<strong>如果你手下的错误连续三次是同一类，那不是他的问题，是你的规矩太软。</strong></p>
<p>诸葛亮斩马谡，杀完人之后亲自去吊丧，还照顾马谡的家人。<strong>他手上有刀，也有眼泪，两样都真。</strong></p>
<p><strong>什么情况可以松：</strong>如果这个人还在学、还在长，那严格的标准要配够多的时间。给不出时间就别立那个标准，那是拿标准当脾气。</p>
<h3 id="p-六四-富家-大吉-让跟着你的人过上日子">六四 · 富家，大吉 —— 让跟着你的人过上日子</h3>
<blockquote class="pw-quote"><strong>六四：富家，大吉。</strong><br>象曰：富家大吉，顺在位也。</blockquote>
<p><strong>你现在在这个位置：你手上管着资源和分配。谁能拿多少，你有很大发言权。</strong></p>
<p>「富家」不是让你自己发财。注疏说，「富」是禄位昌盛——你这一摊整体变好了。</p>
<p>这一爻给的动作很实在：<strong>你手上这块资源，先分给那些真干活的人。</strong></p>
<p>不是喊口号。是这个月的奖金、明年的编制、能露脸的项目，你去数一数，分给了谁。分得对不对，下面人心里有一本账，比你清楚。</p>
<p>「顺在位也」四个字值得琢磨——六四判大吉，靠的是守着位置、顺着上面。<strong>你没有权力改分配规则，但你有权力在执行的时候把手抬高一点。</strong></p>
<p>范仲淹做参知政事的时候，拿出自己的俸禄在苏州买了几千亩地做义庄，养族里的穷人，一直养到清末。<strong>他这一支范家，八百年没散。</strong></p>
<p><strong>什么情况可以往自己这边多留：</strong>如果你这一年担的风险最大、投的钱最多，那多拿是应该的。让利是给有余力的人准备的，你自己都周转不开还硬让，那不叫格局，叫失血。</p>
<h3 id="p-九五-王假有家-勿恤-吉-做到不用操心">九五 · 王假有家，勿恤，吉 —— 做到不用操心</h3>
<blockquote class="pw-quote"><strong>九五：王假有家，勿恤，吉。</strong><br>象曰：王假有家，交相爱也。</blockquote>
<p><strong>你现在在这个位置：你是这个家里最高的那个。你可以选择天天盯着，也可以选择放手。</strong></p>
<p>「假」是到的意思。王到了这个家——他真的是这个家的一部分，不是站在外面看的。</p>
<p>「勿恤」是不用忧虑。象传给了原因，四个字：<strong>「交相爱也」。</strong></p>
<p>家里人互相之间有感情，你就不用天天盯着。</p>
<p>这一爻是家人卦的高点，也是最难做到的。它要求的不是控制力，是你这个人有没有让周围人愿意彼此靠近。</p>
<p>具体动作：<strong>把你们家、你们团队里最容易被忽略的那个人，单独照顾一次。</strong>不是给钱，是让他被看见一次——在会上提一次他的名字，吃饭的时候坐他旁边。</p>
<p>再补一条：<strong>别当那个唯一的裁判。</strong>有矛盾的时候让他们先互相说，你最后再说。你说得越早，他们越不会自己解决。</p>
<p>舜的家里很糟——父亲和继母几次想害死他，弟弟象要抢他的财物。<strong>舜没有报复，也没有一刀两断，他该怎么孝顺还怎么孝顺。</strong>后来尧把两个女儿嫁给他，把天下交给他。</p>
<p><strong>什么情况不能交心：</strong>如果这个「家」里有人一直在利用你的善意，那就得先把账算清。交相爱的前提是彼此都把这个家当回事。</p>
<h3 id="p-上九-有孚威如-威严是省出来的">上九 · 有孚威如 —— 威严是省出来的</h3>
<blockquote class="pw-quote"><strong>上九：有孚威如，终吉。</strong><br>象曰：威如之吉，反身之谓也。</blockquote>
<p><strong>你现在在这个位置：你是这个家里辈分最高、资历最老的那个。你不用争，也没人跟你争。</strong></p>
<p>「有孚威如」——有信用，所以有威严。</p>
<p>象传给的解释值得抄下来：<strong>「反身之谓也。」</strong>威严不是坐在那儿瞪眼睛，是你回头管住自己。</p>
<p>上九是全家卦的收尾。它讲的其实是同一件事：位置最高的人，能管住的只有自己。你管不住自己，下面的人就学会了两套话。</p>
<p>具体动作：<strong>找出你要求别人做到、而你自己没做到的那一条，当众改过来。</strong>不用承认错误，改就行。别人看得见。</p>
<p>再补一条：<strong>你在家里说的每句话，都要能兑现。</strong>兑现不了的就别说。上九的威严是攒出来的，不是吼出来的。</p>
<p>曾国藩家书写了一辈子，写给弟弟、写给儿子，讲的都是读书、节俭、不张扬。曾家后面几代出了不少人才，没出一个败家的。<strong>他留下的不是钱，是一套自己也照着做的规矩。</strong></p>
<p><strong>什么情况可以破例：</strong>如果家里出了急事、大事，这时候不用讲平时那套。当家人这时候拍板、担责、把话说死，反而是最让人安心的。</p>
<h3 id="p-最后-家里的事-从来不是靠讲道理解决的">最后：家里的事，从来不是靠讲道理解决的</h3>
<p>家人卦六个爻，讲的都是怎么把秩序立起来：立规矩，守本分，宁可严一点，让干活的人过得好，做到不用操心，最后把自己管住。</p>
<p>它没有一处让你去说服谁。</p>
<p>家里的事说服不了。你只能做，做久了，别人就跟着做了。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别指望把家里人讲明白。你先把自己那一条做到，剩下的会自己归位。</blockquote>
  `,
  kui: `
<p>你跟你最好的那个朋友，已经半年没联系了。</p>
<p>不是什么大事。去年他找你帮忙，你当时正好忙，回得晚了两天，他后来就没再提。你再想问，又觉得好像没必要。</p>
<p>公司里也有这么一个人。你俩在会上对着干过两回，现在你看见他绕道走。你心里已经给他定好了性——这人就这样。</p>
<p>睽卦讲的就是这件事：两个人是怎么从一条路上分开的。</p>
<p>上离下兑，火往上烧，泽往下渗，一个往上走，一个往下走。彖传说「二女同居，其志不同行」——住在一个屋檐下，想的是两件事。</p>
<p>可睽卦不是让你分手。彖传后半段说了一句很妙的话：「天地睽而其事同也。」</p>
<p>天地离得那么远，可它们干的是同一件事。</p>
<h3 id="p-初九-丧马勿逐-自复-丢了的别追">初九 · 丧马勿逐，自复 —— 丢了的别追</h3>
<blockquote class="pw-quote"><strong>初九：悔亡。丧马勿逐，自复。见恶人，无咎。</strong><br>象曰：见恶人，以辟咎也。</blockquote>
<p><strong>你现在在这个位置：你跟某个人闹掰了，或者某个机会、某笔钱没了。你正在四处找补。</strong></p>
<p>「丧马勿逐，自复」——马跑了别去追，它自己会回来。</p>
<p>初九给的头一条建议就是：<strong>先别动。</strong></p>
<p>人在关系破裂的头几天，冲动是最强的。你会想发一条长消息，把这三年的委屈一次说完。发出去之后，关系就真的没了。</p>
<p>具体动作：<strong>把你想发的那段话写在备忘录里，写完存着。</strong>定个期限，七天。七天里你什么都不做，只观察对方有没有动。</p>
<p>第二条更反直觉：<strong>「见恶人，无咎。」</strong>跟你看不顺眼的那个人，见一面。</p>
<p>不是去和解，是去露个面。人不见面的时候，会自己在脑子里把对方越想越坏。见一面，发现他也就那样。</p>
<p>蔺相如位在廉颇之上，廉颇放话要当面羞辱他。蔺相如就躲，上朝称病，路上看见廉颇的车就引车避匿。<strong>他不是怕，他是算过——两虎相斗，秦国会趁机打过来。</strong></p>
<p><strong>什么情况必须去追：</strong>如果丢的是钱、是合同、是证据，那就得追，越早越好。这一爻讲的是人心和关系，不适用于账户。</p>
<h3 id="p-九二-遇主于巷-找个不那么正式的地方">九二 · 遇主于巷 —— 找个不那么正式的地方</h3>
<blockquote class="pw-quote"><strong>九二：遇主于巷，无咎。</strong><br>象曰：遇主于巷，未失道也。</blockquote>
<p><strong>你现在在这个位置：你需要跟一个跟你不对付的人把话讲开。你已经约了他三次，他都没答应。</strong></p>
<p>「遇主于巷」——在小巷子里碰上了。不是在大殿上，不是正式约见，是碰巧遇到。</p>
<p>注疏里说，九二跟上面那位本来该相求，只是路走不通，「不假远涉而自相遇」——不用跑远路，就近碰上。</p>
<p>这一爻的诀窍是：<strong>正式场合谈不成的事，换个不那么正式的地方谈。</strong></p>
<p>为什么？正式场合有位置、有面子、有旁人在看。两个人在会议室里，谁先开口谁就矮一头。</p>
<p>在电梯里、在楼下抽烟的地方、在饭局散了往外走那几步，就不一样了。</p>
<p>具体怎么做：<strong>别约。等他出现。</strong></p>
<p>搞清楚他每天什么时候去什么地方——食堂、电梯、楼下的便利店。你自然出现在那儿，打个招呼，说两句跟公事无关的。一次不够就两次。</p>
<p>孟尝君被罢相之后，门客跑了大半。后来他复了位，那些跑掉的人又回来了。他没骂人，只跟冯谖说了一句，冯谖劝他别断了这些人。</p>
<p><strong>他后来还是把这些人收回来了——因为这些人还有用。</strong></p>
<p><strong>什么情况不用绕：</strong>如果这件事本来就该摆到台面上讲，那就正大光明地开个会说。绕小巷是为了避开没必要的脸面之争，不是为了躲责任。</p>
<h3 id="p-六三-见舆曳-其牛掣-你被夹在中间-两头受气">六三 · 见舆曳，其牛掣 —— 你被夹在中间，两头受气</h3>
<blockquote class="pw-quote"><strong>六三：见舆曳，其牛掣，其人天且劓，无初有终。</strong><br>象曰：见舆曳，位不当也。无初有终，遇刚也。</blockquote>
<p><strong>你现在在这个位置：两边都不待见你。你想往东走，西边的人拉你；你想往前，前头有人牵住你的牛。</strong></p>
<p>「见舆曳，其牛掣」——车被人往后拖，牛被人往前拽。你坐在中间，动弹不得。</p>
<p>后面那句更狠。「其人天且劓」——天是在额头上刺字，劓是割鼻子。注疏里说，这是两边的人各从上下罚他一回。</p>
<p>这大概是所有处境里最难受的一种：不是有人害你，是<strong>两边都觉得你站错了队。</strong></p>
<p>给的动作只有一条：<strong>别急着选边，先守住你手上那件具体的事。</strong></p>
<p>「无初有终」——开头很难看，结尾有转机。象传给的理由是「遇刚也」，最后会有个够硬的人接住你。</p>
<p>具体怎么做：这三个月里你只做一件事，把柄子交出去的一部分收回来——手上的项目自己盯紧，关键的人自己联系，该留的记录留好。你不站边，但你要站得住。</p>
<p>汉初的时候，陈平从项羽那边投到刘邦这边，两边都有人骂他。周勃、灌婴跟刘邦说他「盗嫂受金」，反复无常。<strong>刘邦把他叫来质问，陈平把话讲清楚，刘邦反而赏了他。</strong></p>
<p><strong>他熬过了开头那一段。</strong></p>
<p><strong>什么情况必须选边：</strong>如果两边争的是对错、是有人在做不该做的事，那就不能中立。中立在那种局面里等于默认。</p>
<h3 id="p-九四-睽孤-遇元夫-你孤立了-那就去找另一个孤立">九四 · 睽孤，遇元夫 —— 你孤立了，那就去找另一个孤立的</h3>
<blockquote class="pw-quote"><strong>九四：睽孤，遇元夫，交孚，厉无咎。</strong><br>象曰：交孚无咎，志行也。</blockquote>
<p><strong>你现在在这个位置：你被孤立了。开会没人接你的话，群里没人回你的消息。</strong></p>
<p>「睽孤」两个字，把那种冷清写得很准。</p>
<p>这一爻给的出路很特别：<strong>「遇元夫。」</strong>去找那个同样被孤立的人。</p>
<p>注疏说「元夫」是初九——卦最开始的那一爻，位置最低的那个。不是你的上级，不是你的盟友，是一个同样在外围的人。</p>
<p>这很反常识。人在孤立的时候，本能是往高处靠，找一个有分量的人替自己说话。可高处的人不缺人靠，你去了也只是排队。</p>
<p>具体动作：<strong>数一数这半年谁没被叫去开过会，谁的项目没人接。</strong>那些人里挑一个，去吃顿饭，不谈结盟，只谈事。</p>
<p>「交孚」是双方都得把底交出来。单方面贴上去没用，那叫投靠。</p>
<p>刘邦在汉中那几年，被项羽压得死死的，跟着他的人跑了一批又一批。韩信那时候是个管粮仓的小官，也没人待见。<strong>萧何追了他一晚上，把他追回来。</strong></p>
<p>****这两个人在那之前都很孤单。</p>
<p><strong>什么情况不用找伴：</strong>如果你手上这件事本來就该一个人做完，那孤立不是问题。硬拉个人进来分你的功劳，比一个人干更麻烦。</p>
<h3 id="p-六五-厥宗噬肤-往何咎-那边已经在啃了-你赶紧过">六五 · 厥宗噬肤，往何咎 —— 那边已经在啃了，你赶紧过去</h3>
<blockquote class="pw-quote"><strong>六五：悔亡，厥宗噬肤，往何咎。</strong><br>象曰：厥宗噬肤，往有庆也。</blockquote>
<p><strong>你现在在这个位置：有个跟你分开很久的人，正在向你这边动手——不是打你，是他自己把那层隔膜咬开了。</strong></p>
<p>「厥宗噬肤」——你的同宗在咬那层薄皮。「肤」是柔脆的东西，一咬就破。</p>
<p>这一爻讲的是关系破冰的时机。<strong>隔膜已经被对面咬开了，你别还端着。</strong></p>
<p>很多人卡在这儿。对面先低了头，你反倒不知道怎么办了，因为你已经习惯了对立这个姿势。你怕一松口就显得自己之前错了。</p>
<p>具体怎么做：<strong>对面给你递了话、发了消息、托人带了东西，你当天回。</strong>别拖到第二天再回，拖一天，那层皮又长回去了。</p>
<p>「往何咎」——过去就是了，有什么好怪的。象传还给了一个好词：「往有庆也」，过去有喜事。</p>
<p>廉颇负荆请罪，到蔺相如家门上认错。蔺相如没让他跪多久，两个人当场结成了刎颈之交。<strong>那时候赵国还在，秦国还得掂量着来。</strong></p>
<p><strong>什么情况可以不去：</strong>如果对面只是嘴上说说，没有实际动作，那就不用急。判断标准是看他让出了什么。让出实质的，才是真破冰。</p>
<h3 id="p-上九-见豕负涂-载鬼一车-你把对方想成了鬼">上九 · 见豕负涂，载鬼一车 —— 你把对方想成了鬼</h3>
<blockquote class="pw-quote"><strong>上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。</strong><br>象曰：遇雨之吉，群疑亡也。</blockquote>
<p><strong>你现在在这个位置：你已经把那个人恨到骨头里了。你脑子里全是他的坏，越想越具体。</strong></p>
<p>上九是睽卦最后一爻，也是全卦最精彩的一爻。</p>
<p>你看见一头猪背着一身泥，看见一车鬼。你把弓拉满了，准备射。后来你把弓放下了——那不是贼，是来结亲的。</p>
<p>象传给了四个字，是全卦的钥匙：<strong>「群疑亡也。」</strong>雨一下，所有的猜疑都冲没了。</p>
<p>这一段讲的不是别人，是你自己。<strong>关系坏到最后，坏人不是做出来的，是想出来的。</strong></p>
<p>具体怎么做：<strong>把你对那个人的判断，一条一条写下来，每条后面标上——这是事实，还是我猜的。</strong></p>
<p>你会发现大部分是猜的。你猜他那天那句话是故意的，你猜他背后说了你什么。猜的次数多了，就变成事实了。</p>
<p>然后做一个动作：<strong>找一次机会，让他把话说完整。</strong>不打断，不反驳，听完再走。十有八九你会听到一个你没想到的版本。</p>
<p>周勃被免相回到封地，天天穿着铠甲见郡守，被人告谋反，下了狱。他在狱里被狱吏欺负，出狱之后说了一句：我曾经带过百万兵，可我怎么知道狱吏这么厉害。<strong>后来是薄太后替他说了话，文帝放了他。</strong></p>
<p>****他那些年被想成什么样，不难猜。</p>
<p><strong>什么情况疑心是对的：</strong>如果这个人有前科，而且你的怀疑有具体证据——文件、记录、别人当面的证词——那就不是多疑。这时候你要做的是留证据，不是说服自己大度。</p>
<h3 id="p-最后-分开是常态-合起来要有人先迈一步">最后：分开是常态，合起来要有人先迈一步</h3>
<p>睽卦六个爻，几乎每个都在讲怎么把断开的东西接上。</p>
<p>丢了的不去追，等它自己回来；正式的地方谈不成，换个地方；被孤立了，去找另一个被孤立的；对面咬了那层皮，你当天就回；想成了鬼，就去见一面。</p>
<p>它从头到尾没让你去赢过谁。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">你以为的敌人，多半是你自己想了半年想出来的。去见一面，很多事当场就散了。</blockquote>
  `,
  jian: `
<p>你的项目卡在第三个月。</p>
<p>钱批不下来，关键的那个人调走了，你的上级也说不清下一步该怎么办。你每天上班，做的都是些不痛不痒的事。</p>
<p>你也想过换条路。可你已经投进去一年，团队是你拉起来的，你舍不得。</p>
<p>蹇卦讲的就是这件事：路走不通的时候怎么办。</p>
<p>上坎下艮，山上有水。山本来就难爬，山上还有水，一脚踩下去不知道深浅。</p>
<p>彖传里有一句赞叹，说的是「见险而能止，知矣哉」——<strong>看见危险能停下来，这才叫聪明。</strong></p>
<p>卦辞给的方向也很具体：「利西南，不利东北。」西南平坦，东北险峻。</p>
<p>这一卦六个爻，句式出奇地一致。有五爻都是「往蹇，来……」——<strong>往前走是难，退回来有出路。</strong></p>
<h3 id="p-初六-往蹇-来誉-现在退-别人会夸你">初六 · 往蹇，来誉 —— 现在退，别人会夸你</h3>
<blockquote class="pw-quote"><strong>初六：往蹇，来誉。</strong><br>象曰：往蹇来誉，宜待也。</blockquote>
<p><strong>你现在在这个位置：你刚看出前面不对，但还没投入太多。你正犹豫要不要开始。</strong></p>
<p>初六是蹇卦里最轻松的一爻，也是收益最直接的一爻。</p>
<p>「往蹇，来誉」——往前是坑，退回来还能落个好名声。</p>
<p>为什么退回来会被夸？象传给了答案：<strong>「宜待也」</strong>，这个阶段该等。</p>
<p>你退得早，别人看见的是你能看清形势。你退得晚，别人看见的就是你撞了南墙才回头。</p>
<p>具体动作：<strong>把你正在评估的这件事，定一条明确的否决线。</strong></p>
<p>比如：三个月内拿不到这笔钱就不做。比如：那个关键的人留不住就不做。线先划下来，写下来，告诉自己到点就停。</p>
<p>人最容易在「已经投入这么多」的地方失去判断力。你提前划好线，等到那个点的时候，你只是在执行，不用再做一次艰难的决定。</p>
<p>张良在下邳桥上给那个老人捡鞋，捡了三次，老人叫他五天后来。头两次他都迟到了，被骂回去。第三次他半夜就去等着。</p>
<p><strong>那时候他什么都不是，可他等得住。</strong></p>
<p><strong>什么情况不用等：</strong>如果这件事投入很小，输了也不伤筋骨，那就直接试。等待本身也是有成本的，小成本的试错比等更划算。</p>
<h3 id="p-六二-王臣蹇蹇-匪躬之故-这一趟不为自己">六二 · 王臣蹇蹇，匪躬之故 —— 这一趟不为自己</h3>
<blockquote class="pw-quote"><strong>六二：王臣蹇蹇，匪躬之故。</strong><br>象曰：王臣蹇蹇，终无尤也。</blockquote>
<p><strong>你现在在这个位置：你本来可以抽身，但你没有。因为这件事倒了，会有一批人跟着倒霉。</strong></p>
<p>「蹇蹇」是难上加难。「匪躬之故」——不是你自己的事。</p>
<p>注疏讲得很清楚：六二是九五的臣子，往应于五，去救那个难，「尽忠于君，匪以私身之故而不往济君」。</p>
<p>这一爻讲的是<strong>什么时候该硬扛。</strong></p>
<p>判断它值不值得，只有一条：<strong>你退出去以后，谁替你接这个烂摊子？</strong></p>
<p>如果是一批刚起步的年轻人，或者一个你带了三年的摊子，那你现在扛着是有意义的。扛的不是这个项目，是这些人对你的信任。</p>
<p>具体动作：把这段最难的时间定个期限。<strong>告诉自己「我扛到几月几号」。</strong>不设期限的硬扛会把人耗空，耗空之后再想走，连走的力气都没有了。</p>
<p>再补一条：<strong>把苦劳变成看得见的东西。</strong>每周写一份简短进度发给相关的人。不是诉苦，是留痕。</p>
<p>诸葛亮六出祁山，蜀汉国力早就撑不住了。他自己也知道很难成功，可他还是去。<strong>白帝城托孤那一句，他记了一辈子。</strong></p>
<p><strong>什么情况不用扛：</strong>如果这个摊子垮掉的根因在上面，而且上面毫无改变的意愿，那你扛多久都是白扛。这种情况下降损离场，比悲壮地耗死划算。</p>
<h3 id="p-九三-往蹇-来反-退回来-稳住你的基本盘">九三 · 往蹇，来反 —— 退回来，稳住你的基本盘</h3>
<blockquote class="pw-quote"><strong>九三：往蹇，来反。</strong><br>象曰：往蹇来反，内喜之也。</blockquote>
<p><strong>你现在在这个位置：你已经冲进去一次了，撞得头破血流。你的团队开始有人动摇。</strong></p>
<p>「来反」，就是回来。</p>
<p>九三比初六难。初六是还没进去，退回来很轻松。九三是已经陷进去了，退回来要认错、要交代、要面对那些跟着你的人。</p>
<p>象传给了四个字安慰你：<strong>「内喜之也。」</strong>你回来，里面的人是高兴的。</p>
<p>为什么？因为你回来意味着这个摊子还有主心骨。你把队伍从悬崖边拉回来了。</p>
<p>具体动作：<strong>开一次会，把「不再往前冲」这件事讲明白。</strong>不要含糊，不要让大家猜。人最怕的不是难，是不知道该往哪使劲。</p>
<p>然后立刻做一件事：<strong>把手上现有的资源和人员，收缩到最能守住的那一块。</strong>别平均分配，集中到一处。</p>
<p>刘邦在荥阳、成皋那几年，跟项羽正面打一次输一次。他后来改了打法——正面守，让韩信去北边抄，让彭越在后面捣乱。<strong>他不再想着一次打赢，他先把局面稳住。</strong></p>
<p><strong>什么情况不能退：</strong>如果退一步就会全军覆没——比如退了就违约、就赔不起、就散伙——那只能往前。这时候你的问题是赌注下错了，不是路走错了。</p>
<h3 id="p-六四-往蹇-来连-一个人扛不动-就找人一起扛">六四 · 往蹇，来连 —— 一个人扛不动，就找人一起扛</h3>
<blockquote class="pw-quote"><strong>六四：往蹇，来连。</strong><br>象曰：往蹇来连，当位实也。</blockquote>
<p><strong>你现在在这个位置：你手上有资源，但不够。这件事你自己干不成，必须拉人。</strong></p>
<p>「来连」，回来联合。</p>
<p>注疏里对「连」有两种讲法，一种是「连亦难也」，一种是「迟久之意」。两种都通。</p>
<p>这一爻的关键词是「当位实也」——你回来是有东西可依的，不是空手回来。</p>
<p>具体动作：<strong>把你需要的帮助，拆成几件别人能立刻给的小事。</strong></p>
<p>不要说「请支持我一下」，那句话没人知道该怎么接。要说「你能不能帮我约一下某某」「你们那边那个流程能不能借来用一次」。小事好答应，答应一次就有第二次。</p>
<p>再补一条：<strong>找对人。</strong>不是找最有权的人，是找那个「你这件事办成了对他也有好处」的人。利益一致，比关系好使。</p>
<p>苏秦游说六国合纵，一个人说服不了任何人。他先去燕国，再去赵国，再到韩、魏、齐、楚，一国的国君答应了他才拿着凭证去下一国。<strong>他靠的不是才华，是六份盖了章的合同。</strong></p>
<p><strong>什么情况不用拉人：</strong>如果这件事越少人知道越好，或者拉进来的人会分走关键的控制权，那就别拉。合作是有代价的，算清楚再谈。</p>
<h3 id="p-九五-大蹇-朋来-最大的难关-才是试金石">九五 · 大蹇，朋来 —— 最大的难关，才是试金石</h3>
<blockquote class="pw-quote"><strong>九五：大蹇，朋来。</strong><br>象曰：大蹇朋来，以中节也。</blockquote>
<p><strong>你现在在这个位置：你是主事的人。难的已经不只是事，是所有人都在看你怎么办。</strong></p>
<p>「大蹇」——大难。九五在坎卦正中，是险中之险。</p>
<p>「朋来」——朋友们来了。注疏给的解释是「同志者自远而来」。</p>
<p>这一爻的分量在于：<strong>来的人不是被你叫来的，是你平时攒下的。</strong></p>
<p>象传给了原因，三个字：<strong>「以中节也。」</strong>你平时守中持节，所以人家才来。</p>
<p>这一段你要做的事，是<strong>别在做难的时候变形。</strong></p>
<p>具体是两条。</p>
<p>第一，<strong>别乱许诺。</strong>人在难关里容易开口打包票，承诺一多，兑现不了，人心散得更快。</p>
<p>第二，<strong>把真实的困难告诉大家。</strong>别装。装作没事，下面的人会觉得你不信任他们。</p>
<p>还有一条最要紧：<strong>主动去找那个你不好意思找的人。</strong>你最难的时候还愿意伸手的，往往是你曾经帮过、却早就忘了的人。</p>
<p>唐太宗征高丽，打得很不顺，回来之后很后悔。他手下的将领在安市城下死战，他也是靠这批人撑住的。<strong>他能撑住，是因为这些人信他不会亏待他们。</strong></p>
<p><strong>什么情况人不会来：</strong>如果你平时只跟人谈利益、从不谈交情，那难关的时候就别指望有人来。这不是人心凉薄，这是账目清楚。</p>
<h3 id="p-上六-往蹇-来硕-回头才有结果">上六 · 往蹇，来硕 —— 回头才有结果</h3>
<blockquote class="pw-quote"><strong>上六：往蹇，来硕，吉，利见大人。</strong><br>象曰：往蹇来硕，志在内也。利见大人，以从贵也。</blockquote>
<p><strong>你现在在这个位置：你是这个困局里陷得最深的人，可能也是最先想明白的人。</strong></p>
<p>「来硕」，硕是大。回头，才有大的收获。</p>
<p>上六是蹇卦的终点，也是转折点。注疏说「来则难终，难终则众难皆济」——你一回头，这堆难就到头了。</p>
<p>「志在内也」四个字很关键。你的志向是往里的，往里就是回到内部，回到自己身上。</p>
<p>大象给了这一卦的总纲，也是全卦唯一一句讲怎么做人的话：<strong>「君子以反身修德。」</strong></p>
<p>遇阻先反省自己。</p>
<p>具体动作：<strong>把这次失败的原因列出来，只写你自己那部分。</strong></p>
<p>不写别人怎么坑你，不写环境怎么差。就写哪一步你看错了，哪一句话你不该信，哪个信号你当时忽略了。写完这一页，收起来。</p>
<p>「利见大人」——去请教一个比你有经验的人。不是求他救你，是让他看一遍你的这一页。</p>
<p>秦穆公在崤之战折了三员大将、两万多兵。他没杀孟明视，反而把责任揽在自己身上，说「孤之过也」。<strong>三年之后，孟明视带兵渡河，把晋国打服了，秦国从此转向西边。</strong></p>
<p><strong>什么情况不用反省：</strong>如果这次失败纯粹是运气，或者纯粹是别人恶意使坏，那就别硬往自己身上找原因。过度反省会让人变得畏首畏尾，那不是修德，是自损。</p>
<h3 id="p-最后-山不会给你让路-你只能换个走法">最后：山不会给你让路，你只能换个走法</h3>
<p>蹇卦六个爻，五个都在说「往蹇，来」。</p>
<p>往前是难，回来有出路。这个句式重复了五遍，不是啰嗦，是怕你看不见。</p>
<p>你现在的难，多半不是能力不够，是路选错了。而你舍不得换，因为你在错路上投了太多。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">走不通的路，早一天回来就多一天。撞到血本无归才回头的人，不是坚持，是不会算账。</blockquote>
  `,
  xie: `
<p>危机过了。</p>
<p>上个月差点黄掉的那个单子签了，怒气冲冲要走的那个客户回心转意了，团队里那场差点散伙的架也吵完了。</p>
<p>可你发现自己缓不过来。你还在一遍遍回想是谁在关键时刻没站你这边，还在琢磨要不要把那两个人调走。</p>
<p>解卦讲的就是这件事：难解开了以后，你该怎么收场。</p>
<p>上震下雷，下坎为险。雷雨大作，把积了一冬的闷气一下子放掉了。</p>
<p>彖传写得很好看：「天地解而雷雨作，雷雨作而百果草木皆甲坼。」一声雷、一场雨，草木的壳全裂开了。</p>
<p>卦辞给了两条路：「无所往，其来复吉」——没事就回去过日子；「有攸往，夙吉」——还有事要办，就越早越好。</p>
<h3 id="p-初六-无咎-刚缓过来-别急着搞事">初六 · 无咎 —— 刚缓过来，别急着搞事</h3>
<blockquote class="pw-quote"><strong>初六：无咎。</strong><br>象曰：刚柔之际，义无咎也。</blockquote>
<p><strong>你现在在这个位置：最难的时候刚刚过去。你还在喘气，也还在后怕。</strong></p>
<p>初六的爻辞只有两个字：「无咎。」没有吉，没有凶，就是没事。</p>
<p>这种爻在《周易》里很少见。它什么都不让你做。</p>
<p>注疏说，蹇难刚解的时候，刚强的人不再欺负人，柔弱的人也不至于受害，所以「不虑有咎」。</p>
<p>这个阶段最该干的事只有一件：<strong>什么都别动。</strong></p>
<p>人在紧绷了很久之后，会有一股想立刻重整旗鼓的冲动。你想换人，想改流程，想开一次大会统一思想。这些事本身没错，但时间不对。</p>
<p>你的判断力还没恢复。</p>
<p>具体动作：<strong>给自己三周的缓冲期。</strong>三周内不做任何人事决定，不签任何新的承诺。把这三周用来睡觉、吃饭、把攒下的杂事清一清。</p>
<p>判断标准：<strong>如果你现在做决定的时候，心跳比平时快，那就先不做。</strong>身体比脑子诚实。</p>
<p>汉文帝刚即位那几个月，周勃陈平这些人刚灭完诸吕，朝里一片乱。他没急着动谁，先大赦天下，赏了功臣，把周勃升为右丞相。<strong>等局面稳了，他才慢慢把周勃请回封地。</strong></p>
<p><strong>什么情况不能停：</strong>如果这个「危机解除」只是暂时的，对面正在准备下一轮，那就得趁这个空档补墙。缓冲是为了恢复判断，不是为了放松警惕。</p>
<h3 id="p-九二-田获三狐-得黄矢-该清的-一次清干净">九二 · 田获三狐，得黄矢 —— 该清的，一次清干净</h3>
<blockquote class="pw-quote"><strong>九二：田获三狐，得黄矢，贞吉。</strong><br>象曰：九二贞吉，得中道也。</blockquote>
<p><strong>你现在在这个位置：你已经缓过来了。现在轮到你处理那个制造麻烦的人。</strong></p>
<p>「田获三狐」——打猎打到了三只狐狸。「得黄矢」——还捡到一支黄铜箭。</p>
<p>狐狸是什么？注疏说得很准：「狐是隐伏之物」。躲在暗处、不正面来、专门挑事的那种人。</p>
<p>「三」是成数，意思是<strong>清干净</strong>，不是只抓一个。</p>
<p>这个阶段的动作：<strong>动手，但要动得有依据。</strong></p>
<p>不是凭感觉开人。是把事情一条条摆出来——哪一次他在什么场合说了什么，造成了什么后果。落到纸面上，再谈。</p>
<p>「得黄矢」的黄是中色，矢是直。<strong>处理人的时候要走直道，不走偏门。</strong>不搞突然袭击，不背后放话，当面谈。</p>
<p>具体一条：<strong>处理的时候只谈行为，不谈人品。</strong>说清他做了什么、造成了什么、接下来怎么改。给人留台阶，也给自己留余地。</p>
<p>汉宣帝收拾霍家，从霍光死到霍家被诛，隔了三年。他不是不动，是先把霍家在外面的兵权一个一个换掉。<strong>等到霍家真的动手谋反，他才一击到底。</strong></p>
<p><strong>什么情况可以不动手：</strong>如果那个人只是能力差，不是使坏，那就调岗而不是开人。清狐狸和换驴是两回事。</p>
<h3 id="p-六三-负且乘-致寇至-你德不配位-祸是自己招的">六三 · 负且乘，致寇至 —— 你德不配位，祸是自己招的</h3>
<blockquote class="pw-quote"><strong>六三：负且乘，致寇至，贞吝。</strong><br>象曰：负且乘，亦可丑也。自我致戎，又谁咎也。</blockquote>
<p><strong>你现在在这个位置：你手上拿着超出你身份的东西。可能是钱，可能是权，可能是你撑不起来的一个位子。</strong></p>
<p>「负且乘」——背着财物，还坐在车上招摇。</p>
<p>注疏讲得极狠：乘是君子坐的车，负是小人干的活。一个人背着东西还坐车，强盗一看就知道那东西不是他的，都想来抢。</p>
<p>象传最后六个字是全卦最重的一句：<strong>「自我致戎，又谁咎也。」</strong>祸是你自己招的，怪谁。</p>
<p>这一爻讲的不是道德，是<strong>风险敞口</strong>。</p>
<p>你现在的处境里，有没有一样东西是「别人一看就知道不该是你的」？一个越级的头衔，一笔来路不清的钱，一个你压不住的团队。</p>
<p>具体动作：<strong>把那件最扎眼的东西处理掉。</strong>要么补上与之相配的本事，要么让出去一部分。</p>
<p>再一条：<strong>别在困难刚解决的时候炫耀。</strong>你这个月签了个大单，在群里发了三遍，在饭桌上讲了五次——这些都是在告诉别人，你手上有货。</p>
<p>石崇跟王恺斗富，王恺用糖水刷锅，石崇就用蜡烛当柴烧。斗到最后，石崇被孙秀盯上，抄家灭族。<strong>他招来的那批人，都是他自己请来的。</strong></p>
<p><strong>什么情况可以亮出来：</strong>如果你手上这东西是凭本事挣的，而且亮出来能带来实际的合作机会，那就亮。关键是分清楚哪些是资产，哪些是靶子。</p>
<h3 id="p-九四-解而拇-朋至斯孚-先把那只手甩开">九四 · 解而拇，朋至斯孚 —— 先把那只手甩开</h3>
<blockquote class="pw-quote"><strong>九四：解而拇，朋至斯孚。</strong><br>象曰：解而拇，未当位也。</blockquote>
<p><strong>你现在在这个位置：你身边有一个人或者一件事，一直黏着你。你也知道不对，但就是甩不掉。</strong></p>
<p>「拇」是脚的大拇指。「解而拇」——把大拇指解开。</p>
<p>注疏说得很形象：三从下面附上来，像手指附在脚上。你得先把这个解开，真正的朋友才会来。</p>
<p><strong>这一爻讲的是一种很常见的困局：你身边那个最亲近的人，正在挡掉你所有的机会。</strong></p>
<p>具体怎么判断那个人是不是你的「拇」？三个信号：</p>
<p>一是<strong>别人找你谈事，总要绕开他</strong>；二是<strong>他替你做决定，而且理由都是「为你好」</strong>；三是<strong>你想做的事，他总有办法让它慢下来。</strong></p>
<p>三条里有两条，就是拇。</p>
<p>动作要干脆：<strong>把关系退回公事。</strong>不谈私交，只谈分工、指标、结算。不用撕破脸，把边界画出来就行。</p>
<p>「朋至斯孚」——你这边清干净了，真朋友才会以诚相待。象传还补了一句「未当位也」，你现在的位子本来就不该带这么个人。</p>
<p>范蠡离开越国的时候，给文种留了一封信，说勾践这个人「可与共患难，不可与共乐」。文种没走，后来被赐死。<strong>范蠡把该解的拇解开了，所以他后来在陶地做生意，成了陶朱公。</strong></p>
<p><strong>什么情况不用解：</strong>如果这个人是你创业初期的合伙人，而且他真的出过力，那就不是拇，是骨。骨不能砍，只能重新分工。</p>
<h3 id="p-六五-君子维有解-吉-该示好就示好">六五 · 君子维有解，吉 —— 该示好就示好</h3>
<blockquote class="pw-quote"><strong>六五：君子维有解，吉，有孚于小人。</strong><br>象曰：君子有解，小人退也。</blockquote>
<p><strong>你现在在这个位置：你是那个说了算的人。难解了，现在所有人都看着你怎么分这个果子。</strong></p>
<p>「君子维有解，吉」——君子的解法，是吉的。</p>
<p>「有孚于小人」这句历来有两种读法，一种是小人信服了，一种是君子对小人也讲信用。两种意思都能落地。</p>
<p>这一爻的核心是：<strong>危机之后，你得让人看见你不打算清算。</strong></p>
<p>象传给的是「小人退也」——你用君子的办法处理，那些投机的人自己会退。</p>
<p>具体动作，三条：</p>
<p><strong>一是不扩大打击面。</strong>只处理跟这次危机直接相关的，别借机把平时看不顺眼的人一起收拾。</p>
<p><strong>二是给留下来的人明确的好处。</strong>不用多，要明确。说清这个季度奖金怎么算，说清谁的位置不变。</p>
<p><strong>三是当面跟被你怀疑过的人说一句。</strong>不用道歉，就说一句「这段时间辛苦了」。这句话解开的东西比你想的多。</p>
<p>刘邦封了雍齿。雍齿是最早背叛他的那批人之一，刘邦恨他恨得牙痒。张良说，你封了他，剩下的人就都安心了。</p>
<p><strong>刘邦真封了，那些等着看风向的人当天就不慌了。</strong></p>
<p><strong>什么情况不能这么宽：</strong>如果那个人触碰的是底线——贪了、害了人、背了信——那就不能宽。宽了这种人，守规矩的人会觉得自己是傻子。</p>
<h3 id="p-上六-公用射隼于高墉之上-一箭射掉那个根子">上六 · 公用射隼于高墉之上 —— 一箭射掉那个根子</h3>
<blockquote class="pw-quote"><strong>上六：公用射隼于高墉之上，获之，无不利。</strong><br>象曰：公用射隼，以解悖也。</blockquote>
<p><strong>你现在在这个位置：你已经站到局外了，你看得见全局，也看得见那个真正的祸根在哪。</strong></p>
<p>「公用射隼于高墉之上」——王公站在高墙上，一箭把鹰射下来。</p>
<p>隼是高处的猛禽，站得高、看得远、抓得准。它比喻的是那个最难处理的人——位置高、手腕硬、你抓不住他把柄。</p>
<p>上六说的是：<strong>到了最后一步，该动手就得动手，而且必须一箭中的。</strong></p>
<p>「以解悖也」——解决的是一股悖逆之气。事情到这一步，已经不是谁对谁错，是这股气不除，局面就永远好不了。</p>
<p>具体怎么做：<strong>等他在墙上。</strong></p>
<p>他站在高墙上，是因为他觉得自己安全。你要等的就是他松懈的那一刻——一个他必须露面的场合，一件他必须签字的事。</p>
<p>一动就要有结果。射不中，他下次就再也不上墙了。</p>
<p>刘邦要杀韩信，自己不动手，让萧何去请，吕后在长乐宫钟室办的事。<strong>这件事不体面，可从刘邦的角度看，他等了好几年，等到韩信真的动了心思。</strong></p>
<p><strong>什么情况不要动手：</strong>如果这个人只是嘴上不服，没有实际动作，那就别动。上六这一箭是要见血的，射错了人，你之前所有的宽大都白做了。</p>
<h3 id="p-最后-解卦讲的是收场">最后：解卦讲的是收场</h3>
<p>六个爻，其实在讲两个阶段。</p>
<p>前三个爻讲的是刚缓过来的时候别乱动、该清的要清、别炫耀自己的得手。后三个爻讲的是怎么放手、怎么示好、什么时候一箭到底。</p>
<p>解卦的卦辞里有个词叫「夙吉」——要办的事，越早越好。</p>
<p>一件事拖着不办，成本是滚着往上涨的。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">危机过去之后最危险。清算太多会散人心，一点不清会留祸根，这个度你得自己拿。</blockquote>
  `,
  sun: `
<p>你算过一笔账，算完有点心惊。</p>
<p>去年一年，你借钱给三个朋友，加起来小十万。有两个提都没提过还。你帮同事顶了四次班，加班到半夜的那些活儿，署名都写了别人。</p>
<p>你不是不心疼。可每次开口拒绝之前，你脑子里先冒出来的是「这样会不会显得我很小气」。</p>
<p>损卦讲的就是这件事：什么时候该往外给，给到什么程度。</p>
<p>上艮下兑，山下有泽。泽把自己的水让给山，让山显得更高。</p>
<p>这个卦名听着就不吉利，可卦辞开头两个字是「元吉」——大吉。前提是三个字：<strong>「有孚。」</strong></p>
<p>你得是真心给，不是被逼着给，也不是为了换点什么。</p>
<h3 id="p-初九-已事遄往-酌损之-快去帮忙-但别掏空自己">初九 · 已事遄往，酌损之 —— 快去帮忙，但别掏空自己</h3>
<blockquote class="pw-quote"><strong>初九：已事遄往，无咎，酌损之。</strong><br>象曰：已事遄往，尚合志也。</blockquote>
<p><strong>你现在在这个位置：有人找你帮忙。你能帮，但帮完你自己会紧。</strong></p>
<p>「已事遄往」——自己的事做完了，赶紧过去。「遄」是快。这一爻让你给得痛快。</p>
<p>可后面跟了三个字：<strong>「酌损之。」</strong>酌就是掂量。掂量着减损自己。</p>
<p>这四个字是损卦的总开关。<strong>给是应该的，但要有量。</strong></p>
<p>注疏说这一爻的意思是「尚合志也」——你跟对方志同道合，所以值得跑一趟。</p>
<p>具体怎么做：<strong>给之前先算第二笔账。</strong></p>
<p>第一笔账是「他需要多少」，第二笔是「给完之后我还能不能正常运转」。多数人只算第一笔。算完第二笔你会发现，有些给法会伤到你自己。</p>
<p>举个具体的：朋友借五万，你手上只有六万。那就借两万，实话告诉他你只有这么多。<strong>说清楚数额比硬撑着答应要好。</strong></p>
<p>****硬撑着答应，到了还钱的时候，你比他还难受。</p>
<p>再一条：<strong>帮忙要给期限。</strong>「我这两天帮你弄」和「我帮你弄」是两句话，前者有边界，后者没有。</p>
<p>信陵君窃符救赵，是为了救赵国，也是为了救他姐姐。他做了，可他知道这一下把魏王得罪透了，之后留在赵国十年不敢回去。<strong>他清楚代价，所以才敢动手。</strong></p>
<p><strong>什么情况可以倾囊：</strong>如果这个人是救命的、而且除了你没有别人能帮，那就别算了。人的一生里没几次这样的机会。</p>
<h3 id="p-九二-利贞-征凶-别拿贬低自己去讨好谁">九二 · 利贞，征凶 —— 别拿贬低自己去讨好谁</h3>
<blockquote class="pw-quote"><strong>九二：利贞，征凶。弗损益之。</strong><br>象曰：九二利贞，中以为志也。</blockquote>
<p><strong>你现在在这个位置：有人明里暗里让你「表示表示」。你心里清楚这是在压你，可你觉得低个头事就过去了。</strong></p>
<p>「利贞，征凶」——守正有利，出击有凶。</p>
<p>「弗损益之」四个字是全卦最要紧的一句：<strong>不用减损自己，就是对别人最好的增益。</strong></p>
<p>这句话有点绕，但是真的。</p>
<p>注疏讲得明白：如果九二再往外让，整个卦就变成剥卦了——一层一层被剥光。<strong>让到某个程度，就不是美德，是塌方。</strong></p>
<p>具体动作：<strong>找出你最近一次「为了让别人舒服而故意矮化自己」的行为。</strong></p>
<p>比如明明是你做的，你说「主要是大家的功劳」；明明你有把握，你说「我也就是瞎猜」。这些话第一次说显得谦虚，说多了，别人就真按这个标准判断你了。</p>
<p>改法很简单：<strong>把功劳说清楚，把话说实。</strong>你可以不争，但不能不说。</p>
<p>刘邦问韩信自己能带多少兵，韩信说十万。刘邦问你能带多少，韩信说「臣多多而益善耳」。<strong>他没有为了照顾刘邦的面子往下说。</strong></p>
<p>****他后来因此被猜忌，可那一次他没矮自己。</p>
<p><strong>什么情况可以放低：</strong>如果对方是你的客户、你的长辈，或者这个场合就是需要你退一步，那退就是。但退的是姿态，不是你的判断和价值。</p>
<h3 id="p-六三-三人行-则损一人-人一多-事就散了">六三 · 三人行，则损一人 —— 人一多，事就散了</h3>
<blockquote class="pw-quote"><strong>六三：三人行，则损一人；一人行，则得其友。</strong><br>象曰：一人行，三则疑也。</blockquote>
<p><strong>你现在在这个位置：你想合伙，或者你已经在几个人一起做事了。你隐隐觉得不太对。</strong></p>
<p>这一爻是损卦里最有名的一句。</p>
<p>「三人行，则损一人；一人行，则得其友。」</p>
<p>象传给的理由只有四个字：<strong>「三则疑也。」</strong></p>
<p>三个人在一起，必然有两个人先走得近，第三个人就开始猜。猜来猜去，事就办不成。</p>
<p>注疏里讲得更具体：六三上面有两个阴爻，如果三个人一起走，上面那位就会起疑；一个人走，对方反而放心。</p>
<p>这一爻讲的不是人数，是<strong>关系的结构</strong>。两个人是一条线，三个人是一个三角，三角永远在晃。</p>
<p>具体动作：<strong>如果你现在是三个人合伙，把决策权明确到一个人。</strong></p>
<p>不是让另外两个退出，是说清楚：这件事谁拍板。另外两个人各管一块，各担一块。三个人都拍板，等于没人拍板。</p>
<p>再一条：<strong>别把两个互相不对付的人放进同一个小组。</strong>你以为能调和，实际上你只是给他们造了个战场。</p>
<p>陈平离开项羽投奔刘邦，路上遇到渡船，船夫看他像个有钱人，想劫他。他脱了衣服帮船夫撑船，让人看见他身上没东西。<strong>他一个人走，走脱了。</strong></p>
<p>****他跟着魏王的时候出过主意没人听，跟着项羽的时候也没待住。</p>
<p><strong>什么情况人多更好：</strong>如果是纯粹的出力活、不需要拿主意，那人越多越好。三个人搬砖和三个人分钱是两件完全不同的事。</p>
<h3 id="p-六四-损其疾-使遄有喜-改毛病-越快越好">六四 · 损其疾，使遄有喜 —— 改毛病，越快越好</h3>
<blockquote class="pw-quote"><strong>六四：损其疾，使遄有喜，无咎。</strong><br>象曰：损其疾，亦可喜也。</blockquote>
<p><strong>你现在在这个位置：你自己身上有个老毛病，已经误了几次事。你每次都说下次改。</strong></p>
<p>「损其疾」——把你的病减掉。「使遄有喜」——赶紧的，快了就有喜事。</p>
<p>这一爻讲的减损，对象是你自己。</p>
<p>前面三爻讲的都是给别人让，这一爻突然转向：<strong>你也该减一回，减的是你身上那个常年不改的东西。</strong></p>
<p>这个毛病通常是这么几样：答应得太快、话说得太满、情绪上来就发消息、开会不做记录、账目不清。</p>
<p>具体怎么做：<strong>别改成「我要变得更好」，那太虚。改成一条能检查的动作。</strong></p>
<p>比如你的毛病是话说太满，那就定一条：<strong>任何承诺，说出口之前加一个时间范围。</strong>「我周五下午之前给你」而不是「我尽快」。</p>
<p>比如你的毛病是情绪上来就发消息，那就定一条：<strong>重要的消息，写完存草稿，隔十分钟再发。</strong></p>
<p>给你一条判断线：<strong>如果你这个毛病，已经让同一个人吃过两次亏，那就不是小毛病。</strong></p>
<p>魏征给唐太宗提了两百多次意见，太宗有几次气得说要杀这个乡巴佬。他后来还是忍住了，因为长孙皇后说了一句话——「主明臣直」。<strong>改脾气这件事，太宗做了一辈子。</strong></p>
<p><strong>什么情况不用改：</strong>如果这个「毛病」其实是你的特点，只是有人不喜欢，那就别改。判断标准是它有没有真的造成损失。没有损失，那叫个性。</p>
<h3 id="p-六五-或益之十朋之龟-弗克违-该收的时候要收">六五 · 或益之十朋之龟，弗克违 —— 该收的时候要收</h3>
<blockquote class="pw-quote"><strong>六五：或益之十朋之龟，弗克违，元吉。</strong><br>象曰：六五元吉，自上祐也。</blockquote>
<p><strong>你现在在这个位置：有人主动要给你东西——钱、资源、机会。你第一反应是推。</strong></p>
<p>「或益之十朋之龟」——有人送你价值十朋的大宝龟。朋是古代的货币单位，十朋是很重的一份礼。</p>
<p>「弗克违」三个字是关键：<strong>推不掉。</strong></p>
<p>这一爻讲的是损卦的另一面。前面都在讲怎么给，这一爻突然讲<strong>怎么收。</strong></p>
<p>注疏说，六五「居益用谦」，处在受益的位置还保持着谦冲，所以东西从外面自己来了。</p>
<p>可你要是死命推，就过了。<strong>过分的谦让，是把别人的善意变成了尴尬。</strong></p>
<p>具体动作：<strong>别人诚心给你东西，接住，然后说清你怎么用。</strong></p>
<p>别说「这怎么好意思」，说了三遍还不接，对方会觉得你看不上。接住，说一句「我收下，这件事我这么办」，比推辞十次都体面。</p>
<p>再补一条：<strong>收的时候别附加条件。</strong>对方给你是因为信任，你当场许愿、当场表态站队，那份信任就变味了。</p>
<p>孟尝君被罢相，冯谖替他去薛地收债。冯谖到了那儿，把债券全烧了，回来跟孟尝君说，我给你买了个「义」。孟尝君当时很不高兴。</p>
<p><strong>后来他被罢相回薛地，老百姓扶老携幼来接他，他才明白那笔钱花在了哪儿。</strong></p>
<p><strong>什么情况必须推：</strong>如果这份东西来路不正，或者接受它就意味着你要替对方做不该做的事，那就坚决推掉。推的时候不用找借口，直说就行。</p>
<h3 id="p-上九-弗损益之-得臣无家-让到位了-就不用再让">上九 · 弗损益之，得臣无家 —— 让到位了，就不用再让</h3>
<blockquote class="pw-quote"><strong>上九：弗损益之，无咎，贞吉，利有攸往，得臣无家。</strong><br>象曰：弗损益之，大得志也。</blockquote>
<p><strong>你现在在这个位置：你已经在上面了。你手上有的东西足够了，不用再靠让来换什么。</strong></p>
<p>「弗损益之」跟九二一样，可意思更深了一层。</p>
<p>九二说的是别贬低自己去讨好，上九说的是<strong>你到了这个位置，不减损自己就是对所有人最大的增益。</strong></p>
<p>「得臣无家」——得到的是不把家放在心上、愿意跟你走的臣属。注疏说这是「大得志也」。</p>
<p>这一段讲的是一种状态：<strong>你把自己该做的做到了，剩下的人自然聚过来，你不用再往外掏。</strong></p>
<p>具体动作，两条。</p>
<p>一是<strong>停止无意义的资源输出。</strong>你还在给人好处，可有些人已经不缺这个了。你现在给他们好处，反而是不信任他们。</p>
<p>二是<strong>把标准立起来。</strong>到了这个位置，你留人的方式不是给钱，是让跟着你的人知道规矩是什么、上限在哪儿。</p>
<p>范雎在秦国做相，提出「远交近攻」，帮秦昭王把权力从太后和穰侯手里收回来。<strong>他做的事不是给人好处，是重新定了规矩。</strong></p>
<p><strong>什么情况还得继续让：</strong>如果你这个位子是刚坐上的，下面的人还没认你，那该给的还得给。让位是分阶段的，别提前进入上九。</p>
<h3 id="p-最后-损卦不是让你当好人">最后：损卦不是让你当好人</h3>
<p>它讲的是算账。</p>
<p>该给的时候痛快给，给之前算清楚自己还剩多少。不该给的时候一句不给，不用怕别人说你小气。别人给你的，接住。</p>
<p>自己身上的毛病，趁着还能改赶紧改。</p>
<p>注疏里有一句话说得很好——「损益盈虚，与时偕行。」什么时候该减、减多少，看时机。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">给出去的东西要是从自己身上割的，那不叫大方，叫失血。真的有余力才叫给。</blockquote>
  `,
  yiyi: `
<p>账上趴着一笔钱。不多，但够你干一件想干很久的事。</p>
<p>也可能是另一种富余——你有时间，有人脉，有一个别人进不来的渠道。你已经攥了两年，一直没动。</p>
<p>你反复算过，还是不敢下手。你怕这一动，把现有的也搭进去。</p>
<p>益卦讲的就是这件事：手里有余的时候，往哪儿使。</p>
<p>上巽下震，风雷相激。雷一动，风就跟着起来，风一吹，雷势更猛。两样东西互相往上抬。</p>
<p>损卦是「损下益上」，减下面补上面。益卦正好反过来：<strong>「损上益下。」</strong></p>
<p>彖传给了一句很不寻常的话：「自上下下，其道大光。」——上面的人肯往下走，这条路亮堂得很。</p>
<h3 id="p-初九-利用为大作-元吉-无咎-一开始就干件大的">初九 · 利用为大作，元吉，无咎 —— 一开始就干件大的</h3>
<blockquote class="pw-quote"><strong>初九：利用为大作，元吉，无咎。</strong><br>象曰：元吉无咎，下不厚事也。</blockquote>
<p><strong>你现在在这个位置：你刚拿到一笔资源、一个机会，或者刚被托付了一件要紧的事。</strong></p>
<p>「利用为大作」——正好用来干一件大事。</p>
<p>初九是益卦的第一爻，它一开口就让你干大的，这有点反常。一般第一爻都是让你稳着点。</p>
<p>象传给的理由是「下不厚事也」：你位置低，本来不该老干小事。<strong>机会给到你了，你就把这件大的接住。</strong></p>
<p>但注意前面四个字：<strong>「元吉，无咎。」</strong>要做得非常好，才能免于过错。</p>
<p><strong>这一爻的意思是：大动作可以，但标准得拉到顶。</strong></p>
<p>具体动作：<strong>给这件事定一个你自己觉得有点吃力的标准。</strong></p>
<p>不是「做完」，是「做到什么程度」。不是「上线」，是「上线之后多少人真的在用」。标准定低了，干完也没人记得。</p>
<p>再一条：<strong>别分散。</strong>你现在手上这笔资源，只投一件事。投两件等于两件都投不到位。</p>
<p>商鞅变法，一开始就不是小改。他把户籍、军功、土地、度量衡全动了一遍，一次性推到底。<strong>秦孝公给了他这个权力，他没用来修修补补。</strong></p>
<p><strong>什么情况先干小的：</strong>如果你对这个方向还不确定，那就先拿一小笔试。作大作的前提是你知道往哪儿作。方向不明的时候，大作就是大亏。</p>
<h3 id="p-六二-或益之十朋之龟-有人给你-接着">六二 · 或益之十朋之龟 —— 有人给你，接着</h3>
<blockquote class="pw-quote"><strong>六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。</strong><br>象曰：或益之，自外来也。</blockquote>
<p><strong>你现在在这个位置：你什么都没求，可有人主动来帮你。资源、人、钱，从你想不到的地方来了。</strong></p>
<p>这句爻辞在损卦六五出现过一次，在益卦六二又出现一次。同一个位置——柔顺守中的人。</p>
<p>「或益之」的「或」字很妙，是「有人」的意思，你不知道是谁。</p>
<p>象传说得明白：<strong>「自外来也。」</strong>从外面来的。</p>
<p>这里最容易犯的错是：<strong>你开始琢磨他为什么给我。</strong></p>
<p>想多了你就会怀疑，怀疑了你就推辞，推辞了那份好意就凉了。</p>
<p>具体动作：<strong>接住，然后守正。</strong></p>
<p>「永贞吉」三个字是条件——长期守着中正才吉。<strong>别人给你是因为你是个靠谱的人，你要是拿了东西就变了，那这笔钱就是最后一笔。</strong></p>
<p>再补一条：不要把这份人情立刻还掉。立刻还，是在告诉对方「我不想欠你」。欠着，关系才继续。</p>
<p>周公辅佐成王，管叔、蔡叔在外面造谣说他要篡位。他没辩解，该干什么干什么。<strong>成王后来打开了金滕之书，看见周公当年替武王祈祷愿意替死的祝词，才明白过来。</strong></p>
<p><strong>什么情况要警惕：</strong>如果这份好意来得太突然，而且带着明确的附加条件，那就得看清楚。真诚的帮助给的是东西，不真诚的帮助给的是绳子。</p>
<h3 id="p-六三-益之用凶事-往难处投钱">六三 · 益之用凶事 —— 往难处投钱</h3>
<blockquote class="pw-quote"><strong>六三：益之用凶事，无咎。有孚中行，告公用圭。</strong><br>象曰：益用凶事，固有之也。</blockquote>
<p><strong>你现在在这个位置：你手上有资源，而某个地方正在出事。你在想要不要管。</strong></p>
<p>「益之用凶事」——把增益用在凶险的事情上。</p>
<p>注疏里说得很好：六三这个人本来有毛病，「以阴居阳」，是求好处的那一类。可要是他把力气用在救灾救难上，那就「无咎」。</p>
<p><strong>这一爻讲的是：往最难的地方投钱，反而最安全。</strong></p>
<p>为什么？因为救急这件事，不需要你去解释动机。你帮的是明明白白的难。</p>
<p>具体动作：<strong>把你手上那笔资源的一部分，投到那个正在出问题的环节。</strong></p>
<p>不是投给最赚钱的地方，是投给那个一旦垮掉、会连累所有人的地方。</p>
<p>「告公用圭」——拿着圭去见公。圭是信物。</p>
<p>意思是：<strong>你去帮忙的时候，要带着凭证。</strong>说清楚你要做什么、需要什么支持。</p>
<p>别做无名英雄，无名英雄撑不了多久。</p>
<p>「有孚中行」是条件：心里得真是为了救难，不是为了趁机拿好处。</p>
<p>范仲淹在杭州做知州的时候赶上大饥荒。他没有按常规开仓放粮，反而大办佛事、大兴土木，还鼓励富人家赛龙舟。有人弹劾他，他说，我要的就是让有钱人手上有活干，让穷人有个吃饭的地方。</p>
<p><strong>那一年杭州没出大乱子。</strong></p>
<p><strong>什么情况不用管：</strong>如果那个「凶事」是对方自己作出来的，而且你帮了这一次还有下一次，那就别直接给钱。给方法，给渠道，别给现钱。</p>
<h3 id="p-六四-中行-告公从-利用为依迁国-该搬就搬">六四 · 中行，告公从，利用为依迁国 —— 该搬就搬</h3>
<blockquote class="pw-quote"><strong>六四：中行，告公从，利用为依迁国。</strong><br>象曰：告公从，以益志也。</blockquote>
<p><strong>你现在在这个位置：你知道现在这个地方待不下去了，但搬迁的成本很大。你在硬撑。</strong></p>
<p>「利用为依迁国」——可以依靠着别人搬一次家。</p>
<p>注疏说六四「位虽不中，用中行者也」——位置不算最好，可做事走中道。</p>
<p>「迁国」在古代是大事。盘庚迁殷，周室东迁，都是把整个国家挪个地方。这里说的是：<strong>当你所在的环境已经不能支撑你的时候，挪窝是正解。</strong></p>
<p>具体动作，两步。</p>
<p>第一步，<strong>先找到「依」。</strong>「利用为依」——你得有个可以靠的东西。新的城市、新的平台、新的合作方，先谈拢再动。</p>
<p>第二步，<strong>公开说清楚为什么要搬。</strong>「告公从」——你去报告，上面同意了。搬是大事，含糊着搬，一半人会反对你。</p>
<p>判断标准很简单：<strong>如果留在这里，你未来两年的能力增长是零，那就该搬。</strong>注意是能力增长，不是收入增长。</p>
<p>周太王古公亶父住在豳地，狄人一次次来打。他给狄人送皮币、送狗马、送珠玉，还是被打。最后他说，老百姓跟着我是为了过好日子，不是为了打仗。</p>
<p><strong>他带着人迁到岐山下，一年成邑，三年成都。</strong></p>
<p><strong>什么情况不用搬：</strong>如果问题出在你自己身上，换个地方还是一样。搬之前先问一句：这里发生的事，换个地方会不会重演？</p>
<h3 id="p-九五-有孚惠心-勿问元吉-别问回报">九五 · 有孚惠心，勿问元吉 —— 别问回报</h3>
<blockquote class="pw-quote"><strong>九五：有孚惠心，勿问元吉。有孚惠我德。</strong><br>象曰：有孚惠心，勿问之矣。惠我德，大得志也。</blockquote>
<p><strong>你现在在这个位置：你是给东西的那个人。你已经在做对的事，但你心里还在算这笔投入什么时候能回来。</strong></p>
<p>「有孚惠心」——怀着诚信去惠泽别人。<strong>「勿问元吉」——别问结果，一定大吉。</strong></p>
<p>这四个字是全卦分量最重的一句。<strong>别问。</strong></p>
<p>象传接着说「惠我德」——别人会用诚信回报你的德行。</p>
<p>这一爻不是让你当圣人，是让你别在给的时候想着换。<strong>你一边给一边等回报，给出去了也不痛快，收的人也感觉得到。</strong></p>
<p>具体动作：<strong>挑一件你正在做、但短期看不到回报的事，继续做。</strong></p>
<p>注意，这不是让你当冤大头。前提是这件事本身方向对，只是回报周期长。<strong>方向对的长期投入，跟无底洞是两码事。</strong></p>
<p>再补一条：<strong>给的额度要定下来。</strong>「我每年投这么多在这件事上」，定了就不再加。定量的付出才能持久。</p>
<p>秦穆公的马车丢了，是岐山下三百个乡民把他的马杀了吃掉。官吏要办他们，穆公说，吃马肉不喝酒会伤身，还赐了酒。<strong>几年后秦晋韩原之战，穆公被围，就是这三百人冲出来把他救走的。</strong></p>
<p><strong>什么情况必须问回报：</strong>如果你给的是生意，那当然要问。这一爻讲的是恩义，不是交易。做买卖的时候用这一爻，亏了别怪卦。</p>
<h3 id="p-上九-莫益之-或击之-只拿不给-早晚挨打">上九 · 莫益之，或击之 —— 只拿不给，早晚挨打</h3>
<blockquote class="pw-quote"><strong>上九：莫益之，或击之，立心勿恒，凶。</strong><br>象曰：莫益之，偏辞也。或击之，自外来也。</blockquote>
<p><strong>你现在在这个位置：你在这个位置上待久了，习惯了拿。你已经很久没想过给。</strong></p>
<p>「莫益之」——没人来增益他。「或击之」——还有人要打他。</p>
<p>上九是益卦最后一爻，也是唯一一个直接说「凶」的。</p>
<p>象传给了两个解释，一个说「偏辞也」，意思是他心里只有自己那一头；一个说「自外来也」，攻击是从外面来的。</p>
<p>合起来就是：<strong>你只索取不付出，周围的人就会从合作者变成对手。</strong></p>
<p>「立心勿恒」四个字是全卦最重的诊断——<strong>你的心不定。</strong></p>
<p>你今天靠这个人，明天靠那个人；这件事有利就做，明天没利就丢。这不是精明，这是没根。</p>
<p>具体动作：<strong>回去看看你这个季度拿了多少、给了多少。</strong></p>
<p>如果拿的明显多于给的，那就得调。不是让你立刻大出血，是至少把比例拉平。</p>
<p>再一条：<strong>把一件你已经很久没管、但一直靠你名义撑着的事，要么认真管起来，要么公开放手。</strong>挂着不管，比不管更伤人。</p>
<p>智伯在晋国最强，他向韩、魏、赵三家要地。韩魏给了，赵不给。他就带着韩魏去打赵。</p>
<p><strong>打到晋阳城下，韩魏反戈，跟赵联手把智伯灭了，头骨被漆成饮器。</strong></p>
<p>他只要不给，最后连命都留不住。</p>
<p><strong>什么情况可以继续拿：</strong>如果你拿的这些是为了再分配下去，那你拿得越多越好。上九的问题不在于拿，在于拿了之后不再往下给。</p>
<h3 id="p-最后-益卦是往下的">最后：益卦是往下的</h3>
<p>损卦把力气往上使，益卦把力气往下使。</p>
<p>有意思的是，益卦的卦辞说「利有攸往，利涉大川」——敢走远路，敢过大河。往下给的人反而敢冒险，因为他身后有人。</p>
<p>彖传最后一句是「凡益之道，与时偕行」。给也要看时机，不是越多越好，是越准越好。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">手里攥着东西不放的人，最后攥住的是自己。往下给一点，路就宽一点。</blockquote>
  `,
  guai: `
<p>团队里那个人，所有人都知道他不对。</p>
<p>他占着位子不干活，抢了别人的功劳，背后还传话。你手上的证据足够了，你随时可以摊牌。</p>
<p>可你已经拖了三个月。你怕摊牌之后场面难看，怕他反咬一口，也怕别人说你心狠。</p>
<p>夬卦讲的就是这件事：清除最后一个祸患。</p>
<p>下乾上兑，五个阳爻在下，一个阴爻在最上面。阳气盛到极点，就剩顶上那一个。</p>
<p>「夬」是决断，是决堤。卦辞说「扬于王庭」，要摆到明面上；又说「不利即戎」——<strong>别一上来就动武。</strong></p>
<p>只有一爻的位置了，剩下的全是手法。</p>
<h3 id="p-初九-壮于前趾-往不胜为咎-脚趾头先动-就是输">初九 · 壮于前趾，往不胜为咎 —— 脚趾头先动，就是输</h3>
<blockquote class="pw-quote"><strong>初九：壮于前趾，往不胜为咎。</strong><br>象曰：不胜而往，咎也。</blockquote>
<p><strong>你现在在这个位置：你气到不行，恨不得明天就把这件事捅出去。你觉得对错这么清楚，凭什么还要等。</strong></p>
<p>「壮于前趾」——力气全在脚趾头上，就是憋着一股劲要先迈那一步。</p>
<p>象传给的话很冷淡：<strong>「不胜而往，咎也。」</strong>打不赢还去，就是你的错。</p>
<p>注意，它没说「凶」，说的是「咎」——<strong>这是你自己的过失。</strong></p>
<p>明明是他做错了，为什么最后算你的过失？因为你明知道赢不了还动手，把事情搞砸了。</p>
<p>具体动作：<strong>别急，先做三件事。</strong></p>
<p>一、<strong>把证据从口头变成文字。</strong>聊天记录、邮件、签字文件。有多少收多少。</p>
<p>二、<strong>数人头。</strong>这件事捅出去，会有几个人站你这边？三个以下，先别动。</p>
<p>三、<strong>想清楚你要的结果是什么。</strong>是他走人，还是这件事被纠正？两个目标要的打法不一样。</p>
<p>灌婴和周勃要除掉诸吕，动手之前先做的事是跟陈平握手。他们本来是两拨人，为了这件事合到一块。<strong>他们不是当天冲进去的，是等吕后死了，等吕禄交出兵权之后才动的。</strong></p>
<p><strong>什么情况可以立刻动手：</strong>如果那个人正在做一件马上就要造成不可逆损失的事——比如转移资产、销毁记录——那就不能等。这种情况下出手要快，而且要留好你已经掌握的全部东西。</p>
<h3 id="p-九二-惕号-莫夜有戎-勿恤-把警报拉满">九二 · 惕号，莫夜有戎，勿恤 —— 把警报拉满</h3>
<blockquote class="pw-quote"><strong>九二：惕号，莫夜有戎，勿恤。</strong><br>象曰：有戎勿恤，得中道也。</blockquote>
<p><strong>你现在在这个位置：你已经在准备了。可你心里发虚，总怕对方先动手。</strong></p>
<p>「惕号」——警惕地呼号，把警报拉响。</p>
<p>「莫夜有戎」——半夜可能有人来打你。「勿恤」——不用怕。</p>
<p>注疏说得很明白：九二「体健居中」，能把这件事办成，而且没有疑惑。有人告警说夜里会有兵来，他能判断、能应对，所以不慌。</p>
<p><strong>这一爻讲的不是不怕，是准备好了所以不怕。</strong></p>
<p>具体动作：<strong>假设对方会反扑，把反扑的路径写下来。</strong></p>
<p>他会找谁说话？他会拿哪件事做文章？他手上有没有你的把柄？</p>
<p>一条条写完，每条后面写你的应对。写完你会发现，大部分你已经有准备了，剩下那一两条去补。</p>
<p>判断标准：<strong>如果你现在还是「担心」，那就准备不够；如果你能说出他接下来三步大概怎么走，那就够了。</strong></p>
<p>曹参接替萧何做丞相，什么都不改，全按萧何那一套办。</p>
<p>惠帝问他，他说，你比得上高帝吗？我比得上萧何吗？都比不上，那守着他们的规矩就是了。</p>
<p><strong>他不折腾，所以那几年汉朝没出事。</strong></p>
<p><strong>什么情况不用戒备：</strong>如果你手上这件事证据铁到没人能翻，而且周围人的态度都很明确，那就别把气氛搞得草木皆兵。过度防备本身会让人觉得你有问题。</p>
<h3 id="p-九三-壮于頄-有凶-别把心思写在脸上">九三 · 壮于頄，有凶 —— 别把心思写在脸上</h3>
<blockquote class="pw-quote"><strong>九三：壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。</strong><br>象曰：君子夬夬，终无咎也。</blockquote>
<p><strong>你现在在这个位置：你一看他就来气，你周围的人都看出来了。有人已经开始躲你。</strong></p>
<p>「頄」是颧骨。「壮于頄」——怒气全写在脸上。</p>
<p>象传直接判「有凶」。为什么？因为<strong>你把态度亮出来了，对方就有了防备，中间派也开始怕你。</strong></p>
<p>后面那句是夬卦里最难做到的一段：「独行遇雨，若濡有愠。」</p>
<p>一个人走在雨里，被淋湿了，别人还生你的气。你还是得走。</p>
<p><strong>这一爻讲的是：该做的事，哪怕被误解、被孤立，也得做。但做的时候脸上不能带火。</strong></p>
<p>具体动作：<strong>练一件事——在公开场合对他保持基本礼貌。</strong></p>
<p>打招呼，点头，会上正常对话。这不是虚伪，这是不给自己树敌。你越平静，中间那些人越敢站你这边。</p>
<p>再一条：<strong>别到处跟人说你要办他。</strong>你说得越多，他准备得越充分。</p>
<p>周勃被罢相回到封地，怕被朝廷害，天天穿着铠甲见郡守。结果被人告发谋反，下了狱。他在狱里被狱吏欺辱，出来后感慨狱吏之贵。</p>
<p><strong>他防备得太外露，反而把自己送进去了。</strong></p>
<p><strong>什么情况可以摆脸色：</strong>如果这件事已经到了公开表决的阶段，那立场必须明明白白。这时候还客气，别人会以为你在骑墙。</p>
<h3 id="p-九四-臀无肤-其行次且-你想动-但动不了">九四 · 臀无肤，其行次且 —— 你想动，但动不了</h3>
<blockquote class="pw-quote"><strong>九四：臀无肤，其行次且。牵羊悔亡，闻言不信。</strong><br>象曰：其行次且，位不当也。闻言不信，聪不明也。</blockquote>
<p><strong>你现在在这个位置：你知道该动，可你动不了。你的位置不上不下，你一动就会得罪人。</strong></p>
<p>「臀无肤」——屁股上没肉，坐不住。「其行次且」——走路摇摇晃晃，迈不开步。</p>
<p>这两个比喻合起来就是：<strong>留也不是，走也不是。</strong></p>
<p>「牵羊悔亡」——牵着一只羊就没事了。羊是「抵狠难移之物」，指的是九五一爻。<strong>意思是：跟着那个最强的走。</strong></p>
<p>「闻言不信」是这一爻真正的病根。象传给的话很重：<strong>「聪不明也。」</strong>听到建议不信，这是真的糊涂。</p>
<p>具体动作：<strong>去找那个最有分量的人，问一句「你怎么看」。</strong></p>
<p>你现在缺的不是判断，是有人跟你一起担。九四的问题是自己在那儿耗，耗到最后时机没了。</p>
<p>听他说完，<strong>就算你不完全同意，也先按他的路子走一段。</strong>你现在需要的不是最优解，是有人跟你站在一起。</p>
<p>韩信在楚汉相持的时候，手上有重兵。项羽派人来劝他自立，蒯通也劝他。他犹豫了很久，最后还是站在刘邦这边。</p>
<p><strong>他摇摆的那段时间，两边都在防他。</strong></p>
<p><strong>什么情况可以自己拿主意：</strong>如果你已经看清楚了，而且你手上的人足够多，那就别去问。问来问去会让你显得没主张，反而掉价。</p>
<h3 id="p-九五-苋陆夬夬-中行无咎-下手要轻-但要走中道">九五 · 苋陆夬夬，中行无咎 —— 下手要轻，但要走中道</h3>
<blockquote class="pw-quote"><strong>九五：苋陆夬夬，中行无咎。</strong><br>象曰：中行无咎，中未光也。</blockquote>
<p><strong>你现在在这个位置：你就是那个拍板的人。这件事最后怎么办，你说了算。</strong></p>
<p>「苋陆」是一种柔脆的草，一掐就断。</p>
<p>「苋陆夬夬」——对付这种软东西，要果断。它经不起你反复衡量。</p>
<p>这一爻是夬卦里位置最好的，可象传还是留了一句遗憾：<strong>「中未光也。」</strong>走中道没错，但还不够光明。</p>
<p>意思是：做到了分寸，但没做到让人心服。</p>
<p>具体动作，两条。</p>
<p>一、<strong>处理要干净。</strong>既然确定了，就别拖。今天决定，今天就通知，别留三天让人猜。</p>
<p>二、<strong>给人留退路。</strong>他不干活，你让他走人；但怎么走、走的时候说什么，你可以定得体面一点。<strong>给对手留面子，是给你自己留后路。</strong></p>
<p>再一条：<strong>别搞连坐。</strong>跟他走得近的人，不等于跟他一样。这次只处理他一个。</p>
<p>宋太祖赵匡胤杯酒释兵权，把石守信那批老将的兵权收回来，同时给了他们良田美宅。<strong>他没有杀一个人，那些人也活得很好。</strong>这件事在历史上被反复提起，不是因为他狠，是因为他做得干净。</p>
<p><strong>什么情况不用留退路：</strong>如果这个人做过违法的事，那就交给该管的部门。私下处理反而让你自己脱不了干系。</p>
<h3 id="p-上六-无号-终有凶-到这时候喊也没用了">上六 · 无号，终有凶 —— 到这时候喊也没用了</h3>
<blockquote class="pw-quote"><strong>上六：无号，终有凶。</strong><br>象曰：无号之凶，终不可长也。</blockquote>
<p><strong>你现在在这个位置：你就是顶上那一个。你知道大家都在盯着你，你已经撑不了多久了。</strong></p>
<p>上六是夬卦里唯一的阴爻，就是所有人都要清除的那一个。</p>
<p>「无号」——不用喊了。「终有凶」——结局已经定了。</p>
<p>象传给了四个字：<strong>「终不可长也。」</strong>这样下去长不了。</p>
<p>这一爻是给那个站在顶上的人写的。</p>
<p>如果你现在的位置是这一爻，那么你手里其实只剩一件事可以做：<strong>体面地退。</strong></p>
<p>具体怎么做：</p>
<p>一、<strong>别再拉人下水。</strong>这个时候找人替你挡，找到的都是应付你的。</p>
<p>二、<strong>把手上的东西整理清楚交出去。</strong>你交接得越干净，走的时候越没人再提你的事。</p>
<p>三、<strong>别删东西。</strong>删记录、毁证据，是把自己从「做错了」变成「犯了法」。</p>
<p>智伯向韩魏赵三家要地，韩魏给了，赵不给。他带着韩魏去打赵，把晋阳围了三年。<strong>就在城快破的时候，韩魏两家反戈，跟赵襄子一起把智伯灭了。</strong></p>
<p>****他一直到死都没想明白，那两家为什么会反。</p>
<p><strong>什么情况还有转机：</strong>如果你手上还有别人离不开的东西——一个客户、一项技术、一份人情——那还有谈的余地。这时候主动去谈，比等着被处理强。</p>
<h3 id="p-最后-夬卦讲的是怎么把最后一步走完">最后：夬卦讲的是怎么把最后一步走完</h3>
<p>五个阳爻对付一个阴爻，力量对比悬殊到这个地步，卦辞居然还在讲「孚号有厉」「不利即戎」。</p>
<p>它怕的不是打不过，是打得太难看。</p>
<p>初爻让你别急，二爻让你准备，三爻让你脸上别带火，四爻让你找人一起担，五爻让你下手干净，上爻给那个要退的人留了个提醒。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">清除一个人，赢的不是力气，是时机和分寸。把最后一步走难看的人，前面全白干了。</blockquote>
  `,
  gou: `
<p>去年这个时候，有个合作方塞了个人进来。你当时觉得无所谓，一个岗位而已，给就给了。</p>
<p>三个月前，那个人开始在一些会上替你说话。上个月，你的一个核心客户被转到了他名下。昨天，你听说他要单独拉一个组。</p>
<p>你回头想，那件事在最开始的时候，其实特别好拦。</p>
<p>姤卦讲的就是这件事：不期而遇，以及那些一开始特别小、后来拦不住的隐患。</p>
<p>下巽上乾，天下有风。风一吹，什么东西都能碰上。</p>
<p>卦辞第一句就很不客气：<strong>「女壮，勿用取女。」</strong></p>
<p>一个阴爻刚刚在五个阳爻下面生出来，弱得不能再弱。《周易》对它的态度是：别跟它长期处。</p>
<p>彖传留了半句好话，「天地相遇，品物咸章」——相遇本身有大用。关键在于你怎么应对。</p>
<h3 id="p-初六-系于金柅-贞吉-把它拴住">初六 · 系于金柅，贞吉 —— 把它拴住</h3>
<blockquote class="pw-quote"><strong>初六：系于金柅，贞吉。有攸往，见凶，羸豕孚蹢躅。</strong><br>象曰：系于金柅，柔道牵也。</blockquote>
<p><strong>你现在在这个位置：有一件小事让你心里不太舒服。说大不大，说出去别人可能觉得你小题大做。</strong></p>
<p>「金柅」是金属做的刹车，专门用来让车轮停住。</p>
<p>「系于金柅，贞吉」——<strong>趁它还小，拿刹车把它拴住，就对了。</strong></p>
<p>「有攸往，见凶」——<strong>你要是放任它往前走，凶。</strong></p>
<p>后面那句最传神：「羸豕孚蹢躅。」瘦弱的猪，看着没劲，可它一直在原地躁动，一直想往前走。注疏里说，羸豕是母猪，比公猪弱，可它「淫躁特甚」。</p>
<p><strong>这一爻讲的是：隐患不看体型，看势头。</strong></p>
<p>具体动作：<strong>在它还小的时候，做一次明确的表态。</strong></p>
<p>不用发火，不用上纲上线，就是把边界说清楚。比如那个人的职责范围是什么、什么事必须先经过你。说清楚，落到文字上。</p>
<p>判断标准只有一条：<strong>这件事你现在说，成本有多低？</strong>低就说。拖三个月再说，成本翻十倍。</p>
<p>刘邦进咸阳，诸将都去抢金银财宝，萧何先去把秦朝的律令图书收了起来。<strong>别人都在抢看得见的东西，他抢的是后面几十年要用的东西。</strong>那一下不显眼，可后来刘邦能知道天下户口多少、地形险要，全靠这一手。</p>
<p><strong>什么情况不用管：</strong>如果这件事不涉及你的地盘、你的钱、你的核心关系，那就放着。把所有小事都当信号，人会变得疑神疑鬼，比迟钝更麻烦。</p>
<h3 id="p-九二-包有鱼-无咎-把它包住">九二 · 包有鱼，无咎 —— 把它包住</h3>
<blockquote class="pw-quote"><strong>九二：包有鱼，无咎，不利宾。</strong><br>象曰：包有鱼，义不及宾也。</blockquote>
<p><strong>你现在在这个位置：那个人已经归到你这儿了。他现在在你手上，但也不完全听你的。</strong></p>
<p>「包有鱼」——厨房里有鱼。</p>
<p>注疏说，初六这条鱼本来该归九四，可它自己愿意待在九二的厨下，所以九二「包有鱼，无咎」。</p>
<p><strong>关键在于「不利宾」——别把它拿给别人。</strong></p>
<p>象传给了理由：「义不及宾也。」按道理，它不该给外人。</p>
<p>落到今天：<strong>你已经接手的人或事，就自己攥好，别再转手。</strong></p>
<p>很多人在这儿会犯一个错：因为不喜欢这个人，就把他推给别人带。推出去的那一刻你以为甩掉了，实际上是把手上的牌送给了别人。</p>
<p>具体动作：<strong>把你能控制的东西，逐条过一遍。</strong></p>
<p>哪些人、哪些客户、哪些信息是经过你手的？给它们定一个规矩：什么情况下可以流出去，流出去要经过谁。</p>
<p>再一条：<strong>别急着表态喜欢或不喜欢。</strong>「包」的意思是先装进来，慢慢看。这一爻没让你信任他，也没让你用他。</p>
<p>曹操收张绣，张绣杀过他的儿子和侄子。后来张绣又降，曹操接了，还封了侯。<strong>他不是不记仇，他是算过——收下这个人，比杀了他有用。</strong></p>
<p><strong>什么情况可以放手：</strong>如果这个人或这件事本来就不该归你管，那硬包着是给自己找麻烦。包的前提是你有那个位置和精力。</p>
<h3 id="p-九三-臀无肤-其行次且-你动不了">九三 · 臀无肤，其行次且 —— 你动不了</h3>
<blockquote class="pw-quote"><strong>九三：臀无肤，其行次且，厉，无大咎。</strong><br>象曰：其行次且，行未牵也。</blockquote>
<p><strong>你现在在这个位置：你夹在中间，上面没人接你，下面有个人顶着。你想做什么都推不动。</strong></p>
<p>「臀无肤，其行次且」，跟夬卦九四一模一样的两句。</p>
<p>夬卦九四是「位不当」，姤卦九三是<strong>「乘于二，无阴可据」</strong>——坐在九二上面，可九二不归他，下面没有根基。</p>
<p>这一爻的判词是「厉，无大咎」。有危险，但没有大错。</p>
<p>象传给了四个字：<strong>「行未牵也。」</strong>你走得不顺，但你没有被谁牵住。</p>
<p><strong>这一爻讲的是一种暂时的僵持。这个阶段你最重要的动作就是不犯错。</strong></p>
<p>具体动作：</p>
<p>一、<strong>别越级。</strong>你现在最想干的就是绕过上面那位直接找更高的人，这一步走出去就回不来了。</p>
<p>二、<strong>把你手上的事做扎实。</strong>僵持的时候没人看你的态度，都在看你的活儿。</p>
<p>三、<strong>跟九二保持基本的关系。</strong>你不喜欢他，但你们现在是一条线上的。</p>
<p>韩安国在梁国做官，梁孝王跟汉景帝闹别扭，事情很大。韩安国夹在中间，一边是梁王，一边是朝廷。<strong>他两边跑，两边说好话，最后把这件事平了下来。</strong></p>
<p>****那几年他没什么光彩的事，可他也没出错。</p>
<p><strong>什么情况可以硬闯：</strong>如果上面那位明确要拿你背锅，那就不能僵着。这种情况下你得先把自己摘清楚，该说的话一次说完。</p>
<h3 id="p-九四-包无鱼-起凶-东西没了-才想起要抓">九四 · 包无鱼，起凶 —— 东西没了，才想起要抓</h3>
<blockquote class="pw-quote"><strong>九四：包无鱼，起凶。</strong><br>象曰：无鱼之凶，远民也。</blockquote>
<p><strong>你现在在这个位置：你发现手底下的人不听话了。事情还在你名下，可实际上已经指挥不动。</strong></p>
<p>「包无鱼」——厨房里没鱼了。</p>
<p>九四本来是该管初六的，可初六跑到九二那儿去了。他手上空了。</p>
<p>象传给的原因三个字：<strong>「远民也。」</strong>离下面的人太远了。</p>
<p><strong>这一爻讲的不是别人抢了你的东西，是你自己离得太远。</strong></p>
<p>具体动作：<strong>做一次摸底。</strong></p>
<p>你直接管的那些人，上一次单独谈话是什么时候？他们现在手上的活是什么？他们最近一次遇到麻烦，先找的是谁？</p>
<p>三个问题里有两个答不上来，你手上的鱼已经在往外游了。</p>
<p>再一条：<strong>别靠制度管人。</strong>制度管得住流程，管不住人心。人心是见面聊出来的。</p>
<p>霍光死后，霍家还掌着兵权，看着很稳。可霍家的人从来不跟底下的军官打交道，等到汉宣帝要动他们的时候，没一个人替霍家说话。<strong>离得太远，出事的时候连个报信的人都没有。</strong></p>
<p><strong>什么情况可以松手：</strong>如果你手下的人已经能自立，而且业绩一直好，那你离远一点没问题。这种情况下你的问题是多余的干预，不是疏远。</p>
<h3 id="p-九五-以杞包瓜-含章-用枝叶把瓜包起来">九五 · 以杞包瓜，含章 —— 用枝叶把瓜包起来</h3>
<blockquote class="pw-quote"><strong>九五：以杞包瓜，含章，有陨自天。</strong><br>象曰：九五含章，中正也。有陨自天，志不舍命也。</blockquote>
<p><strong>你现在在这个位置：你是上面那个。你看得见下面那个正在长起来的东西，你也知道压不住。</strong></p>
<p>「以杞包瓜」——杞是高大的树，用它宽大的枝叶把下面的瓜护起来。</p>
<p>这个「包」跟九二的「包」不一样。九二是把它攥在手里，九五是把它护在身下。</p>
<p><strong>「含章」——内里藏着好东西，不急着亮出来。</strong></p>
<p>「有陨自天」——福气从天上掉下来。象传说，是因为他「志不舍命」——心志坚定，不放弃自己的本分。</p>
<p><strong>这一爻是姤卦里境界最高的一爻。它讲的是：面对一个挡不住的势头，最好的办法是把它变成自己的人。</strong></p>
<p>具体动作：</p>
<p>一、<strong>给那个正在长起来的人一个位置。</strong>不是压他，是把他放进来，让他有个正当的名分。</p>
<p>二、<strong>给他资源，但别当众给他。</strong>当众给，别人会觉得你在偏心；私下给，他会记你这份情。</p>
<p>三、<strong>自己别急着出手。</strong>「含章」就是先把本事收着，等到该用的时候。</p>
<p>刘邦封韩信为大将，韩信那时候什么资历都没有。萧何追他回来，刘邦问怎么办，萧何说，你要用他，就得给他真位置。<strong>刘邦真筑了坛，当众拜将。</strong></p>
<p>****这个举动让所有人都吃了一惊，也让韩信从此死心塌地。</p>
<p><strong>什么情况不能包：</strong>如果这个人已经明确在做损害别人的事，那就不能包。护着这样的人，你护住的不是人才，是毒。</p>
<h3 id="p-上九-姤其角-吝-无咎-撞到角上了">上九 · 姤其角，吝，无咎 —— 撞到角上了</h3>
<blockquote class="pw-quote"><strong>上九：姤其角，吝，无咎。</strong><br>象曰：姤其角，上穷吝也。</blockquote>
<p><strong>你现在在这个位置：你是资历最老、位子最高的那个。你已经很久没有新东西进来了。</strong></p>
<p>「姤其角」——碰上了他的角。角是硬的，是顶在最外面的。</p>
<p>象传给了四个字：<strong>「上穷吝也。」</strong>到顶了，所以难看。</p>
<p>这一爻讲的是：<strong>到了最高的位置，你对外界的态度就只剩下硬碰硬了。</strong></p>
<p>新的做法你不想听，新的人你不想用，新的机会你觉得不靠谱。不是这些东西不好，是你已经没有位置让它们进来了。</p>
<p>有意思的是，这一爻最后判的是「无咎」。<strong>它给了个台阶：你没有大错，只是不好看。</strong></p>
<p>具体动作：<strong>这个月见一个比你小十岁、做着你不懂的事的人。</strong></p>
<p>不谈合作，就是听。听他怎么做这件事、靠什么赚钱、怕什么。听的时候别评价，别给建议。</p>
<p>再一条：<strong>在你的地盘上留一块实验田。</strong>给一个年轻人、一件新事、一小笔钱，让他自己折腾。你只看结果。</p>
<p>汉武帝晚年下了轮台诏，说这些年兴兵太苦了天下人，以后不再折腾了。<strong>他早年开边拓土，晚年认了错，转回来休养生息。</strong>一个到顶的人肯回头，才不至于把前面全赔进去。</p>
<p><strong>什么情况可以硬到底：</strong>如果这件事关系到根本原则，或者方向本身就是错的，那就得顶住。角不是不能用，是不能什么都用角。</p>
<h3 id="p-最后-姤卦讲的是那个刚开始的东西">最后：姤卦讲的是那个刚开始的东西</h3>
<p>一阴生于五阳之下，用力量算，它什么都不是。</p>
<p>可《周易》对这个「什么都不是」的东西，给出了整整六爻的应对：拴住、包住、稳住、别离太远、护起来、别用角去顶。</p>
<p>这六条里没有一条是「打」。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">真正出事的东西，从来不是突然冒出来的。它早就在你眼皮底下蹢躅了很久，是你当时没当回事。</blockquote>
  `,
  cui: `
<p>你拉了一个群，四十七个人，名字起得很响亮。头三天热闹，第四天开始只剩你一个人在里面发消息。</p>
<p>半年后你回头看，这个群里真正帮过你忙的，不超过三个。</p>
<p>萃卦讲的就是这件事：<strong>人聚起来了，不等于人心在你这里。</strong></p>
<p>下坤是地，上兑是泽。水在地上面汇成一个湖，这就是「萃」。可水能蓄住，靠的是底下那层土兜得住。土要是漏的，水来多少走多少。</p>
<p>《周易正義》里有一句说得很毒：「聚而无主，不散则乱。」一群人凑在一起，没有主心骨，要么散掉，要么乱掉，没有第三种结局。</p>
<p>我下面按六个位置说。你现在在哪个位置，就先看哪一段。</p>
<h3 id="p-初六-有孚不终-乃乱乃萃-你开始疑神疑鬼">初六 · 有孚不终，乃乱乃萃 —— 你开始疑神疑鬼</h3>
<blockquote class="pw-quote"><strong>初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。</strong><br>象曰：乃乱乃萃，其志乱也。</blockquote>
<p><strong>你现在在这个位置：你刚进一个圈子，本来跟某人说好了，可你发现他跟别人走得更近。你心里开始打鼓。</strong></p>
<p>「有孚不终」——一开始的信任，没能坚持到最后。信任一断，人就乱了，聚也聚得不成样子。</p>
<p>这个阶段的动作只有一个：<strong>别在心里演，直接去问。</strong></p>
<p>问的话要具体，别问「你是不是不打算管我了」，这种问法对方只能回你一句客套。你要问的是：这件事你什么时候给我回话？下周那个会你来不来？</p>
<p>标准是——<strong>你的问题如果能被一句「再看吧」挡回来，那就是你问得不够具体。</strong></p>
<p>爻辞后半句更有意思：「若号，一握为笑，勿恤。」你大声喊一句，别人一把拉住你，笑你太急。别管他。</p>
<p>这里说的是：<strong>求助的时候姿态难看一点没关系，难看的姿态比没有结果的体面值钱。</strong></p>
<p>陈平刚从项羽那边跑过来投刘邦，刘邦跟他聊了一次就给他官做，周勃、灌婴那帮老兄弟不干了，天天在刘邦耳边说陈平收钱、人品不行。陈平没缩着，他直接找刘邦把话说开，刘邦反而更信他。</p>
<p><strong>什么情况可以不动：</strong>如果你只是刚进一个新环境，别人还没认识你，那不必急着要承诺。这时候你去要，要到的也只是敷衍。等你干出过一件具体的事，再开口，那时候的话才有分量。</p>
<h3 id="p-六二-引吉-无咎-孚乃利用禴-等一个人来拉你">六二 · 引吉，无咎，孚乃利用禴 —— 等一个人来拉你</h3>
<blockquote class="pw-quote"><strong>六二：引吉，无咎，孚乃利用禴。</strong><br>象曰：引吉无咎，中未变也。</blockquote>
<p><strong>你现在在这个位置：你本事不差，但你在这个圈子里没有位置。你自己往上凑，凑不进去。</strong></p>
<p>「引吉」——有人拉着你进去，才吉。</p>
<p>萃卦的规矩是「贵相从就」，意思是聚合这件事，讲究的是有人带你。你一个人硬挤，挤进去也是个外人。</p>
<p>六二这一爻的处境在《正義》里说得明白：「志于静退……不欲相从者也。」你本来是不想凑热闹的那种人，可「乖众违时则致危害」，你跟大家不合群，时间长了是要吃亏的。所以需要有人牵一把。</p>
<p>这个阶段给你两条：</p>
<p>一是<strong>盯住那个已经站在圈里的人</strong>。不是让你去巴结他，是让你把一件他正头疼的事做得漂亮，做到他自己想把你拉进去。你干得好，他会主动开口；你只是态度好，他最多请你吃顿饭。</p>
<p>二是<strong>别舍不得花小钱</strong>。「孚乃利用禴」，禴是四季祭里最薄的那一种。诚意到了，用最省的东西也管用。你不用请客送礼搞排场，你要让对方明确知道：我站你这边。</p>
<p>萧何月下追韩信，追回来之后刘邦还是不肯用。萧何说的是：你要争天下，非用他不可。韩信自己一次都没去求过刘邦，是萧何把他引进去的。</p>
<p><strong>什么情况可以自己上：</strong>如果这个圈子本身很松散，没有明确的中心，那就不用等引荐。人聚得散的地方，谁先出声谁就是中心。</p>
<h3 id="p-六三-萃如嗟如-无攸利-你挤在一个不属于你的圈子">六三 · 萃如嗟如，无攸利 —— 你挤在一个不属于你的圈子里</h3>
<blockquote class="pw-quote"><strong>六三：萃如嗟如，无攸利。往无咎，小吝。</strong><br>象曰：往无咎，上巽也。</blockquote>
<p><strong>你现在在这个位置：你在一个局里，可你说不上话。你去了也是坐在角落，不去又怕被落下。你最近经常叹气。</strong></p>
<p>「萃如嗟如」——聚是聚在一起了，可你只有叹气的份。</p>
<p>《正義》把这一爻解释得很直白：「不正相聚，相聚不正，患所生也。」你聚的这个地方，本身就不正。你靠的不是本事进去的，是关系、是凑数、是别人拉你垫个位子。</p>
<p>这种局待下去，只有一个结果：<strong>你的时间被消耗，你的名字被借用，你别无所获。</strong></p>
<p>爻辞给的出路是「往无咎」——走，没错。</p>
<p>这里的「往」不是让你跟人翻脸。是让你把位置挪一挪，挪到一个相互看得上的地方去。象传说「上巽也」，上是柔顺的意思，你走得体面一点，别摔门。</p>
<p>具体动作：<strong>给这个圈子里的关系做一次减法。</strong> 列出里面真正跟你交换过东西的人——帮过你、你帮过、以后还可能互相用的。超过三个算你交情广，三个一下才是常态。剩下的人，不用删好友，但别再投时间。</p>
<p><strong>什么情况不能走：</strong>如果这个圈子是你的饭碗本身——客户在里面，单子在里面——那就不能走。这时候要改的不是位置，是你在里面的角色：找一个他们没人愿意干、但缺了就不转的活，钻进去。</p>
<h3 id="p-九四-大吉-无咎-你的位置是借来的">九四 · 大吉，无咎 —— 你的位置是借来的</h3>
<blockquote class="pw-quote"><strong>九四：大吉，无咎。</strong><br>象曰：大吉无咎，位不当也。</blockquote>
<p><strong>你现在在这个位置：你手里有权，可这个权不是你的名分给你的。是你抢来的、老板临时给的、或者前任留下的。</strong></p>
<p>这一爻只有四个字，可象传补的那句话很扎心：「位不当也。」</p>
<p>《正義》说：「以阳处阴，明履非其位……若以萃之时，立夫大功，获其大吉乃得无咎。」</p>
<p>翻译成白话：<strong>你不占理。你想没事，只有一个办法——立一个足够大的功。</strong></p>
<p>别人的位置是名分撑着的，你的位置是功撑着的。功没了，位置就没了。所以你不能休息，也不能只做维持。</p>
<p>具体要做什么：</p>
<p>- <strong>每三个月交出一个能被人看见的成果。</strong> 不是苦劳，是成果。你做成一件别人做不成的事，所有人都会记得。</p>
<p>- <strong>别在这个位置上讲情面。</strong> 你本来就不占理，再去和稀泥，就没人拿你当回事了。</p>
<p>- <strong>把你做的事留痕。</strong> 关键的事，都要有一份能拿出来的记录。</p>
<p>霍光废了昌邑王刘贺，改立汉宣帝，那时候他手里握着的是废立之权，可他的名分只是个大司马大将军。他靠的是一次次的功，所以他在世时没人敢动他。</p>
<p><strong>什么情况可以缓一口气：</strong>如果你在这个位置上已经稳定干了两年，上下都认你，那说明功已经换成了名分。这时候可以开始讲长期的事，不用再靠一次次的战绩续命。</p>
<h3 id="p-九五-萃有位-无咎-匪孚-元永贞-人来了-心没来">九五 · 萃有位，无咎。匪孚，元永贞 —— 人来了，心没来</h3>
<blockquote class="pw-quote"><strong>九五：萃有位，无咎。匪孚，元永贞，悔亡。</strong><br>象曰：萃有位，志未光也。</blockquote>
<p><strong>你现在在这个位置：你是这个局的头。人都在，会都开，可你心里清楚，真正认你的人不多。</strong></p>
<p>「萃有位」——你有人有事有位置，看起来什么都不缺。</p>
<p>下一句是「匪孚」：人心还没归你。</p>
<p>《正義》说得很冷静：「聚而无主，不散则乱。」位置给你的是发号施令的资格，不是别人心服的理由。</p>
<p>象传四个字，「志未光也」——你的心志还没能照到别人身上。</p>
<p>这个阶段只有一个动作：<strong>元永贞，用时间和守正去补。</strong></p>
<p>不是靠一次讲话，不是靠团建，不是靠加薪。是靠一件一件的事积累出来的信用。人心这东西涨得慢，可一旦涨上去就不容易跌。</p>
<p>落地的三条：</p>
<p>- <strong>答应的事必须兑现，兑现不了要提前说。</strong> 你在上面的一句轻诺，下面会当成制度去执行。</p>
<p>- <strong>出了事你扛，出了功你分。</strong> 顺序不能反。</p>
<p>- <strong>守住那条你自己定的规矩。</strong> 你不守，就再也没人守了。</p>
<p>刘邦进了关中，跟父老约法三章，杀人者死，伤人及盗抵罪，其余秦法全废。他没讲什么大道理，就是把三条最要紧的规矩立住，自己带头守。关中的人心，从那时候开始归他。</p>
<p><strong>什么情况不用等：</strong>如果局面正在往下滑，等你把人心焐热，摊子已经散了。这时候先用强手段把秩序立住，让人心慢慢跟上来。顺序可以颠倒，但两件事都得做。</p>
<h3 id="p-上六-赍咨涕洟-无咎-聚到头-就是散">上六 · 赍咨涕洟，无咎 —— 聚到头，就是散</h3>
<blockquote class="pw-quote"><strong>上六：赍咨涕洟，无咎。</strong><br>象曰：赍咨涕洟，未安上也。</blockquote>
<p><strong>你现在在这个位置：这个局曾经是你张罗起来的，现在它已经不需要你了。你在里面说话，大家客气地点点头。</strong></p>
<p>「赍咨涕洟」——叹气，掉眼泪。</p>
<p>《正義》说这一爻「处极而忧危，思援而求朋」，位置到了顶，心里反而不安。</p>
<p>这一爻给的答案很奇怪：<strong>哭，是可以的。而且哭了才能无咎。</strong></p>
<p>哭在这里不是让你软弱。是说这个阶段的解法，是承认它结束了。</p>
<p>具体怎么承认：</p>
<p>- <strong>把人交出去。</strong> 找到那个能接着张罗的人，当面把关系、把资源、把那几个关键名字，一个一个交给他。交接要当着别人的面，别私下给，否则接的人名不正。</p>
<p>- <strong>别放冷箭。</strong> 你退下来以后对这个局的每一句评论，都会被传回去，而且会被放大。你越有分量，放大得越厉害。</p>
<p>- <strong>留一个不参与的身份。</strong> 顾问、名誉、老朋友，都行。要的是那个「还能回来坐坐」的名分，不是那个位置。</p>
<p>范蠡帮越王勾践灭了吴国，功成之后他没有留下来,他泛舟五湖走了，后来改名陶朱公去做生意。文种没走，留下来继续当相国，勾践赐了他一把剑。</p>
<p><strong>什么情况可以再上一把：</strong>如果你退下来不是因为局势变了，只是因为你累了，那就别退。歇一阵，把手上那个最耗人的活交出去，位置留着。累不是理由。</p>
<h3 id="p-最后-聚散这件事-看的不是人数">最后：聚散这件事，看的不是人数</h3>
<p>你回头看那些散掉的局，散掉的原因几乎都不是钱。</p>
<p>是有人觉得，自己在这个局里，从来没有被当成自己人。</p>
<p>萃卦从头到尾讲的就是这一件事：<strong>聚集靠的从来不是把人拉进来，而是让进来的人在这里找到他的位置。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">你能聚多少人，不看你请了多少顿饭，看有多少人愿意在没好处的时候，还站你这边。</blockquote>
  `,
  sheng: `
<p>有个读者跟我说过一件事。他在一家公司三年，从专员升到总监，中间跳了两级。他说他睡不着。</p>
<p>我问他怕什么。他说：我怕他们发现我其实不行。</p>
<p>升卦讲的就是这件事。<strong>上升本身是好事，可上升得太顺，人容易把自己看错。</strong></p>
<p>下巽是木，上坤是地。树从土里长出来，一天高一点，你看不见它在长,可它一直在长。</p>
<p>大地象里那句话是全卦的总纲：「君子以顺德，积小以高大。」树的长法，就是升卦的升法。</p>
<p>《周易正義》里说得更狠：「纯柔则不能自升，刚亢则物不从。」你太软，升不上去；你太冲，没人跟你走。</p>
<p>我下面按六个位置说。你找一个最像自己的。</p>
<h3 id="p-初六-允升-大吉-先被认可-再往上走">初六 · 允升，大吉 —— 先被认可，再往上走</h3>
<blockquote class="pw-quote"><strong>初六：允升，大吉。</strong><br>象曰：允升大吉，上合志也。</blockquote>
<p><strong>你现在在这个位置：你刚进入一个新环境，或者刚接一个新摊子。你想快点往上走。</strong></p>
<p>「允升」——允是当、是信。被人认可了才升，这才叫大吉。</p>
<p>《正義》讲这一爻讲得很细：巽卦三个爻都想往上走，二三爻上面有应，升得没有疑问。只有初六上面没应，它自己升不了。</p>
<p>那怎么办？<strong>跟着二三一起升。</strong></p>
<p>这不是让你抱大腿。是说在这个阶段，你的上升通道不在你自己手里，在于你能不能跟正在往上走的那批人合上拍。</p>
<p>象传给的标准就四个字：「上合志也。」你跟上面那些人，想法是不是一致。</p>
<p>具体动作：<strong>找到那个正在往上走的人，把他手上最琐碎、最不出彩、但最占时间的那块活接过来。</strong> 不是接他的功，是接他的麻烦。他腾出手去升，你跟着水涨船高。</p>
<p>周勃这个人，早年在沛县就是个吹箫办丧事的。跟着刘邦起兵以后，他不抢头功，专干最硬的活——打硬仗、守要地。刘邦临死前说「安刘氏者必勃也」。别人在争位置的时候，他在攒别人欠他的账。</p>
<p><strong>什么情况别跟着人走：</strong>你跟着的那个人，自己都升不上去，那就赶紧换。判断标准很简单——他在这个位置上待了两年，有没有多拿到过一样新东西？没有，他也在原地打转。</p>
<h3 id="p-九二-孚乃利用禴-无咎-你不需要搞排场">九二 · 孚乃利用禴，无咎 —— 你不需要搞排场</h3>
<blockquote class="pw-quote"><strong>九二：孚乃利用禴，无咎。</strong><br>象曰：九二之孚，有喜也。</blockquote>
<p><strong>你现在在这个位置：你想让上面看见你，可你手上没有预算，也没有人脉。</strong></p>
<p>「孚乃利用禴」。禴是四季祭里最薄的那一种，供品最少。意思是：诚意到了，最简单的形式也管用。</p>
<p>《正義》的解释是：「二体刚德，而履乎中，进不求宠，志在大业，用心如此，乃可荐其省约于神明而无咎也。」</p>
<p>你在这位置上，最忌讳的就是学别人的排场。别人请客你请客，别人送礼你送礼，你用的是自己的钱，人家用的是公司的钱。你打不过。</p>
<p>你在九二能拿出来的，只有一样东西：<strong>你把事做成的事实。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>每做成一件事，留一个能被验证的结果。</strong> 数字、交付物、别人的评价，都行。别只写过程，过程没人看。</p>
<p>- <strong>汇报的时候先说结果，再说过程，最后才说困难。</strong> 你把困难放前面，领导记住的就只有困难。</p>
<p>- <strong>别在嘴上表忠心。</strong> 表一次减一次分。</p>
<p>晏婴做齐国的相，一顿饭不吃两样荤菜，妾不穿丝帛。齐景公要给他换大房子，他不换。他在那个位置上待了三朝，靠的不是排场。</p>
<p><strong>什么情况必须花这个钱：</strong>如果对方的判断标准就是看排场——他只看你带什么来，不听你说什么——那你就得入乡随俗。这时候省下来的不是钱，是机会。</p>
<h3 id="p-九三-升虚邑-你升得太顺了">九三 · 升虚邑 —— 你升得太顺了</h3>
<blockquote class="pw-quote"><strong>九三：升虚邑。</strong><br>象曰：升虚邑，无所疑也。</blockquote>
<p><strong>你现在在这个位置：事情顺得反常。你提什么批什么，推什么成什么。你心里那点紧绷感，最近松了。</strong></p>
<p>「升虚邑」——上升像进了一座空城，没人拦你。</p>
<p>爻辞只有三个字，没有一句吉凶。象传补的是「无所疑也」——你一点疑虑都没有。</p>
<p>这恰恰是这一爻的危险。<strong>《正義》说「升空虚无阻」，可一个位置上升得毫无阻力，往往说明那个位置本来没人要。</strong></p>
<p>空城为什么空？要么是人被打跑了，要么是这地方压根不值得守。</p>
<p>所以九三要做的，不是享受顺风，是查三件事：</p>
<p>一是查<strong>这个位置前任为什么走</strong>。前任是升了、平调了，还是被赶走的。三种情况对应三种风险。</p>
<p>二是查<strong>你的顺，是谁给的</strong>。是一个人给你的，还是机制给你的。一个人给你的，他走了你就没了。</p>
<p>三是查<strong>你最近三个月有没有被拒绝过</strong>。一次都没被拒绝，说明你周围已经没人跟你说真话了。</p>
<p>赵括接替廉颇的时候，赵国上下没有一个人反对，他母亲倒是去跟赵王说了一句：这孩子不能当将。赵王没听。长平之战，四十万赵军。</p>
<p><strong>什么情况可以放心享受顺风：</strong>如果这个位置是你一步一步熬上来的，中间被拒过、被压过、被抢过功劳，那这个顺风是你该得的，安心走。别把正常的好运，也当成不祥之兆。</p>
<h3 id="p-六四-王用亨于岐山-别挡别人的路">六四 · 王用亨于岐山 —— 别挡别人的路</h3>
<blockquote class="pw-quote"><strong>六四：王用亨于岐山，吉，无咎。</strong><br>象曰：王用亨于岐山，顺事也。</blockquote>
<p><strong>你现在在这个位置：你已经到了一个关口，下面有一批人正往上走，而通道正好经过你这里。</strong></p>
<p>「王用亨于岐山」。岐山是周人起家的地方，文王在那里会盟诸侯。这一爻说的是文王在岐山接纳四方来投的人。</p>
<p>《正義》把这一爻的机关说破了：六四处在上升的口子上，下面三爻都想上来，「可纳而不可距」——你能接，不能挡。</p>
<p>象传是「顺事也」——顺着事情本来的样子去做。</p>
<p>具体怎么做：</p>
<p>- <strong>把你能给的机会明确地给出去。</strong> 谁可以升、条件是几条、什么时候评，说清楚。你不说清楚，下面的人只会猜，猜出来的都是你的偏心。</p>
<p>- <strong>别在心里算「他上来会不会盖过我」。</strong> 你这一层最大的价值，就是你是通道，不是闸门。</p>
<p>- <strong>你提上来的人，得是你敢在出事的时候替他说话的人。</strong> 不敢替他说话的，当初就别提。</p>
<p>鲍叔牙跟管仲一起做生意，管仲多分钱，打仗时管仲往后缩，鲍叔牙一次次替他说好话。后来齐桓公要拜相，鲍叔牙把管仲推了上去，自己做了副手。</p>
<p><strong>什么情况必须挡一下：</strong>要上来的人明显会把这个摊子搞砸，就得挡。但要用规矩挡，不用情绪挡——把标准摆出来，让他自己去对。你硬压，压不住，还得罪人。</p>
<h3 id="p-六五-贞吉-升阶-一级一级走上去">六五 · 贞吉，升阶 —— 一级一级走上去</h3>
<blockquote class="pw-quote"><strong>六五：贞吉，升阶。</strong><br>象曰：贞吉升阶，大得志也。</blockquote>
<p><strong>你现在在这个位置：你已经到了很高的位置上。你手上有权力，也有资源，可以一次做成很多事。</strong></p>
<p>「升阶」——顺着台阶一级一级上。</p>
<p>《正義》讲得清楚：「六五以柔居尊位，纳于九二，不自专权，故得贞吉升阶。」</p>
<p>注意「不自专权」四个字。你在最高处，最容易犯的错就是什么都自己拍板。</p>
<p>台阶的意义在于：每一步都踩实了，下一步才站得稳。你跳过两三级往上蹦，蹦上去也是悬着的。</p>
<p>这个阶段的动作有三条：</p>
<p>- <strong>一次只改一件事。</strong> 你想同时改考核、改汇报线、改产品方向，三件事一起动，下面的人会先乱掉。</p>
<p>- <strong>每一步都留出退回来的时间。</strong> 推下去两周看一眼数据，不对就退。别硬扛，扛到最后撤的成本比当初推的成本还高。</p>
<p>- <strong>把最重要的一件事抓在自己手里，别的都放。</strong></p>
<p>周武王伐纣，孟津观兵那一次，八百诸侯不期而会，都说可以打了。武王说不行，还不到时候，退兵回去。又等了两年，纣王杀了比干、囚了箕子，他才出兵，一战而定。</p>
<p><strong>什么情况可以跳级：</strong>机会窗口只开一次，错过就没有了，这时候可以跳。但跳之前你得想清楚两件事——你手里有没有人，你的钱能撑几个月。这两件都没底，跳上去就是摔。</p>
<h3 id="p-上六-冥升-利于不息之贞-停不下来了">上六 · 冥升，利于不息之贞 —— 停不下来了</h3>
<blockquote class="pw-quote"><strong>上六：冥升，利于不息之贞。</strong><br>象曰：冥升在上，消不富也。</blockquote>
<p><strong>你现在在这个位置：你已经升到了顶，可你还想往上。你最近老在看别的机会。</strong></p>
<p>「冥升」——冥是暗。昏暗之中还在往上爬。</p>
<p>《正義》说得不留情面：「若宴升在上，陵物为主，则丧亡斯及。」你到了顶还不肯停，还想着压别人一头，灾祸就来了。</p>
<p>象传四个字更冷：「消不富也。」——你在消耗，而且这种消耗什么都不产生。</p>
<p>上六的解法很别扭：「利于不息之贞」。你停不下来，那就不停，但把那股劲换个方向使——从往上争，改成往下修。</p>
<p>- <strong>把争的心气，转成修自己。</strong> 该补的短板补，该练的身体练。你现在往上争一步，成本高过收益十倍。</p>
<p>- <strong>数一下你还剩多少时间。</strong> 你今年多大，这件事还能干几年。想清楚这个，很多升不升的问题自动有答案。</p>
<p>- <strong>别碰那些需要你亲自下场的烂仗。</strong> 你在这个位置上打的每一仗，都该是最后一仗。</p>
<p>李斯做到秦朝丞相，长子李由做三川郡守，家里办酒席门前的车马有上千。他叹气说，物极则衰，我不知道最后会停在哪儿。后来赵高找他合谋，他还是点了头。他没停下来。</p>
<p><strong>什么情况可以再升一次：</strong>如果你身体好、家里没拖累、这条路你也确实喜欢，那就升。但先把退路铺好——一份能养活自己的手艺、一笔够花两年的钱。有退路的人去争，和没退路的人去争，是两回事。</p>
<h3 id="p-最后-树从来不着急">最后：树从来不着急</h3>
<p>地中生木，你看不见它每天长多少。可十年之后，它比谁都高。</p>
<p>升卦讲的就是这个节奏：<strong>允升，虚邑，升阶，冥升——从被人拉着走，到自己往上走，到停不下来。</strong></p>
<p>四个阶段里，最要命的不是升得慢，是升得没数。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">向上这件事，急着证明的人走不远，心里有数的人走得久。</blockquote>
  `,
  kun4: `
<p>有个做生意的朋友，前年资金链断了。他挨个给以前的合作伙伴打电话。</p>
<p>他说最难受的不是借不到钱。是他说「我下个月就能回款，你再等我二十天」，对面那一声「嗯」。</p>
<p>那一声「嗯」里什么都听不出来。他知道，对面已经不信他了。</p>
<p>困卦讲的就是这一段。<strong>你被困住，而且你越解释，越没人信。</strong></p>
<p>上兑是泽，下坎是水。水漏到泽底下去了，泽里干了。泽没水，就是困。</p>
<p>卦辞里那四个字最冷：「有言不信。」《周易正義》补了一句：「徒尚口说，更致困穷。」你光靠嘴，只会更窘。</p>
<p>我下面按六个位置说。你现在在哪个位置，就先看哪一段。</p>
<h3 id="p-初六-臀困于株木-入于幽谷-三岁不觌-先躲起来">初六 · 臀困于株木，入于幽谷，三岁不觌 —— 先躲起来</h3>
<blockquote class="pw-quote"><strong>初六：臀困于株木，入于幽谷，三岁不觌。</strong><br>象曰：入于幽谷，幽不明也。</blockquote>
<p><strong>你现在在这个位置：你出了事，到处找人说话，可谁都不接你的话。你越说越像在辩解。</strong></p>
<p>「臀困于株木」——屁股坐在一截枯树桩上。坐不住，也没地方去。</p>
<p>「入于幽谷，三岁不觌」——退进深谷里，三年不露面。</p>
<p>这一爻给的答案很反直觉：<strong>困到最底下的时候，该做的是消失。</strong></p>
<p>不是消极。是你现在开口就是减分。你每解释一次，都在提醒别人这件事还没过去。</p>
<p>具体怎么做：</p>
<p>- <strong>把通讯录关一半。</strong> 不是不接电话，是不主动找人。除了必须回的工作消息，别再去跟人聊你的处境。</p>
<p>- <strong>给自己定一个期限。</strong> 《正義》说「困之为道，不过数岁」，困境本身有个头。你自己定一个——一年、两年——在这个期限里，你只干一件事。</p>
<p>- <strong>把嘴上的劲，换成手上的活。</strong> 你现在唯一还能积累的东西，是本事和作品。别的都在贬值。</p>
<p>重耳流亡在外十九年，从狄到卫，从齐到楚，被农夫扔过土块，被曹共公偷看过肋骨。他在齐国待着舒服了，不想走，是身边的人把他灌醉拉上车的。他后来回国做了晋文公。</p>
<p><strong>什么情况不能躲：</strong>如果你身后还有一摊人靠你吃饭，躲就是逃。这时候你要留一个能对外说话的人，自己退到后面做事，但别真消失。</p>
<h3 id="p-九二-困于酒食-朱绂方来-利用亨祀-有吃有喝-也">九二 · 困于酒食，朱绂方来，利用亨祀 —— 有吃有喝，也是困</h3>
<blockquote class="pw-quote"><strong>九二：困于酒食，朱绂方来，利用亨祀，征凶，无咎。</strong><br>象曰：困于酒食，中有庆也。</blockquote>
<p><strong>你现在在这个位置：你的困境不难看。你还有饭吃，还有人来往，甚至还有人给你递橄榄枝。可你就是心里堵。</strong></p>
<p>「困于酒食」——困在酒肉里。这是很特殊的一种困。</p>
<p>《正義》解释得很妙：「处中则不失其宜……物莫不至，不胜丰衍。」</p>
<p>意思是：你这个人有本事、又谦和、又公道，所以东西都往你这儿来。可你接不住，或者你不想接。</p>
<p>象传是「中有庆也」——你心里那点公道，是好事。</p>
<p>这个阶段的动作：<strong>先把来的东西接住，别急着往前冲。</strong></p>
<p>爻辞说得很明确：「朱绂方来……征凶。」朱绂是祭服，好东西正在路上。这时候你要祭、要敬、要等，不能出击。</p>
<p>落地两条：</p>
<p>- <strong>把手上的东西盘清楚。</strong> 你有多少现金、多少人、多少时间。别凭感觉，写下来。</p>
<p>- <strong>别接超出你消化能力的活。</strong> 九二最典型的死法，是被人捧了几句就接下大单，然后砸了。</p>
<p>刘邦进了汉中，被封汉王，地偏人少。他烧了栈道，表示不出来了。萧何替他追人、替他筹粮，他等了一年多才出来。出来的时候，韩信已经练好了兵。</p>
<p><strong>什么情况必须动：</strong>如果守在这儿东西会越来越少——市场在缩、人在走——那就不是守着等，是守着准备。这种情况下不动也是死，你得挑一个成本最低的时候出手。</p>
<h3 id="p-六三-困于石-据于蒺藜-入于其宫-不见其妻-靠错">六三 · 困于石，据于蒺藜，入于其宫，不见其妻 —— 靠错了人</h3>
<blockquote class="pw-quote"><strong>六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。</strong><br>象曰：据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。</blockquote>
<p><strong>你现在在这个位置：你抱住了一个人，以为他能救你。可靠上去才发现，这个人靠不住。</strong></p>
<p>「困于石」——撞上一块石头，又硬又推不动。</p>
<p>「据于蒺藜」——手撑在一丛刺上。</p>
<p>《正義》解得极准：往上附于四，四自己顾不过来；往下靠二，二又是个刚阳，「非己所据」。上面攀不上，下面踩不住。</p>
<p>「入于其宫，不见其妻」——回到自己家里，人也没了。</p>
<p>这一爻是全卦最凶。凶在哪里？凶在你<strong>把命交给了别人。</strong></p>
<p>这一爻只给一条动作：<strong>立刻停止对那个人的指望。</strong></p>
<p>不是让你翻脸，是让你把方案重做一遍，假设这个人不存在。</p>
<p>- 谁还能给你钱？写下来。</p>
<p>- 谁能替你说一句话？写下来。</p>
<p>- 如果这个人都没了，你还能撑几个月？算出来。</p>
<p>第二个问题最要紧。多数人做危机方案的时候，把「有人会替我说句话」算成了资产。那不是资产，那是运气。</p>
<p>楚怀王被张仪用六百里商於之地的空话骗了，绝齐之后去要地，张仪说我说的是六里。怀王发兵，丹阳、蓝田两战皆败，后来被骗进武关，死在秦国。</p>
<p><strong>什么情况可以再赌一次：</strong>如果你是第一次求这个人，他以前没骗过你，那就再试一次。但这次要拿到具体的、可核对的东西——不是承诺，是时间、是金额、是白纸黑字。</p>
<h3 id="p-九四-来徐徐-困于金车-救兵在路上-走得很慢">九四 · 来徐徐，困于金车 —— 救兵在路上，走得很慢</h3>
<blockquote class="pw-quote"><strong>九四：来徐徐，困于金车，吝，有终。</strong><br>象曰：来徐徐，志在下也。虽不当位，有与也。</blockquote>
<p><strong>你现在在这个位置：你已经答应帮一个人，但你自己也被卡着。你想快，快不了。</strong></p>
<p>「来徐徐」——慢吞吞地来。</p>
<p>「困于金车」——被一辆财势的车挡住了。</p>
<p>《正義》说是「有应于初而碍于九二」。你想去救初六，可中间隔着九二。</p>
<p><strong>你成了别人唯一的希望，可你自己也动不了。</strong> 你想解释，可解释听起来都是推脱。</p>
<p>「吝，有终」——难看，但最后有个结果。</p>
<p>这个阶段要做的，就是<strong>把「慢慢来」变成一个可预期的进度。</strong></p>
<p>- <strong>给对方一个明确的时间点，而不是一个态度。</strong> 说「我在办」等于没说，说「下周三之前落定」才有用。</p>
<p>- <strong>中途主动同步两次。</strong> 人在等的时候最怕不知道你在不在动。</p>
<p>- <strong>别硬闯。</strong> 绕着走，别去撞那辆车。你撞上去，你自己也翻。</p>
<p>信陵君窃符救赵，这件事他谋划了很久。他先去找侯嬴，侯嬴没给他办法，让他自己去想；他又去找如姬，如姬替他把兵符偷了出来。每一步都慢，但每一步都踩到了实处。</p>
<p><strong>什么情况可以加速：</strong>如果对方已经到了最后关头，慢就等于没救，那就别走正门。绕过中间那层，直接找能拍板的人。这时候的关键不是体面，是能不能在时间内把事办成。</p>
<h3 id="p-九五-劓刖-困于赤绂-乃徐有说-被削了-还能缓过">九五 · 劓刖，困于赤绂，乃徐有说 —— 被削了，还能缓过来</h3>
<blockquote class="pw-quote"><strong>九五：劓刖，困于赤绂，乃徐有说，利用祭祀。</strong><br>象曰：劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。</blockquote>
<p><strong>你现在在这个位置：你在一个很高的位置上受挫。可能是被削权、被架空、被公开处理。面子伤得很重。</strong></p>
<p>「劓刖」是古代的两种刑罚，割鼻和断足。用在这里，是说自己被伤得很难看。</p>
<p>「困于赤绂」——被这身官服困住了。你越是站在那个位置上，越下不来台。</p>
<p>这一爻的关键在三个字：<strong>「乃徐有说」。</strong> 说通脱，慢慢会解脱出来。</p>
<p>象传补的是「以中直也」——你立身正，慢慢就能缓过来。</p>
<p>这个阶段做的事，都是修复：</p>
<p>- <strong>把事情说清楚，一遍就够。</strong> 交代、复盘、认账，讲完就完了。反复讲就成了诉苦。</p>
<p>- <strong>把精力挪到具体的事上。</strong> 你在高位受挫以后，最容易陷在「谁害了我」里。这个念头一出来，你自己就完了。</p>
<p>- <strong>把关系重新捋一遍。</strong> 这时候还愿意跟你打交道的人，是真好。列个名单，一个一个记住。</p>
<p>勾践在夫椒战败，带着五千人退到会稽山上，向吴国请降。他去吴国做马前卒，给夫差牵马、尝粪。回国以后卧薪尝胆，十年生聚，十年教训。二十年后灭吴。</p>
<p><strong>什么情况不用等：</strong>如果这次受挫是因为规则本身不公，不是你做错了事，那就别在这儿等着慢慢好。换个地方，从零开始，比在这儿修复快得多。</p>
<h3 id="p-上六-困于葛藟-于臲卼-曰动悔-有悔-征吉-动一">上六 · 困于葛藟，于臲卼，曰动悔，有悔，征吉 —— 动一下就后悔，那也动</h3>
<blockquote class="pw-quote"><strong>上六：困于葛藟，于臲卼，曰动悔，有悔，征吉。</strong><br>象曰：困于葛藟，未当也。动悔有悔，吉行也。</blockquote>
<p><strong>你现在在这个位置：你已经困到极点了。你什么都试过了，现在连动都不敢动——因为你一动，就会后悔。</strong></p>
<p>「困于葛藟」——被藤蔓缠住了。越挣越紧。</p>
<p>「于臲卼」——摇摇晃晃，站不稳。</p>
<p>这一爻给了全卦唯一的出路：「曰动悔，有悔，征吉。」</p>
<p>翻译一遍：你心里说，动一下就会后悔。可你已经后悔了。那就走。</p>
<p>象传讲得更透：「动悔有悔，吉行也。」<strong>你不动也在后悔，那就没有可损失的了。</strong></p>
<p>上六的动作：</p>
<p>- <strong>停止计算风险。</strong> 你现在算出来的每个结果都是坏的，算下去只会更不敢动。</p>
<p>- <strong>挑一个最小的动作先做。</strong> 打一个电话、发一条消息、把一个方案写完。不需要是决定性的一步，只需要是一步。</p>
<p>- <strong>找一个 deadline。</strong> 给自己定一个日子，到那天无论如何都要动。困到最后的人，缺的不是办法，是期限。</p>
<p>伍子胥过昭关，一夜白头。他带着太子建的儿子胜一路逃，到了吴国，在市井里吹箫讨饭，后来被公子光收用。他做的第一件事不是报仇，是先活下来，先找到一个能用他的人。</p>
<p><strong>什么情况忍过这一关：</strong>如果你判断转机在几周之内就会来——比如一笔钱、一个消息、一个决定——那就忍这几周。上六的「征」，是把最后的力气用在最后的一步上，不是用来发泄的。</p>
<h3 id="p-最后-困是用来认人的">最后：困是用来认人的</h3>
<p>你顺的时候，围在你身边的人你分不清。</p>
<p>困这一卦，做的事就是把水分挤掉。</p>
<p><strong>它让你看清两件事：哪个人的话是算数的，以及哪件事是真值得干的。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">困住你的从来不是那件事，是你还指望那个不会来的人。</blockquote>
  `,
  jing: `
<p>一个技术很硬的人跟我说：我把东西做到这个程度了，为什么还是没人用。</p>
<p>我看了一眼他做的东西。确实好。好到只有他自己知道好在哪。</p>
<p>井卦讲的就是这件事。<strong>井水再好，打不上来，跟没有一样。</strong></p>
<p>下巽是木，上坎是水。木入于水，把水提上来，这就是井。</p>
<p>卦辞里有几句话，是全卦最值钱的部分：「改邑不改井，无丧无得，往来井井。」</p>
<p>村子搬了，井不动。你天天打，它不少；你一年不打，它也不多。人来人往，井还是那个井。</p>
<p>《周易正義》里补了一句，把这一卦的赌注说清楚了：「汲水未出而覆，喻修德未成而止，所以致凶。」</p>
<p><strong>水没提出井口，就不算数。</strong></p>
<p>我下面按六个位置说。你找一个最像自己的。</p>
<h3 id="p-初六-井泥不食-旧井无禽-你先把自己荒了">初六 · 井泥不食，旧井无禽 —— 你先把自己荒了</h3>
<blockquote class="pw-quote"><strong>初六：井泥不食，旧井无禽。</strong><br>象曰：井泥不食，下也。旧井无禽，时舍也。</blockquote>
<p><strong>你现在在这个位置：你手上那点本事，是好几年前的了。你自己也知道，但一直没动。</strong></p>
<p>「井泥不食」——井底淤住了，打上来的水是浑的，不能喝。</p>
<p>「旧井无禽」——时间长了，连鸟都不来了。</p>
<p>《正義》说得不留情：「久井不见渫治，禽所不向，而况人乎？」</p>
<p>象传那三个字更狠：「时舍也。」——时代把你放下了。</p>
<p>这一爻的动作只有一个：<strong>重新淘井。</strong></p>
<p>淘井的意思是，把你吃饭的那门手艺，从头到尾过一遍。不是学新东西，是先把旧东西修好。</p>
<p>具体三条：</p>
<p>- <strong>把你这门手艺里，你三年前会、现在生疏的部分，列出来，一周之内补回去。</strong></p>
<p>- <strong>找一次真刀真枪的检验。</strong> 接一个具体的活，交付出去，看别人怎么评价。自己觉得自己行，不算。</p>
<p>- <strong>别急着学新的。</strong> 井底没清干净，灌什么进去都是泥。</p>
<p>苏秦第一次出去游说秦王，书上了十次，秦王不用他。他钱花光了，回家的时候「妻不下纴，嫂不为炊，父母不与言」。他没去怪家里人，他把箱子里那本《阴符》拿出来，读了一年。第二年出去，佩六国相印。</p>
<p><strong>什么情况可以另挖一口井：</strong>如果你原来那门手艺整个行业都没了——不是你不熟练，是这个行当不存在了——那就别淘了，另找地方挖。判断标准：这个行当里，最近两年有没有新人靠它赚到钱。</p>
<h3 id="p-九二-井谷射鲋-瓮敝漏-你的本事只够打几条小鱼">九二 · 井谷射鲋，瓮敝漏 —— 你的本事只够打几条小鱼</h3>
<blockquote class="pw-quote"><strong>九二：井谷射鲋，瓮敝漏。</strong><br>象曰：井谷射鲋，无与也。</blockquote>
<p><strong>你现在在这个位置：你能干活，你也确实在干。可你干出来的东西，只在一个很小的范围里打转。</strong></p>
<p>「井谷射鲋」——井水往下流，只能射到几条小鱼。鲋是鲫鱼，很小的鱼。</p>
<p>「瓮敝漏」——打水的坛子还是破的，边打边漏。</p>
<p>《正義》解这一爻：「井既处下，宜应汲上。今反养下，则不与之交，物莫之与。」</p>
<p>你把这口井的水，全浇在自己脚边了。</p>
<p>这一爻给的判词是「无与也」——没人跟你来往了。不是别人不搭理你，是你的产出跟别人的需求对不上。</p>
<p>具体怎么做：</p>
<p>- <strong>先修那个破坛子。</strong> 你交付的方式有没有问题？是不是每次都延期、每次都要别人催？这些看着是小事，可它们决定了别人愿不愿意再用你。</p>
<p>- <strong>把水往上引。</strong> 你现在做的东西，谁在用它？它的下一层用户是谁？你能不能直接对接那个人？</p>
<p>- <strong>看清楚「小鱼」长什么样。</strong> 你现在服务的对象，如果一年给你带来的东西不超过一顿饭钱，那就该换了。</p>
<p>李广一辈子打了七十多仗，匈奴人叫他飞将军，可他到死没封侯。他带兵靠个人勇武，文书报功总是对不上。他的水，一直浇在自己的勇名上。</p>
<p><strong>什么情况可以继续往下浇：</strong>如果下面那群「小鱼」正在长大——今年是几条，明年可能是一群——那你就继续浇。押注未来比换赛道便宜。</p>
<h3 id="p-九三-井渫不食-为我心恻-你把自己修好了-没人来">九三 · 井渫不食，为我心恻 —— 你把自己修好了，没人来用</h3>
<blockquote class="pw-quote"><strong>九三：井渫不食，为我心恻。可用汲，王明，并受其福。</strong><br>象曰：井渫不食，行恻也。求王明，受福也。</blockquote>
<p><strong>你现在在这个位置：你已经把自己修好了。你东西做到了，能力补上了。可还是没人来。</strong></p>
<p>「井渫不食」——井淘干净了，水清了，可没人喝。</p>
<p>「为我心恻」——路过的人看了都替你难受。</p>
<p>这四个字很毒。它说的不是「你惨」，是「你明明可以，就是没人给你机会」。</p>
<p>《正義》说：「井之可汲，犹人可用。若不遇明王，则滞其才用。」</p>
<p>你被卡住的原因不在你身上，在于<strong>没有一个识货的人。</strong></p>
<p>这一爻的动作，是这一卦里最关键的：</p>
<p><strong>去找到那个「王」，不是等那个「王」。</strong></p>
<p>- <strong>你不需要让所有人知道你。</strong> 你只需要让三个人知道。列出三个「如果他说我行，别人就会认」的人。</p>
<p>- <strong>给他们看结果，不是看过程。</strong> 你不要讲多辛苦，你给他一个能立刻判断好坏的东西。</p>
<p>- <strong>被拒绝之后要问原因。</strong> 多数人不问，被拒了就回去继续淘井。问一句「差在哪」，答案往往值一年。</p>
<p>百里奚是虞国的大夫，虞国亡了，他被俘做了奴隶，秦穆公用五张黑羊皮把他换回来。那时候他已经七十多岁。他见秦穆公，谈了三天，穆公拜他为相。</p>
<p><strong>什么情况不用找人：</strong>如果你的东西是卖给一群人的，不是卖给一个关键人物的，那就别去找「王」。把东西直接摆到人最多的地方去，让买家自己来判断。</p>
<h3 id="p-六四-井甃-无咎-修井壁-不是修水">六四 · 井甃，无咎 —— 修井壁，不是修水</h3>
<blockquote class="pw-quote"><strong>六四：井甃，无咎。</strong><br>象曰：井甃无咎，修井也。</blockquote>
<p><strong>你现在在这个位置：你的方向是对的，可最近老出岔子。不是大错，都是些渗水的小洞。</strong></p>
<p>「井甃」——用砖石把井壁砌起来。</p>
<p>注意：这一爻修的不是水，是井壁。水本身没问题。</p>
<p>《正義》说：「修井也。」就这么一句。</p>
<p>这一爻讲的是<strong>把基础工程做扎实。</strong></p>
<p>你的能力是水，你的流程、工具、习惯、身体，是井壁。井壁渗漏，水再多也存不住。</p>
<p>具体的四条，你现在就检查：</p>
<p>- <strong>钱：</strong> 你手上现金能撑几个月？你有没有一笔专门不动的钱？</p>
<p>- <strong>时间：</strong> 你每天有多少小时是真正在产出，多少小时在处理杂事？</p>
<p>- <strong>身体：</strong> 你最近一年体检了吗？你睡够了吗？</p>
<p>- <strong>文档：</strong> 你的东西，别人接手得了吗？</p>
<p>这四条里，任何一条没有答案，你就是一口漏井。</p>
<p>范仲淹在应天书院读书的时候，每天煮一锅粥，凉了划成四块，早晚各吃两块，就着咸菜。他不光是省，是在给自己砌井壁——把生活压到最简单的结构上，让所有的水都流向一处。</p>
<p><strong>什么情况不用这么抠：</strong>如果你的产出完全靠灵感、靠爆发，把什么都规矩化反而把你掐死了，那就别砌这么严实。但至少要留一样结构——比如固定的交付时间。</p>
<h3 id="p-九五-井洌-寒泉食-水清到能喝">九五 · 井洌，寒泉食 —— 水清到能喝</h3>
<blockquote class="pw-quote"><strong>九五：井洌，寒泉食。</strong><br>象曰：寒泉之食，中正也。</blockquote>
<p><strong>你现在在这个位置：你的东西被人认可了。有人主动来找你，而且用完之后还会再来。</strong></p>
<p>「井洌，寒泉食」——井水清冽，甘泉可以直接喝。</p>
<p>象传是「中正也」。你的东西好，而且好得正。</p>
<p>这一爻最危险的，不是做不好，是<strong>做得好之后的两种走法。</strong></p>
<p>第一种，你开始省力。反正人家认，你用老一套应付，水会慢慢变浑。</p>
<p>第二种，你开始摆谱。你让人来求你，你才有面子。可井从来不为打水的人设门槛。</p>
<p>这个阶段的三条：</p>
<p>- <strong>保持那个清的标准。</strong> 你自己心里有一条线，是「这个程度我可以交出去」。线不能往下移。</p>
<p>- <strong>别涨价涨到离谱。</strong> 你值多少钱，是你的产出说的，不是你的姿态说的。</p>
<p>- <strong>开始教人。</strong> 你一个人打水，一天就那么多。你教会三个人打水，这口井的价值翻三倍。</p>
<p>诸葛亮在隆中待了十年，出山之后从军师中郎将做到丞相，还写了《便宜十六策》给下面的人。他不是一个人扛，他把方法写下来给别人用。</p>
<p><strong>什么情况可以歇一歇：</strong>如果你已经连着几年高强度输出，井水开始泛浑了，那就停一停。井不下雨也满，因为它有源头。你的源头是什么，隔一阵得回去看看。</p>
<h3 id="p-上六-井收勿幕-有孚元吉-别盖井盖">上六 · 井收勿幕，有孚元吉 —— 别盖井盖</h3>
<blockquote class="pw-quote"><strong>上六：井收勿幕，有孚元吉。</strong><br>象曰：元吉在上，大成也。</blockquote>
<p><strong>你现在在这个位置：你已经有东西了。你的东西成了，你的名字有人认了。</strong></p>
<p>「井收勿幕」——水打上来了，别给井盖个盖子。</p>
<p>《正義》说这是「大成也」。井这件事做到最后，就是<strong>把盖子拿掉。</strong></p>
<p>你想想那个画面。一口井，水又好，就在那儿敞着，谁来都能打。它有门槛吗？没有。它需要别人捧着吗？不需要。</p>
<p>这就是这一爻的全部意思：<strong>你成了之后，唯一该做的是拆掉门槛。</strong></p>
<p>落地的三条：</p>
<p>- <strong>把你的方法写出来。</strong> 免费的，公开的。你藏着那点东西，藏着藏着就旧了。</p>
<p>- <strong>别在帮人的时候算账。</strong> 你帮过一百个人，记住你的人可能就三个。但那三个，比一百次精打细算值钱。</p>
<p>- <strong>别设身份门槛。</strong> 「你得先证明你够格我才教你」——这句话一出来，你就给自己盖了个井盖。</p>
<p>孔子办学，束脩以上，吾未尝无诲焉。一束干肉就能来听。他没有筛选学生的家世，所以他的东西传了两千多年。</p>
<p><strong>什么情况必须盖盖子：</strong>两种。一是这东西用错了会伤人——安全、法律、医疗这类，不能谁来了都给。二是别人拿你的东西去害人，那你得收着。盖盖子不是护食，是对后果负责。</p>
<h3 id="p-最后-井的好处-在于它一直在这儿">最后：井的好处，在于它一直在这儿</h3>
<p>你回头看那些真正被人记住的人，往往不是最强的那个。</p>
<p>是那种你什么时候去找他，他都在；你什么时候要，他都拿得出来的人。</p>
<p>井卦讲的其实就是这一件事：<strong>你的价值不在你今天有多高，在你是不是一直都在。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">井不因为人来得少就变浅，你也不该因为没人看见就荒了自己。</blockquote>
  `,
  ge: `
<p>一个朋友接了家公司，进去第一周就发现流程烂得不行。</p>
<p>他花了两周做方案，第三周开会宣布，二十条一起改。第四周，三个老员工递了辞呈。</p>
<p>他改错了吗？他改的那些，确实都该改。他错在<strong>改的时间不对，改的量不对。</strong></p>
<p>革卦讲的就是这个。上兑是泽，下离是火。火在水底下烧，水在上面，两个东西互相克，非要变一个出来。</p>
<p>卦辞开头四个字是「己日乃孚」。己日不是第一天，是过了些日子以后。<strong>《周易正義》说得很白：「即日不孚，己日乃孚。」当天没人信你，过一段才有人信。</strong></p>
<p>这句话是全卦的总纲。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-巩用黄牛之革-现在什么都别动">初九 · 巩用黄牛之革 —— 现在什么都别动</h3>
<blockquote class="pw-quote"><strong>初九：巩用黄牛之革。</strong><br>象曰：巩用黄牛，不可以有为也。</blockquote>
<p><strong>你现在在这个位置：你刚到一个新的地方，或者你刚发现一个必须改的问题。你心里很急。</strong></p>
<p>「巩用黄牛之革」——用黄牛的皮把自己捆起来。</p>
<p>牛皮是最韧的东西，捆上就挣不开。《正義》说这一爻是「守夫常中，未能应变……未肯造次以从变者也」。</p>
<p>象传给了一句斩钉截铁的话：「不可以有为也。」</p>
<p>不是不宜，是不可以。</p>
<p>这个阶段的动作，就一件事：<strong>看清，别动。</strong></p>
<p>具体三条：</p>
<p>- <strong>头三个月，只做记录，不做决定。</strong> 你发现的问题，一条一条写在本子上。写满一页，你再看一遍，会发现有一半是你没看懂。</p>
<p>- <strong>找出这件事现在为什么这么运转。</strong> 一个烂流程能活下来，通常是因为它在替某个人兜底。你砍掉流程，等于砍掉那个人的安全感。</p>
<p>- <strong>建立最小信任。</strong> 找三个关键的人，各吃一次饭。不谈改什么，只问他们最烦什么。</p>
<p>商鞅到秦国，先见秦孝公。前两次他讲帝道、王道，孝公听得打瞌睡。第三次他讲霸道，孝公「语数日不厌」。他没有一开始就把最狠的方案甩出来，他先试出了孝公要什么。</p>
<p><strong>什么情况必须立刻动：</strong>如果这件事再过一个月就要出大事——合规、安全、资金断链——那捆牛的绳子就得解开。这时候你要做的不是说服所有人，是保住最要紧的那一块。</p>
<h3 id="p-六二-己日乃革之-征吉-无咎-等到了-就别再等">六二 · 己日乃革之，征吉，无咎 —— 等到了，就别再等</h3>
<blockquote class="pw-quote"><strong>六二：己日乃革之，征吉，无咎。</strong><br>象曰：己日革之，行有嘉也。</blockquote>
<p><strong>你现在在这个位置：你已经看明白了，时机也差不多到了。可你还在犹豫。</strong></p>
<p>「己日乃革之」——到了那一天，就改。</p>
<p>注意，这一爻和初九是配对的。初九说不能动，六二说该动了。</p>
<p>《正義》说六二「与五相应，同处厥中，阴阳相应，往必合志」。</p>
<p>意思是：你和上面那个能拍板的人，已经对上眼了。</p>
<p><strong>时机到了的标准，是三条凑齐：</strong></p>
<p>一是<strong>上面点头了。</strong> 不是口头说「你看着办」，是他愿意为这件事在会上说一句话。</p>
<p>二是<strong>下面有人了。</strong> 至少有一个中层愿意跟你一起扛。</p>
<p>三是<strong>你自己有方案了。</strong> 不是方向，是步骤。</p>
<p>三条凑齐两条可以先动，凑齐一条就别动。</p>
<p>象传说「行有嘉也」——你走出去，会有好结果。</p>
<p>赵武灵王要胡服骑射，先找的是肥义，又找楼缓，一个个谈通了，才在朝会上宣布。宣布的时候，只有公子成反对，他又亲自去公子成家里把他劝服。</p>
<p><strong>什么情况还要再等：</strong>如果反对你的人里，有那种他一反对就有一批人跟着走的人，那你得先把他谈下来。绕开他硬推，推成了也是短期成果。</p>
<h3 id="p-九三-征凶-贞厉-革言三就-有孚-方案要过三遍">九三 · 征凶，贞厉。革言三就，有孚 —— 方案要过三遍</h3>
<blockquote class="pw-quote"><strong>九三：征凶，贞厉。革言三就，有孚。</strong><br>象曰：革言三就，又何之矣。</blockquote>
<p><strong>你现在在这个位置：你已经推着改了一段时间。有人开始有怨气，有人开始阳奉阴违。</strong></p>
<p>「征凶，贞厉」——硬推是凶，死守也是险。两头都堵。</p>
<p>出路在「革言三就」——关于变革的话，要反复议三次，成三次。</p>
<p>《正義》说：「自四至上，从命而变，不敢有违，则从革之言三爻并成就不虚。」</p>
<p>三次不是个虚数。第一次是听，第二次是议，第三次才是定。</p>
<p>这个阶段做什么：</p>
<p>- <strong>把方案拿回去改第三遍。</strong> 前两遍改的是道理，第三遍改的是执行细节——谁在什么时候做什么、不做会怎样。</p>
<p>- <strong>让反对的人参与改。</strong> 让他改一条，他就成了方案的一部分。等你推的时候，他不会砸自己的东西。</p>
<p>- <strong>准备好一句话回应所有人：「我知道这会让你多干什么。」</strong> 你不说这句，下面的人会觉得你根本不知道他们的处境。</p>
<p>管仲在齐国改革，把国分为二十一乡，士农工商各安其居，又搞盐铁官营。这套东西不是一天出来的，他辅佐齐桓公四十年，边改边调。</p>
<p><strong>什么情况不用议三次：</strong>如果局面已经明确要崩，来不及开会，那就先动手再解释。但要记住：这种时候你欠下的沟通债，以后要还。</p>
<h3 id="p-九四-悔亡-有孚改命-吉-信任够了-就雷厉风行">九四 · 悔亡，有孚改命，吉 —— 信任够了，就雷厉风行</h3>
<blockquote class="pw-quote"><strong>九四：悔亡，有孚改命，吉。</strong><br>象曰：改命之吉，信志也。</blockquote>
<p><strong>你现在在这个位置：前面铺垫够了，人心也稳了。现在到了必须动手的那一下。</strong></p>
<p>「有孚改命」——信任建立了，就可以改命。</p>
<p>《正義》说九四「居会变之始，能不固吝，不疑于下」。</p>
<p>这是全卦的转折点。前三个爻都在等、在议、在磨，到九四，一下就要落地。</p>
<p>这一爻的动作有三条：</p>
<p>- <strong>一次改到位，别改一半。</strong> 半改的东西最难用，旧的坏了，新的没立起来，人夹在中间。</p>
<p>- <strong>自己先按新规矩做。</strong> 你定的第一条规矩，第一个月的第一个执行对象是你自己。</p>
<p>- <strong>把改完之后的第一个受益者找出来，让他说话。</strong> 你说一百句好，不如一个受益的人说一句。</p>
<p>商鞅变法，徙木立信。他在南门立了一根木头，说谁能搬到北门，给十金。没人信。他加到五十金，有人试了，他当场给了。第二天，新法推行，秦国没人敢不当回事。</p>
<p><strong>什么情况要留一半：</strong>如果这个改动涉及人命的、涉及法律的，就得留缓冲。先把新规矩立起来，老规矩给一个期限退出。</p>
<h3 id="p-九五-大人虎变-未占有孚-改完之后-你得长得像新">九五 · 大人虎变，未占有孚 —— 改完之后，你得长得像新的</h3>
<blockquote class="pw-quote"><strong>九五：大人虎变，未占有孚。</strong><br>象曰：大人虎变，其文炳也。</blockquote>
<p><strong>你现在在这个位置：你是这场变革的主导者。事情推下去了，现在大家在看你。</strong></p>
<p>「大人虎变」——老虎换毛。虎换毛的时候，毛色变得鲜明有纹。</p>
<p>「未占有孚」——不用占卜，人心自服。</p>
<p>象传是「其文炳也」——纹路清清楚楚，亮得刺眼。</p>
<p>这一爻讲的是：<strong>变革的主导者，自己得变成另一个人。</strong></p>
<p>你不能一边说改，一边还是老做派。你昨天怎么开会、怎么拍板、怎么用人，今天就得变。</p>
<p>具体三条：</p>
<p>- <strong>旧身份要主动扔掉一样。</strong> 比如以前你习惯独断，现在就得真的开会让别人说完。</p>
<p>- <strong>公开承认一次自己以前的错。</strong> 这个动作很贵，但换来的是所有人的信任。</p>
<p>- <strong>把新标准刻在明面上。</strong> 考核什么、奖励什么、什么行为会被处理，写清楚，贴出来。</p>
<p>秦孝公任用商鞅十年，太子犯法，商鞅处理了太子的老师公子虔和公孙贾，一个被割了鼻子，一个被在脸上刺了字。这件事传出去，秦国上下再没人拿新法当儿戏。</p>
<p><strong>什么情况不用这么激烈：</strong>如果这场变革本来就小，涉及的人不多，那就别把自己也搞得面目全非。虎变是因为虎要镇住山林，你改的只是一间办公室，用不着。</p>
<h3 id="p-上六-君子豹变-小人革面-征凶-居贞吉-收手">上六 · 君子豹变，小人革面。征凶，居贞吉 —— 收手</h3>
<blockquote class="pw-quote"><strong>上六：君子豹变，小人革面。征凶，居贞吉。</strong><br>象曰：君子豹变，其文蔚也。小人革面，顺以从君也。</blockquote>
<p><strong>你现在在这个位置：改完了。你想再往前走一步，把剩下的也一起改了。</strong></p>
<p>「君子豹变」——真正的明白人，从里到外都变了。</p>
<p>「小人革面」——另一批人只是脸上变了，心里没变，但他们表面上服从了。</p>
<p>象传把这两句分开说得很清楚：君子的变是「其文蔚也」，小人的变是「顺以从君也」。</p>
<p>这一爻给的答案是「征凶，居贞吉」。<strong>再往前推一步就是凶，守住已有的就是吉。</strong></p>
<p>停下来之后做三件事：</p>
<p>- <strong>宣布结束。</strong> 明确告诉所有人，这一轮改到这儿为止，接下来一年不再动。人不喜欢变革，人讨厌的是不知道什么时候是个头。</p>
<p>- <strong>看那些「革面」的人。</strong> 他们不是敌人，是还没跟上的人。给他们时间和具体的路径，别急着淘汰。</p>
<p>- <strong>把新规矩固化下来。</strong> 写进制度、写进考核、写进新人手册。靠你个人推着的新规矩，你一走就没了。</p>
<p>汉武帝晚年下了轮台诏，说「当今务在禁苛暴，止擅赋，力本农」，把前面几十年的扩张政策收了。他打了四十年的仗，最后收手，所以汉朝没有在他手上崩掉。</p>
<p><strong>什么情况可以再推一轮：</strong>如果这次改完之后，明显还有一块没动到，而且它正在拖累已经改好的部分，那就再推。但记住上一轮的经验：议三次，一次到位，然后收手。</p>
<h3 id="p-最后-变不是目的">最后：变不是目的</h3>
<p>革这一卦六爻走完，你会发现它大半的时间都在等、在议、在磨。</p>
<p>真正动手的只有九四那一下。</p>
<p>这就是这一卦的意思。<strong>变革的成本，九成花在变革之前。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">别急着让人服你。你要的是改完以后，大家过得好，不是当时大家鼓了掌。</blockquote>
  `,
  ding: `
<p>一个创业者拿了笔钱，把公司从十几个人扩到六十个人。</p>
<p>半年后他跟我说：人招齐了，事反而慢了。以前三个人两天能出东西，现在开三次会还没定。</p>
<p>我问他招来的人怎么分工的。他说：以前那三个还是干以前的活，新来的六十个在边上配合。</p>
<p>鼎卦讲的就是这件事。<strong>革是破旧，鼎是立新。破完了不立，摊子照样是散的。</strong></p>
<p>下巽是木，上离是火。木上面烧着火，这就是做饭的鼎。</p>
<p>鼎这个东西，三只脚站着才稳，中间是空的才装得下东西。</p>
<p>大象那句话是全卦的骨架：「君子以正位凝命。」——把位置摆正，把要干的这件事定死。</p>
<p>《周易正義》说：「鼎之为器，且有二义：一有烹饪之用，二有物象之法。」它既是个锅，也是个规矩。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-鼎颠趾-利出否-得妾以其子-先把锅翻过来倒">初六 · 鼎颠趾，利出否，得妾以其子 —— 先把锅翻过来倒渣</h3>
<blockquote class="pw-quote"><strong>初六：鼎颠趾，利出否，得妾以其子，无咎。</strong><br>象曰：鼎颠趾，未悖也。利出否，以从贵也。</blockquote>
<p><strong>你现在在这个位置：你刚接手一个新摊子，或者刚开始一件新事。你手上有一堆前任留下的东西。</strong></p>
<p>「鼎颠趾」——把鼎倒过来，脚朝上。</p>
<p>锅倒过来是件不合规矩的事。可象传说「未悖也」——不算错。因为下一句是「利出否」：把里面的脏东西倒出去。</p>
<p>《正義》说得很直白：「旧，秽也。新，贵也。弃秽纳新，所以从贵也。」</p>
<p>这个阶段的动作，就四个字：<strong>先清，后立。</strong></p>
<p>具体三条：</p>
<p>- <strong>列一张「不做」的清单。</strong> 前任留下来的事，一件一件过：这件事今天还有人要吗？要的人是谁？说不出来源头的，砍掉。</p>
<p>- <strong>清人比清事难，但更值钱。</strong> 那些占着位置、又说不清自己在干什么的人，你要在这个阶段处理。等到你开始推新东西的时候再动，就变成人事斗争了。</p>
<p>- <strong>新东西一次只上一样。</strong> 你想同时上三个新项目，等于什么都没上。</p>
<p>刘邦进咸阳，诸将都去抢金帛财物，萧何一个人跑进丞相府，把秦朝的律令、图书、户口册全部收起来。别人在抢东西，他在清底账。</p>
<p><strong>什么情况不用清：</strong>如果你接的摊子本来就是好的，前任是升迁走的，团队也完整，那就别折腾。清是给烂摊子准备的。好摊子上做清，纯粹是给自己找事。</p>
<h3 id="p-九二-鼎有实-我仇有疾-不我能即-锅里有东西-别">九二 · 鼎有实，我仇有疾，不我能即 —— 锅里有东西，别再加</h3>
<blockquote class="pw-quote"><strong>九二：鼎有实，我仇有疾，不我能即，吉。</strong><br>象曰：鼎有实，慎所之也。我仇有疾，终无尤也。</blockquote>
<p><strong>你现在在这个位置：你手里有货，也有人在盯着你。你担心别人来抢、来搅。</strong></p>
<p>「鼎有实」——锅里已经有东西了。</p>
<p>「我仇有疾，不我能即」——你的对头自己有毛病，靠不过来。</p>
<p>象传给的第一句是「慎所之也」——你去哪儿，要慎。</p>
<p>《正義》：「有实之物，不可复加也。加之则溢，而伤其实矣。」</p>
<p><strong>这话是对那些手里已经有东西的人说的。你现在最该怕的不是少，是多。</strong></p>
<p>具体怎么做：</p>
<p>- <strong>把手上正在做的事减到三件以内。</strong> 你有多少精力，你自己清楚。三件事以外的，要么交出去，要么停掉。</p>
<p>- <strong>别接那种「非你不可」的活。</strong> 那种活接一次是信任，接三次是绑架。</p>
<p>- <strong>对头那边不用管。</strong> 他真要有本事扑过来，早就扑了。他不动，是因为他动不了。</p>
<p>周勃在吕后当权的时候，身为太尉却连军营都进不去。他没有硬碰，就在家里待着。吕后一死，他和陈平一动手，诸吕就完了。他手里的东西一直在，他没急着往外掏。</p>
<p><strong>什么情况要往外掏：</strong>如果你的东西放着会过期——技术会旧、机会会关——那就得拿出来用。判断标准：这个东西再过半年，还有没有人要。</p>
<h3 id="p-九三-鼎耳革-其行塞-雉膏不食-你关上了门">九三 · 鼎耳革，其行塞，雉膏不食 —— 你关上了门</h3>
<blockquote class="pw-quote"><strong>九三：鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。</strong><br>象曰：鼎耳革，失其义也。</blockquote>
<p><strong>你现在在这个位置：你能干，你也干得多。可你太久没跟外面通气了。你一个人在那儿闷头做。</strong></p>
<p>「鼎耳革，其行塞」——鼎的耳朵变了形，抬不动了。</p>
<p>鼎的耳朵是用来穿杠子抬的。耳朵一坏，锅再好也抬不走。</p>
<p>「雉膏不食」——锅里有野鸡肉这样的好东西，可没人吃得到。</p>
<p>象传四个字：「失其义也。」——你把鼎的用处给丢了。</p>
<p>《正義》说九三「以实处实」，位置本来就该是空的，他偏要塞满。</p>
<p>这个阶段的动作，是<strong>把耳朵修回来。</strong></p>
<p>- <strong>主动约三次饭，或者三个电话。</strong> 不谈事，只问人家最近在干什么、卡在哪。</p>
<p>- <strong>把你手上的东西说出去。</strong> 你觉得不值一提的东西，别人可能正需要。你不说，就是「雉膏不食」。</p>
<p>- <strong>接受一次别人的帮忙。</strong> 九三最典型的状态是「我自己能搞定」。你什么都自己搞定，别人就没有跟你发生关系的入口。</p>
<p>范雎在魏国被须贾诬陷，被打断了肋骨扔在厕所里，靠装死逃到秦国。他见了秦昭王，第一句话就点破了秦国「穰侯专权、太后擅政」的病根。他不是上来就炫才，是先说出了秦王最堵的那件事。</p>
<p><strong>什么情况可以继续关着门：</strong>如果你正在做一件需要绝对保密的事——竞标、专利、关键谈判——那就关着。但关的时间要有期限，到了期限必须开。</p>
<h3 id="p-九四-鼎折足-覆公餗-其形渥-凶-撑不住-就全砸">九四 · 鼎折足，覆公餗，其形渥，凶 —— 撑不住，就全砸了</h3>
<blockquote class="pw-quote"><strong>九四：鼎折足，覆公餗，其形渥，凶。</strong><br>象曰：覆公餗，信如何也。</blockquote>
<p><strong>你现在在这个位置：你被放在一个关键位置上，责任很大。你自己知道有点吃力，但你不想让人看出来。</strong></p>
<p>「鼎折足」——鼎的脚断了。</p>
<p>「覆公餗」——把公家的一锅好饭全洒了。</p>
<p>「其形渥」——洒得满身都是。</p>
<p>这是全卦唯一一个「凶」。《正義》说是「既承且施，非己所堪」。</p>
<p>象传反问一句：「信如何也。」——你当初是怎么让人信你的？</p>
<p><strong>这一爻讲的是能力配不上位置的代价。而且这个代价不是你自己付，是整个盘子一起付。</strong></p>
<p>这一爻的动作，很难做，但必须做：</p>
<p>- <strong>在断之前说出来。</strong> 找那个把你放上去的人，讲清楚：这件事我现在撑不住，我需要人、需要资源、或者需要往后推。</p>
<p>- <strong>具体说缺什么。</strong> 别说「压力大」，说「我缺一个懂供应链的人」。</p>
<p>- <strong>如果补不上，就退。</strong> 退下来丢一次面子，砸下来丢的是所有人的东西。</p>
<p>赵括的母亲去见赵王，说赵括不能当将。理由很具体：他父亲赵奢当将时，亲自捧着饭给几十个人吃，大王赏的东西全分给军吏；赵括一当将，就朝东坐着受拜，军吏没人敢抬头，赏的金帛全拿回家买田宅。赵王没听，长平四十万人。</p>
<p><strong>什么情况可以硬撑：</strong>如果你缺的东西三个月内能补上，那撑一撑可以。判断标准：你现在每个月出问题的次数，是在减少还是在增加。增加，就撑不住。</p>
<h3 id="p-六五-鼎黄耳金铉-利贞-耳朵好用-杠子结实">六五 · 鼎黄耳金铉，利贞 —— 耳朵好用，杠子结实</h3>
<blockquote class="pw-quote"><strong>六五：鼎黄耳金铉，利贞。</strong><br>象曰：鼎黄耳，中以为实也。</blockquote>
<p><strong>你现在在这个位置：你在主事。你不用自己下厨，你要保证这口锅能被抬得动、抬得稳。</strong></p>
<p>「鼎黄耳金铉」——黄色的耳朵，金属的杠子。黄是中色，金是坚。</p>
<p>耳朵和杠子，都不是锅本身。它们是<strong>连接器</strong>——把锅里的东西，跟外面需要的人连起来。</p>
<p>象传是「中以为实也」。你这个位置的价值，在于中间那点分寸。</p>
<p>这个阶段的动作有三条：</p>
<p>- <strong>把接口做好。</strong> 下面的人做出东西，怎么到你这里，怎么到客户那里。中间的每一步，谁负责、要多久，写清楚。</p>
<p>- <strong>别改锅里的东西。</strong> 你在这个位置上，最容易犯的错是觉得别人做的都不如自己。你一伸手，下面就不动脑了。</p>
<p>- <strong>找对那根杠子。</strong> 谁是那个能把你和外面接上的人？可能是销售，可能是渠道，可能是你原来的老同事。找到他，给他足够的条件。</p>
<p>刘备入蜀之后，没有自己管钱粮、自己管刑名，他让诸葛亮管后勤和法度，让法正做谋主，让关羽守荆州。他自己做的是把人放在对的位置上。</p>
<p><strong>什么情况要亲自动手：</strong>锅里的东西出了问题，快糊了，那你就得伸手。但伸手之后要复盘一次：为什么会糊，是接口的问题还是人的问题。</p>
<h3 id="p-上九-鼎玉铉-大吉-无不利-最结实的杠子-是最不">上九 · 鼎玉铉，大吉，无不利 —— 最结实的杠子，是最不显眼的那根</h3>
<blockquote class="pw-quote"><strong>上九：鼎玉铉，大吉，无不利。</strong><br>象曰：玉铉在上，刚柔节也。</blockquote>
<p><strong>你现在在这个位置：你已经不在最前面了，但这件事还跟你有关。你是那个大家都愿意来找的人。</strong></p>
<p>「鼎玉铉」——玉做的杠子。</p>
<p>玉这个东西，硬，但是不伤人。金杠子能抬锅，玉杠子抬得动，还好看。</p>
<p>象传是「刚柔节也」——硬的和软的，在你这里配得刚好。</p>
<p>《正義》说这一爻是「刚柔节也」，说的是分寸。</p>
<p><strong>这一爻讲的是一种很高的位置：你不掌权，但你的话有人听。</strong></p>
<p>这个位置做什么：</p>
<p>- <strong>只在大事上说话。</strong> 你说得越少，每次说的分量越重。</p>
<p>- <strong>用建议，不用命令。</strong> 你现在的力量来自别人信你，不来自别人怕你。</p>
<p>- <strong>在局面要崩的时候出来一次。</strong> 别的时候都退着，只有那一下必须出来。</p>
<p>张良在刘邦称帝之后就退了大半。他称病不朝，跟着赤松子学辟谷。可刘邦要换太子的时候，吕后请他出面，他出了个主意——请商山四皓。这一件事，定了汉朝后面几十年的局面。</p>
<p><strong>什么情况不该退这么远：</strong>如果这件事还是你的身家性命，你就不能只当玉铉。玉铉是给已经上岸的人准备的。你还在水里，就得自己划。</p>
<h3 id="p-最后-锅要空-才装得下">最后：锅要空，才装得下</h3>
<p>鼎这个器，有意思的地方在中间那个空。</p>
<p>正因为它是空的，才能装东西。</p>
<p>鼎卦讲的其实就这一件事：<strong>你手上这个摊子，重要的不是你往里塞了什么，是它能不能装、装的东西能不能被人吃到。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">新摊子最怕的不是没人，是有人没位置，有位置没人，有锅没耳朵。</blockquote>
  `,
  zhen: `
<p>凌晨两点，一个做电商的朋友给我发消息。仓库烧了。</p>
<p>他打了三行字：完了，全完了，我这几年的东西全完了。</p>
<p>我回他：先睡觉，明天再说。</p>
<p>第二天早上他给我打电话，说仓库的货保住了七成，烧的是隔壁那间。他说，他昨晚一晚上没睡，但今天早上他把该打的电话都打了。</p>
<p>震卦讲的就是这一段。<strong>雷打下来的那一刻，你手里那杯酒有没有洒。</strong></p>
<p>震是雷。上下都是震，雷一个接一个地打。</p>
<p>卦辞里那句「震惊百里，不丧匕鬯」，匕是取肉的勺子，鬯是祭神的香酒。雷声震动百里，主祭的人手里那杯酒，一滴没洒。</p>
<p>《周易正義》说：「惊远而惧迩也。」远处的人被惊到，近处的人被吓住——可主持大局的那个，手是稳的。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-震来虩虩-后笑言哑哑-先怕-才能后笑">初九 · 震来虩虩，后笑言哑哑 —— 先怕，才能后笑</h3>
<blockquote class="pw-quote"><strong>初九：震来虩虩，后笑言哑哑，吉。</strong><br>象曰：震来虩虩，恐致福也。笑言哑哑，后有则也。</blockquote>
<p><strong>你现在在这个位置：事情刚出，你被吓到了。你心跳很快，脑子里一团乱。</strong></p>
<p>「震来虩虩」——虩虩是发抖的样子。</p>
<p>「后笑言哑哑」——后来能笑着说话。</p>
<p>象传把顺序讲清楚了：「恐致福也」——害怕本身能带来福。「后有则也」——后来你有了章法。</p>
<p><strong>注意这个顺序。恐惧在前，章法在后。没有恐惧过的人，不会有章法。</strong></p>
<p>这一爻的动作，是在被吓到的当下做三件事：</p>
<p>- <strong>先把「怕」这件事认下来。</strong> 别硬撑着说没事。人在否认的时候，判断力是关着的。</p>
<p>- <strong>只做一件事：止血。</strong> 现在不要想原因，不要想以后，先让损失不再扩大。打一个电话、停一个动作、发一条通知。</p>
<p>- <strong>写下三行字。</strong> 第一行：现在最坏会怎样。第二行：这件事谁受影响。第三行：明天早上第一件要做的事是什么。</p>
<p>巨鹿之战，项羽渡河之后把船凿沉、把锅砸了，只带三天干粮。他手下的兵一开始也是怕的。可这一仗打下来，诸侯将来见项羽，「无不膝行而前，莫敢仰视」。怕过了，才有那个规矩。</p>
<p><strong>什么情况不用这么紧张：</strong>如果这件事其实不影响你的根本——不影响钱、不影响人、不影响信誉——那就别把它当雷。人有一种毛病，把小麻烦当大灾难，把小确幸当大机会。</p>
<h3 id="p-六二-震来厉-亿丧贝-跻于九陵-勿逐-七日得-丢">六二 · 震来厉，亿丧贝，跻于九陵，勿逐，七日得 —— 丢的东西，别追</h3>
<blockquote class="pw-quote"><strong>六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得。</strong><br>象曰：震来厉，乘刚也。</blockquote>
<p><strong>你现在在这个位置：你已经损失了。可能是钱，可能是客户，可能是时间。你现在满脑子都是怎么把它追回来。</strong></p>
<p>「亿丧贝」——损失了很多钱财。</p>
<p>「跻于九陵」——爬到高地上躲。</p>
<p>「勿逐，七日得」——别去追，七天之后自然回来。</p>
<p>这一爻给的答案，是全卦里最实用的一条：<strong>丢了的东西，当场不要追。</strong></p>
<p>理由很实在。你在惊恐状态下的判断是打折扣的。你追的时候会加价、会松口、会答应一些平时不会答应的事。</p>
<p>具体怎么做：</p>
<p>- <strong>把「追」推迟七天。</strong> 七天不是虚数，是给你的情绪一个冷却期。</p>
<p>- <strong>这七天里做两件事：</strong> 一是把损失算清楚，二是把没受影响的那部分稳住。</p>
<p>- <strong>七天之后再看。</strong> 有些东西自己会回来——客户会回头问价，员工会再联系你。自己回来的那些，比你追回来的更牢。</p>
<p>刘邦在彭城被项羽打得大败，退到荥阳。他父亲和妻子都被项羽抓了。他没有立刻反攻，他在荥阳扎下来，让萧何从关中往前线送人送粮。几年之后，局面全变了。</p>
<p><strong>什么情况必须马上追：</strong>丢的是不能再生的东西——比如一次性的资格、一个只在今天有效的窗口——那就得追。但追之前先设一个上限：最多付出多少，超过就不追了。</p>
<h3 id="p-六三-震苏苏-震行无眚-心慌-但脚不能停">六三 · 震苏苏，震行无眚 —— 心慌，但脚不能停</h3>
<blockquote class="pw-quote"><strong>六三：震苏苏，震行无眚。</strong><br>象曰：震苏苏，位不当也。</blockquote>
<p><strong>你现在在这个位置：事情过去了最惊的那一下。可你一直没缓过来，做什么都提心吊胆。</strong></p>
<p>「苏苏」是畏惧不安的样子。</p>
<p>「震行无眚」——在震动中照常行动，就没有灾。</p>
<p>象传是「位不当也」——你现在的这个位置，本来就不是个安稳位置。</p>
<p>这一爻的意思很简单：<strong>你可以心慌，但你不能停。</strong></p>
<p>具体三条：</p>
<p>- <strong>把标准降下来。</strong> 你现在做不出平时的水准，这是正常的。那就先按六成的标准交付，别空着。</p>
<p>- <strong>固定作息。</strong> 心慌的人最需要的是节律。几点起、几点吃、几点开始干第一件事，写下来照做。</p>
<p>- <strong>每天只定一件必成的事。</strong> 完成它，今天就算过关。</p>
<p>曹操在赤壁大败之后，退守南郡。他没有停，他一边收拾残兵，一边在北方推屯田、修水利。他这辈子输过好几次，每次都是败完接着干。</p>
<p><strong>什么情况必须停：</strong>如果你已经连续失眠、注意力涣散、开始做明显错误的基本判断，那就不是心慌，是伤到了。这时候必须停，找人、看医生、请假。扛着不叫坚强。</p>
<h3 id="p-九四-震遂泥-被吓瘫在泥里">九四 · 震遂泥 —— 被吓瘫在泥里</h3>
<blockquote class="pw-quote"><strong>九四：震遂泥。</strong><br>象曰：震遂泥，未光也。</blockquote>
<p><strong>你现在在这个位置：你已经停下来了。不是主动停的，是动不了了。</strong></p>
<p>「震遂泥」——雷打在泥上，陷下去了。</p>
<p>爻辞只有三个字，什么吉凶都没说。象传补的是「未光也」——你没能走出来。</p>
<p><strong>这一爻是全卦最闷的一爻。它不凶不吉，它就是不动。</strong> 前面初九在怕，六三在慌，起码还在动。九四连动都不动了。</p>
<p>为什么不动？《正義》说这一爻「以阳居阴」，一个本该刚强的位置，被放在了软的地方。</p>
<p>这个阶段做的事，只有一件：<strong>找一个最小的出口。</strong></p>
<p>- <strong>别给自己定目标，定动作。</strong> 「我要振作起来」不是动作。「今天下午三点，我给张三打个电话」是。</p>
<p>- <strong>把条件缩小。</strong> 你现在做不了大决定，就做最小的那个——把桌上的纸收一收，把邮箱清一清。</p>
<p>- <strong>找一个能盯着你的人。</strong> 让他每天问你一句「今天那件事做了吗」。人陷在泥里的时候，外部的节律比内部的自律管用。</p>
<p>伍子胥在昭关一夜白头之后，到了吴国，一度只能在市井里吹箫讨饭。他没有等一个完美的机会，他找的是公子光——一个正在谋划上位的人。他从最小的切口进去了。</p>
<p><strong>什么情况允许再躺一阵：</strong>如果这件事真的伤到了你的根本，硬起来只会摔得更狠，那就躺。但给躺定一个期限，写在日历上。</p>
<h3 id="p-六五-震往来厉-亿无丧-有事-雷一直在打-你还在">六五 · 震往来厉，亿无丧，有事 —— 雷一直在打，你还在撑</h3>
<blockquote class="pw-quote"><strong>六五：震往来厉，亿无丧，有事。</strong><br>象曰：震往来厉，危行也。其事在中，大无丧也。</blockquote>
<p><strong>你现在在这个位置：你不是第一次遇到事了，这已经是第几轮。你还在扛着，扛着整个摊子。</strong></p>
<p>「震往来厉」——雷来雷去，一直是危险的。</p>
<p>「亿无丧，有事」——损失很大，但没有全丢，事情还在办。</p>
<p>象传是「危行也……其事在中，大无丧也」。</p>
<p><strong>这一爻讲的是长期危机中的主事者。你的处境不是「怎么赢」，是「怎么不垮」。</strong></p>
<p>这个阶段的动作有三条：</p>
<p>- <strong>保核心。</strong> 把所有资源往一件事上堆——那件没了你就真没了的事。别的都可以放。</p>
<p>- <strong>定期跟所有人说一次实话。</strong> 不用说得悲观，但要说真的。人在长危机里最怕不知道真实情况。</p>
<p>- <strong>给自己留一个人。</strong> 一个你什么都能跟他说的人。你在六五这个位置上跟谁都得端着，你会撑不住。</p>
<p>汉文帝刚即位的时候，功臣集团、诸侯王、匈奴，三面都压着他。他没跟任何一面硬碰，一件一件来：先稳住周勃，再分齐国的地，对匈奴和亲。他扛了二十三年。</p>
<p><strong>什么情况可以放手：</strong>如果你扛的这件事本来就没救，你只是在拖时间，那就放。拖着的时候，人会把自己也拖进去。</p>
<h3 id="p-上六-震索索-视矍矍-征凶-震不于其躬-于其邻-">上六 · 震索索，视矍矍，征凶。震不于其躬，于其邻 —— 别人出事的时候，你就该准备</h3>
<blockquote class="pw-quote"><strong>上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。</strong><br>象曰：震索索，中未得也。虽凶无咎，畏邻戒也。</blockquote>
<p><strong>你现在在这个位置：那件坏事还没落到你头上，但它落在了一个跟你很像的人身上。你看着，心里发凉。</strong></p>
<p>「震索索，视矍矍」——腿在抖，眼睛到处看。</p>
<p>「征凶」——这时候出击是凶。</p>
<p>「震不于其躬，于其邻」——雷没打在你身上，打在你邻居身上。</p>
<p>这一爻给的动作是：<strong>别人出事，就是给你的预警。</strong></p>
<p>象传是「畏邻戒也」——因为怕邻居遭遇的事，所以自己先戒备。</p>
<p>这是全卦最值钱的一条。</p>
<p>具体做四件事：</p>
<p>- <strong>把那个人的处境，跟你自己的对一遍。</strong> 他的哪个条件跟你一样？那个条件，就是你的雷。</p>
<p>- <strong>现在就把漏洞补掉。</strong> 现金流、关键人依赖、单一客户、合规，找一个最像的，这个月就动。</p>
<p>- <strong>不用大动干戈。</strong> 「无咎」不是「大吉」。做到及格就行，别把自己吓死。</p>
<p>- <strong>别插手。</strong> 「婚媾有言」——你去帮忙还会有人说闲话。事后帮他可以，出事的时候先管自己。</p>
<p>孙叔敖做楚国的令尹，有个老人教他三句话：位已高而意益下，官益大而心益小，禄已厚而慎不取。他照着做了，楚国大治。</p>
<p><strong>什么情况可以不管：</strong>如果那个人的情况跟你的完全不同——他倒是因为他自己的糊涂，你身上没有那个糊涂——那就别自己吓自己。看热闹可以，别入戏。</p>
<h3 id="p-最后-雷打过之后-天会晴">最后：雷打过之后，天会晴</h3>
<p>震卦六爻走下来，你会发现没有一爻是教你打赢的。</p>
<p>它教的都是<strong>怎么在震动里不出局。</strong></p>
<p>先怕，然后有章法。丢了先不追。慌着也得走。动不了就找个最小的出口。扛着的时候保住核心。别人倒了你就补自己的洞。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">出事那天晚上你睡不睡得好不重要。第二天早上你还起不起得来，才重要。</blockquote>
  `,
  gen: `
<p>一个人做了十二年，去年把公司卖了。卖完他跟我说：我不知道明天干什么。</p>
<p>三个月后他又开始干新项目。半年后新项目停了。他跟我说：我不是想做，我是停不下来。</p>
<p>艮卦讲的就是这件事。<strong>该走的时候走不难，该停的时候停，难。</strong></p>
<p>艮是山。上下都是山，两座山叠在一起，就是一动不动。</p>
<p>卦辞有一句很难懂的话：「艮其背，不获其身，行其庭，不见其人。」</p>
<p>背是人身看不见自己的地方。《正義》解释得很妙：「背者，无见之物也。夫无见则自然静止。」</p>
<p><strong>你止在那个看不见自己的地方，就不会被自己的欲望牵走。</strong></p>
<p>彖传里那句话是全卦的总纲：「时止则止，时行则行，动静不失其时，其道光明。」</p>
<p>艮不是不动，是<strong>在对的时候停。</strong></p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-艮其趾-无咎-利永贞-脚趾刚动-就按住">初六 · 艮其趾，无咎，利永贞 —— 脚趾刚动，就按住</h3>
<blockquote class="pw-quote"><strong>初六：艮其趾，无咎，利永贞。</strong><br>象曰：艮其趾，未失正也。</blockquote>
<p><strong>你现在在这个位置：有个念头刚冒出来。你想做点什么——回一句话、发一条动态、投一笔钱、订一张票。</strong></p>
<p>「艮其趾」——止住脚趾。</p>
<p>脚趾是身上最先动的地方。念头一起，脚趾先动。在这一刻止住，是成本最小的一次「止」。</p>
<p>《正義》：「居止之初，行无所适，止其足而不行，乃得无咎。」</p>
<p>这个阶段只有一个动作：<strong>给冲动加一道手续。</strong></p>
<p>具体三条：</p>
<p>- <strong>把「立刻回」改成「明天回」。</strong> 微信、邮件、任何让你情绪上来的消息，一律隔夜。</p>
<p>- <strong>把想花的钱放进购物车，放四十八小时。</strong> 四十八小时之后还想要的，再买。</p>
<p>- <strong>把想说的话写进备忘录，不写进对话框。</strong> 你写完就发现，你要的不是说，是发泄。</p>
<p>张良在博浪沙刺秦始皇，找了个大力士，用一百二十斤的铁椎砸车。砸错了，砸中的是副车。秦始皇大怒，天下大索十日。张良那一下如果忍住，他后来就不用改名换姓躲在下邳了。可他在下邳桥上遇见了那个老人，学会了忍。后来他说：我这一生的本事，都是从那一次失败开始的。</p>
<p><strong>什么情况该动就动：</strong>如果这个念头你已经有半年了，反复出现，每次都被你自己按下去——那不是冲动，那是你想清楚的事。这时候按住脚趾，就是把正经事耽误了。</p>
<h3 id="p-六二-艮其腓-不拯其随-其心不快-你被卡在中间">六二 · 艮其腓，不拯其随，其心不快 —— 你被卡在中间</h3>
<blockquote class="pw-quote"><strong>六二：艮其腓，不拯其随，其心不快。</strong><br>象曰：不拯其随，未退听也。</blockquote>
<p><strong>你现在在这个位置：上面让你停，可你知道停了会出事。你想说，说了没用。</strong></p>
<p>「腓」是小腿肚。腓是躁动的东西，小腿一动，脚就跟着走。</p>
<p>「艮其腓，不拯其随」——按住小腿，可脚已经跟着去了，救不回来。</p>
<p>「其心不快」——心里堵得慌。</p>
<p>《正義》：「贪进而不得动，则情与质乖也。」</p>
<p><strong>这一爻讲的是一种很难受的处境：你的判断跟上面的决定对不上，而你没有权限改。</strong></p>
<p>这个阶段做什么：</p>
<p>- <strong>把反对写下来，一次。</strong> 写成文字发给能做决定的人，讲清楚你的判断和依据。发完存档。</p>
<p>- <strong>执行的时候不打折。</strong> 你已经说过了，执行的时候再软磨硬泡，是把风险留给自己。</p>
<p>- <strong>记录你预判的事。</strong> 如果那件事真的发生了，你手上的记录就不是抱怨，是资本。</p>
<p>田丰劝袁绍不要打官渡之战，袁绍不听，把他关了起来。田丰在牢里说：如果打赢了，我还能活；打输了，我必死。袁绍败回来，果然把他杀了。田丰说对了，可他说对的方式救不了他——他劝完还在继续劝。</p>
<p><strong>什么情况必须越级：</strong>如果这件事会出人命、会违法、会让所有人一起完蛋，那就不能只写一份记录。越级上报，或者直接拒绝执行。这种情况下你承担的风险，比跟着一起完蛋要小。</p>
<h3 id="p-九三-艮其限-列其夤-厉薰心-硬卡住-会把人劈成">九三 · 艮其限，列其夤，厉薰心 —— 硬卡住，会把人劈成两半</h3>
<blockquote class="pw-quote"><strong>九三：艮其限，列其夤，厉。</strong><br>象曰：艮其限，危薰心也。</blockquote>
<p><strong>你现在在这个位置：你给自己上了很硬的规矩。不准休息，不准接私活，不准有情绪。你以为这叫自律。</strong></p>
<p>「限」是腰。「夤」是背上那条脊肉。</p>
<p>「艮其限，列其夤」——硬卡在腰上，把脊背都撕开了。</p>
<p>「厉薰心」——危险烧到心里去了。</p>
<p>《正義》说得非常重：「列夤则身亡。」上下不通，人就散了。</p>
<p><strong>这一爻讲的是过度克制。你把上半身和下半身切断，人就不成一个整体了。</strong></p>
<p>你在九三如果出现下面三种情况，就是「艮其限」：</p>
<p>- <strong>你定的规矩，你自己已经连续违反三次以上，每次都很自责。</strong></p>
<p>- <strong>你已经很久没真正开心过，连做成事都没什么感觉。</strong></p>
<p>- <strong>你的身体开始报警——睡不着、吃不下、莫名其妙的疼。</strong></p>
<p>这时候要做的不是加码，是松开：</p>
<p>- <strong>把规矩减少到两条。</strong> 只留最要紧的那两条。</p>
<p>- <strong>安排一件纯粹为了高兴的事。</strong> 不为成长，不为社交，就是高兴。</p>
<p>- <strong>跟人说实话。</strong> 不要讲你的成绩，讲你真实的感受。</p>
<p>诸葛亮最后一次北伐，屯兵五丈原。司马懿不问军事，只问使者：丞相起居如何。使者说，罚二十以上的事都亲自批，饭吃得很少。司马懿说：诸葛孔明其能久乎。那年秋天，他死在军中。</p>
<p><strong>什么情况必须硬卡：</strong>如果你正处在戒断期——戒酒、戒赌、戒一段耗人的关系——那就得卡死。松一次，前面全白费。但戒断有期限，过了就得松。</p>
<h3 id="p-六四-艮其身-无咎-先管住自己">六四 · 艮其身，无咎 —— 先管住自己</h3>
<blockquote class="pw-quote"><strong>六四：艮其身，无咎。</strong><br>象曰：艮其身，止诸躬也。</blockquote>
<p><strong>你现在在这个位置：周围乱得很。别人在争、在抢、在闹。你想说点什么，想做点什么。</strong></p>
<p>「艮其身」——止住自己这个人。</p>
<p>象传四个字：「止诸躬也。」——把止的功夫，用在自己身上。</p>
<p>《正義》说得直接：「能止其身，则无咎。」</p>
<p><strong>这一爻的处境是：你没有能力管别人，你只能管自己。这不是退让，这是本分。</strong></p>
<p>大象给的那句话，正是从这一爻来的：「君子以思不出其位。」——你想的事，不出你现在的这个位置。</p>
<p>具体三条：</p>
<p>- <strong>不评论。</strong> 别人在争的时候，你的每一句评论都会被当成站队。</p>
<p>- <strong>不打听。</strong> 你去打听消息，消息就会传成「他在打听」。</p>
<p>- <strong>把手上那件事做完。</strong> 局势越乱，越需要有人在做实事。做实事的那个，最后往往是赢家。</p>
<p>曹参接替萧何做汉朝的相国，一切都照萧何定的办，自己天天喝酒。汉惠帝看不下去，让曹参的儿子去问他父亲。曹参把儿子打了一顿，然后跟惠帝说：你不如先帝，我不如萧何，他们定的东西已经够好了，守着就行。这就是萧规曹随。</p>
<p><strong>什么情况不能只守身：</strong>如果乱局会烧到你身上，守身就是等死。这时候要么站队，要么走。守身是有前提的——你得在火线之外。</p>
<h3 id="p-六五-艮其辅-言有序-悔亡-话要一句一句说">六五 · 艮其辅，言有序，悔亡 —— 话要一句一句说</h3>
<blockquote class="pw-quote"><strong>六五：艮其辅，言有序，悔亡。</strong><br>象曰：艮其辅，以中正也。</blockquote>
<p><strong>你现在在这个位置：你要开口了。可能是一次谈判，一次述职，一次解释。</strong></p>
<p>「辅」是牙床，是说话用的。</p>
<p>「艮其辅，言有序」——管住嘴，让话有次序。</p>
<p>《正義》：「以中正也。」你的话立得住，是因为你的人立得住。</p>
<p><strong>这一爻讲的是表达的克制。不是不说，是有序。</strong></p>
<p>具体四条：</p>
<p>- <strong>先说结论。</strong> 你要什么、你判断什么，放第一句。</p>
<p>- <strong>再给三个理由，不多于三个。</strong> 第四个理由会让前三个都变弱。</p>
<p>- <strong>主动说一个问题。</strong> 你自己提出来的问题，别人就没法拿它攻击你。</p>
<p>- <strong>停下来。</strong> 说完就停，等对方。沉默会让你多得到很多东西。</p>
<p>蔺相如完璧归赵，到了秦国，把和氏璧献上去，看秦王没有给城的意思，他说璧上有瑕疵，请让我指给大王看。拿回璧之后，他靠着柱子，把话说得有理有节，最后派人把璧送回了赵国。他全程只说该说的话。</p>
<p><strong>什么情况可以多说：</strong>如果对方需要的是你的判断，不是你的一句话答案，那就展开讲。判断标准：他问的是「行不行」，还是「为什么」。</p>
<h3 id="p-上九-敦艮-吉-止到最后-成了稳重">上九 · 敦艮，吉 —— 止到最后，成了稳重</h3>
<blockquote class="pw-quote"><strong>上九：敦艮，吉。</strong><br>象曰：敦艮之吉，以厚终也。</blockquote>
<p><strong>你现在在这个位置：你已经止了很久了。你不再是忍着，你就是这个样子了。</strong></p>
<p>「敦艮」——敦是厚。</p>
<p>《正義》：「以厚终也。」你从「忍不住地止」，变成了「自然而然地止」。</p>
<p><strong>这是艮卦的最高境界。前面所有的止都是用力气的，到上九不用力了。</strong></p>
<p>这个阶段做什么：</p>
<p>- <strong>把经验说给人听。</strong> 你现在知道什么该做、什么不该做。这些东西不写下来，就跟你一起走了。</p>
<p>- <strong>守住那个你一直守的东西。</strong> 你可能守的是信誉，是不占便宜，是不说假话。这是你最后的东西了。</p>
<p>- <strong>接受你不再往前冲这件事。</strong> 不是认输，是位置变了。</p>
<p>张良晚年跟刘邦说：我家世代相韩，韩国灭了，我不惜万金为韩报仇。现在以三寸舌为帝者师，封万户，位列侯，这是布衣的极点了，我愿弃人间事，从赤松子游。他后来学辟谷，道引轻身。他止住了，所以他善终。</p>
<p><strong>什么情况不该止：</strong>如果你才三十几岁，身体好，手上有事想做，那就是止早了。敦艮是给走完全程的人准备的。你在半路上用这个境界，是给自己找台阶。</p>
<h3 id="p-最后-停不下来的人-是不知道自己要去哪">最后：停不下来的人，是不知道自己要去哪</h3>
<p>艮卦六爻，从脚趾到手，到腰，到身，到嘴。</p>
<p>一路往上，越止越难，也越止越值钱。</p>
<p>它讲的其实就一件事：<strong>你不需要一直动，你需要知道什么时候不动。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">停不是放弃。停是把手从方向盘上松开一下，看看自己到底在往哪儿开。</blockquote>
  `,
  jianjian: `
<p>一个人跟我说，他做自媒体两年了，粉丝八千。</p>
<p>他说：我是不是不适合干这个。</p>
<p>我问他这两年发了多少条。他说一百多条。我说，你平均两天一条都不到，这不是不适合，这是还没开始。</p>
<p>渐卦讲的就是这件事。<strong>慢不怕，怕的是慢着慢着，你自己先不信了。</strong></p>
<p>下艮是山，上巽是木。木在山上长。山上的树，长得比平地慢，可扎得比平地深。</p>
<p>卦辞是「女归吉，利贞」。女归是女子出嫁。古代出嫁要六礼——纳采、问名、纳吉、纳征、请期、亲迎，一步都不能少。<strong>该走的程序走完，才叫吉。</strong></p>
<p>《周易正義》：「渐者，不速之名也。凡物有变移，徐而不速，谓之渐也。」</p>
<p>全卦用鸿雁做比喻。鸿雁从水边，一级一级往上飞。六个爻，就是六级台阶。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初六-鸿渐于干-小子厉-有言-无咎-你刚落地-有">初六 · 鸿渐于干，小子厉，有言，无咎 —— 你刚落地，有人说你</h3>
<blockquote class="pw-quote"><strong>初六：鸿渐于干，小子厉，有言，无咎。</strong><br>象曰：小子之厉，义无咎也。</blockquote>
<p><strong>你现在在这个位置：你刚到一个新地方，新人、新团队、新行业。你说话没人听，做的事也没人看。</strong></p>
<p>「鸿渐于干」——鸿雁落在水边。干是水涯，是陆地跟水的交界处，一个还没上岸的位置。</p>
<p>「小子厉，有言」——你会被轻视，会被说闲话。</p>
<p>《正義》说：「始进未得显位，易致凌辱，则是危于小子，而被毁于谤言。」</p>
<p><strong>这一爻给的答案很干脆：「无咎。」只是有闲话而已，没什么实质损失。</strong></p>
<p>象传是「义无咎也」——从道理上讲，你没做错。</p>
<p>这个阶段只做三件事：</p>
<p>- <strong>先把落脚点站稳。</strong> 你现在要的不是表现，是「这个人靠得住」这个基本印象。准时、守约、把你答应的小事做完。</p>
<p>- <strong>不解释。</strong> 别人说你外行、说你撑不了多久，别辩。初六的辩解没有分量，因为你的作品还没出来。</p>
<p>- <strong>找到一个参照物。</strong> 找出这个圈子里公认做得好的人，把他的东西拆开看。不是抄，是看清楚标准在哪。</p>
<p>韩信从项羽那边跑过来投刘邦，一开始只做了个连敖，后来做治粟都尉，管粮仓。没人知道他。他中途跑了一次，是萧何连夜把他追回来的。在萧何追他之前，他一直在做的是把粮仓管好。</p>
<p><strong>什么情况必须说话：</strong>如果你不说话就会被当成好欺负，那不叫闲话，那叫试探。第一次被越界的时候就得把线划出来，用最平的口气。</p>
<h3 id="p-六二-鸿渐于磐-饮食衎衎-先站到一块稳的石头上">六二 · 鸿渐于磐，饮食衎衎 —— 先站到一块稳的石头上</h3>
<blockquote class="pw-quote"><strong>六二：鸿渐于磐，饮食衎衎，吉。</strong><br>象曰：饮食衎衎，不素饱也。</blockquote>
<p><strong>你现在在这个位置：你站稳了。有人认你，你有一块自己的地盘。日子不算大，但踏实。</strong></p>
<p>「鸿渐于磐」——鸿雁落在大石头上。磐是又平又稳的大石。</p>
<p>「饮食衎衎」——衎衎是和乐的样子。吃吃喝喝，从容自在。</p>
<p>「不素饱也」——象传补了这一句：你不是白吃饭的。</p>
<p><strong>这一爻是全卦最舒服的一爻。可它也是最容易废掉一个人的一爻。</strong></p>
<p>《正義》说：「既得可安之地，所以饮食衎衎然，乐而获吉福也。」</p>
<p>具体做什么：</p>
<p>- <strong>把这块石头夯实。</strong> 你现在有的东西——客户、技能、人脉——一样一样拿出来看：哪一个三年后还在？</p>
<p>- <strong>建立你的积累机制。</strong> 每做完一件事，留一份东西下来。一份文档、一套模板、一个流程。这些东西会自己长大。</p>
<p>- <strong>别急着往上一级跳。</strong> 六二的位置是「安」，从安里往上跳，通常跳不好。</p>
<p>李冰做蜀郡守，修都江堰。他不是修一年两年，他修了一整套东西——鱼嘴、飞沙堰、宝瓶口，还定了「深淘滩，低作堰」六字。这套东西用了两千多年。他在蜀郡待了很久。</p>
<p><strong>什么情况该往上走：</strong>如果这块石头上已经没有你能学的东西了，而且你留在这儿靠的是重复，那就该走。重复不是积累。</p>
<h3 id="p-九三-鸿渐于陆-夫征不复-妇孕不育-你脱离了队伍">九三 · 鸿渐于陆，夫征不复，妇孕不育 —— 你脱离了队伍</h3>
<blockquote class="pw-quote"><strong>九三：鸿渐于陆，夫征不复，妇孕不育，凶。利御寇。</strong><br>象曰：夫征不复，离群丑也。妇孕不育，失其道也。利用御寇，顺相保也。</blockquote>
<p><strong>你现在在这个位置：你升得比同批人快。你觉得自己看明白了，想单干，或者想抄近路。</strong></p>
<p>「鸿渐于陆」——雁飞到了高平之地。</p>
<p>「夫征不复，妇孕不育」——出去的人回不来，怀的孩子生不下来。</p>
<p>象传是「离群丑也」——丑是类，你离开了你的同类。</p>
<p>《正義》说得直接：「见利忘义，贪进忘旧，凶之道也。」</p>
<p><strong>这一爻讲的是一个人跑太快的代价。你前面的台阶还没踩实，你跳到更上面去了。</strong></p>
<p>具体三条：</p>
<p>- <strong>回头看你的同批人。</strong> 他们现在在干什么？如果他们已经跟不上你了，那说明你在走，他们在停。</p>
<p>- <strong>算清楚你甩掉了什么。</strong> 离开原来的平台、伙伴、渠道，你省下了什么，又失去了什么。</p>
<p>- <strong>别断掉根。</strong> 「利用御寇，顺相保也」——保住你的同类，他们是你出事时的退路。</p>
<p>陈胜称王之后，以前一起种地的老乡去找他，喊他的小名。陈胜觉得丢人，把那个老乡杀了。这件事之后，他手下的老兄弟开始一个个离开他。他后来被自己的车夫庄贾杀了。</p>
<p><strong>什么情况可以单独走：</strong>如果原来那批人跟你走的根本就不是一条路，你留在一起是互相耽误，那就走。但走的时候把话说清楚，别留一屁股人情债。</p>
<h3 id="p-六四-鸿渐于木-或得其桷-找个能站的枝">六四 · 鸿渐于木，或得其桷 —— 找个能站的枝</h3>
<blockquote class="pw-quote"><strong>六四：鸿渐于木，或得其桷，无咎。</strong><br>象曰：或得其桷，顺以巽也。</blockquote>
<p><strong>你现在在这个位置：你到了一个更高的层级。可这个地方不太适合你——你的本事用不上，规则也不是你熟的那套。</strong></p>
<p>「鸿渐于木」——鸿雁飞到树上。</p>
<p>鸿雁是水鸟，爪子上有蹼，抓不住树枝。这是个很不舒服的处境。</p>
<p>「或得其桷」——桷是方正的椽子。要是能找到一根平的、稳的树枝，就能站住。</p>
<p>象传是「顺以巽也」——顺，而且要低。</p>
<p><strong>这一爻讲的是：到了不适合的位置，你要自己找那根能站的枝。</strong></p>
<p>具体三条：</p>
<p>- <strong>先找那根枝。</strong> 现在这个环境里，哪件事是你擅长、而且这里需要、而且没人跟你抢的？那件事就是你的桷。</p>
<p>- <strong>姿态放低。</strong> 六四容易犯的错是端着——我原来是干什么的，我怎么会做这个。你端一次，那根枝就没了。</p>
<p>- <strong>给自己一个期限。</strong> 半年、一年。到这个期限你还找不到枝，就不是环境的问题了。</p>
<p>韩信到了刘邦这边，一开始也是没法站。直到夏侯婴跟他聊了一次，觉得不一般，跟刘邦说了；萧何又跟他聊，也觉得不一般。他的「桷」是治粟都尉这个位置——管后勤，恰好是他擅长而刘邦这里最缺的。</p>
<p><strong>什么情况该走：</strong>如果这里没有任何一根枝适合你——你的技能跟这里需要的完全不搭——那待着就是浪费。走之前先想清楚：下一家会不会也不搭。</p>
<h3 id="p-九五-鸿渐于陵-妇三岁不孕-终莫之胜-三年没结果">九五 · 鸿渐于陵，妇三岁不孕，终莫之胜 —— 三年没结果，还没人能赢你</h3>
<blockquote class="pw-quote"><strong>九五：鸿渐于陵，妇三岁不孕，终莫之胜，吉。</strong><br>象曰：终莫之胜吉，得所愿也。</blockquote>
<p><strong>你现在在这个位置：你已经到了一个很高的位置。可你谋划的那件大事，三年了，还没有结果。</strong></p>
<p>「鸿渐于陵」——陵比陆还高，是土山。</p>
<p>「妇三岁不孕」——三年没有生育。</p>
<p>「终莫之胜，吉」——最终没有人能赢你，所以吉。</p>
<p>《正義》说这一爻是「久而不获，终莫之能胜」。</p>
<p><strong>这是全卦最励志的一爻，也是最难熬的一爻。三年。它不是三个月。</strong></p>
<p>这个阶段做什么：</p>
<p>- <strong>把成果的验收标准从「结果」改成「位置」。</strong> 三年里你可能一个结果都没有，但你的位置一直在往上。位置比结果重要。</p>
<p>- <strong>每年做一次对照。</strong> 拿出三年前的自己，跟现在比。资源、能力、能调动的人。只要这三样在涨，你就没白熬。</p>
<p>- <strong>别在下坡的时候改方向。</strong> 三年没结果是常态，不是信号。真正该改方向的信号，是你连位置都没在涨。</p>
<p>晋文公重耳流亡十九年。他先后到过狄、卫、齐、曹、宋、郑、楚、秦。他在齐国娶了妻，过得很舒服，不想走。狐偃、赵衰这些人把他灌醉，抬上车才走成。他六十二岁回国即位，之后九年，成了霸主。</p>
<p><strong>什么情况必须转向：</strong>如果你熬的过程里，位置没涨、资源没涨、你自己也没变强，只是在重复同一年——那不是没到火候，那是这条路不通。</p>
<h3 id="p-上九-鸿渐于陆-其羽可用为仪-你的羽毛-成了别人">上九 · 鸿渐于陆，其羽可用为仪 —— 你的羽毛，成了别人的规矩</h3>
<blockquote class="pw-quote"><strong>上九：鸿渐于陆，其羽可用为仪，吉。</strong><br>象曰：其羽可用为仪吉，不可乱也。</blockquote>
<p><strong>你现在在这个位置：你走完了。你手上的事成了，或者你已经从这个位置上退下来了。</strong></p>
<p>「鸿渐于陆」——雁又飞回了高平之地。</p>
<p>「其羽可用为仪」——它的羽毛可以拿来做礼仪的装饰。</p>
<p><strong>这是全卦的收尾。雁飞过去了，留下的是那身羽毛，后人拿它当规矩用。</strong></p>
<p>象传是「不可乱也」——这些东西不能乱。</p>
<p>这个阶段做三件事：</p>
<p>- <strong>把你走过的那条路，写下来。</strong> 哪一步是必须的，哪一步是可以省的，哪一步差点把你坑死。</p>
<p>- <strong>交一个人。</strong> 找一个正在你当年的位置上的人，把你的羽毛给他。</p>
<p>- <strong>守好最后的规矩。</strong> 你退了以后，你以前定的东西还在不在被人遵守。你破坏一次，前面全废。</p>
<p>孔子周游列国十四年，到处碰壁，没做成什么官。他回来之后整理诗书、删定礼乐、写春秋。他自己的路没走通，可他留下的那套东西，后来成了两千年的规矩。</p>
<p><strong>什么情况不用交出去：</strong>如果你的东西只适合你自己那个环境，换个环境就是毒药，那就别硬传。留在自己这儿，比传出去害人强。</p>
<h3 id="p-最后-渐卦的慢-不是磨蹭">最后：渐卦的慢，不是磨蹭</h3>
<p>六个爻走下来：水边、磐石、高地、树上、土山、又回到高地。</p>
<p>一级都没有跳。</p>
<p>它讲的就是这一件事：<strong>台阶是要一级一级踩的。你跳过的那几级，迟早要回来补，而且补的时候更贵。</strong></p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">你不是走得慢，你是还没到那一步。分清楚这两件事，很多焦虑就没了。</blockquote>
  `,
  guimei: `
<p>一个姑娘跟我说，她跟一个人在一起四年。住一起，一起还贷，一起见过双方父母。</p>
<p>我问她，你们算什么关系。她愣了一会儿，说：这个事没怎么正经谈过。</p>
<p>归妹卦讲的就是这件事。<strong>关系都快过成一家人了，名分还悬着。</strong></p>
<p>下兑是悦，上震是动。心里高兴，就动起来了。这就是归妹。</p>
<p>《正義》说：「说以动，所归妹也。」少女被喜欢冲昏了头，急着嫁。</p>
<p>卦辞只有五个字，很冷：「征凶，无攸利。」往前冲是凶，没什么好处。</p>
<p>为什么会这样？《正義》的解释是「位不当也」「柔乘刚也」。</p>
<p>一卦六个位置，五个位置都不对。<strong>位置不对，事情再热乎也长不了。</strong></p>
<p>大象那句是全卦的清醒剂：「君子以永终知敝。」——想求一个长久的结局，就得先看清哪里会坏。</p>
<p>我下面按六个位置说。</p>
<h3 id="p-初九-归妹以娣-跛能履-征吉-先进门-别争名分">初九 · 归妹以娣，跛能履，征吉 —— 先进门，别争名分</h3>
<blockquote class="pw-quote"><strong>初九：归妹以娣，跛能履，征吉。</strong><br>象曰：归妹以娣，以恒也。跛能履吉，相承也。</blockquote>
<p><strong>你现在在这个位置：你想进入一个圈子、一段关系、一个项目。可你进的时候不是主角，是搭头的那个。</strong></p>
<p>「归妹以娣」——娣是陪嫁的妹妹。姐姐嫁过去，妹妹跟着去，做妾。</p>
<p>「跛能履」——跛脚的人，走不快，但还能走。</p>
<p>《正義》说得很实在：「少长非偶，为妻而行则凶焉，为娣而行则吉。」</p>
<p><strong>同一个位置，你以什么身份进去，结果完全不同。</strong></p>
<p>这个阶段的做法：</p>
<p>- <strong>先接住角色，别急着改角色。</strong> 你现在是辅助，就把辅助做扎实。你越急着上位，上面越防你。</p>
<p>- <strong>走那条能走的路。</strong> 你跛，就走慢一点，别去跟跑得快的人比速度。</p>
<p>- <strong>把「恒」字立住。</strong> 象传说「以恒也」。你靠的是长期稳定，不是一时表现。</p>
<p>卫青出身是平阳侯家的骑奴，姐姐卫子夫进宫做了皇后，他才被带进宫里当差。他第一次出击匈奴，是四路大军里唯一一路打赢的，可他没有立刻要封赏。他一步步从车骑将军做到大司马大将军。</p>
<p><strong>什么情况可以争名分：</strong>如果这个角色明摆着是临时的、用完就扔的，那就得先把条件谈清楚。判断标准：这个人以前用过几个「搭头的」？他们都是怎么走的？</p>
<h3 id="p-九二-眇能视-利幽人之贞-看得见-但看不全">九二 · 眇能视，利幽人之贞 —— 看得见，但看不全</h3>
<blockquote class="pw-quote"><strong>九二：眇能视，利幽人之贞。</strong><br>象曰：利幽人之贞，未变常也。</blockquote>
<p><strong>你现在在这个位置：你在这个局里，但你的位置不正。你看得见前面，可你看到的东西不全。</strong></p>
<p>「眇能视」——瞎了一只眼，还能看见，但视野是缺的。</p>
<p>《正義》：「虽失其位，不废居内处中……犹如眇目之人，视虽不正，不废能视耳。」</p>
<p>象传给的动作是「幽人之贞」——像隐居的人那样守住自己。</p>
<p><strong>这一爻讲的是：位置不正的时候，你要守住「常」。</strong></p>
<p>具体三条：</p>
<p>- <strong>守住你的本分，不越线。</strong> 你现在的处境最容易犯的错，是觉得自己看明白了，去指点别人怎么做事。</p>
<p>- <strong>把最关键的信息补上。</strong> 你只有一只眼，那就主动去问、去看、去核对。你瞎的那只眼，得靠别人替你补。</p>
<p>- <strong>不走，不闹。</strong> 「幽人」不是消失，是不出声地待着。</p>
<p>萧何在刘邦军中的位置，一直是后方。刘邦在前线，萧何在关中，他看不见前线的事，可靠着秦朝留下的户籍、地形、人口册子，把粮草和兵员算得清清楚楚。他补上了自己看不见的那部分。</p>
<p><strong>什么情况可以表态：</strong>如果你手上已经掌握了完整的事实，而且这事正卡在你这里，那就该说。判断标准：你说的话有没有具体的、可以被核对的东西。</p>
<h3 id="p-六三-归妹以须-反归以娣-时候没到-退回去等">六三 · 归妹以须，反归以娣 —— 时候没到，退回去等</h3>
<blockquote class="pw-quote"><strong>六三：归妹以须，反归以娣。</strong><br>象曰：归妹以须，未当也。</blockquote>
<p><strong>你现在在这个位置：你很急。你想赶紧定下来，可所有条件都差一口气。</strong></p>
<p>「须」是等待。</p>
<p>「反归以娣」——退回去，等一等，再以陪嫁的身份进门。</p>
<p>《正義》：「未当其位，则宜有待。」</p>
<p><strong>这一爻给的答案是：退回去。</strong></p>
<p>注意，是「反归」，是往回走，不是往前冲。</p>
<p>这个阶段做什么：</p>
<p>- <strong>把那个 deadline 往后推。</strong> 你自己定的「今年必须怎样」，可能就是个催命符。</p>
<p>- <strong>退回一步，看清对方的底牌。</strong> 你急着进，对方就不急。你一退，对方的态度立刻暴露。</p>
<p>- <strong>把「娣」的条件先保住。</strong> 你不能一步到位做主角，那就先确保自己有个位置，别两头都空。</p>
<p>息妫是息侯的夫人，息国被楚文王灭了，她被掳进楚宫，生了两个儿子，可她一直不说话。楚文王问她为什么，她说：我一个女人，伺候了两个丈夫，纵然不能死，又有什么可说的。她的沉默，是她在自己没有位置的时候，唯一还能守的东西。</p>
<p><strong>什么情况不能再等：</strong>如果对方在拖着你的同时，已经跟别人把事情办了，那就不是等的时候了。这时候要做的不是等，是止损。</p>
<h3 id="p-九四-归妹愆期-迟归有时-婚期推迟-不代表结不成">九四 · 归妹愆期，迟归有时 —— 婚期推迟，不代表结不成</h3>
<blockquote class="pw-quote"><strong>九四：归妹愆期，迟归有时。</strong><br>象曰：愆期之志，有待而行也。</blockquote>
<p><strong>你现在在这个位置：该定的事，一直定不下来。你等得很累，你开始怀疑这件事到底成不成。</strong></p>
<p>「愆期」——过了约定的日期。</p>
<p>「迟归有时」——晚一点嫁，总有嫁的时候。</p>
<p>象传是「有待而行也」——你等，是因为你在等一个对的时候走。</p>
<p><strong>这一爻讲的是「主动的等待」。九四不是被动地拖，是看清楚了，宁可推迟。</strong></p>
<p>这个阶段做什么：</p>
<p>- <strong>把等待变成一个决定。</strong> 你自己说：我决定等，等到什么时候。这样你等的是自己的判断，不是别人的施舍。</p>
<p>- <strong>在等的这段时间里涨本事。</strong> 你等的时候如果什么都没长，那这个等就是浪费时间。</p>
<p>- <strong>给对方一个可核验的信号。</strong> 你等的是什么？条件、时间、钱、还是某个人的态度。说出来，看对方认不认。</p>
<p>姜子牙在渭水边钓鱼，直钩，不设饵。他等到了七十多岁，等来了周文王。他不是被动地等，他一直在研究天下大势，心里有一套完整的伐商方案。</p>
<p><strong>什么情况等不下去了：</strong>等的时间已经超过了这件事本身的周期——比如一件小事拖了三年——那就不是时机问题，是对方根本没打算办。</p>
<h3 id="p-六五-帝乙归妹-其君之袂-不如其娣之袂良-你穿得">六五 · 帝乙归妹，其君之袂，不如其娣之袂良 —— 你穿得比配角还朴素</h3>
<blockquote class="pw-quote"><strong>六五：帝乙归妹，其君之袂，不如其娣之袂良。月几望，吉。</strong><br>象曰：帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。</blockquote>
<p><strong>你现在在这个位置：你在一个很高的位置上，你要跟另一个很高的位置联姻、合作、合并。</strong></p>
<p>「帝乙归妹」——帝乙是商朝的天子，他把妹妹嫁出去。</p>
<p>「其君之袂，不如其娣之袂良」——新娘的衣袖，还不如陪嫁妹妹的漂亮。袂是衣袖，那时候衣袖的料子和绣工就是身份的招牌。</p>
<p>「月几望，吉」——月亮快圆了，但还没圆，吉。</p>
<p><strong>这一爻讲的是：你在最高的位置上做联合，反而要穿得朴素。</strong></p>
<p>《正義》：「其位在中，以贵行也。」你贵在你站的位置，不在你的排场。</p>
<p>具体三条：</p>
<p>- <strong>让对方的体面大过你。</strong> 你越低调，对方越放心。合作里最怕的是「我要盖过你」。</p>
<p>- <strong>别用月亮圆的那天。</strong> 「月几望」——快圆但没圆。留一点余地，别把话说满。</p>
<p>- <strong>把实惠给到具体的人。</strong> 你省下的排场钱，换成对方经办人看得见的好处。</p>
<p>周文王娶太姒，《诗经》里说「文定厥祥，亲迎于渭」。造舟为梁，就是搭浮桥去迎亲，规模不小，可他后来对商朝的态度一直很低——他活着的时候没有称王，是武王追封的。</p>
<p><strong>什么情况该讲排场：</strong>如果这次合作的对象，判断标准就是看排场——他看你带多少人来、坐什么车、住什么酒店——那你就得照着办。这时候朴素不是美德，是不尊重。</p>
<h3 id="p-上六-女承筐无实-士刲羊无血-空筐子-办不成事">上六 · 女承筐无实，士刲羊无血 —— 空筐子，办不成事</h3>
<blockquote class="pw-quote"><strong>上六：女承筐无实，士刲羊无血，无攸利。</strong><br>象曰：上六无实，承虚筐也。</blockquote>
<p><strong>你现在在这个位置：这件事看起来什么都齐了。流程走了，场面做了，朋友圈也发了。可你心里知道，里面是空的。</strong></p>
<p>「女承筐无实」——女子捧着筐，筐里什么都没有。</p>
<p>「士刲羊无血」——男子杀羊，羊身上没有血。</p>
<p>古礼里，女方要捧装满的筐，男方要刲羊取血。这两样是祭祀的实质。空了，礼就成了表演。</p>
<p>象传四个字：「承虚筐也。」</p>
<p>《正義》说这一爻是「无实」，就是没有内容。</p>
<p><strong>这一爻讲的是形式主义的终局。你做了所有的样子，该长的东西一点没长。</strong></p>
<p>上六的处境，只做一件事：<strong>回过头去看那些实的部分。</strong></p>
<p>- <strong>列三样东西：</strong> 关系里、项目里，什么是实的？什么是虚的？实的写具体——钱、人、时间、承诺。</p>
<p>- <strong>补一件实的事。</strong> 不用补全，补一件。今天就能做的那种。</p>
<p>- <strong>如果补不了，就承认它空了。</strong> 承认比继续演强。</p>
<p>赵括的母亲跟赵王讲的那段话，就是这个意思。赵括的父亲赵奢当将时，亲手捧着饭给几十个人吃，大王赏的东西全分给军吏；赵括一当将，接受军吏的朝拜，赏的东西全拿回家买田宅。排场一样不少，里头是空的。</p>
<p><strong>什么情况可以只做形式：</strong>如果这件事本来就是走个过场——比如例行的手续、必要的礼节——那就把形式做完，别往里加戏。不是所有事都需要内容。</p>
<h3 id="p-最后-先谈清楚-再热乎">最后：先谈清楚，再热乎</h3>
<p>归妹这一卦，六个爻里没有一个说感情不好。</p>
<p>它说的是：<strong>感情之外的那些东西——名分、顺序、条件、退出方式——你没谈，它们不会自己长出来。</strong></p>
<p>卦辞说「征凶，无攸利」，不是让你别爱，是让你别在名分不清的时候，把自己全押进去。</p>
<p>有一句话你可以带走：</p>
<blockquote class="pw-quote">关系里最贵的不是感情，是名分。感情会变，名分不会。</blockquote>
  `,
  feng: `
<p>一个人四十二岁，公司做到行业前三，手里管着八百人。他跟我说了一句话，我印象很深：「我现在没人跟我说真话了。」</p>
<p>他不是在感慨。他是在陈述一个事实。去年他拍板的一个项目亏了两千多万，事后复盘，会上七个人，没有一个人当初反对过。</p>
<p>丰卦讲的就是这件事。你到了最好的时候，光最亮，地方最大，钱最多，人最齐。可也正是在这个时候，你看不清了。</p>
<h3 id="p-初九-遇其配主-虽旬无咎-找个跟你一样能打的人">初九 · 遇其配主，虽旬无咎 —— 找个跟你一样能打的人</h3>
<blockquote class="pw-quote"><strong>初九：遇其配主，虽旬无咎，往有尚。</strong><br>象曰：虽旬无咎，过旬灾也。</blockquote>
<p><strong>你现在在这个位置：你起来了，一个人忙不过来，你需要一个搭子。</strong></p>
<p>这一爻的「配主」不是你的下属，是跟你分量相当的人。旬是均等的意思，两个人势力均等，才能互相照亮。</p>
<p>判断标准很硬：<strong>这个人敢不敢在没人的时候跟你说「你这事不对」。</strong>敢，就是配主；只会点头、只会补台的，那是跟班。</p>
<p>再补一条：<strong>合作超过一定年份，要主动重新划一次边界。</strong>象传说得很直白，「过旬灾也」——均势一旦破了，就不再是互相照亮，而是互相倾轧。</p>
<p>刘邦和韩信就是均势破了的样子。韩信要齐王那一次，两个人还能坐下来谈；等到项羽一死，天下再没有第三方，这份均势立刻归零。</p>
<p><strong>什么情况可以破例：</strong>如果你现在正要打的是一场硬仗，队里必须只有一个声音，那就别讲均势。打仗的时候要独断，分钱分权的时候才讲均势。</p>
<p>还有一层：这个「配主」不一定非得是同事。同行、老同学、甚至一个专挑你毛病的客户，只要他跟你分量相当、又不怕得罪你，都算。<strong>你要的是能跟你对撞的人，不是能跟你喝酒的人。</strong></p>
<h3 id="p-六二-丰其蔀-日中见斗-你被围住了">六二 · 丰其蔀，日中见斗 —— 你被围住了</h3>
<blockquote class="pw-quote"><strong>六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。</strong><br>象曰：有孚发若，信以发志也。</blockquote>
<p><strong>你现在在这个位置：你的消息全是二手的。你听到的每一句话，都已经被人过滤过一遍。</strong></p>
<p>「丰其蔀」是说遮光的帘子太大，「日中见斗」是说大白天的正午，居然能看见北斗星。光被挡到什么程度，你才需要抬头找星星。</p>
<p>这个阶段的动作只有一个：<strong>建立一条绕开中间层的通道。</strong></p>
<p>具体怎么做：定一个日子，一季度一次，随机点三个人吃饭。不通知他们的上级，不设议题，就问三句——你手上那件事卡在哪、你觉得公司哪个流程最蠢、你最近听人抱怨过什么。听完不评价，只记。</p>
<p>九二「有孚发若」，说的是用真心去把局面撬开。诸葛亮在《出师表》里劝刘禅「咨诹善道，察纳雅言」，讲的就是这个——皇帝身边的人越多，真话越少。</p>
<p><strong>什么情况可以不动：</strong>如果你现在的位置本来就低，上面隔着三层，硬要越级去捞信息，那叫找死。先把你自己这一亩三分地的实情摸清楚。</p>
<h3 id="p-九三-丰其沛-折其右肱-这条腿先卸下来">九三 · 丰其沛，折其右肱 —— 这条腿先卸下来</h3>
<blockquote class="pw-quote"><strong>九三：丰其沛，日中见沫，折其右肱，无咎。</strong><br>象曰：丰其沛，不可大事也。折其右肱，终不可用也。</blockquote>
<p><strong>你现在在这个位置：你左右手都不好使了。你想干大事，可你发现自己推不动。</strong></p>
<p>「丰其沛」比「丰其蔀」还要暗一层——蔀是帘子，沛是帐幔，把你整个人罩起来。到这一步，正午看见的已经不是星星，是「沫」，比星星还暗的东西。</p>
<p>象传给了一句很狠的话：「不可大事也。」</p>
<p>这一爻的解法是「折其右肱」——右胳膊断了，那就别用右胳膊。<strong>把那条已经废掉的腿卸下来，用左腿走路。</strong></p>
<p>说白了：<strong>换人，或者换路。</strong></p>
<p>这个阶段最容易犯的错，是舍不得。你已经投进去三年，那个人是你一手提上来的，那条业务线是你亲手做的。你不断，它就拖着你的整盘棋一起往下走。</p>
<p>苻坚在淝水之前，把整个氐族的家底都投了进去。他不是没有明白人劝，是他舍不得停。</p>
<p><strong>什么情况不用断：</strong>如果废的只是一个环节、不是一条链，别急着砍。修那个环节，成本比推倒重来低得多。</p>
<h3 id="p-九四-遇其夷主-吉-别怕找一个跟你抢的人">九四 · 遇其夷主，吉 —— 别怕找一个跟你抢的人</h3>
<blockquote class="pw-quote"><strong>九四：丰其蔀，日中见斗，遇其夷主，吉。</strong><br>象曰：丰其蔀，位不当也。日中见斗，幽不明也。遇其夷主，吉行也。</blockquote>
<p><strong>你现在在这个位置：你自己也被遮着。你不是不知道有问题，你是不知道问题到底出在哪儿。</strong></p>
<p>九四是臣位里最高的位置，靠近君位，也最容易被防着。这里又出现一次「丰其蔀，日中见斗」，说明这个阶段的暗，是结构性的。</p>
<p>解法落在「夷主」三个字上。夷是平常、是平等。找一个跟你平等的人，一起把话说开。</p>
<p><strong>具体做法：找一个跟你级别差不多、但没有直接竞争的人，每个月闭门谈一次。</strong></p>
<p>不谈感情，只谈三样：我这块最近出了什么问题、你那块最近出了什么问题、上面最近在意什么。三样讲完就散。这种对话的价值，就在它绕开了汇报关系——跟你下属谈，他要防着你；跟你上级谈，你要防着他。</p>
<p>郭子仪和李光弼早年有旧怨，安史之乱一起来，郭子仪手握兵权却主动把李光弼推上去做河东节度使。两个人从此一辈子绑在一根绳上。</p>
<p><strong>什么情况别谈：</strong>如果对方是那种转头就把你的话当投名状的人，谈了就是递刀。这种人一个都不要留。</p>
<h3 id="p-六五-来章-有庆誉-把聪明人招到身边">六五 · 来章，有庆誉 —— 把聪明人招到身边</h3>
<blockquote class="pw-quote"><strong>六五：来章，有庆誉，吉。</strong><br>象曰：六五之吉，有庆也。</blockquote>
<p><strong>你现在在这个位置：你说了算。所有人都看着你接下来要抬举谁。</strong></p>
<p>「来章」的章是文采、是才干。这一爻讲的是：<strong>你现在的活儿不是自己发光，是把有光的人弄到你身边来。</strong></p>
<p>到了这个位置，你亲手做的那点事，已经不重要了。</p>
<p>三个具体动作：</p>
<p><strong>一、给位置，不给夸奖。</strong>夸一百句不如挪一次椅子。凡是能被你夸而没有位置的人，三个月内一定会走。</p>
<p><strong>二、允许下面的人比你强。</strong>六五是阴爻居尊位——本身就说明这个位置要的是容人，不是逞能。你真要跟下面的人比手艺，比赢一次，输掉一片。</p>
<p><strong>三、公开表扬要具体。</strong>别说「小王很努力」，要说「小王那个方案砍掉了两个环节，省了三百万」。含糊的表扬，底下人听懂的是分猪肉。</p>
<p>汉高祖定天下之后论功，萧何第一。武将们不服，刘邦讲了一段「功人功狗」的话，把位置给了那个从没上过战场的人。</p>
<p><strong>什么情况要自己上：</strong>如果这件事只有你会、错了就要命，先自己顶住。等人练出来了再交，交早了就是拿家底赌。</p>
<h3 id="p-上六-丰其屋-阒其无人-你把自己关起来了">上六 · 丰其屋，阒其无人 —— 你把自己关起来了</h3>
<blockquote class="pw-quote"><strong>上六：丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。</strong><br>象曰：丰其屋，天际翔也。窥其户，阒其无人，自藏也。</blockquote>
<p><strong>你现在在这个位置：你的楼越盖越高，房子越来越大，可你发现没人来找你了。</strong></p>
<p>「阒其无人」，门口静得能听见风声。象传最后三个字最要命——「自藏也」。</p>
<p>不是别人不来，是你自己把自己藏起来了。</p>
<p><strong>这一爻的凶，凶在它是自己选的。</strong>你换了更大的办公室，进门要过三道门禁；你开始只跟同级的人吃饭；你把微信设成了仅聊天。每一件事都有正当理由，加起来就是三年没人跟你说真话。</p>
<p>丰卦整篇最狠的一句就在这儿：<strong>你的成功本身，会一点一点把你和真实世界隔开。</strong></p>
<p>卫青做到了大司马大将军，姐姐是皇后，三个儿子封侯。他这一辈子的做法是——皇帝给的封赏他往外推，打了胜仗把功劳记在部下头上。他死的时候，汉武帝给他修的墓像庐山。</p>
<p><strong>什么情况该关起来：</strong>如果你正处在被围攻、被查、被翻旧账的时候，闭门是真的能保命。这时候的「藏」是策略，不是病。区别在于——你自己心里清不清楚这是暂时的。</p>
<p>还有一条更细的：<strong>每年做一次「我最近听谁说过真话」的清点。</strong>如果答案是一个人名，说明你的圈子已经窄到危险了。如果答案是三个以上，你还能撑很久。这个清点不用给别人看，自己写下来就行。</p>
<h3 id="p-最后-日中则昃">最后：日中则昃</h3>
<p>丰卦的彖传讲了一句天地间最平常、也最没人爱听的话：</p>
<p><strong>日中则昃，月盈则食。</strong></p>
<p>太阳到了正当中，下一步就是偏西。月亮圆到最满，下一步就是亏。</p>
<p>你现在的处境越好，这句话离你越近。</p>
<p>不是说你要倒霉。是说<strong>你现在手里的一切，都是借来的，时间到了要还</strong>。你还得体面，还是难看，取决于两件事：你有没有人跟你说真话，你有没有在最好的时候把手里的东西分出去一点。</p>
<p>丰卦六爻里，一半在讲「被遮住」。遮住你的不是敌人，是位置本身。</p>
<p><strong>丰卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">越亮的地方越看不见影子。趁你还亮着，先修一条通往真话的路。</blockquote>
  `,
  lv: `
<p>一个人从大厂出来，去了另一个城市，加入一家新公司做 VP。头一个月他给我打电话，说感觉很奇怪：「我说话，他们听；我安排的事，他们也做。可我总觉得我是借住在这儿。」</p>
<p>他说对了。他就是借住。</p>
<p>旅卦讲的不是旅游。是你离开了自己的地盘——换城市、换行业、空降进一个新团队、去别人主场谈事——总之，你现在脚下这块地不是你的。</p>
<h3 id="p-初六-旅琐琐-斯其所取灾-别在小钱上露怯">初六 · 旅琐琐，斯其所取灾 —— 别在小钱上露怯</h3>
<blockquote class="pw-quote"><strong>初六：旅琐琐，斯其所取灾。</strong><br>象曰：旅琐琐，志穷灾也。</blockquote>
<p><strong>你现在在这个位置：你刚到一个新环境，处处怕吃亏。</strong></p>
<p>「琐琐」是细碎卑贱的样子。爻辞说得很直白：你在外头还抠抠搜搜、斤斤计较，这个灾是你自己招来的。</p>
<p>具体到能做的事：</p>
<p><strong>一、报账别抠。</strong>打车三十块、咖啡四十块，该报就报，别攒着发票等报销日。你越是在小钱上犹豫，别人越觉得你底气不足。</p>
<p><strong>二、请客要抢头一回。</strong>到新地方第一顿饭，你买单。不是为了让人欠你人情，是为了让所有人知道——你不缺这点钱，你不是来讨饭的。</p>
<p><strong>三、别打听别人的工资和职级。</strong>这个话题一开口，你就把自己摆到了跟班的位置上。</p>
<p><strong>四、随身带一样拿得出手的东西。</strong>一支好笔、一块表、一盒好茶，都行。出门在外，身上得有一件能证明你来路的东西。</p>
<p>韩信年轻时在淮阴受胯下之辱，饭都吃不上，靠漂母接济。他后来封了楚王，回去找到那个漂母，给了一千金。</p>
<p><strong>什么情况可以省：</strong>如果你本来就是去吃苦的——比如去创业公司过渡三个月——那就别装。装出来的体面，撑不过一个月。</p>
<h3 id="p-六二-旅即次-怀其资-得童仆贞-先安顿好三件事">六二 · 旅即次，怀其资，得童仆贞 —— 先安顿好三件事</h3>
<blockquote class="pw-quote"><strong>六二：旅即次，怀其资，得童仆贞。</strong><br>象曰：得童仆贞，终无尤也。</blockquote>
<p><strong>你现在在这个位置：你站稳了一点，起码有个落脚的地方了。</strong></p>
<p>这一爻是好爻，讲的是客居在外的三条命根子：住处、盘缠、人手。</p>
<p>「即次」是有地方住。别住公司安排的宿舍，也别跟同事合租。<strong>在外面，你得有一个谁也进不来的地方。</strong>这是你喘气的地方，也是你保存自己的地方。</p>
<p>「怀其资」是身上有钱。不是公司发的那点工资，是你自己留的一笔能撑半年的现金。<strong>在外地，现金流就是胆量。</strong>没这笔钱，你什么硬话都不敢说。</p>
<p>「得童仆贞」是身边有靠得住的人。哪怕只有一个。这个人最好是当地人，知道哪条路堵、哪个部门难缠、谁是真正拍板的。</p>
<p>苏武出使匈奴被扣了十九年，在北海放羊。他能活下来，靠的是身边一直有几个跟着他的人，也靠他手里那根汉节——那是他的身份凭证。</p>
<p><strong>什么情况不用这么讲究：</strong>如果你只是短期出差，两三个月的事，别铺张。住酒店、吃外卖，把活儿干完就走。</p>
<h3 id="p-九三-旅焚其次-丧其童仆-别在别人地盘收买人心">九三 · 旅焚其次，丧其童仆 —— 别在别人地盘收买人心</h3>
<blockquote class="pw-quote"><strong>九三：旅焚其次，丧其童仆，贞厉。</strong><br>象曰：旅焚其次，亦以伤矣。以旅与下，其义丧也。</blockquote>
<p><strong>你现在在这个位置：你在新团队里开始有人跟你了。你觉得自己有点势力了。</strong></p>
<p>这一爻是全卦最凶的警告。</p>
<p>「旅焚其次」——落脚的地方烧了。「丧其童仆」——身边的人也散了。象传点破原因：「以旅与下，其义丧也」。你一个客居的人，却去给下面的人施恩、发好处、拉队伍，这不合规矩。</p>
<p><strong>说白了：你是外人，你在别人地盘上收买人心，主人第一件事就是弄死你。</strong></p>
<p>这条在现代职场里一模一样。空降的管理者最爱干的事，就是给团队涨薪、加人、许愿。三个月后他就发现，自己被架空了。</p>
<p>真正该做的是：<strong>先跟你的上级把关系做实，再谈别的。</strong></p>
<p>田氏代齐就是这么来的。田乞、田常父子在齐国几代人，用大斗借出、小斗收进，把齐国的民心一点点买走。他们本来就是外来户，最后把姜家的齐国整个端了。齐国的国君到死才明白，可那时候已经没人替他说话了。</p>
<p><strong>什么情况可以放手带人：</strong>如果你来的时候就是带着任命、带着授权、带着能开除人的权力来的，那这个团队本来就是给你的。区别在于：你的权力是不是上面明确交到你手上的。</p>
<h3 id="p-九四-旅于处-得其资斧-有个位置-但不是你的">九四 · 旅于处，得其资斧 —— 有个位置，但不是你的</h3>
<blockquote class="pw-quote"><strong>九四：旅于处，得其资斧，我心不快。</strong><br>象曰：旅于处，未得位也。得其资斧，心未快也。</blockquote>
<p><strong>你现在在这个位置：你被重用了，待遇不错，但那个位置不是你的。</strong></p>
<p>「旅于处」是找到一个能待的地方，但只是待着。「得其资斧」是拿到了干活的家伙——权力、预算、人手，都有。可爻辞后半句是「我心不快」。</p>
<p>不快在哪？<strong>因为你知道这是临时的。</strong></p>
<p>象传讲得明白：「未得位也」。你有实权，没名分。这种状态最熬人，因为你干出来的功劳，随时可能被收回去。</p>
<p>这个阶段给你三条：</p>
<p><strong>一、把成果变成可带走的东西。</strong>名分带不走，作品带得走。做完一件事，一定要留下能被后人查到的东西——文档、案例、数据、署名。</p>
<p><strong>二、别抱怨。</strong>「我心不快」是你自己的感受，讲出去就变成了不识抬举。</p>
<p><strong>三、主动问一句：我什么时候转正。</strong>不主动问，那个位置永远不会给你。问了被拒，你至少知道该走还是该留。</p>
<p>孔子在卫国待过，卫灵公给他俸禄，问他军旅之事。孔子第二天就走了。他说的是「鸟兽不可与同群」——他要的不是一份俸禄，是一个能行道的地方。</p>
<p><strong>什么情况可以一直待着：</strong>如果你要的就是钱和履历，名分不重要，那就安心拿钱。想清楚自己要什么，比想清楚对方给什么更要紧。</p>
<h3 id="p-六五-射雉一矢亡-终以誉命-你只带了一根箭">六五 · 射雉一矢亡，终以誉命 —— 你只带了一根箭</h3>
<blockquote class="pw-quote"><strong>六五：射雉一矢亡，终以誉命。</strong><br>象曰：终以誉命，上逮也。</blockquote>
<p><strong>你现在在这个位置：你以一个外人的身份，坐到了很高的位置上。</strong></p>
<p>六五是君位。一个「旅」的人坐到君位，这是极罕见也极危险的事。爻辞给了一个画面：射野鸡，只有一支箭，射出去，箭丢了，鸡也没打着。</p>
<p>这个比喻的意思是：<strong>你手里只有一次机会，而这唯一的筹码还很容易打光。</strong></p>
<p>这个阶段能做的事只有一件：<strong>把姿态放到最低，把事儿办到最好。</strong></p>
<p>不讲排场，不要待遇，不跟老人争座次。你要的是「誉命」——口碑和任命。口碑这东西，客居的人只能靠它活。</p>
<p>乐毅伐齐，连下七十余城，燕昭王死了以后，燕惠王继位，田单一个反间计，乐毅就跑了。他没回燕国，去了赵国。他一个外臣，功劳太大，新君容不下他。</p>
<p><strong>什么情况可以争：</strong>如果这个位置本来就该你坐，规矩上、程序上都是你的，那就别装孙子。让得过了头，别人当你是心虚。</p>
<h3 id="p-上九-鸟焚其巢-先笑后号咷-别把借住当成了家">上九 · 鸟焚其巢，先笑后号咷 —— 别把借住当成了家</h3>
<blockquote class="pw-quote"><strong>上九：鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。</strong><br>象曰：以旅在上，其义焚也。丧牛于易，终莫之闻也。</blockquote>
<p><strong>你现在在这个位置：你已经完全融入了，你觉得自己就是这儿的人了。</strong></p>
<p>这一爻是最惨的一条路。</p>
<p>「鸟焚其巢」——鸟把巢筑在最高的地方，最后巢被烧了。「先笑后号咷」——先是笑，后是哭。「丧牛于易」——在「易」这个地方把牛丢了，牛是顺服的象征，丢了牛就是丢了安身立命的根本。</p>
<p>象传「以旅在上，其义焚也」——你一个做客的人，爬到最上面去了，这个结果本来就是烧。</p>
<p><strong>这一爻讲的是：你在别人的地盘上爬得越高，摔得越狠，而且没人会替你惋惜。</strong></p>
<p>主父偃是典型。他从齐国一个穷书生，一路做到汉武帝的宠臣，一年之内四次升迁。他得意的时候说：「丈夫生不五鼎食，死即五鼎烹耳。」后来他逼死了齐王，公孙弘一句话，汉武帝就把他族诛了。他死的时候，门下食客没有一个去看他。</p>
<p><strong>什么情况可以往上走：</strong>如果你已经在这个地方扎了根——买了房、入了籍、家人都在、跟几个核心人物是过命的交情——那你不再是旅人，可以往上走。判断标准是：你出事的时候，有几个人会替你说话。</p>
<h3 id="p-最后-山上的火-烧完就走">最后：山上的火，烧完就走</h3>
<p>旅卦的象是「山上有火」。火在山上烧，烧完这片草就往下一片去，它不停留。</p>
<p>这就是客居的本质。你在一个地方，但你迟早要走。</p>
<p>所以旅卦从头到尾只讲一件事：<strong>别把临时的地方当成永久的家，也别把自己当成这儿的主人。</strong></p>
<p>能带走的只有三样：手艺、名声、和几个真愿意在你落难时接你电话的人。</p>
<p><strong>旅卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">出门在外，谦一点、抠一点、把落脚的地方守住。你不是来扎根的，你是来办事的。</blockquote>
  `,
  xun: `
<p>一个部门负责人找我吐槽。他说他推一个新流程推了半年，会开了七八次，文件发了两轮，下面的人该怎么做还怎么做。</p>
<p>我问他：你每次是怎么说的？</p>
<p>他说：我就在会上讲一遍，讲得挺清楚的。</p>
<p>问题就在这儿。<strong>你以为「说清楚」就够了，其实「说出去」只是开始。</strong></p>
<p>巽卦讲的是风。风这个东西没有形状，可它能钻进每一道缝里。巽卦要教你的就是：怎么让你的话像风一样，进得去，留得下。</p>
<h3 id="p-初六-进退-利武人之贞-别在会上摇摆">初六 · 进退，利武人之贞 —— 别在会上摇摆</h3>
<blockquote class="pw-quote"><strong>初六：进退，利武人之贞。</strong><br>象曰：进退，志疑也。利武人之贞，志治也。</blockquote>
<p><strong>你现在在这个位置：你说了个方案，底下人问了两句，你自己先犹豫了。</strong></p>
<p>「进退」是又想这样又想那样。象传点破原因：「志疑也」——你自己都没想清楚。</p>
<p>这一爻有意思的地方在于，它给的不是「再想想」，而是「利武人之贞」——用武人那样的果决。</p>
<p><strong>具体就是两件事：</strong></p>
<p><strong>一、表态之前先想清楚，表态之后不再改口。</strong>你可以关起门来跟三个人吵三天，但一出门，只有一个口径。</p>
<p><strong>二、把「我觉得」换成「就这么办」。</strong>同样一个意思，「我觉得这样可以」和「就按这个来」，底下人收到的信号完全不同。</p>
<p>商鞅变法之初，秦孝公也拿不定主意，商鞅跟甘龙、杜挚在朝堂上辩了一场。商鞅说了一句很硬的话：「疑行无名，疑事无功。」意思是做事犹豫就不会成名，办事犹豫就不会成功。孝公当场拍板。</p>
<p><strong>什么情况可以摇摆：</strong>如果这件事的成本你还没算清楚，那就在会前摇摆，别在会上摇摆。会上摇摆一次，你的话以后就要打七折。</p>
<h3 id="p-九二-巽在床下-用史巫纷若-把话说到人心里去">九二 · 巽在床下，用史巫纷若 —— 把话说到人心里去</h3>
<blockquote class="pw-quote"><strong>九二：巽在床下，用史巫纷若，吉，无咎。</strong><br>象曰：纷若之吉，得中也。</blockquote>
<p><strong>你现在在这个位置：你说了很多遍，道理都对，可大家就是不动。</strong></p>
<p>「巽在床下」是个很妙的画面。床底下是最低、最暗、最接近人私密处的地方。风要吹到这儿，才算真的进去了。</p>
<p>「用史巫纷若」——像史官和巫祝那样，翻来覆去地讲。纷若是繁复的样子。</p>
<p><strong>这一爻讲的是：话要生效，得往下走三层，往深里走三遍。</strong></p>
<p>往下三层是哪三层？<strong>会议室 → 部门 → 工位。</strong>你的话只到会议室，那叫通知；到了部门，那叫传达；到了工位，每一个具体的人都知道自己明天该改哪个动作，那才叫落地。</p>
<p>往深里走三遍又是哪三遍？<strong>讲为什么、讲怎么做、讲做错了怎么办。</strong></p>
<p>大多数人的沟通只做了第一遍。</p>
<p>周公辅成王的时候，管叔、蔡叔在外面散布流言，说周公要篡位。周公没有急着辩解，他先去做事，然后一遍遍发诰命，《尚书》里留了好几篇。他就是用这个笨办法，把话说到了每一个人耳朵里。</p>
<p><strong>什么情况别啰嗦：</strong>如果这件事根本不需要所有人懂，只需要三个人执行，那就别开大会。把范围缩小，比反复宣讲高效。</p>
<h3 id="p-九三-频巽-吝-一天一个说法">九三 · 频巽，吝 —— 一天一个说法</h3>
<blockquote class="pw-quote"><strong>九三：频巽，吝。</strong><br>象曰：频巽之吝，志穷也。</blockquote>
<p><strong>你现在在这个位置：你在不停地调整口径，因为情况一直在变。</strong></p>
<p>「频巽」是反复地顺从、反复地改。</p>
<p>这一爻的判词是「吝」，不是凶，是憋屈、是不体面。象传「志穷也」——你自己也不知道该怎么办了，所以只能跟着变。</p>
<p><strong>这一爻讲的是信任的消耗方式：你的每一次改口，都在花你的信用。</strong></p>
<p>具体到能做的：</p>
<p><strong>一、把「改口径」和「改方案」分开。</strong>方案可以随时改，口径不能。方案改十次都行，只要对外说的还是那句话：「目标没变，做法在调。」</p>
<p><strong>二、改口必须给理由。</strong>哪怕是「上面压下来了」，也比悄无声息地换一套说辞强。</p>
<p><strong>三、别在同一个群里反复说。</strong>你今天否掉昨天说的话，底下人不觉得你在纠错，只觉得你靠不住。</p>
<p>赵括纸上谈兵，到了长平前线，把廉颇的军令全部换掉，换了编制、换了打法。他改的每一条单独看都有道理，可四十多万人在他手里，已经没人知道该听哪一句了。</p>
<p><strong>什么情况必须改口：</strong>如果原来的方向是错的，且已经造成了损失，那就要当众改，而且要说明白错在哪。这种改口是加分项，拖下去才是减分。</p>
<h3 id="p-六四-悔亡-田获三品-打猎打到了三样东西">六四 · 悔亡，田获三品 —— 打猎打到了三样东西</h3>
<blockquote class="pw-quote"><strong>六四：悔亡，田获三品。</strong><br>象曰：田获三品，有功也。</blockquote>
<p><strong>你现在在这个位置：你以前推不动的事，现在推得动了。</strong></p>
<p>「田获三品」是打猎打到了三类猎物。古礼里这三品是供干肉、供宾客、供国君。意思是你一次动作，拿到了多重收获。</p>
<p><strong>这一爻讲的是：沟通到了一定火候，会开始有复利。</strong></p>
<p>你的话开始有人复述，你的口径开始变成部门的口径，你不用再解释了。</p>
<p><strong>这个阶段该做的是趁热立规矩。</strong></p>
<p>把已经形成共识的东西写下来——写成一页纸的流程，写成一份会议纪要，写成一个表格。别留在嘴上。</p>
<p>嘴上答应的事，人的记忆会自己打折；写下来的事，折扣小得多。</p>
<p>萧何进咸阳的时候，别人抢金银，他去收秦朝的丞相御史律令图书。后来刘邦定天下，靠的就是这批档案——哪里有多少户口、哪里有多少兵、天下的关隘险要在哪，一清二楚。</p>
<p><strong>什么情况别急着立规矩：</strong>如果这件事还在快速变化，写死反而添乱。这时候写原则，不写细则。</p>
<h3 id="p-九五-无初有终-先庚三日-后庚三日-先商量三天-">九五 · 无初有终。先庚三日，后庚三日 —— 先商量三天，再盯三天</h3>
<blockquote class="pw-quote"><strong>九五：贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。</strong><br>象曰：九五之吉，位正中也。</blockquote>
<p><strong>你现在在这个位置：这件事由你定。你需要让一堆人按你的意思动起来。</strong></p>
<p>这一爻是全卦的枢纽，也是整篇最实用的一条。</p>
<p>「无初有终」——开头不顺利，结尾能成。这话是在安慰你：推不动是正常的。</p>
<p>「先庚三日，后庚三日」，庚是天干里主「变更」的那一个。先庚三日是变革之前留三天，后庚三日是变革之后留三天。</p>
<p><strong>翻成现代的话：任何一次变动，前后各留出缓冲期。</strong></p>
<p><strong>变革前三天做什么？</strong>放风。让消息先漏出去，让反对的人有时间来找你。所有人都在会上第一次听说，那这个方案一定会出事。</p>
<p><strong>变革后三天做什么？</strong>回访。挨个问那几个最可能出问题的人：卡在哪了？需要什么？——这一步不做，你前面所有的铺垫都会漏气。</p>
<p>盘庚迁殷是这么干的。他要从奄迁到殷，贵族反对得很厉害。他没有硬来，写了三篇诰命《盘庚》上中下，一遍遍讲道理、讲天命、讲利害，讲完了才动。迁过去之后，商朝才真正稳下来。</p>
<p><strong>什么情况不用缓冲：</strong>如果这件事就是救火，今天不动明天就完，那就直接下命令，事后补说明。危机面前讲流程，是拿流程当挡箭牌。</p>
<h3 id="p-上九-巽在床下-丧其资斧-跪太久了-站不起来">上九 · 巽在床下，丧其资斧 —— 跪太久了，站不起来</h3>
<blockquote class="pw-quote"><strong>上九：巽在床下，丧其资斧，贞凶。</strong><br>象曰：巽在床下，上穷也。丧其资斧，正乎凶也。</blockquote>
<p><strong>你现在在这个位置：你已经习惯性地顺着别人了。你都记不清自己上次说「不行」是什么时候。</strong></p>
<p>九二和上九的爻辞开头一模一样，都是「巽在床下」。区别在结果：九二是「吉，无咎」，上九是「丧其资斧，贞凶」。</p>
<p><strong>同一个动作，位置不同，结果就反了。</strong></p>
<p>九二的谦下是为了把话送进去，是有目的的。上九的谦下是因为没有别的办法了，是没底线的。</p>
<p>「丧其资斧」——把干活的家伙都丢了。资斧是钱财，也是工具、是权力、是你安身立命的那点硬东西。</p>
<p><strong>你一味顺从，最后丢的不是面子，是筹码。</strong></p>
<p>具体怎么自救：</p>
<p><strong>一、找出你最近一次说「不」是哪天。</strong>超过一个月，你就有问题了。</p>
<p><strong>二、主动提一个别人可能反对的要求。</strong>不用大，可以是资源、可以是时间、可以是一个人。提出来，看对方什么反应。</p>
<p><strong>三、手里始终留一件只有你能干的事。</strong>这是你唯一不用求人的地方。</p>
<p>叔孙通在秦二世面前，明明看出陈胜是造反，却说「此特群盗鼠窃狗盗耳」。他顺着二世的话保住了命，转头就跑去投了项梁。他知道什么时候该跪，也知道跪完要跑。</p>
<p><strong>什么情况可以一直顺着：</strong>如果你就是靠这个吃饭的——比如你的岗位本来就是执行岗，决策不归你——那就顺着，但要在别的地方攒筹码。顺从是策略，不能是生活方式。</p>
<h3 id="p-最后-风不跟人争-可它什么都进得去">最后：风不跟人争，可它什么都进得去</h3>
<p>巽卦上下都是风。风从来不用蛮力，它绕着走、顺着走、找缝走，最后还是它把整个屋子吹透了。</p>
<p>你推不动一件事，多半不是你说得不对，是你只说了一次，或者只说到会议室。</p>
<p><strong>巽卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">话不是讲给所有人听的，是讲给每一个具体的人听的。你要像风一样，一层一层吹到他耳朵边上。</blockquote>
  `,
  dui: `
<p>一个人做销售总监，团队里人缘最好。谁有事找他，他都有办法；谁闹情绪，他都能哄住。</p>
<p>去年裁员的名单出来，第一个是他。</p>
<p>他很懵，说我对谁都够意思啊。</p>
<p>我问他一句：那你跟谁说过「不行」？</p>
<p>他想了半天，说没有。</p>
<p>兑卦讲的就是这件事。兑是悦，是高兴。可《周易》讲的悦，跟讨好不是一回事。</p>
<h3 id="p-初九-和兑-吉-让人舒服-但不图什么">初九 · 和兑，吉 —— 让人舒服，但不图什么</h3>
<blockquote class="pw-quote"><strong>初九：和兑，吉。</strong><br>象曰：和兑之吉，行未疑也。</blockquote>
<p><strong>你现在在这个位置：你在一个新环境里，跟谁都处得来，你还没站队。</strong></p>
<p>「和兑」的和，是平和的、不偏不倚的和。九二讲信，六三讲谄，初九夹在中间，讲的是自然的和气。</p>
<p>象传「行未疑也」——你这样做，没人怀疑你有目的。</p>
<p><strong>这一爻的标准很明确：你的好，不能是定向的。</strong></p>
<p>具体到能做的：</p>
<p><strong>一、对新来的人好一点。</strong>这件事成本最低，收益最高。他什么都不懂的时候你伸了一把手，他记一辈子。</p>
<p><strong>二、别只对能给你办事的人笑。</strong>你只对有用的人热情，三个月之内所有人都会看出来。</p>
<p><strong>三、请客吃饭要均匀。</strong>今天你请，明天他请。老是同几个人凑一桌，那个圈子之外的人就会给你贴标签。</p>
<p>魏其侯窦婴失势的时候，门下的宾客跑得一个不剩，只有灌夫还跟他来往。窦婴后来跟灌夫交好，是因为他落魄的时候，只有灌夫不躲。</p>
<p><strong>什么情况不用这么费心：</strong>如果你手上就是有个明确的目标——比如要拉一个关键人物入伙——那就定向用力，别装公允。装出来的公允，比直接的偏私更让人反感。</p>
<h3 id="p-九二-孚兑-吉-悔亡-你的好-得有个真的底子">九二 · 孚兑，吉，悔亡 —— 你的好，得有个真的底子</h3>
<blockquote class="pw-quote"><strong>九二：孚兑，吉，悔亡。</strong><br>象曰：孚兑之吉，信志也。</blockquote>
<p><strong>你现在在这个位置：你已经有点口碑了，可你自己心里不踏实——你知道有些答应的事你做不到。</strong></p>
<p>「孚兑」是把诚信放在愉悦前面的那种好。</p>
<p>象传「信志也」——你的心是真的。</p>
<p><strong>这一爻讲的是：你让人舒服的能力，必须有一个东西托着。那个东西就是你说话算数。</strong></p>
<p>具体怎么做：</p>
<p><strong>一、把答应别人的事记下来。</strong>手机备忘录就行，不用多复杂。答应过什么、什么时候答应、什么时候该给。这一条能解决你一半的人际问题。</p>
<p><strong>二、做不到的事当场就说。</strong>「这个我做不了」，比「我尽量」强一百倍。「我尽量」是给对方希望，也是给自己挖坑。</p>
<p><strong>三、宁可少答应，也别多答应。</strong>你答应十件办成九件，在那个人心里你是那个「没办成的人」。你答应三件办成三件，他就把事交给你了。</p>
<p>季布在楚地有个名声，叫「得黄金百斤，不如得季布一诺」。他后来被刘邦通缉，是那些朋友冒着灭族的风险藏他，才让他活下来的。</p>
<p><strong>什么情况可以含糊：</strong>如果对方是在试探你的底牌，那你确实不该给准话。但要把「我现在不能答」说出来，别用「再看看」拖。</p>
<h3 id="p-六三-来兑-凶-讨好-是消耗">六三 · 来兑，凶 —— 讨好，是消耗</h3>
<blockquote class="pw-quote"><strong>六三：来兑，凶。</strong><br>象曰：来兑之凶，位不当也。</blockquote>
<p><strong>你现在在这个位置：你开始主动去哄人了。你怕冷场，怕别人不高兴。</strong></p>
<p>「来兑」是主动凑上去求悦。象传「位不当也」——这个位置本来不该这么干。</p>
<p><strong>这一爻给的判词是「凶」，全卦唯一一个凶。</strong></p>
<p>为什么讨好会凶？因为你哄人的时候，你把自己的位置放低了。<strong>你低一次是客气，低十次就成了你的定价。</strong></p>
<p>具体要停掉的动作：</p>
<p><strong>一、别主动解释。</strong>你说了一句话，有人脸色变了，你追着解释三遍——你在告诉他，你的脸色能左右我。</p>
<p><strong>二、别在群里捧场。</strong>每条消息都点赞、每个观点都「说得太对了」，这种人没人当真。</p>
<p><strong>三、别替别人的情绪负责。</strong>他今天不高兴，可能是昨晚跟老婆吵架，跟你没关系。</p>
<p>易牙是齐桓公的厨子。桓公说没吃过人肉，易牙就把自己儿子煮了端上去。管仲临死前跟桓公说，这个人连儿子都舍得，还有谁舍不得。桓公没听，最后被易牙锁在宫里饿死。</p>
<p><strong>什么情况该哄：</strong>如果对方是你得罪不起的人，而且这件事对你有实际影响，那就哄。但要清楚这是交易，不是关系。</p>
<h3 id="p-九四-商兑未宁-介疾有喜-该翻脸的时候翻脸">九四 · 商兑未宁，介疾有喜 —— 该翻脸的时候翻脸</h3>
<blockquote class="pw-quote"><strong>九四：商兑未宁，介疾有喜。</strong><br>象曰：九四之喜，有庆也。</blockquote>
<p><strong>你现在在这个位置：你心里在权衡——这件事到底要不要顺着来。你有点不安。</strong></p>
<p>「商兑未宁」是心里反复掂量，定不下来。「介疾有喜」的介是划开、是隔断；疾是毛病、是那个让你不舒服的东西。</p>
<p><strong>这一爻讲的是：当你为「要不要顺着」纠结的时候，答案通常是不顺。</strong></p>
<p>象传给了「有庆」两个字，是说这样做会有好结果。</p>
<p>具体怎么翻脸：</p>
<p><strong>一、只对事，不对人。</strong>「这个方案我不同意」和「你这人不行」，差别在于前者还能继续合作。</p>
<p><strong>二、翻脸一次就够。</strong>别翻完了又去解释、又去修补。你要的效果是让他知道你是有底线的，不是让他恨你。</p>
<p><strong>三、翻完不用道歉。</strong>你道歉，那这次翻脸就白翻了。你可以就具体说话的口气软一点，但立场别让。</p>
<p>蔺相如在渑池之会上逼着秦王击缶。他不是不怕，他是算清楚了——这一退，赵国的脸就没了。他后来对廉颇处处退让，那是另一件事，退让的内容是国家内政，不是国格。</p>
<p><strong>什么情况先忍着：</strong>如果你还没搞清楚对方是不是在故意试探，先观察一次。把「他是不是针对我」和「他就是这个脾气」分清楚，能省掉很多没必要的翻脸。</p>
<h3 id="p-九五-孚于剥-有厉-你在信一个正在掏空你的人">九五 · 孚于剥，有厉 —— 你在信一个正在掏空你的人</h3>
<blockquote class="pw-quote"><strong>九五：孚于剥，有厉。</strong><br>象曰：孚于剥，位正当也。</blockquote>
<p><strong>你现在在这个位置：你身居高位，你信任一个人，而这个人正在一点点拿掉你的东西。</strong></p>
<p>「剥」是剥落、是侵蚀。爻辞说的是：你对他有诚信，可他在剥你。这件事有危险。</p>
<p>象传一句「位正当也」，是在提醒你——<strong>正因为你在这个位置上，这件事才危险。</strong>普通员工信错人，损失的是一份工作；你信错人，损失的是整个盘子。</p>
<p><strong>这一爻的功课是：定期清点谁在从你这里拿东西。</strong></p>
<p>具体三条：</p>
<p><strong>一、列出最近半年你给出去的东西。</strong>钱、位置、资源、人情，都算。然后看回报。</p>
<p><strong>二、注意那些从不提要求的人。</strong>一个人长时间不提任何要求，要么他无所求，要么他求的东西你给不了。</p>
<p><strong>三、看他在你不在场的时候怎么说你。</strong>这句话传得到你耳朵里，说明还有人向着你；一句都传不到，你要小心了。</p>
<p>齐桓公一辈子信管仲，管仲死后信易牙、竖刁、开方。这三个人把持了宫门，桓公病重的时候，他们筑起高墙，不让人进去，桓公死在床上六十七天没人收尸。</p>
<p><strong>什么情况可以继续信：</strong>如果这个人拿了你的东西，也替你挡了子弹，那就别疑神疑鬼。信任本身就是一种投资，投出去就怕亏的人，做不成大事。</p>
<h3 id="p-上六-引兑-你被快乐拖住了">上六 · 引兑 —— 你被快乐拖住了</h3>
<blockquote class="pw-quote"><strong>上六：引兑。</strong><br>象曰：上六引兑，未光也。</blockquote>
<p><strong>你现在在这个位置：你在靠外面的东西让自己高兴——酒、局、人捧着你、消息里的点赞。</strong></p>
<p>「引兑」的引是牵引、是拉着走。你被那个「悦」牵着走了。</p>
<p>爻辞只有两个字，没有吉也没有凶。象传补了一句「未光也」——不光彩，也走不远。</p>
<p><strong>这一爻讲的是：所有靠外部刺激换来的高兴，都会要求你加码。</strong></p>
<p>今天喝两杯舒服，下周就得三杯；今天被人捧两句开心，下个月没人捧你就难受。这个账户只会越花越贵。</p>
<p>具体要做的：</p>
<p><strong>一、找到一件不出声也能让你高兴的事。</strong>写字、跑步、钓鱼、修东西，都行。标准是——这件事不需要观众。</p>
<p><strong>二、给自己定一条「不」的线。</strong>比如过了十二点不喝、不在群里聊工作、周末不接酒局。线定下来，就不用每次都重新做决定。</p>
<p><strong>三、警惕那种让你「上头」的场合。</strong>一群人互相吹捧、越聊越兴奋，散场之后你会觉得空。</p>
<p>陈后主叔宝在隋军压境的时候，还在跟妃子、狎客写诗。他写了《玉树后庭花》，写得很美。隋军打进建康的时候，他带着两个妃子躲进枯井，被人用绳子拉上来。</p>
<p><strong>什么情况可以放开玩：</strong>如果你刚打完一场硬仗，需要缓一缓，那就去玩，别有负担。区别在于——你知道这是休息，还是已经离不开它。</p>
<h3 id="p-最后-两泽相连-才能互相滋润">最后：两泽相连，才能互相滋润</h3>
<p>兑卦的象是「丽泽」——两个湖连在一起，水互相流过去，谁都不缺。</p>
<p>这就是悦的本质。<strong>它得是双向的。</strong></p>
<p>你一个人往外放水，那不叫泽，那叫渗漏。放到最后，你干了，别人也不记得你湿过。</p>
<p><strong>兑卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">让人舒服是本事，可这本事要有底。底就是你得先让自己不那么难受。</blockquote>
  `,
  huan: `
<p>一个老板跟我说，公司最难的时候不是没钱，是没人说话。</p>
<p>开会的时候，他讲完，底下没人接。不是反对，是那种集体沉默。他说那种沉默比吵架还可怕。</p>
<p>涣卦讲的就是这种局面。涣是散——人心散、队伍散、气也散。</p>
<p>但《周易》给涣卦的第一个字是「亨」，是通的。它认为散这件事本身不全是坏事。</p>
<h3 id="p-初六-用拯马壮-吉-刚散的时候-借一匹快马">初六 · 用拯马壮，吉 —— 刚散的时候，借一匹快马</h3>
<blockquote class="pw-quote"><strong>初六：用拯马壮，吉。</strong><br>象曰：初六之吉，顺也。</blockquote>
<p><strong>你现在在这个位置：你刚感觉到不对劲。有几个人开始不主动说话了，群里安静了。</strong></p>
<p>「用拯马壮」——用一匹壮马来救。涣刚起头的时候，火还没烧起来，这时候扑最容易。</p>
<p>象传给了一个字：「顺」。顺着来，别硬掰。</p>
<p><strong>具体怎么做：涣散的苗头，要在饭桌上解决，不要在会议室里解决。</strong></p>
<p>发现两个人不对劲，别发通知开会，约一顿饭。饭桌上能说的话，会上说不了。<strong>会议室是宣判的地方，饭桌是修补的地方。</strong></p>
<p>判断标准给你一条：<strong>一个人开始不主动汇报了，这是个信号。</strong>不主动汇报，说明他觉得汇报没用，或者觉得你不值得汇报。这时候找他聊一次，成本是一顿饭；拖三个月，成本是一个岗位。</p>
<p>刘邦入关中的时候，跟秦地百姓约法三章，把秦朝那些严苛的法令全废了。他不是在讲道理，他是在告诉所有人：跟着我，日子会松快。</p>
<p><strong>什么情况可以等等看：</strong>如果只是某个人最近状态不好，而他对整体没影响，别急着扑。把所有波动都当危机处理，你会先把自己累垮。</p>
<h3 id="p-九二-涣奔其机-悔亡-先去找那个还能靠的人">九二 · 涣奔其机，悔亡 —— 先去找那个还能靠的人</h3>
<blockquote class="pw-quote"><strong>九二：涣奔其机，悔亡。</strong><br>象曰：涣奔其机，得愿也。</blockquote>
<p><strong>你现在在这个位置：局面在散，你救不了所有人。你得先保住一部分。</strong></p>
<p>「机」是承托东西的几案。涣奔其机，就是奔向那个能托住你的东西。</p>
<p>象传「得愿也」——你这么做，是符合心愿的。</p>
<p><strong>这一爻讲的是一个很冷的道理：散局里，先救支点，别救所有人。</strong></p>
<p>什么是支点？<strong>是那种他一走，会带走一整个环节的人。</strong></p>
<p>给你一个判断表：你手上有十个人，写下他们的名字，然后假设明天每个人都提离职，分别会发生什么。写不出后果的，就不是支点；写出来让你心一沉的，那就是。</p>
<p>把资源、注意力、谈话的时间，先给这几个人。</p>
<p>曹操在官渡之前，实力远不如袁绍，手下不少人在暗中给袁绍写信。曹操打赢之后，搜出那些信，一把火烧了。他说了一句：「当绍之强，孤犹不能自保，而况众人乎！」这一把火，把人心烧回来了。</p>
<p><strong>什么情况可以全都救：</strong>如果你手上本来就没几个人，每个人都是支点，那就别挑了，一个一个谈。规模小的时候，摊薄等于放弃。</p>
<h3 id="p-六三-涣其躬-无悔-先把自己散出去">六三 · 涣其躬，无悔 —— 先把自己散出去</h3>
<blockquote class="pw-quote"><strong>六三：涣其躬，无悔。</strong><br>象曰：涣其躬，志在外也。</blockquote>
<p><strong>你现在在这个位置：事情推到你这儿了。你要往里投点什么，可你不确定值不值。</strong></p>
<p>「涣其躬」——把自己的身体散出去。这说的是往里面搭自己。</p>
<p>象传「志在外也」——你的心思在外面那件事上，不在自己身上。</p>
<p><strong>这一爻讲的是：有些局面，非得有人先把自己押上去，才动得了。</strong></p>
<p>具体到能做的：</p>
<p><strong>一、在别人还看不清的时候，你先把自己的那份押上。</strong>可以是钱，可以是时间，可以是名声。你押了，别人才敢跟。</p>
<p><strong>二、别讲条件。</strong>六三讲的是无条件地投入。你一边投入一边谈条件，那个投入的效果就打了对折。条件留到事成之后再谈。</p>
<p><strong>三、押的东西要看得见。</strong>你私下加班没人知道，你把工资买成公司的股份、把房子抵押出去发工资，所有人都知道。</p>
<p>田单守即墨的时候，燕军围城，他把自己的妻妾编进队伍里，把家里的钱拿出来犒军。城里人一看，将军的家眷都在城墙上，那就没什么好说的了。</p>
<p><strong>什么情况别押：</strong>如果你押上去之后，输了就翻不了身，那就别押。<strong>捐躯和送死是两回事，区别是活着的人还能不能接着干。</strong></p>
<h3 id="p-六四-涣其群-元吉-把山头拆了">六四 · 涣其群，元吉 —— 把山头拆了</h3>
<blockquote class="pw-quote"><strong>六四：涣其群，元吉。涣有丘，匪夷所思。</strong><br>象曰：涣其群，元吉，光大也。</blockquote>
<p><strong>你现在在这个位置：你手里有实权了，你发现底下已经结成了好几个圈子。</strong></p>
<p>「涣其群」——把小团体打散。这一爻给的判词是「元吉」，最高的吉。</p>
<p>「涣有丘，匪夷所思」——丘是高地，是说拆掉小圈子之后，众人重新聚成一个高地，这个规模大到超出常人的想象。</p>
<p><strong>这一爻是全卦最狠也最有价值的一条。</strong></p>
<p><strong>小圈子不是靠开会拆的，是靠流动拆的。</strong></p>
<p>具体三个动作：</p>
<p><strong>一、轮岗。</strong>让几个圈子的核心成员互换位置。不用大动，一两个人换一下，圈子就散了。</p>
<p><strong>二、改汇报线。</strong>以前三个人汇报给 A，现在拆开，两个汇报给你，一个汇报给 B。汇报线一改，山头自动消失。</p>
<p><strong>三、别在公开场合点破。</strong>你要的是散，不是抓。点破了，那几个圈子会立刻抱得更紧。</p>
<p>宋太祖「杯酒释兵权」，他没有杀石守信、高怀德这些人，就是请他们喝了顿酒，让他们交出兵权，换田宅、换富贵、换一门亲事。兵权一散，割据的根基就断了。</p>
<p><strong>什么情况不能拆：</strong>如果这几个圈子正在替你打仗、正在替你顶事，那就先留着。<strong>拆山头要在天下定了之后，不能在外敌还在的时候。</strong>打仗的时候拆自己人的台，那是替对手办事。</p>
<h3 id="p-九五-涣汗其大号-涣王居-无咎-号令发出去-就不">九五 · 涣汗其大号，涣王居，无咎 —— 号令发出去，就不能收回</h3>
<blockquote class="pw-quote"><strong>九五：涣汗其大号，涣王居，无咎。</strong><br>象曰：王居无咎，正位也。</blockquote>
<p><strong>你现在在这个位置：局面乱了，所有人都在等你说一句话。</strong></p>
<p>「涣汗其大号」——号令像出汗一样发出来，一发就收不回去。</p>
<p>这个比喻极准。汗出来，就回不去了。你的号令也一样。</p>
<p><strong>这一爻讲的是：散局里最忌讳的不是说错，是不说，或者说了又改。</strong></p>
<p>具体三条：</p>
<p><strong>一、说一次，说完。</strong>不要今天讲一句、明天补一句、后天再修一句。散局里，反复是毒的。</p>
<p><strong>二、号令要短。</strong>这时候不是一个能讲战略的时候。三句话说清楚：现在最重要的是什么、谁负责、什么时候交。</p>
<p><strong>三、说完了你自己得先做。</strong>你要求大家十点到，你九点五十就得到。散局里，命令是靠示范撑着的，不是靠职位。</p>
<p>周勃在吕后死后，跟陈平合谋诛诸吕。他去北军，对全军喊了一句：「为吕氏右袒，为刘氏左袒！」一句话，整个军队全把左胳膊露出来了。他没有讲道理，他只给了一个二选一。</p>
<p><strong>什么情况可以含糊：</strong>如果这件事本身还没定，那就别说。含糊比反复强——含糊只是让人觉得你有事没说，反复会让人觉得你没谱。</p>
<h3 id="p-上九-涣其血-去逖出-离开那个流血的地方">上九 · 涣其血，去逖出 —— 离开那个流血的地方</h3>
<blockquote class="pw-quote"><strong>上九：涣其血，去逖出，无咎。</strong><br>象曰：涣其血，远害也。</blockquote>
<p><strong>你现在在这个位置：有个烂摊子，已经伤到你了，你却还留在里面。</strong></p>
<p>「涣其血」——把那个流血的事散掉。「去逖出」——远远地离开。「逖」是远的意思。</p>
<p>象传三个字讲得直白：「远害也」。</p>
<p><strong>这一爻讲的是：不是所有的散都叫逃，有些散叫止损。</strong></p>
<p>具体怎么判断该不该走：</p>
<p><strong>一、这个局里还有没有你在乎的人。</strong>有，再撑一下；没有，就是个数字游戏。</p>
<p><strong>二、你走了以后，这事会不会更糟。</strong>如果你走了它就崩，你不是不能走，是你得先把摊子交出去再走。<strong>先安置，后离场。</strong></p>
<p><strong>三、你留下是为了什么。</strong>为了把它做成——留下；为了不甘心——走。不甘心是个无底洞，它吃多少年都填不满。</p>
<p>范蠡辅佐勾践灭了吴国，功成名就之后，他给勾践留了一封信，说「飞鸟尽，良弓藏；狡兔死，走狗烹」，然后带着西施泛舟五湖，改名换姓去做生意，成了陶朱公。文种没走，勾践赐了他一把剑。</p>
<p><strong>什么情况必须留下：</strong>如果这件事是你亲手起的头，而且你走了别人接不住，那你得撑到能交出去那一天。撂挑子的人和放手的人是两种人。</p>
<h3 id="p-最后-风一吹-水就散了-可水也就能流了">最后：风一吹，水就散了，可水也就能流了</h3>
<p>涣卦的象是「风行水上」。风一吹，水面碎了，可水也因此动了起来。</p>
<p>人心散了，不全是坏事。<strong>有些圈子本来就该散，有些旧规矩本来就该破。</strong></p>
<p>难的是一边破一边立。散之前你得想清楚：散了以后，用什么把这些人重新拢到一起。</p>
<p><strong>涣卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">散是治不是病。你要做的不是把水按住，是给它找一条新的河道。</blockquote>
  `,
  jie: `
<p>一个人去年开始记账。外卖不点了，咖啡自己冲，衣服两年没买。</p>
<p>年底一算，省了三万。可他那年奖金少了八万。</p>
<p>他说他不明白。</p>
<p>我明白。<strong>他节的是最容易节的那一块，丢的是最贵的那一块。</strong></p>
<p>节卦讲的是竹节。竹子一节一节往上长，节是让它长得更高的东西，不是拦着它的东西。所以节不是苦哈哈地省，是知道哪儿该收、哪儿该放。</p>
<h3 id="p-初九-不出户庭-无咎-该关的门先关上">初九 · 不出户庭，无咎 —— 该关的门先关上</h3>
<blockquote class="pw-quote"><strong>初九：不出户庭，无咎。</strong><br>象曰：不出户庭，知通塞也。</blockquote>
<p><strong>你现在在这个位置：你手上有个想法，还没成型。你已经忍不住想跟人说了。</strong></p>
<p>「不出户庭」——连院子门都不出去。</p>
<p>象传「知通塞也」——你知道现在这条路是通的还是堵的。</p>
<p><strong>这一爻的判词是无咎，不是吉。</strong>意思是：你不出去，不会出错，但也不会有什么收获。这是个防守动作。</p>
<p>具体怎么做：<strong>在方案成型之前，控制知情范围。</strong></p>
<p>定一个数字，比如「只跟三个人说」。超过这个数，你就管不住消息了。消息一旦扩散，你会收到一堆意见，然后你会发现方案被改得面目全非，而且你还要为它负责。</p>
<p>范雎进秦国的时候，先给秦昭王上书，昭王召见，他到了宫里却不说正事。昭王问他，他说：「臣非敢然也。」他要等昭王把身边的人屏退，才肯说那句「远交近攻」。他知道这话一旦漏出去，自己就没命了。</p>
<p><strong>什么情况不用关着：</strong>如果这件事本来就需要大家一起想，那早说比晚说好。判断标准是：<strong>这件事是需要共识，还是需要保密？</strong>需要共识的，越早拉人越好。</p>
<h3 id="p-九二-不出门庭-凶-该出门的时候你还关着">九二 · 不出门庭，凶 —— 该出门的时候你还关着</h3>
<blockquote class="pw-quote"><strong>九二：不出门庭，凶。</strong><br>象曰：不出门庭，失时极也。</blockquote>
<p><strong>你现在在这个位置：你准备好了，可你还压着不动。</strong></p>
<p>初九和九二，爻辞几乎一样，结果一个是无咎，一个是凶。</p>
<p><strong>这是节卦最精彩的一处对照。</strong></p>
<p>象传把话说死了：「失时极也」。极是中的意思，你错过了那个最合适的时点。</p>
<p><strong>同一个动作，时机不对，就从谨慎变成了怯懦。</strong></p>
<p>具体怎么判断该出门了：</p>
<p><strong>一、你的方案已经能被人听懂了。</strong>初九的时候你只有感觉，现在你能讲出三步。能讲清三步，就该出去。</p>
<p><strong>二、「再说说」这句话你说过三次以上了。</strong>说过三次，你就不是在打磨，是在拖。</p>
<p><strong>三、外面有人开始做同一件事了。</strong>这时候你再憋着，就不是你先做，是你跟做。</p>
<p>韩信在汉中，刘邦被项羽封在偏远的地方，将士天天跑。韩信也跑了，是萧何连夜把他追回来的。韩信该等的时候等了，可他不该再等的时候，是萧何替他做的决定。</p>
<p><strong>什么情况可以一直不出门：</strong>如果这件事必须一次成功、失败就没有第二次，那就慢慢磨。<strong>一次性的机会，值得等；可以反复试的事，不值得。</strong></p>
<h3 id="p-六三-不节若-则嗟若-不节制的账-迟早要还">六三 · 不节若，则嗟若 —— 不节制的账，迟早要还</h3>
<blockquote class="pw-quote"><strong>六三：不节若，则嗟若，无咎。</strong><br>象曰：不节之嗟，又谁咎也。</blockquote>
<p><strong>你现在在这个位置：你已经透支了一段时间了。身体、钱、或者信用。</strong></p>
<p>「不节若，则嗟若」——不节制，然后就叹气。</p>
<p>象传问了一句特别扎人的话：「又谁咎也」——你怪谁呢？</p>
<p><strong>这一爻的「无咎」很特别。它不是说没事，是说这事怪不得别人。</strong></p>
<p>具体怎么办：</p>
<p><strong>一、先算清账，别急着改。</strong>把你欠了什么列出来——欠多少钱、欠多少睡眠、欠了多少人情。写下来。人对模糊的恐惧远大于对具体数字的恐惧。</p>
<p><strong>二、只改一项。</strong>同时改五项的，五项都改不成。挑那个最要命的，先改一个月。</p>
<p><strong>三、别搞仪式感。</strong>买新本子、下载新 App、发朋友圈宣布——这些动作会给你一种已经改了的错觉。</p>
<p>隋炀帝三征高句丽，修大运河，建东都，每一件单看都是大工程。他把这些全挤在十几年里做完，民力耗尽了。他不是不知道民怨，他是停不下来。</p>
<p><strong>什么情况可以继续透支：</strong>如果这件事有个明确的截止点，你知道撑到那天就结束了，那就撑。<strong>透支本身不可怕，可怕的是没有尽头的透支。</strong></p>
<h3 id="p-六四-安节-亨-节制成了习惯-就不累了">六四 · 安节，亨 —— 节制成了习惯，就不累了</h3>
<blockquote class="pw-quote"><strong>六四：安节，亨。</strong><br>象曰：安节之亨，承上道也。</blockquote>
<p><strong>你现在在这个位置：你已经节了一段时间了，而且你发现没那么难受。</strong></p>
<p>「安节」——安于节制。</p>
<p>象传「承上道也」——你顺着上面那条道走，走顺了。</p>
<p><strong>这一爻讲的是习惯的力量：真正的节制，是不需要动用意志力的节制。</strong></p>
<p>怎么判断你到了六四？<strong>你不用每天做决定了。</strong>到点吃饭、到点睡、该花的钱直接花、不该花的自动划走。你没在忍，你只是在过日子。</p>
<p>具体怎么到这个状态：</p>
<p><strong>一、把规则前置。</strong>不要等到点外卖的时候再决定吃不吃，而是根本不在手机里装那个 App。</p>
<p><strong>二、让环境替你决定。</strong>家里不放零食、信用卡只留一张、工资一到账自动划走一部分。<strong>靠环境省力，靠意志费力。</strong></p>
<p><strong>三、别追求完美。</strong>一周破一次戒没关系，破完接着走。追求完美的人，破一次戒就全线崩溃了。</p>
<p>晏婴做齐国宰相，一件狐裘穿了三十年。他不是在演清贫，他是真觉得没必要换。齐国人都知道他俭，所以他说的话有人信。</p>
<p><strong>什么情况可以放松一下：</strong>如果这套规矩已经开始让你身边的人难受了——比如家人觉得你抠得过分——那就松一档。<strong>节制的目的是让日子过得下去，不是让你变成一个难相处的人。</strong></p>
<h3 id="p-九五-甘节-吉-让人尝到甜头的规矩">九五 · 甘节，吉 —— 让人尝到甜头的规矩</h3>
<blockquote class="pw-quote"><strong>九五：甘节，吉；往有尚。</strong><br>象曰：甘节之吉，居位中也。</blockquote>
<p><strong>你现在在这个位置：规矩是你定的。你定的规矩，下面的人正在执行。</strong></p>
<p>「甘节」——甘甜的节制。爻辞给的判词只有一个字：吉，还补了一句「往有尚」，往前走会被人推崇。</p>
<p><strong>这一爻讲的是：好的规矩，执行的人应该尝到甜头，而不是觉得自己在受苦。</strong></p>
<p>具体三条：</p>
<p><strong>一、把省下来的东西分一部分出去。</strong>你砍了预算，省下的钱别全归公司，拿一部分做奖金或者改善条件。<strong>不分的节流，一定会被反弹回来。</strong></p>
<p><strong>二、别只节别人。</strong>你要求大家不报销打车费，你自己上下班专车接送——这个规矩活不过一个月。</p>
<p><strong>三、给出选择。</strong>「你可以选 A 或者 B」，比「你必须做 A」接受度高得多。同样是限制，一个感觉是规矩，一个感觉是命令。</p>
<p>汉文帝想修一座露台，工匠算了一笔账，说要百金，相当于十户中等人家的家产。文帝说：「百金，中人十家之产也。吾奉先帝宫室，常恐羞之，何以台为！」他这话不是说给自己听的，是说给全天下听的。</p>
<p><strong>什么情况可以严一点：</strong>如果局面已经很糟，非下猛药不可，那就先严后宽。<strong>先严后宽，别人会感激你；先宽后严，别人会恨你。</strong></p>
<h3 id="p-上六-苦节-贞凶-省到头-就是抠">上六 · 苦节，贞凶 —— 省到头，就是抠</h3>
<blockquote class="pw-quote"><strong>上六：苦节，贞凶，悔亡。</strong><br>象曰：苦节贞凶，其道穷也。</blockquote>
<p><strong>你现在在这个位置：你已经把节制定成了一种苦修。你自己难受，身边的人更难受。</strong></p>
<p>「苦节」——苦涩的节制。爻辞说得很重：「贞凶」。你把这套苦法子当成正道坚持下去，结果是凶。</p>
<p>象传「其道穷也」——这条路走到头了。</p>
<p><strong>这一爻和九五正对着。同样是节制，一个甘一个苦，一个吉一个凶。</strong></p>
<p>具体要停掉的动作：</p>
<p><strong>一、停掉那些「为省而省」的动作。</strong>打印纸双面用、会议室不开空调、团建改成加班——这些省下来的钱，远远抵不上它们造成的士气损失。</p>
<p><strong>二、听一次抱怨。</strong>如果同一个抱怨你听到过三次，那它不是抱怨，是反馈。</p>
<p><strong>三、给自己留一个口子。</strong>留一件你绝对不会省的事。可以是家里的茶，可以是每年的旅行，可以是给孩子买书。这个口子是你的弹性，弹性没了，整套节制的架子会一起塌。</p>
<p>公孙弘做汉武帝的丞相，自己盖布被子，吃饭只有一个肉菜。汲黯当众说他这是「饰诈欲以钓名」。一个宰相连被子都要省，在别人眼里，这已经不是节俭，是在做姿态。</p>
<p><strong>什么情况可以继续苦：</strong>如果你正处在生死关头——公司账上只够发一个月工资——那就苦，而且要苦得让所有人看见。<strong>危机里的苦是凝聚力，太平日子里的苦是折磨。</strong></p>
<h3 id="p-最后-竹子的节-是为了长得更高">最后：竹子的节，是为了长得更高</h3>
<p>节卦不是教你怎么省。它教你怎么给事情划界限。</p>
<p><strong>界限划对内了，事情自己会往上走；界限划错地方了，你越用力，事情塌得越快。</strong></p>
<p>该收的时候收，该放的时候放。这两个动作是一样的重要，只是大部分人会做第一个。</p>
<p><strong>节卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">别在便宜的地方省钱。你省下的那点小钱，正在悄悄吃掉你最贵的那块。</blockquote>
  `,
  zhongfu: `
<p>一个人跟我讲他带团队的方法。他说他有一套话术，专门用来激励人——讲愿景、讲成长、讲未来。</p>
<p>我问他：你自己信吗？</p>
<p>他笑了一下，没说话。</p>
<p>那个笑就是答案。</p>
<p>中孚卦讲的就是这个。孚是信。中孚是<strong>信从心里出来</strong>，不是从嘴里出来。</p>
<h3 id="p-初九-虞吉-有它不燕-信-一次只能给一个人">初九 · 虞吉，有它不燕 —— 信，一次只能给一个人</h3>
<blockquote class="pw-quote"><strong>初九：虞吉，有它不燕。</strong><br>象曰：初九虞吉，志未变也。</blockquote>
<p><strong>你现在在这个位置：你刚跟一个人交心。你还想着要不要多留几条后路。</strong></p>
<p>「虞」是专一，「燕」是安宁。「有它不燕」——你心里还装着别的打算，你就睡不踏实。</p>
<p>象传「志未变也」——你得在还没变心的时候把心定下来。</p>
<p><strong>这一爻讲的是：信任是有排他性的。你同时信三个人，那就不叫信。</strong></p>
<p>具体怎么判断你到位了没有：</p>
<p><strong>一、你能不能对这个人说一句会让你难堪的实话。</strong>能，就是交心了；不能，就是还在应酬。</p>
<p><strong>二、你有没有在背后留一手。</strong>留了，就承认自己在留。别一边留一手，一边说自己推心置腹。</p>
<p><strong>三、你能不能忍受他有一次没帮你。</strong>能，你的信是真的；不能，你要的不是朋友，是保险。</p>
<p>豫让给智伯报仇，第一次行刺赵襄子失败了，赵襄子放了他。第二次他把漆涂在身上弄烂皮肤，吞炭弄哑嗓子，躲在桥下等着。朋友劝他：你假装投靠赵襄子，不就能接近他了？豫让说，那是「怀二心以事其君」。他宁可死，也不肯揣着别的打算去接近一个人。</p>
<p><strong>什么情况必须留一手：</strong>如果对方是你的商业对手，或者是那种有过背刺记录的人，留后路是本职。<strong>专一是给值得的人准备的。</strong></p>
<h3 id="p-九二-鸣鹤在阴-其子和之-真的东西-自己会传">九二 · 鸣鹤在阴，其子和之 —— 真的东西，自己会传</h3>
<blockquote class="pw-quote"><strong>九二：鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。</strong><br>象曰：其子和之，中心愿也。</blockquote>
<p><strong>你现在在这个位置：你没有在宣传什么，可已经有人主动来找你了。</strong></p>
<p>「鸣鹤在阴」——鹤在看不见的地方叫。</p>
<p>这是全卦最美的一爻。老鹤在暗处叫了一声，小鹤远远地应和。没有人指挥，没有人安排。</p>
<p>象传「中心愿也」——那是心里愿意。</p>
<p><strong>这一爻讲的是：真诚的作用方式是共振，不是说服。</strong></p>
<p><strong>你不需要说服任何人。你只要把你自己那件事做真了，对的人自己会来。</strong></p>
<p>具体三条：</p>
<p><strong>一、别做广告，做作品。</strong>你把东西做出来了，它自己会说话。写文章、做产品、把一件事做到别人做不到的水平，都是这个路子。</p>
<p><strong>二、好东西要分出去。</strong>「我有好爵，吾与尔靡之」——我有好酒，跟你一起喝。别把好东西都攥着，攥着的东西不会产生回响。</p>
<p><strong>三、别追着人解释。</strong>你追着人解释，说明你心虚。你把事情做好了，不解释也有人问。</p>
<p>孔子在陈蔡之间被困，跟弟子们断了粮。子路气冲冲地问他：「君子亦有穷乎？」孔子回了一句：「君子固穷，小人穷斯滥矣。」他没有解释自己为什么落到这个地步，他只说了句该说的话，然后接着弹琴唱歌。</p>
<p><strong>什么情况要主动出击：</strong>如果你做的事情别人根本不知道，那就得说。<strong>共振需要一个起点，那个起点通常就是你先叫一声。</strong></p>
<h3 id="p-六三-得敌-或鼓或罢-或泣或歌-你把自己交给别人">六三 · 得敌，或鼓或罢，或泣或歌 —— 你把自己交给别人了</h3>
<blockquote class="pw-quote"><strong>六三：得敌，或鼓或罢，或泣或歌。</strong><br>象曰：或鼓或罢，位不当也。</blockquote>
<p><strong>你现在在这个位置：你遇上了一个跟你势均力敌的人。你的情绪开始跟着他走。</strong></p>
<p>「得敌」是遇到对手。或鼓或罢、或泣或歌——一会进攻一会收兵，一会哭一会笑。</p>
<p><strong>这一爻讲的是：你把情绪的开关交到了别人手上。</strong></p>
<p>象传「位不当也」——你站错位置了。</p>
<p>具体要做的：</p>
<p><strong>一、把你的决定和对方的反应分开。</strong>他今天态度好，你就加码；他今天冷脸，你就退。这种节奏不是你在带，是他在带。</p>
<p><strong>二、给自己定一条不下决定的规矩。</strong>情绪起伏的时候不做决定，等四十八小时。</p>
<p><strong>三、把「他什么意思」换成「我要什么」。</strong>你这几天想的全是他，这说明你已经被卷进去了。</p>
<p>项羽抓了刘邦的父亲，架起锅说要煮了他。刘邦在城下喊：「吾与项羽俱北面受命怀王，曰约为兄弟，吾翁即若翁，必欲烹而翁，则幸分我一杯羹。」刘邦不是不在乎，他是知道这时候跟着对方的节奏走，就输了。</p>
<p><strong>什么情况可以跟着走：</strong>如果这个人是你信得过的老搭档，而且他掌握的判断比你的准，那就跟着。<strong>关键是你要清醒地选择跟，而不是不由自主地被带。</strong></p>
<h3 id="p-六四-月几望-马匹亡-跟你的老伙计分开">六四 · 月几望，马匹亡 —— 跟你的老伙计分开</h3>
<blockquote class="pw-quote"><strong>六四：月几望，马匹亡，无咎。</strong><br>象曰：马匹亡，绝类上也。</blockquote>
<p><strong>你现在在这个位置：你要往上走，可你身边有一帮跟你一起上来的老兄弟。</strong></p>
<p>「月几望」——月亮快圆了，你快要到顶了。</p>
<p>「马匹亡」——马跑丢了。这里的马，说的是跟你成双成对的那一匹。</p>
<p>象传「绝类上也」——跟同类断掉，是为了往上。</p>
<p><strong>这一爻讲的是：往上走，是一定要付出人际代价的。</strong></p>
<p>具体怎么处理：</p>
<p><strong>一、先把话说明白。</strong>你要往上走了，跟老兄弟的关系一定会变。别假装什么都没变——那个假装撑不过半年。</p>
<p><strong>二、给实际的东西，别给空头承诺。</strong>位置给不了，就把钱、资源、机会给足。<strong>别用感情抵账。</strong></p>
<p><strong>三、接受有人会骂你。</strong>一定有人会觉得你变了。这个代价你躲不掉。</p>
<p>刘邦当了皇帝之后，萧何、曹参这些沛县的老兄弟还在，可韩信、彭越、英布这些人——那些后来才来的、跟他平起平坐过的——都被收拾了。这个过程的残酷，是位置本身要求的。</p>
<p><strong>什么情况可以带着老兄弟一起走：</strong>如果你的新位置需要的就是这批人，那就带着。<strong>判断标准是：他们是拖累，还是基本盘。</strong></p>
<h3 id="p-九五-有孚挛如-把人拴在一起的-是信任">九五 · 有孚挛如 —— 把人拴在一起的，是信任</h3>
<blockquote class="pw-quote"><strong>九五：有孚挛如，无咎。</strong><br>象曰：有孚挛如，位正当也。</blockquote>
<p><strong>你现在在这个位置：你是核心。你手上这批人，是你最大的资产。</strong></p>
<p>「挛如」是连在一起的样子。有孚挛如——因为有信任，所以连成一片。</p>
<p>象传「位正当也」——你在这个位置上，正好该干这个事。</p>
<p><strong>这一爻讲的是：到了最高处，你唯一能靠的，就是别人对你的信。</strong></p>
<p>具体三条：</p>
<p><strong>一、你答应的每一件小事都要兑现。</strong>小到「我明天把表发你」。<strong>大信任是由小兑现堆出来的。</strong></p>
<p><strong>二、出了事先自己扛。</strong>功劳往下分，责任往上揽。这一条做到，你不需要做别的。</p>
<p><strong>三、别用权术。</strong>到了这个位置还用手段，下面的人一眼看穿，然后他们会用同样的手段对你。</p>
<p>周武王伐纣，八百诸侯会于孟津。这些人凭什么来？不是因为周武王给了他们什么，是因为他们信这个人能成事。牧野之战，商军阵前倒戈，倒的不是商纣的兵，是纣王自己失掉的人心。</p>
<p><strong>什么情况可以不用这么累：</strong>如果你手上就是一个短期项目组，干完就散，那就把规则讲清楚，别谈信任。<strong>信任是长期资产，短期合作靠的是契约。</strong></p>
<h3 id="p-上九-翰音登于天-贞凶-名声比本事大">上九 · 翰音登于天，贞凶 —— 名声比本事大</h3>
<blockquote class="pw-quote"><strong>上九：翰音登于天，贞凶。</strong><br>象曰：翰音登于天，何可长也。</blockquote>
<p><strong>你现在在这个位置：你的名声很大，可你自己知道，你撑不住这个名声。</strong></p>
<p>「翰音」是鸡的叫声，鸡飞不高，声音却传得远。翰音登于天——声音上了天，身子还在地上。</p>
<p>象传反问一句：「何可长也」。</p>
<p><strong>这一爻讲的是：名气超过实力，是最危险的状态。</strong></p>
<p>具体怎么止损：</p>
<p><strong>一、把宣传的力度降下来。</strong>少接受采访、少上会、少发朋友圈。你在往回收，别人反而觉得你有东西。</p>
<p><strong>二、赶紧补那块最短的板。</strong>名声给了你时间，但不给你本事。这段时间你得用来干活，不是用来应酬。</p>
<p><strong>三、主动说一次「这个我不懂」。</strong>这句话会立刻降低别人对你的预期，而降低预期是保命动作。</p>
<p>赵括从小读兵书，谈兵论战，他父亲赵奢都驳不倒他。名声大得很。可真到了长平，他连粮道怎么走都没弄清楚。他母亲去向赵王求情，说这孩子不能当将领——一个当妈的最清楚，儿子的名声是虚的。</p>
<p><strong>什么情况名声大是好事：</strong>如果你正在融资、招人、打开局面，名声就是实打实的资源。<strong>这时候要做的不是压名声，是赶紧用名声换回实打实的东西。</strong></p>
<h3 id="p-最后-诚信不是道德-是效率">最后：诚信不是道德，是效率</h3>
<p>中孚卦的象是「泽上有风」。风从水面上过，水面自己就动了。</p>
<p>你不用去推水。你把风放出来，水自然会应。</p>
<p><strong>诚信这东西，说到底不是让你做个好人，是让你省事。</strong></p>
<p>你说话算数，别人就不用防你；别人不防你，沟通成本就低；成本低了，你能干的事就多。</p>
<p><strong>中孚卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">别去说服谁。把你自己弄真了，对的人会自己走过来。</blockquote>
  `,
  xiaoguo: `
<p>一个人三十二岁，在一个稳定的单位，做到科级。他跟我说，他觉得这辈子就这样了，心里不甘。</p>
<p>我问他：你现在最想干的是什么？</p>
<p>他说想辞职做个工作室。</p>
<p>我又问：你手里有多少钱？能撑多久？有没有第一个客户？</p>
<p>他一个都答不上来。</p>
<p>小过卦讲的就是这种时候。它不是让你认命，它是告诉你——<strong>翅膀还没长齐的时候，别往高处飞。</strong></p>
<h3 id="p-初六-飞鸟以凶-一上来就想飞">初六 · 飞鸟以凶 —— 一上来就想飞</h3>
<blockquote class="pw-quote"><strong>初六：飞鸟以凶。</strong><br>象曰：飞鸟以凶，不可如何也。</blockquote>
<p><strong>你现在在这个位置：你刚起步，可你已经在想很远的事了。</strong></p>
<p>「飞鸟以凶」——鸟往高处飞，凶。</p>
<p>象传给了一句很冷的话：「不可如何也」。意思是没救了，拉不回来了。</p>
<p><strong>这一爻讲的是：起步阶段，方向选错比速度慢可怕得多。</strong></p>
<p>小过卦的卦辞说「不宜上宜下」。往上飞，是逆势；往下落，是顺势。</p>
<p><strong>具体到能做的：头一年，只做能立刻见到钱的事。</strong></p>
<p>别做平台，别做生态，别做需要三年才能验证的事。你需要的是活下来，不是想象空间。</p>
<p>给你一条判断标准：<strong>如果这件事半年内没有第一笔收入，它就是「往上飞」。</strong>半年内有收入，哪怕很少，那才是「往下」。</p>
<p>陈胜吴广在大泽乡起事，喊出「王侯将相宁有种乎」，半年之内队伍到了几十万。可他派出去的人各占一块地，谁都不服谁。他自己最后被自己的车夫庄贾杀了。<strong>起得越快，摔得越早。</strong></p>
<p><strong>什么情况可以往上飞：</strong>如果你手里有足够多的存粮——钱、人、资源，能支撑三年不赚钱——那你飞。<strong>判断标准是存粮的厚度，不是心气的热度。</strong></p>
<h3 id="p-六二-过其祖-遇其妣-不及其君-遇其臣-越一级找">六二 · 过其祖，遇其妣；不及其君，遇其臣 —— 越一级找对人</h3>
<blockquote class="pw-quote"><strong>六二：过其祖，遇其妣；不及其君，遇其臣，无咎。</strong><br>象曰：不及其君，臣不可过也。</blockquote>
<p><strong>你现在在这个位置：你想找的人够不着，中间隔着好几个人。</strong></p>
<p>「过其祖，遇其妣」——越过了祖父，见到了祖母。「不及其君，遇其臣」——够不着君主，那就去见他的臣子。</p>
<p><strong>这一爻讲的是：够不着那个人，就去够他身边的那个人。</strong></p>
<p>具体怎么操作：</p>
<p><strong>一、先搞清楚谁的推荐有用。</strong>不是谁的职位高，是谁在那个决策者面前说话有分量。</p>
<p><strong>二、别越过你的直接上级。</strong>象传专门补了一句「臣不可过也」。你可以去见上面的人，但你的直接上级必须知道，最好是经他同意。</p>
<p><strong>三、见大人物的时候，带一个他关心的问题去。</strong>不是去要东西，是去请教一件事。这比递名片有用。</p>
<p>苏秦一开始去游说秦惠王，碰了一鼻子灰，钱花光了回家，嫂子都不给他做饭。后来他改去游说赵国的奉阳君，又通过燕文公的左右见到了燕文公，才拿到第一笔投资。<strong>他第二次成功，靠的是找对了那个能替他说话的人。</strong></p>
<p><strong>什么情况可以直接冲上去：</strong>如果这事关重大而且时间紧急，那就直接找最高的人。<strong>但要做好你的直接上级从此记你一笔的准备。</strong></p>
<h3 id="p-九三-弗过防之-从或戕之-该防的人-是你身边的人">九三 · 弗过防之，从或戕之 —— 该防的人，是你身边的人</h3>
<blockquote class="pw-quote"><strong>九三：弗过防之，从或戕之，凶。</strong><br>象曰：从或戕之，凶如何也。</blockquote>
<p><strong>你现在在这个位置：你身边有一帮跟着你的人，你对他们很好，可你隐隐觉得不对。</strong></p>
<p>「弗过防之」——你不去多加防备。「从或戕之」——跟着你的那些人，可能会害你。</p>
<p>象传反问：「凶如何也」。</p>
<p><strong>这一爻讲的是：小过卦里最大的风险，来自内部。</strong></p>
<p>具体怎么防：</p>
<p><strong>一、把账目和权限分清楚。</strong>谁管钱、谁管人、谁管对外，一个人不能同时管两样。<strong>这不是不信任，这是结构。</strong></p>
<p><strong>二、定期查一次具体的事。</strong>不是查人，是抽查一笔账、一个客户、一份合同。查的时候别声张。</p>
<p><strong>三、注意那些「为你着想」的人。</strong>动不动就说「我这是替您考虑」的，往往替自己考虑得更多。</p>
<p>安禄山认杨贵妃做干妈，在唐玄宗面前装憨卖傻，跳胡旋舞讨欢心。他一个人身兼平卢、范阳、河东三镇节度使，天下近一半的兵在他手上。唐玄宗对他好得不能再好，可天宝十四载，他还是反了。</p>
<p><strong>什么情况不用防：</strong>如果这些人是你从零带起来的，而且他们的收益跟你绑在一起，那就别天天查。<strong>把所有关系都当风险，你会先把自己孤立起来。</strong></p>
<h3 id="p-九四-弗过遇之-往厉必戒-别主动-等对方来">九四 · 弗过遇之，往厉必戒 —— 别主动，等对方来</h3>
<blockquote class="pw-quote"><strong>九四：无咎，弗过遇之。往厉必戒，勿用永贞。</strong><br>象曰：弗过遇之，位不当也。往厉必戒，终不可长也。</blockquote>
<p><strong>你现在在这个位置：你有个机会，你很想主动去够。</strong></p>
<p>「弗过遇之」——不越过去，等着碰上。「往厉必戒」——你主动去，就有危险，得警惕。</p>
<p>象传「位不当也」——你现在这个位置不合适。</p>
<p><strong>这一爻讲的是：位置不对的时候，别主动出击，等对方来找你。</strong></p>
<p>具体三条：</p>
<p><strong>一、把「我要争取」改成「让他来问」。</strong>你释放信号，但不表态。谁先开口，谁就露了底。</p>
<p><strong>二、拒绝那种需要你先垫钱、先投入的机会。</strong>这种机会十有八九是坑。</p>
<p><strong>三、别做长期承诺。</strong>「勿用永贞」——不能长久守着。现在这个局是临时的，别签三年的合同。</p>
<p>刘邦进咸阳，诸将都去抢金银财宝，他听樊哙、张良的劝，封了宫室府库，还军霸上，跟百姓约法三章，然后等项羽来。<strong>他当时实力不如项羽，主动出击就是找死，他只能等。</strong></p>
<p><strong>什么情况必须主动：</strong>如果这个机会有明确的截止时间，过了就没了，那你就上。<strong>「等」这个词，只在时间站在你这边的时候才成立。</strong></p>
<h3 id="p-六五-密云不雨-公弋取彼在穴-云很厚-就是不下雨">六五 · 密云不雨，公弋取彼在穴 —— 云很厚，就是不下雨</h3>
<blockquote class="pw-quote"><strong>六五：密云不雨，自我西郊，公弋取彼在穴。</strong><br>象曰：密云不雨，已上也。</blockquote>
<p><strong>你现在在这个位置：你铺垫了很久，声势也造了，可就是不落地。</strong></p>
<p>「密云不雨」——乌云密布，就是不下雨。</p>
<p>象传「已上也」——云飘得太高了。<strong>飘高了，就下不来。</strong></p>
<p><strong>这一爻讲的是：事情推不动，往往不是力度不够，是离地太远。</strong></p>
<p>具体怎么做：</p>
<p><strong>一、把动作落到一个人身上。</strong>不是「要开拓华东市场」，是「张三下周三去见李四」。<strong>动作一旦落到具体的人、具体的时间、具体的事，雨就下来了。</strong></p>
<p><strong>二、砍掉一半的准备工作。</strong>你已经准备了很久了。准备的边际收益早就见底了。</p>
<p><strong>三、去挖那个躲在洞里的人。</strong>「公弋取彼在穴」——那个真正关键的人，藏在洞里，你得去把他找出来。<strong>这件事所有人都在等，而只有你能做。</strong></p>
<p>诸葛亮五次北伐，每次都准备得很足，粮草、兵力、路线都算得清楚。可每次都因为粮运不继而退兵。他不是不会打仗，他是没有那块能下雨的地。</p>
<p><strong>什么情况可以继续等云：</strong>如果这件事的时机确实不成熟，而你有足够的资源撑到时机成熟，那就等。<strong>但要有时间表，没有时间表的等，就是拖。</strong></p>
<h3 id="p-上六-弗遇过之-飞鸟离之-飞太高-撞上去了">上六 · 弗遇过之，飞鸟离之 —— 飞太高，撞上去了</h3>
<blockquote class="pw-quote"><strong>上六：弗遇过之，飞鸟离之，凶，是谓灾眚。</strong><br>象曰：弗遇过之，已亢也。</blockquote>
<p><strong>你现在在这个位置：你已经冲得太高了，而且停不下来。</strong></p>
<p>「弗遇过之」——没有碰上，直接越过去了。「飞鸟离之」——鸟撞进了罗网。</p>
<p>象传「已亢也」——太亢了，到顶了。</p>
<p><strong>这一爻和初六首尾呼应，都是「飞鸟」。初六是刚起飞就出事，上六是飞到最高处出事。</strong></p>
<p><strong>这一爻讲的是：飞得越高，网越密。</strong></p>
<p>具体怎么落地：</p>
<p><strong>一、主动降一档。</strong>把摊子缩小、把目标调低、把速度放慢。这个动作要主动做，不要等到被迫。</p>
<p><strong>二、保住核心。</strong>这时候别想着全都保住，保住那个能让你东山再起的东西。</p>
<p><strong>三、别追加投入。</strong>到了这个位置还想加码翻本，是赌徒的想法。</p>
<p>吴王夫差在黄池之会上跟晋国争盟主，把国内的兵都带走了。越王勾践趁虚打进吴国，俘虏了太子。夫差回来之后还想再打，打了几年，最后在姑苏山上自杀。<strong>他的问题不是打不过，是他飞得太高，底下已经空了。</strong></p>
<p><strong>什么情况可以再冲一次：</strong>如果你的根基还在——人还在、钱还在、口碑还在——那可以再冲。<strong>判断标准是：你输了这一把，还有没有下一把。</strong></p>
<h3 id="p-最后-翅膀不够硬的时候-往下走才是顺势">最后：翅膀不够硬的时候，往下走才是顺势</h3>
<p>小过卦的两个阳爻被四个阴爻包着，像一个飞不起来的形状。</p>
<p>卦辞说「不宜上宜下」。</p>
<p><strong>往下，是顺势；往上，是逆势。</strong></p>
<p>你现在飞不高，那不是你的错。可你如果非要往上飞，那就是你的选择。</p>
<p>小过卦给了三个可以「过」的地方：<strong>行过乎恭，丧过乎哀，用过乎俭。</strong>恭敬多一点、哀痛多一点、节俭多一点——这三样过头了，都没事。</p>
<p><strong>小过卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">格局小的时候，就把小事做到极致。别急着飞，先把翅膀长出来。</blockquote>
  `,
  jiji: `
<p>一个人四十五岁，创业十一年，公司上市了。</p>
<p>敲钟那天晚上，他一个人在酒店房间里，突然不知道该干什么。</p>
<p>他跟我说：「我这十一年，每天睁眼就知道要干什么。现在突然没有了。」</p>
<p>既济卦讲的就是这一刻。既济是「已经渡过河了」。</p>
<p>《周易》六十四卦里，只有既济这一卦六个爻全部当位——该阳的阳，该阴的阴，一个不差。这是最完美的一卦。</p>
<p>可卦辞给你的第一句话是：<strong>初吉终乱。</strong></p>
<h3 id="p-初九-濡其尾-无咎-快上岸了-尾巴湿了">初九 · 濡其尾，无咎 —— 快上岸了，尾巴湿了</h3>
<blockquote class="pw-quote"><strong>初九：濡其尾，无咎。</strong><br>象曰：濡其尾，义无咎也。</blockquote>
<p><strong>你现在在这个位置：事情快成了，你有点松劲，出了个小纰漏。</strong></p>
<p>「濡其尾」——小狐狸过河，快到头了，尾巴沾了水。</p>
<p>象传「义无咎也」——这点小错，不算什么。</p>
<p><strong>这一爻讲的是：成功在望的时候出的错，代价通常不大，但它是个信号。</strong></p>
<p>信号是什么？<strong>是你已经开始松懈了。</strong></p>
<p>具体怎么做：</p>
<p><strong>一、把最后一段单独列出来。</strong>不要跟前十年的进度混在一起看。最后这一段，按天排。</p>
<p><strong>二、重新检查一遍那个你最放心的环节。</strong>出事的地方，通常是你最不设防的地方。</p>
<p><strong>三、别在这个时候庆祝。</strong>庆功宴提前开，人心就散了。<strong>庆祝是个仪式，仪式要用在最需要它的那一刻。</strong></p>
<p>曹操在赤壁之前，一路南下，荆州不战而降。他写信给孙权，说「今治水军八十万众，方与将军会猎于吴」。<strong>这话说得太早了。</strong>他那时候还不知道，自己的兵不习水战，也不知道后面会刮起东南风。</p>
<p><strong>什么情况可以松一口气：</strong>如果这件事已经签了合同、盖了章、钱到账了，那你松。<strong>但在最后一笔钱到账之前，别松。</strong></p>
<h3 id="p-六二-妇丧其茀-勿逐-七日得-丢了东西-先别追">六二 · 妇丧其茀，勿逐，七日得 —— 丢了东西，先别追</h3>
<blockquote class="pw-quote"><strong>六二：妇丧其茀，勿逐，七日得。</strong><br>象曰：七日得，以中道也。</blockquote>
<p><strong>你现在在这个位置：你丢了点东西。可能是一个客户、一个下属、一笔钱。</strong></p>
<p>「茀」是妇人车上的遮蔽物，是她的体面。丢了。</p>
<p>爻辞说：「勿逐，七日得」。别追，七天自己会回来。</p>
<p><strong>这一爻讲的是：有些损失，追不如等。</strong></p>
<p>具体怎么判断该不该追：</p>
<p><strong>一、这个东西有没有替代品。</strong>有，就别追；没有，才值得追。</p>
<p><strong>二、追的成本大不大。</strong>你为了追一个客户投进去三个月，损失的可能比这个客户本身还多。</p>
<p><strong>三、是不是你自己出了问题。</strong>如果人是你气走的、客户是被你的流程逼走的，那你追回来也留不住。<strong>先改原因，再追结果。</strong></p>
<p>象传「以中道也」——你守在中间那条道上，东西自己会回来。这话的意思很实在：<strong>你把自己的事做好，走了的人会回来，走了的客户会介绍新的来。</strong></p>
<p>楚汉相争的时候，刘邦手下跑了不少人。韩信也跑了。萧何没有去追那些跑掉的大多数，他只追了韩信一个。<strong>因为他知道哪个是必要的，哪个是可替代的。</strong></p>
<p><strong>什么情况必须追：</strong>如果丢的是核心客户、是不可替代的人、是能决定生死的东西，那就要追，而且要当天追。<strong>「勿逐」是给可替代的东西准备的。</strong></p>
<h3 id="p-九三-高宗伐鬼方-三年克之-小人勿用-成了之后还">九三 · 高宗伐鬼方，三年克之，小人勿用 —— 成了之后还要打仗</h3>
<blockquote class="pw-quote"><strong>九三：高宗伐鬼方，三年克之。小人勿用。</strong><br>象曰：三年克之，惫也。</blockquote>
<p><strong>你现在在这个位置：主业成了，可还有一块硬骨头没啃下来。</strong></p>
<p>「高宗伐鬼方，三年克之」——商高宗武丁打鬼方，打了三年才打下来。</p>
<p>象传给了一个字：「惫」。累垮了。</p>
<p><strong>这一爻讲的是：守成不是休息，守成是另一种消耗。</strong></p>
<p>最狠的是后面那句「小人勿用」。</p>
<p><strong>打完仗之后用人，比打仗本身还重要。</strong>仗打完的时候，是所有人最松懈的时候，也是小人最容易上位的时候。</p>
<p>具体三条：</p>
<p><strong>一、打完硬仗之后，先歇三个月再动人。</strong>这时候人的判断力是最差的——要么膨胀，要么崩溃。</p>
<p><strong>二、把功劳记清楚。</strong>记不清楚，就会有人来抢。</p>
<p><strong>三、别用那种「战时好用」的人去管「平时」。</strong>打仗的时候需要狠人，过日子需要稳人。<strong>这两种人往往不是同一批。</strong></p>
<p>汉武帝打匈奴，卫青、霍去病打出了赫赫战功。可打完仗之后，他把财政交给了桑弘羊，搞盐铁专卖、算缗告缗，天下中产以上几乎全破了产。<strong>仗打赢了，日子过崩了。</strong></p>
<p><strong>什么情况可以继续用狠人：</strong>如果你的仗还没打完，那狠人就得留着。<strong>什么时候换人，取决于你什么时候真的停战，而不是取决于你想不想换。</strong></p>
<h3 id="p-六四-繻有衣袽-终日戒-船漏了-你得有破布">六四 · 繻有衣袽，终日戒 —— 船漏了，你得有破布</h3>
<blockquote class="pw-quote"><strong>六四：繻有衣袽，终日戒。</strong><br>象曰：终日戒，有所疑也。</blockquote>
<p><strong>你现在在这个位置：一切看起来都很好，可你心里不踏实。</strong></p>
<p>「繻有衣袽」——船上备着破布，用来堵漏。</p>
<p>这一爻讲的是守成者该有的姿态：<strong>在船还没漏的时候，把堵漏的布准备好。</strong></p>
<p>「终日戒」——整天保持戒备。</p>
<p>象传「有所疑也」——你心里有疑虑，这不是坏事。</p>
<p><strong>具体要准备的东西，就是三张纸。</strong></p>
<p><strong>一、一张现金表。</strong>账上还有多少钱、每月固定支出多少、能撑几个月。这张纸每周更新。</p>
<p><strong>二、一张人表。</strong>哪些人走了会出事、他们的替代方案是什么、他们现在满不满意。</p>
<p><strong>三、一张风险表。</strong>列出三件「如果发生就麻烦大了」的事，每件事写一个应对动作。</p>
<p>宋太祖赵匡胤在陈桥兵变之后当了皇帝，他做的第一件事不是打仗，是「杯酒释兵权」。他太清楚了——他自己就是这么上来的。<strong>他最怕的事，就是他做过的事。</strong></p>
<p><strong>什么情况可以不用这么戒备：</strong>如果你手里的事还在高速增长，所有人都在忙着抢地盘，那戒备可以放一放。<strong>守成是针对增长停滞之后的局面。</strong></p>
<h3 id="p-九五-东邻杀牛-不如西邻之禴祭-排场不值钱">九五 · 东邻杀牛，不如西邻之禴祭 —— 排场不值钱</h3>
<blockquote class="pw-quote"><strong>九五：东邻杀牛，不如西邻之禴祭，实受其福。</strong><br>象曰：东邻杀牛，不如西邻之时也。实受其福，吉大来也。</blockquote>
<p><strong>你现在在这个位置：你有钱了，你开始讲究排场。</strong></p>
<p>「东邻杀牛」是大操大办，「西邻之禴祭」是简单的祭祀。爻辞说：<strong>杀牛的那个，不如简单祭的那个。</strong></p>
<p>象传补了一句「不如西邻之时也」——关键在时机，不在规模。</p>
<p><strong>这一爻讲的是：成功之后最容易犯的错，是把钱花在给人看的地方。</strong></p>
<p>具体的：</p>
<p><strong>一、把庆祝的预算砍一半。</strong>省下来的钱，发给做事的人。</p>
<p><strong>二、年会上少讲战略，多发钱。</strong>你讲的那套东西，底下人一年听八遍。钱是新鲜的。</p>
<p><strong>三、别急着换办公室、换车、换行头。</strong>这些东西会给你一种「已经成了」的幻觉，而这个幻觉会让你慢下来。</p>
<p>汉文帝在位二十三年，宫室苑囿狗马服御，一样都没添过。他想修个露台，算下来要百金，他说这是十户中等人家的家产，不修了。<strong>文景之治的底子，就是这么做出来的。</strong></p>
<p><strong>什么情况可以大办：</strong>如果需要靠排场来撑住信用——比如要接一个大客户、要在一个新市场立威——那就办。<strong>排场是工具的时候可以用，是习惯的时候就要命。</strong></p>
<h3 id="p-上六-濡其首-厉-整个人泡进去了">上六 · 濡其首，厉 —— 整个人泡进去了</h3>
<blockquote class="pw-quote"><strong>上六：濡其首，厉。</strong><br>象曰：濡其首厉，何可久也。</blockquote>
<p><strong>你现在在这个位置：你已经彻底放松了。你觉得可以歇了。</strong></p>
<p>初九是「濡其尾」，尾巴沾水，无咎。上六是「濡其首」，头都淹了，厉。</p>
<p><strong>同一个过河的动作，从头到尾，结果从无咎变成了厉。</strong></p>
<p>象传「何可久也」——这样能撑多久。</p>
<p><strong>这一爻讲的是：让你完蛋的，从来不是你做错的那件事，而是你做成了之后的那口气。</strong></p>
<p>具体怎么自救：</p>
<p><strong>一、重新给自己找一个必须做的事。</strong>不是目标，是每天必须做的具体动作。人可以休息，但不能没有日程。</p>
<p><strong>二、找一个敢跟你说真话的人。</strong>这个时候你身边全是好话。</p>
<p><strong>三、把钱和时间分一部分出去。</strong>投一件跟你主业没关系、你也感兴趣的事。<strong>这不叫分散风险，这叫给自己留一个还能动的地方。</strong></p>
<p>唐玄宗开元盛世，他前半辈子是明君。可到了天宝年间，他把政事交给李林甫、杨国忠，自己在宫里听曲、看舞、跟杨贵妃过日子。<strong>安史之乱不是突然来的，是他松了二十年手之后来的。</strong></p>
<p><strong>什么情况可以真的歇：</strong>如果你已经把位置交出去了，交接干净了，那你就歇。<strong>真正危险的歇，是位置还在手上，人已经不在状态了。</strong></p>
<h3 id="p-最后-初吉终乱">最后：初吉终乱</h3>
<p>既济这一卦，六个爻全都当位，是六十四卦里最完美的一卦。</p>
<p>可它的卦辞是「初吉终乱」。</p>
<p><strong>完美的局面里，藏着一个必然的走向。</strong></p>
<p>因为完美意味着没有调整的余地了。你所有的位置都占对了，任何变化都是往坏的方向变。</p>
<p>所以既济给你的功课不是怎么更成功，是<strong>怎么在成功之后不自毁</strong>。</p>
<p>六爻里，「濡」字出现了两次。一次是尾巴，一次是头。中间隔着的，就是你松劲的那几年。</p>
<p><strong>既济卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">事成了，先别高兴。你现在站的地方，是下一段下坡路的起点。</blockquote>
  `,
  weiji: `
<p>一个人做了三年一个项目，倒在了最后一步。</p>
<p>产品做出来了，团队也带起来了，谈崩在最后一轮融资上。</p>
<p>他跟我说：「最难受的不是没做成。是就差一点。」</p>
<p><strong>差一点，是最难受的一种失败。</strong></p>
<p>未济卦是六十四卦的最后一卦。未济是「还没渡过河」。</p>
<p>一部讲变化的书，最后一卦讲的是「还没完」。这件事本身就有意思。</p>
<h3 id="p-初六-濡其尾-吝-一开始就湿了">初六 · 濡其尾，吝 —— 一开始就湿了</h3>
<blockquote class="pw-quote"><strong>初六：濡其尾，吝。</strong><br>象曰：濡其尾，亦不知极也。</blockquote>
<p><strong>你现在在这个位置：你刚起步，就发现自己准备不足。</strong></p>
<p>「濡其尾」——小狐狸过河，尾巴湿了。这一爻给的判词是「吝」，是憋屈、是不体面。</p>
<p>象传「亦不知极也」——你不知道深浅就下水了。</p>
<p><strong>这一爻讲的是：开局时的狼狈，多半是因为没做功课。</strong></p>
<p>具体怎么做：</p>
<p><strong>一、把「我以为」全部换成「我确认过」。</strong>你以为客户要的是 A，你以为成本是三百万，你以为三个月能做完——这些「以为」，一个都别留。</p>
<p><strong>二、找三个已经做过这件事的人聊。</strong>不用问建议，就问他们当初在哪儿栽的。</p>
<p><strong>三、先做最小的一件事。</strong>别从最难的开始，从最容易见效的开始。<strong>你需要一次小胜来稳住自己。</strong></p>
<p>飞将军李广一辈子跟匈奴打了七十多仗，可他有个毛病——行军不派斥候，扎营不看地形。他靠的是个人勇武和临场应变。<strong>这就是「不知极」。</strong>最后一次出征，他在沙漠里迷了路，误了军期，不肯受审，自刎了。</p>
<p><strong>什么情况可以先下水：</strong>如果你要的就是抢占先机，快比准重要，那就先跳。<strong>但要留一笔钱给「湿了尾巴」之后的自己。</strong></p>
<h3 id="p-九二-曳其轮-贞吉-拉住车轮">九二 · 曳其轮，贞吉 —— 拉住车轮</h3>
<blockquote class="pw-quote"><strong>九二：曳其轮，贞吉。</strong><br>象曰：九二贞吉，中以行正也。</blockquote>
<p><strong>你现在在这个位置：你有能力，也有干劲，可你发现事情推得比你想的慢。</strong></p>
<p>「曳其轮」——拉住车轮，不让它跑太快。</p>
<p>爻辞给的判词是「贞吉」。</p>
<p>象传「中以行正也」——你守在中道上，走的是正路。</p>
<p><strong>这一爻讲的是：未成的时候，慢下来是技术动作，不是认输。</strong></p>
<p>具体三个动作：</p>
<p><strong>一、把节奏降一档。</strong>你原本想一年做完的事，改成两年。这不是拖延，这是给意外留出空间。<strong>未成的事，一定会出意外。</strong></p>
<p><strong>二、先把成本压到最低。</strong>现金流就是你的氧气。在这场仗打完之前，任何不能直接带来收入的动作都是奢侈品。</p>
<p><strong>三、别扩张。</strong>这个阶段最忌讳的就是看到一点起色就招人、加投入。<strong>等你连续三个月稳定盈利了，再谈扩张。</strong></p>
<p>周文王被商纣囚在羑里，他没有反抗，没有喊冤，而是在里面推演八卦。他当时的力量远不如商，任何动作都是找死。<strong>他做的是等，等一件他没做、但一定会发生的事。</strong></p>
<p><strong>什么情况可以加速：</strong>如果窗口期真的在关闭——比如你的竞争对手已经拿到融资、政策三个月后要变——那就得加速。<strong>加速的前提是你清楚自己在赌什么。</strong></p>
<h3 id="p-六三-未济-征凶-利涉大川-不该现在动-但别停下">六三 · 未济，征凶，利涉大川 —— 不该现在动，但别停下</h3>
<blockquote class="pw-quote"><strong>六三：未济，征凶，利涉大川。</strong><br>象曰：未济征凶，位不当也。</blockquote>
<p><strong>你现在在这个位置：你想动，可你知道现在动是错的。你又怕不动就死了。</strong></p>
<p>这是全卦最拧巴的一爻。前半句说「征凶」，出发就凶；后半句说「利涉大川」，适合渡大河。</p>
<p><strong>这两句话放在一起，讲的是两种不同的动作。</strong></p>
<p>「征」是正面进攻，是硬碰。「涉大川」是渡河，是迂回过去。</p>
<p><strong>这一爻讲的是：现在不能打，但要往前走。</strong></p>
<p>具体怎么分：</p>
<p><strong>一、停掉所有正面消耗的动作。</strong>跟对手打价格战、公开叫板、投广告抢流量——这些是「征」。</p>
<p><strong>二、保留一条能过河的路。</strong>找一个对手看不上的小市场、一个别人嫌麻烦的客户、一个还没人做的场景。<strong>这条路看起来小，但它能让你过河。</strong></p>
<p><strong>三、别在乎面子。</strong>这一阶段你的动作会被人笑。<strong>笑你的人在岸上，你在水里，你们的处境不一样。</strong></p>
<p>越王勾践在吴国做俘虏，给夫差喂马、牵马，住在石屋里。他回国之后，十年生聚、十年教训，一边送美女西施给夫差，一边偷偷练兵。他一直在「涉大川」，从来没跟吴国正面「征」。</p>
<p><strong>什么情况应该直接征：</strong>如果你手里有压倒性的优势，或者对方的防线已经垮了，那就别绕，直接上。<strong>「征凶」是针对实力不够的时候说的。</strong></p>
<h3 id="p-九四-震用伐鬼方-三年有赏于大国-大事业-三年起">九四 · 震用伐鬼方，三年有赏于大国 —— 大事业，三年起步</h3>
<blockquote class="pw-quote"><strong>九四：贞吉，悔亡，震用伐鬼方，三年有赏于大国。</strong><br>象曰：贞吉悔亡，志行也。</blockquote>
<p><strong>你现在在这个位置：你在啃一块硬骨头，已经啃了一段时间，看不到头。</strong></p>
<p>「震用伐鬼方，三年有赏于大国」——打了三年，才有大国来赏。</p>
<p><strong>这一爻是给坚持的人吃的定心丸。它明明白白告诉你：三年。</strong></p>
<p>象传「志行也」——你的方向是在推进的，只是还没到。</p>
<p>具体怎么做这三年：</p>
<p><strong>一、把三年切成十二个季度。</strong>每季度一个能验收的小目标。<strong>人熬不住三年，但能熬住一个季度。</strong></p>
<p><strong>二、每个季度记一次账。</strong>不是财务的账，是进度的账——比上个季度强在哪。<strong>你需要证据来对抗自我怀疑。</strong></p>
<p><strong>三、找一个人跟你一起熬。</strong>不用多，一个。<strong>一个人熬三年，九成会放弃。</strong></p>
<p>韩信在汉中，从一个管粮的小官，到登坛拜将，中间隔着萧何的一次追、刘邦的一次赌。他真正打出来，是往后四年的事。<strong>这四年里，他没有一天是轻松的。</strong></p>
<p><strong>什么情况该放弃：</strong>如果你啃了三年，而每一年的指标都在往下走，那就别啃了。<strong>三年是给上升曲线准备的，不是给下降曲线准备的。</strong></p>
<h3 id="p-六五-君子之光-有孚-吉-你没成-但别人开始信你">六五 · 君子之光，有孚，吉 —— 你没成，但别人开始信你</h3>
<blockquote class="pw-quote"><strong>六五：贞吉，无悔，君子之光，有孚，吉。</strong><br>象曰：君子之光，其晖吉也。</blockquote>
<p><strong>你现在在这个位置：事情还没成，可你个人已经有口碑了。</strong></p>
<p>「君子之光，有孚」——你的光是因为别人信你。</p>
<p>象传「其晖吉也」——这个光是柔和的、往外散的，不是刺眼的。</p>
<p><strong>这一爻是未济卦里最亮的一处。它说的是：事可以不成，人不能不成。</strong></p>
<p>具体怎么做：</p>
<p><strong>一、把每一次失败都变成一次公开的复盘。</strong>不是自嘲，是讲清楚哪儿判断错了、怎么改的。<strong>别人记住的不是你失败，是你面对失败的样子。</strong></p>
<p><strong>二、别欠人情债。</strong>这个阶段你一定会求人。求了要还，而且要提前还。</p>
<p><strong>三、保持体面。</strong>不抱怨环境、不骂对手、不哭穷。<strong>你现在的每一个动作，都在给未来的合作方打分。</strong></p>
<p>刘备的前半生，投公孙瓒、投陶谦、投曹操、投袁绍、投刘表，二十年没有一块自己的地盘。可他走到哪儿，都有人愿意收留他。<strong>因为他这个人，被天下人认了。</strong>这份认可，最后换来了荆州和益州。</p>
<p><strong>什么情况不用在乎口碑：</strong>如果你做的是那种一锤子买卖、做完就走的生意，那口碑的权重确实低。<strong>但只要你还要在这行待下去，你的名字就是你的资产。</strong></p>
<h3 id="p-上九-有孚于饮酒-无咎-濡其首-有孚失是-喝一杯">上九 · 有孚于饮酒，无咎，濡其首，有孚失是 —— 喝一杯没事，喝趴下就完了</h3>
<blockquote class="pw-quote"><strong>上九：有孚于饮酒，无咎，濡其首，有孚失是。</strong><br>象曰：饮酒濡首，亦不知节也。</blockquote>
<p><strong>你现在在这个位置：事情还没成，你已经很累了。你想喘口气。</strong></p>
<p>「有孚于饮酒」——带着诚信去喝酒，无咎。这是允许你歇的。</p>
<p>「濡其首，有孚失是」——喝到头都淹了，那点诚信也没了。</p>
<p>象传「亦不知节也」——你不知道分寸。</p>
<p><strong>这一爻是给所有「差一点」的人的最后一句提醒：休息可以，放纵不行。</strong></p>
<p>具体怎么分：</p>
<p><strong>一、给自己定一个喘息的时间。</strong>比如两周。两周之内什么都不想，两周之后重新开始。<strong>有期限的放松是充电，没期限的放松是烂掉。</strong></p>
<p><strong>二、别用酒、赌、购物来缓。</strong>这些东西会给你一种「我在恢复」的错觉，实际上是把窟窿挖得更深。</p>
<p><strong>三、把「我失败了」改成「这件事没成」。</strong>你不是失败者，你是这件事暂时没做成。<strong>这个区别看着小，它决定了你明年还起不起来。</strong></p>
<p>项羽在垓下被围，四面楚歌。他还有船可以过江，乌江亭长劝他回江东。他说：「籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之？」他自刎了。<strong>他输掉的不是那场仗，是那口气。</strong></p>
<p><strong>什么情况可以彻底撂下：</strong>如果这件事已经伤到你的身体、家庭、底线，那就放下，真放下。<strong>不是所有的事都值得做完，有些事停下来才是对的。</strong></p>
<h3 id="p-最后-还没完">最后：还没完</h3>
<p>《周易》六十四卦，最后一卦是未济。</p>
<p>它没有给你一个圆满的结局。它告诉你：<strong>一个循环结束了，下一个循环已经开始。</strong></p>
<p>既济是水在火上，饭做熟了。未济是火在水上，饭还没熟。</p>
<p><strong>可饭做熟了，你就只剩吃和洗碗了。饭还没熟，你还有得忙。</strong></p>
<p>这不是安慰，这是实话。活着这件事，本来就是一直在过河。你上了这个岸，前面还有一条河。</p>
<p><strong>未济卦最后给你的一句话：</strong></p>
<blockquote class="pw-quote">差一点不是失败，是还没到。手上那口气别松，也别急着喝那杯酒。</blockquote>
  `,
};

